	using namespace thewizardplusplus::wizard_parser;
	SECTION("without exceptions") {
		const auto [tokens, rest_offset] = lexer::tokenize(
			{
				{std::regex{"[[:alpha:]]+"}, "alpha"},
				{std::regex{"[[:digit:]]+"}, "digit"},
				{std::regex{"[[:space:]]+"}, "space"}
