TEST(Timer, Additivity) {
  Timer T1("T1");
  EXPECT_TRUE(T1.isInitialized());
  T1.startTimer();
  T1.stopTimer();
  auto TR1 = T1.getTotalTime();
  T1.startTimer();
  std::this_thread::sleep_for(std::chrono::milliseconds(1));
  T1.stopTimer();
  auto TR2 = T1.getTotalTime();
  EXPECT_TRUE(TR1 < TR2);
}
