	//Initialize a node with a parent and then remove it.
	TreeNode<int> root;
	TreeNode<int> focusNode;
	
	focusNode.setParent(&root);
	EXPECT_EQ(focusNode.getParent(), &root);

	focusNode.removeParent();
	EXPECT_EQ(focusNode.getParent(), nullptr);
}

