#include <vector>
#include "fuzzer_common.h"
extern "C" int LLVMFuzzerTestOneInput(const uint8_t* Data, size_t Size);
int main(int argc, char* argv[]) {
  for (int i = 1; i < argc; ++i) {
    std::ifstream in(argv[i]);
    assert(in);
    in.seekg(0, std::ios_base::end);
    const auto pos = in.tellg();
    assert(pos >= 0);
    in.seekg(0, std::ios_base::beg);
    std::vector<char> buf(static_cast<size_t>(pos));
    in.read(buf.data(), static_cast<long>(buf.size()));
    assert(in.gcount() == pos);
    LLVMFuzzerTestOneInput(fmt_fuzzer::as_bytes(buf.data()), buf.size());
  }
}

#include <library/cpp/iterator/iterate_keys.h>
#include <library/cpp/testing/gtest/gtest.h>
#include <map>
using namespace testing;
TEST(IterateKeys, ConstMappingIteration) {
    const std::map<int, int> squares{
        {1, 1},
        {2, 4},
        {3, 9},
    };
    EXPECT_THAT(
        IterateKeys(squares),
        ElementsAre(1, 2, 3)
    );
}
TEST(IterateKeys, ConstMultiMappingIteration) {
    const std::multimap<int, int> primesBelow{
        {2, 2},
        {5, 3},
        {5, 5},
        {11, 7},
        {11, 11},
        {23, 13},
        {23, 17},
        {23, 23},
    };
    EXPECT_THAT(
        IterateKeys(primesBelow),
        ElementsAre(2, 5, 5, 11, 11, 23, 23, 23)
    );
}

