  using namespace PERFORMER_DB_HEADER_KEY;
  return {
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) {ENUM_2_STR(enu), _##enu}, //
      PSON_MODEL_FIELD_MAPPING
