UModularSynthComponent::UModularSynthComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	VoiceCount = 8;
}
bool UModularSynthComponent::Init(int32& SampleRate)
{
	NumChannels = 2;
	EpicSynth1.Init(SampleRate, VoiceCount);
	// Set default parameters
	SetEnablePolyphony(false);
	SetOscType(0, ESynth1OscType::Saw);
	SetOscType(1, ESynth1OscType::Saw);
	SetOscCents(1, 2.5f);
	SetOscPulsewidth(0, 0.5f);
	SetOscPulsewidth(1, 0.5f);
	SetEnableUnison(false);
	SetSpread(0.5f);
	SetGainDb(-3.0f);
	SetAttackTime(10.0f);
	SetDecayTime(100.0f);
	SetSustainGain(0.707f);
	SetReleaseTime(5000.0f);
	SetEnableLegato(true);
	SetEnableRetrigger(false);
	SetFilterFrequency(1200.0f);
	SetFilterQ(2.0f);
	SetFilterAlgorithm(ESynthFilterAlgorithm::Ladder);
	SetStereoDelayIsEnabled(true);
	SetStereoDelayMode(ESynthStereoDelayMode::PingPong);
	SetStereoDelayRatio(0.2f);
	SetStereoDelayFeedback(0.7f);
	SetStereoDelayWetlevel(0.3f);
	SetChorusEnabled(false);
	return true;
}
int32 UModularSynthComponent::OnGenerateAudio(float* OutAudio, int32 NumSamples)
{
	for (int32 SampleIndex = 0; SampleIndex < NumSamples; SampleIndex += NumChannels)
	{
		EpicSynth1.GenerateFrame(&OutAudio[SampleIndex]);
	}
	return NumSamples;
}
void UModularSynthLibrary::AddModularSynthPresetToBankAsset(UModularSynthPresetBank* InBank, const FModularSynthPreset& Preset, const FString& PresetName)
{
	if (GIsEditor)
	{
		FModularSynthPresetBankEntry NewBankEntry;
		NewBankEntry.PresetName = PresetName;
		NewBankEntry.Preset = Preset;
		InBank->Presets.Add(NewBankEntry);
		InBank->MarkPackageDirty();
	}
}

