{
  using namespace std;
  for (int i=0; i<v.size(); ++i)
  {
    std::cerr << i << ": ";
    for (int j=0; j<v[i].size(); ++j)
      std::cerr << v[i][j] << " ";
    std::cerr << std::endl;
  }
