#include <typeinfo>

// Interface class I
class I {
public:
    virtual ~I() { }
    virtual void x() { }
};

// Class A inherits from I
class A : public I {
    void x() override { }
};

// Class B inherits from I
class B : public I {
    void x() override { }
};

int main()
{
    // Create instance of A through base pointer
    I *a = new A();

    // Attempt to cast to B (will result in nullptr)
    B *b = dynamic_cast<B *>(a);

    // Suppress unused variable warning
    (void)b;

    // Clean up
    delete a;

    return 0;
}

