using namespace std;

class CCipher {
public:
  // Decodes the cipher text by shifting characters backward
  string decode(string cipherText, int shift) {
    string orig;
    for (char c : cipherText) {
      // Calculate original character with wrap-around using modulo
      orig += 'A' + (c - 'A' - shift + 26) % 26;
    }
    return orig;
  }
};

int main() {
  CCipher cc;
  // Test case: decode full alphabet with shift 10
  assert(cc.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 10) == "QRSTUVWXYZABCDEFGHIJKLMNOP");
}

