using namespace std;

// Main function to demonstrate bitset operations
int main()
{
    // Initialize vector with Fibonacci numbers
    vector<int> ivec = {1, 2, 3, 5, 8, 13, 21};
    unsigned long val = 0UL;

    // Set bits corresponding to values in ivec
    for(auto i : ivec)
    {
        val |= 1UL << i;
    }

    // Print the numeric value of the bitset
    cout << val << endl;

    // Create bitset from the numeric value
    bitset<32> b(val);
    cout << b << endl;

    // Alternative method: directly set bits using set()
    bitset<32> bb;
    for(auto i : ivec)
    {
        bb.set(i);
    }
    cout << bb << endl;

    // Compare both methods
    if(b == bb)
    {
        cout << "b == bb" << endl;
    }
}

