// Driver instance
ics::ICS3* driver {nullptr};

// Publisher for pose feedback
ros::Publisher pub;

// Callback function to handle movement commands
void move(const servo_msgs::IdBased::ConstPtr& msg) 
{
    servo_msgs::IdBased result;
    result.id = msg->id;

    try 
    {
        // Execute movement and get resulting angle
        result.angle = driver->move(msg->id, ics::Angle::newDegree(msg->angle));

        // Publish the result
        pub.publish(result);
    } 
    catch (std::runtime_error e) 
    {
        ROS_INFO("Communicate error: %s", e.what());
    }
}

// Main entry point
int main(int argc, char** argv) 
{
    // Initialize ROS node
    ros::init(argc, argv, "servo_krs_node");

    // Private node handle for parameters
    ros::NodeHandle pn {"~"};

    // Default serial port path
    std::string path {"/dev/ttyUSB0"};

    // Get parameter with default fallback
    pn.param<std::string>("path", path, path);

    // Initialize driver with serial port
    ics::ICS3 ics {std::move(path)};
    driver = &ics;

    // Public node handle for topics
    ros::NodeHandle n {};

    // Subscribe to command topic
    ros::Subscriber sub {n.subscribe("cmd_krs", 100, move)};

    // Advertise pose feedback topic
    pub = n.advertise<servo_msgs::IdBased>("pose_krs", 10);

    // Enter main loop
    ros::spin();

    return 0;
}

