#include <pthread.h>
#include <unistd.h>

// Global read-write lock and shared variable
pthread_rwlock_t rwlock;
int GLOB;

// Thread function that incorrectly writes under a reader lock
void *Thread1(void *p) {
  (void)p;

  // Acquire read lock
  pthread_rwlock_rdlock(&rwlock);

  // Write under reader lock - this is a data race!
  usleep(100);
  GLOB++;

  // Release the lock
  pthread_rwlock_unlock(&rwlock);

  return 0;
}

int main(int argc, char *argv[]) {
  // Initialize the read-write lock
  pthread_rwlock_init(&rwlock, NULL);

  // Main thread acquires read lock
  pthread_rwlock_rdlock(&rwlock);

  // Create worker thread
  pthread_t t;
  pthread_create(&t, 0, Thread1, 0);

  // Read the global variable while holding the lock
  volatile int x = GLOB;
  (void)x;

  // Release the lock
  pthread_rwlock_unlock(&rwlock);

  // Wait for thread to complete
  pthread_join(t, 0);

  // Clean up
  pthread_rwlock_destroy(&rwlock);

  return 0;
}
// CHECK: WARNING: ThreadSanitizer: data race
// CHECK:   Write of size 4 at {{.*}} by thread 1:
// CHECK:     #0 Thread1(void*) {{.*}}write_in_reader_lock.cc:13
// CHECK:   Previous read of size 4 at {{.*}} by main thread:
// CHECK:     #0 main {{.*}}write_in_reader_lock.cc:23

#include <chrono>
#include <cstdint>
#include <iostream>
#include <mutex>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

// Mutex for synchronized output
std::mutex output;

// Function that sleeps and prints the value
void func(unsigned int value)
{
    using std::chrono::seconds;
    using std::cout;
    using std::endl;
    using std::lock_guard;
    using std::mutex;

    // Sleep for the specified number of seconds
    std::this_thread::sleep_for(seconds(value));

    // Print value in a thread-safe manner
    {
        lock_guard<mutex> lock{output};
        cout << value << endl;
    }
}

// Main function
int main(int argc, char** argv)
{
    using std::cout;
    using std::endl;
    using std::string;
    using std::stringstream;
    using std::thread;
    using std::vector;

    // Determine number of threads from command line arguments
    vector<thread>::size_type amount = argc - 1;
    vector<thread> threads;

    // Reserve space to avoid reallocations
    threads.reserve(amount);

    // Parse arguments and spawn threads
    for (auto i = 1; i < argc; ++i)
    {
        stringstream ss;
        ss << argv[i];
        unsigned int value;

        // Try to parse integer argument
        if (!(ss >> value))
        {
            cout << "You input a non-integer: " << argv[i] << endl;
        }
        else
        {
            threads.emplace_back(func, value);
        }
    }

    // Join all threads
    for (auto& thread : threads)
    {
        thread.join();
    }

    return 0;
}

