#include <stdio.h>
#include <Logging.h>
#include <ZipFile.h>

// Main function to process zip file
int main()
{
    // Set logging level to trace
    v::Log::Level = v::Log::LogLevel_Trace;

    // Log debug message about reading zip file
    v::Log::Debug("Reading zip file test.zip");

    try 
    {
        // Create and read zip file
        v::ZipFile zip;
        zip.Read("test.zip");

        // Get all entries
        s::StackArray<v::ZipEntry> entries;
        zip.GetEntries(entries);

        // Process each entry
        for (auto &entry : entries) 
        {
            // Log entry information
            v::Log::Debug("Zip entry %1: %2", FVAR(entry.GetIndex()), FVAR(entry.GetName()));

            // Read entry contents into memory stream
            s::MemoryStream strm;
            entry.Read(strm);

            // Log stream details
            v::Log::Debug("Contents at %1 with size %2", FVAR(strm.strm_pubBuffer), FVAR(strm.Size()));
        }
    } 
    catch (s::Exception ex) 
    {
        // Log fatal error if exception occurs
        v::Log::Fatal("Error: %1", FVAR(ex.Message));
    }

    // Wait for user input before exiting
    getchar();

    return 0;

}

#include "binarytree.h"
#include <iostream>

using namespace std;

// Recursive helper function to print tree in DOT format
template <class T>
void dotPrint(ostream& out, typename BinaryTree<T>::Inspector treeInspector, size_t id)
{
    if (treeInspector.isEmpty())
    {
        out << id << "[label=\"NULL\" shape=point];" << endl;
        return;
    }

    out << id << "[label=\"" << treeInspector.getData() << "\"];" << endl;
    out << id << " -> " << 2*id + 1 << ";" << endl;
    dotPrint<T>(out, treeInspector.left(), 2*id + 1);
    out << id << " -> " << 2*id + 2 << ";" << endl;
    dotPrint<T>(out, treeInspector.right(), 2*id + 2);
}

// Main DOT printing function for a BinaryTree
template <class T>
void dotPrint(ostream& out, const BinaryTree<T>& tree)
{
    out << "digraph G\n{\n";
    dotPrint<T>(out, tree.getInspector(), 0);
    out << "}\n";
}

int main()
{
    // Create a binary tree and build it with some values
    BinaryTree<int> tree;
    BinaryTree<int>::Transformer tr = tree.getTransformer();

    tr.addData(5);
    tr.goLeft();
    tr.addData(2);
    tr.goToParent();
    tr.goRight();
    tr.addData(3);

    // Print the tree in DOT format
    dotPrint(cout, tree);

    return 0;
}

