// Main run function
void run ()
{
    Timer timer;
    CONSOLE ("printing Timer::current_time() at 10ms intervals:");

    for (size_t n = 0; n < 10; ++n)
    {
        CONSOLE ("  current timestamp: " + str(Timer::current_time(), 16)
            + " (from C time(): " + str(time(NULL)) + ")");
        usleep (10000);
    }

    // Print elapsed time
    CONSOLE ("execution took " + str(timer.elapsed()) + " seconds");

    timer.start();
