// Inline function with specific attributes
#define INLINE inline __attribute__((weak)) __attribute__((always_inline)) __attribute__((used))

extern "C" {

// Calls the destructor function on the object if it's not null
INLINE void call_destructor(void *user_context, void (*fn)(void *user_context, void *object), void **object) {
    void *o = *object;
    *object = NULL;

    // Call the function if object is not null
    if (o) {
        fn(user_context, o);
    }
}

