std::ostream& operator<<(std::ostream& os, PackageManager pm)
{
    std::string pm_str;
    switch(pm)
    {
        case PackageManager::kOstree:
            pm_str = "ostree";
            break;
        case PackageManager::kDebian:
            pm_str = "debian";
