// User-defined type for testing atomic operations
struct UserType {
    int i;
    UserType() noexcept {}
    constexpr explicit UserType(int d) noexcept : i(d) {}
    friend bool operator==(const UserType& x, const UserType& y) {
        return x.i == y.i;
    }
};

// Template function to test atomic initialization with different types
template <class Tp>
void test()
{
    typedef std::atomic<Tp> Atomic;
    static_assert(std::is_literal_type<Atomic>::value, "");
    constexpr Tp t(42);

    // Test direct initialization with parentheses
    {
        constexpr Atomic a(t);
        assert(a == t);
    }

    // Test list initialization with braces
    {
        constexpr Atomic a{t};
        assert(a == t);
    }

    // Test initialization using ATOMIC_VAR_INIT macro
    {
        constexpr Atomic a = ATOMIC_VAR_INIT(t);
        assert(a == t);
    }
}

// Main function to run tests with built-in and user-defined types
int main()
{
    test<int>();
    test<UserType>();
}

