#include <vector>
#include <unordered_set>
#include <algorithm>
#include <string>

class Solution {
public:
    // Determines if two strings are close based on character frequency and set of characters
    bool closeStrings(std::string word1, std::string word2) {
        std::vector<int> v1(26, 0), v2(26, 0);
        std::unordered_set<char> s1, s2;

        // Count character frequencies and collect unique characters for word1
        for (const auto& c : word1) {
            v1[c - 'a']++;
            s1.emplace(c);
        }

        // Count character frequencies and collect unique characters for word2
        for (const auto& c : word2) {
            v2[c - 'a']++;
            s2.emplace(c);
        }

        // Sort frequency vectors to compare multiset of frequencies
        std::sort(v1.begin(), v1.end());
        std::sort(v2.begin(), v2.end());

        // Two strings are close if they have the same set of characters and same sorted frequency vectors
        return s1 == s2 && v1 == v2;
    }
};

