#include <Halide.h>

using namespace Halide;

int main(int argc, char **argv)
{
    Var x, y;

    // Define predicate function
    Func pred("pred");
    pred(x, y) = x < y;

    // Define selector function based on predicate
    Func selector("selector");
    selector(x, y) = select(pred(x, y), 1, 0);

    // Compute and vectorize settings
    pred.compute_root();
    selector.compute_root().vectorize(x, 8);

    // Define reduction domain
    RDom range(0, 100, 0, 100);

    // Evaluate the sum
    int32_t result = evaluate<int32_t>(lambda(sum(selector(range.x, range.y))));

    // Verify result
    assert(result == 4950);

    printf("Success!\n");
    return 0;
}

