// Driver instance
ics::ICS3* driver {nullptr};

// Publisher for the result
ros::Publisher pub;

// Callback function to move the servo
void move(const servo_msgs::IdBased::ConstPtr& msg) 
{
    servo_msgs::IdBased result;
    try 
    {
        // Move the servo and get the result
        result.angle = driver->move(msg->id, ics::Angle::newDegree(msg->angle));
        result.id = msg->id;

        // Publish the result
        pub.publish(result);
    } 
    catch (std::runtime_error e) 
    {
        ROS_INFO("Communicate error: %s", e.what());
    }
}

// Main function
int main(int argc, char** argv) 
{
    // Initialize ROS node
    ros::init(argc, argv, "servo_krs_node");

    // Get private node handle
    ros::NodeHandle pn {"~"};

    // Default serial port path
    std::string path {"/dev/ttyUSB0"};

    // Get parameter or use default
    pn.param<std::string>("path", path, path);

    // Log the path
    ROS_INFO("Open servo motor path: %s", path.c_str());

    // Create ICS3 driver instance
    ics::ICS3 ics {std::move(path)};

    // Set global driver pointer
    driver = &ics;

    // Create node handle for subscriber and publisher
    ros::NodeHandle n {};

    // Subscribe to command topic
    ros::Subscriber sub {n.subscribe("cmd_krs", 100, move)};

    // Advertise result topic
    pub = n.advertise<servo_msgs::IdBased>("pose_krs", 10);

    // Spin until shutdown
    ros::spin();

    return 0;
}

