// Helper struct to hold values at compile-time indices
template <std::size_t I, typename T> 
struct holder { 
    T t; 
};

// Implementation detail for tuple-like structure
template <typename Sequence, typename... Ts> 
struct tuple_impl;

// Specialization using index sequence for parameter pack expansion
template <std::size_t... I, typename... Ts>
struct tuple_impl<std::index_sequence<I...>, Ts...> : holder<I, Ts>... {};

// Alias template for the tuple type
template <typename... Ts>
using tuple = tuple_impl<std::make_index_sequence<sizeof...(Ts)>, Ts...>;

// Overloaded get functions for accessing elements
template <std::size_t I, typename T> 
T &get(holder<I, T> &h) { 
    return h.t; 
}

template <typename T, std::size_t I> 
T &get(holder<I, T> &h) { 
    return h.t; 
}

// Test function demonstrating tuple usage
void test_tuple() {
    tuple<int, std::string> t{1, "hello"};

    // Output values in reverse order of declaration
    std::cout << get<1>(t) << "\n";
    std::cout << get<0>(t) << "\n";

    // Modify values using type-based get
    get<int>(t) = 5;
    get<std::string>(t) = "world";

    // Output modified values
    std::cout << get<1>(t) << "\n";
    std::cout << get<0>(t) << "\n";
}

// Overload set for variant visitors
template <typename... F> 
struct overload : F... { 
    using F::operator()...; 
};

// Deduction guide for overload
template <typename... F> 
overload(F...)->overload<F...>;

// Test function demonstrating variant and overload usage
void test_overload() {
    std::variant<int, std::string> v;
    v = std::string("hello");

    // Visit variant with overloaded lambdas
    std::visit(
        overload{
            [](int i) { 
                std::cout << i << " int \n"; 
            },
            [](const std::string &s) { 
                std::cout << s << " string \n"; 
            }
        },
        v);
}

// Main entry point
int main() {
    test_tuple();
    test_overload();
}

