// Reverse command line arguments and their characters
int main(int argc, char* argv[])
{
    using namespace std;

    // Initialize vector with command line arguments (excluding program name)
    vector<string> cmdlineargs {argv+1, argv+argc};

    // Iterate through arguments in reverse order
    for(auto rbiterv = cmdlineargs.rbegin(); rbiterv != cmdlineargs.rend(); ++rbiterv) {
        auto& arg = *rbiterv;

        // Iterate through each character of the argument in reverse
        for(auto rbiterarg = arg.rbegin(); rbiterarg != arg.rend(); ++rbiterarg) {
            cout << *rbiterarg;    
        }

        cout << endl;
    }

    return EXIT_SUCCESS;
}

