#include "testing/gtest/include/gtest/gtest.h"

// Test for WebKitThread
TEST(WebKitThreadTest, DISABLED_ExposedInChromeThread)
{
    int* null = NULL;  // Help the template system out.

    // Initial check before WebKitThread initialization
    EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, null));

    {
        WebKitThread thread;

        // Check before initialization
        EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT,
                                              FROM_HERE, null));

        // Initialize the thread
        thread.Initialize();

        // Check after initialization
        EXPECT_TRUE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT,
                                             FROM_HERE, null));
    }

    // Check after WebKitThread destruction
    EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT,
                                          FROM_HERE, null));
}

#include "simplegameworld.h"

// Adds an entity to the world
void SimpleGameWorld::addEntity(shared_ptr<gamefw::Entity> entity)
{
    m_entity_list.push_back(entity);
}

// Updates all entities in the world
void SimpleGameWorld::update()
{
    foreach(shared_ptr<gamefw::Entity> entity, m_entity_list)
    {
        // Update position based on velocity and orientation
        entity->m_position.x += entity->m_velocity_local.x *
                        glm::cos(glm::radians(entity->m_orientation.x)) +
                        -entity->m_velocity_local.z *
                        glm::sin(glm::radians(entity->m_orientation.x));
        entity->m_position.z += entity->m_velocity_local.x *
                        glm::sin(glm::radians(entity->m_orientation.x)) +
                        entity->m_velocity_local.z *
                        glm::cos(glm::radians(entity->m_orientation.x));
        entity->m_position.y += entity->m_velocity_local.y;

        // Update orientation based on angular velocity
        entity->m_orientation += entity->m_angular_velocity;
    }
}

