using wcount = std::map<std::string, int>;

// Main function to count and display top 10 words
int main(void)
{
    wcount words;
    std::string word;

    // Read words from input and count occurrences
    while (std::cin >> word)
        words[word] += 1;

    // Convert map to vector of pairs
    std::vector<std::pair<std::string, int>> wordv(words.begin(), words.end());

    // Partially sort to get top 10 by value (descending)
    std::partial_sort(wordv.begin(), wordv.begin() + 10, wordv.end(),
            cmp2nd<std::string, int, std::greater<int>>()
            //std::not2(cmp2nd<std::string, int>()) 
            //[](auto &a, auto &b) { return a.second > b.second; }            
            );

    // Print top 10 words with their counts
    for (const auto p : take(wordv, 10))
        std::cout << p.second << ": " << p.first << '\n';

    return 0;
}

