    // Initialize LED and UART
    ic.led.set();
    ic.stdio.setio(&ic.Uart);
    icprintf("Hello world from printf\n");

    // Infinite loop for continuous operation
    while (1)
    {
        // Check button states - toggle behavior based on difference
        if (ic.buttons.b1.isOn() != ic.buttons.b2.isOn())
        {
            ic.led.clr();
            ic.relay.r1.set();
        }
        else
        {
            ic.led.set();
            ic.relay.r1.clr();
        }

        // Sleep for 100 milliseconds
        ic.sleep_ms(100);
    }

    return 0;
}

