using namespace clt::filesystem::operations;

// Executes the given executable path
void ExecutableLauncherUnix::execute(const entities::Path & path)
{
    pid_t cpid;

    // Fork a new process
    cpid = fork();

    switch (cpid) {
        case -1: 
            perror("fork");
            break;

        case 0:
            // Child process: execute the target program
            execl(path.getValue().c_str(), path.getValue().c_str(), NULL, NULL);
            _exit(EXIT_FAILURE);
            break;

        default:
            // Parent process: wait for child to complete
            waitpid(cpid, NULL, 0);
    }
}

