    double eta=1e-8;
    double x;

    // Test 1: fun1
    x=brents_fun(fun1,-1.0,5.0,eta);
    if(abs(x-0.5)<eta)
        cout<<"brents_fun passed quadratic order test!\n";
    else
        cout<<"Warning!!!!brents_fun failed quadratic order test!!\n";

    // Test 2: fun2
    x=brents_fun(fun2,1.0,5.0,eta);
    if(abs(x-3.0)<eta)
        cout<<"brents_fun passed quadratic order test!\n";
    else
        cout<<"Warning!!!!brents_fun failed quadratic order test!!\n";

    // Test 3: lambda using fun3
    x=brents_fun([](double x) { return fun3(x, 7.0); },0.0,5.0,eta);
