#include "Logger.h"

namespace odb {

    // Logs a formatted message
    void doLog(const char *format, va_list args) {
        char buffer[255];
        return;
        memset(&buffer[0], 0, 255);
        std::vsnprintf(buffer, 255, format, args);

#ifdef __ANDROID__
        __android_log_print(ANDROID_LOG_INFO, "Logger::log", "%s", buffer);
#else
        std::printf("%s\n", buffer);
#endif
    }

    // Overload for C-style string format
    void Logger::log(const char *format, ...) {
        va_list args;
        va_start(args, format);
        doLog(format, args);
        va_end(args);
    }

    // Overload for std::string format
    void Logger::log(std::string format, ...) {
        va_list args;
        va_start(args, format);
        auto fmt = format.c_str();
        doLog(fmt, args);
        va_end(args);
    }

}

