            "CIvs4EyDjz59q1V", "EIKi8LuYghXWHD3"};

        std::for_each(data1.begin(), data1.end(), [&out](const std::string& s) {
            WriteStr(out, s.c_str(), s.size());
        });

        out.Flush();
        ASSERT_GT(memory.Counter(), 0);

        MemoryIndexInput in{file};
        std::for_each(data1.begin(), data1.end(), [&in](const std::string& s) {
            const std::string cs = ReadString<std::string>(in);
            EXPECT_EQ(s, cs);
        });

        out.Reset();
        file.clear();

        // some memory would be left as buffers tracking vector is not deallocated
        ASSERT_LT(memory.Counter(), mem);

        // Reuse the same buffer space
        std::for_each(data1.begin(), data1.end(), [&out](const std::string& s) {
            WriteStr(out, s.c_str(), s.size());
        });

        ASSERT_EQ(memory.Counter(), mem);
    }

    // All memory should be released after scope exit
    ASSERT_EQ(memory.Counter(), 0);
}

