#include <ros/ros.h>
#include "init.h"
#include "init_serial.h"
#include "protocol_extracter/nprotocol_extracter.h"

// Main entry point for the tofsense parser node
int main(int argc, char **argv)
{
    // Initialize ROS node
    ros::init(argc, argv, "tofsense_parser");
    ros::NodeHandle nh;

    // Setup serial communication
    serial::Serial serial;
    initSerial(&serial);

    // Initialize protocol extracter and tofsense handler
    NProtocolExtracter extracter;
    tofsense::Init init(&extracter, &serial);

    // Set loop rate
    ros::Rate loop_rate(1000);

    // Main processing loop
    while (ros::ok())
    {
        // Check available bytes in serial buffer
        auto available_bytes = serial.available();
        std::string str_received;

        if (available_bytes)
        {
            // Read data from serial port
            serial.read(str_received, available_bytes);
            // Add new data to extracter
            extracter.AddNewData(str_received);
        }

        // Process ROS callbacks
        ros::spinOnce();
        // Maintain loop rate
        loop_rate.sleep();
    }

    return EXIT_SUCCESS;
}

