void AvgEncodeDecodeCore(size_t step, size_t count) {
  std::vector<uint64_t> values;
  values.reserve(count);

  for (size_t i = 1; i <= count; ++i) {
    values.push_back(i * step);
  }

  auto encoded = values;
  const auto stats =
    irs::encode::avg::encode(encoded.data(), encoded.data() + encoded.size());

  ASSERT_EQ(values[0], std::get<0>(stats));
  ASSERT_EQ(step, std::get<1>(stats));
  ASSERT_EQ(irs::irstd::AllEqual(std::begin(encoded), std::end(encoded)),
            std::get<2>(stats));
  ASSERT_TRUE(std::all_of(encoded.begin(), encoded.end(),
                          [](uint64_t v) { return 0 == v; }));

  auto success = true;
  auto begin = values.begin();
  irs::encode::avg::visit(std::get<0>(stats), std::get<1>(stats),
                          encoded.data(), encoded.data() + encoded.size(),
                          [&begin, &success](uint64_t value) {
                            success = success && (value == *begin);
                            ++begin;
                          });

  ASSERT_TRUE(success);
  ASSERT_EQ(values.end(), begin);

  auto decoded = encoded;
  irs::encode::avg::decode(std::get<0>(stats), std::get<1>(stats),
                           decoded.data(), decoded.data() + decoded.size());
  ASSERT_EQ(values, decoded);
}

void DeltaEncodeDecodeCore(size_t step, size_t count) {
  std::vector<size_t> values;
  values.reserve(count);

  for (size_t i = 1; i <= count; ++i) {
    values.push_back(i * step);
  }

  auto encoded = values;
  irs::encode::delta::Encode(encoded.begin(), encoded.end());

  ASSERT_TRUE(std::all_of(encoded.begin(), encoded.end(),
                          [step](auto v) { return step == v; }));

  auto decoded = encoded;
  irs::encode::delta::Decode(decoded.begin(), decoded.end());
  ASSERT_EQ(values, decoded);
}

void PackedReadWriteCore(const std::vector<uint32_t>& src) {
  static constexpr size_t kBlockSize = 128;
  uint32_t encoded[kBlockSize];
  const auto blocks = src.size() / kBlockSize;

  SDB_ASSERT(blocks);

  // compress data to stream
  irs::bstring buf;
  irs::BytesOutput out(buf);

  auto pack = [](const uint32_t* decoded, uint32_t* encoded,
                 const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + kBlockSize, encoded, bits);
  };

  auto unpack = [](uint32_t* decoded, const uint32_t* encoded,
                   const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + kBlockSize, encoded, bits);
  };

  // write first n compressed blocks
  {
    auto begin = src.data();
    for (size_t i = 0; i < blocks; ++i) {
      irs::bitpack::write_block32(pack, out, begin, encoded, kBlockSize);
      begin += kBlockSize;
    }
  }

  // decompress data from stream
  std::vector<uint32_t> read(src.size());
  irs::BytesViewInput in(buf);

  // read first n compressed blocks
  {
    auto begin = read.data();
    for (size_t i = 0; i < blocks; ++i) {
      irs::bitpack::read_block32(unpack, in, encoded, begin, kBlockSize);
      begin += kBlockSize;
    }
  }

  ASSERT_EQ(src, read);
}

void PackedReadWriteBlockCore(const std::vector<uint32_t>& src) {
  static constexpr size_t kBlockSize = 128;
  uint32_t encoded[kBlockSize];

  auto pack = [](const uint32_t* decoded, uint32_t* encoded,
                 const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + kBlockSize, encoded, bits);
  };

  auto unpack = [](uint32_t* decoded, const uint32_t* encoded,
                   const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + kBlockSize, encoded, bits);
  };

  // compress data to stream
  irs::bstring buf;
  irs::BytesOutput out(buf);
  irs::bitpack::write_block32(pack, out, src.data(), encoded, kBlockSize);

  // decompress data from stream
  std::vector<uint32_t> read(src.size());
  irs::BytesViewInput in(buf);
  irs::bitpack::read_block32(unpack, in, encoded, read.data(), kBlockSize);

  ASSERT_EQ(src, read);
}

using irs::DataInput;
using irs::DataOutput;

template<typename T>
void ReadWriteCore(const std::vector<T>& src,
                   const std::function<T(DataInput&)>& reader,
                   const std::function<void(DataOutput&, T)>& writer) {
  irs::bstring buf;
  irs::BytesOutput out(buf);

  std::for_each(src.begin(), src.end(),
                [&out, &writer](const T& v) { writer(out, v); });

  BytesInput in(buf);
  std::for_each(src.begin(), src.end(),
                [&in, &reader](const T& v) { ASSERT_EQ(v, reader(in)); });
}

// Since NaN != NaN according to the ieee754
template<typename T>
void ReadWriteCoreNan(const std::function<T(DataInput&)>& reader,
                      const std::function<void(DataOutput&, T)>& writer) {
  irs::bstring buf;
  irs::BytesOutput out(buf);

  writer(out, std::numeric_limits<T>::quiet_NaN());
  writer(out, std::numeric_limits<T>::signaling_NaN());

  BytesInput in(buf);
  ASSERT_TRUE(std::isnan(reader(in)));
  ASSERT_TRUE(std::isnan(reader(in)));
}

template<typename Cont>
void ReadWriteCoreContainer(
  const Cont& src, const std::function<Cont(DataInput&)>& reader,
  const std::function<DataOutput&(DataOutput&, const Cont&)>& writer) {
  irs::bstring buf;
  irs::BytesOutput out(buf);
  writer(out, src);

  BytesInput in(buf);
  const Cont read = reader(in);
  ASSERT_EQ(src, read);
}

void ReadWriteBlock(const std::vector<uint32_t>& source,
                    std::vector<uint32_t>& enc_dec_buf) {
  const auto size = source.size();

  auto pack = [&](const uint32_t* decoded, uint32_t* encoded,
                  const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + size, encoded, bits);
  };

  auto unpack = [&](uint32_t* decoded, const uint32_t* encoded,
                    const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + size, encoded, bits);
  };

  // write block
  irs::bstring buf;
  irs::BytesOutput out(buf);
  irs::bitpack::write_block32(pack, out, source.data(), enc_dec_buf.data(),
                              size);

  // read block
  BytesInput in(buf);
  std::vector<uint32_t> read(size);
  irs::bitpack::read_block32(unpack, in, enc_dec_buf.data(), read.data(), size);

  ASSERT_EQ(source, read);
}

void ReadWriteBlock(const std::vector<uint32_t>& source) {
  // intermediate buffer for encoding/decoding
  std::vector<uint32_t> enc_dec_buf(source.size());
  ReadWriteBlock(source, enc_dec_buf);
}

void ShiftPackUnpackCore32(uint32_t value, bool flag) {
  const uint32_t packed = ShiftPack32(value, flag);
  uint32_t unpacked;

  ASSERT_EQ(flag, ShiftUnpack32(packed, unpacked));
  ASSERT_EQ(value, unpacked);
}

void ShiftPackUnpackCore64(uint64_t value, bool flag) {
  const uint64_t packed = ShiftPack64(value, flag);
  uint64_t unpacked;

  ASSERT_EQ(flag, ShiftUnpack64(packed, unpacked));
  ASSERT_EQ(value, unpacked);
}

template<typename T>
void VencodeFromArray(T expected_value, size_t expected_length) {
  ASSERT_EQ(expected_length, irs::bytes_io<T>::vsize(expected_value));

  irs::byte_type buf[irs::bytes_io<T>::kMaxVSize]{};

  // write data
  {
    auto* ptr = buf;
    irs::WriteVarint<T>(expected_value, ptr);
    ASSERT_EQ(expected_length, std::distance(buf, ptr));
  }

  // read data
  {
    const auto* ptr = buf;
    ASSERT_EQ(expected_value, irs::vread<T>(ptr));
    ASSERT_EQ(expected_length,
              std::distance((const irs::byte_type*)(buf), ptr));
  }

  // skip data
  {
    const auto* ptr = buf;
    irs::vskip<T>(ptr);
    ASSERT_GE(ptr, buf);
    ASSERT_EQ(expected_length,
              std::distance((const irs::byte_type*)(buf), ptr));
  }
}

#ifdef IRESEARCH_SSE2
template<size_t N>
void ReadWriteBlockOptimized(const std::array<uint32_t, N>& source) {
  static_assert(128 == N);

  std::array<uint32_t, N> enc_dec_buf;
  std::fill_n(enc_dec_buf.data(), N, std::numeric_limits<uint32_t>::max());

  auto pack_block = [](const uint32_t* IRS_RESTRICT decoded,
                       uint32_t* IRS_RESTRICT encoded,
                       const uint32_t bits) noexcept {
    ::simdpackwithoutmask(decoded, reinterpret_cast<__m128i*>(encoded), bits);
    return bits;
  };

  auto unpack_block = [](uint32_t* decoded, const uint32_t* encoded,
                         const uint32_t bits) noexcept {
    ::simdunpack(reinterpret_cast<const __m128i*>(encoded), decoded, bits);
  };

  // write block
  irs::bstring buf;
  irs::BytesOutput out(buf);
  irs::bitpack::write_block32(pack_block, out, source.data(),
                              enc_dec_buf.data(), N);

  // read block
  BytesInput in(buf);
  std::array<uint32_t, N> read;
  irs::bitpack::read_block32(unpack_block, in, enc_dec_buf.data(), read.data(),
                             N);

  ASSERT_EQ(source, read);
}
#endif

