        // Initialize and start framework
        initialize();
        MayaFlux::Init();
        MayaFlux::Start();

        MF_PRINT(Journal::Component::USER, Journal::Context::Init, "=== AudioVisual Processing Active ===");

        // Run user code
        run();

        std::cout << "Press Enter [Return] to stop...\n";
        MayaFlux::Await();
        MayaFlux::End();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::flush;
        return 1;
    }

    return 0;
}

