    static_assert(std::size(bytes) == std::size(encoded));

    // Verify each string's SHA1 hash matches expected value
    for (size_t i = 0; i < std::size(bytes); ++i)
        TEST_EQUAL(SHA1::CalculateForString(bytes[i]), encoded[i], ());
}

