{
    QApplication a(argc, argv);

    // Load font from resources
    int fontId = QFontDatabase::addApplicationFont(":/fonts/fonts/luculent.ttf");

    if (fontId != -1) {
        // Get the exact font family name
        QString family = QFontDatabase::applicationFontFamilies(fontId).at(0);

        // Set as default font for the entire application
        QFont appFont(family, 10);
        a.setFont(appFont);

        qDebug() << "Successfully loaded font family:" << family;
    } else {
        qDebug() << "Failed to load font from resources!";
    }

    // Initialize logging system first
    auto* log = new LogWidget();
    LogWidget::bindTo(log);                 // <-- sets s_instance
    LogWidget::installQtHandler();          // optional: also capture Qt messages

    // Set up Z80 logger immediately (before any z80_printf calls)
