// Absolute value function for int64_t with 63-bit constraint
int64_t Int63Arith::i_abs(const int64_t x)
{
    // Handle negative values by masking off the sign bit
    if ((x < int64_t(0)))
    {
        return ((int64_t(0) - x) & 0x7FFFFFFFFFFFFFFFLL);
    }
    else
    {
        // Return positive value as-is
        return x;
    }
}

