}

// Pack single value for 32-bit output, when delta + shift < 32
template <uint16_t DELTA, uint16_t SHL, uint32_t MASK>
typename std::enable_if<DELTA + SHL < 32>::type pack_single_in(const uint32_t in,
                                                                 uint32_t *__restrict out) {
  if (SHL == 0) {
    *out = in & MASK;
  } else {
    *out |= (in & MASK) << SHL;
  }
}

