static int ob_mb_wc_utf8mb4(ob_wc_t *pwc, const uchar *s, const uchar *e) {
  uchar c;
  if (s >= e)
    return OB_CS_TOOSMALL;
  c = s[0];
  if (c < 0x80) {
    *pwc = c;
    return 1;
  } else if (c < 0xc2) {
    return OB_CS_ILSEQ;
  } else if (c < 0xe0) {
    if (s + 2 > e)
      return OB_CS_TOOSMALL2;
    if (!(IS_CONTINUATION_BYTE(s[1])))
      return OB_CS_ILSEQ;
    *pwc = ((ob_wc_t)(c & 0x1f) << 6) | (ob_wc_t)(s[1] ^ 0x80);
    return 2;
  } else if (c < 0xf0) {
    if (s + 3 > e)
      return OB_CS_TOOSMALL3;
    if (!(IS_CONTINUATION_BYTE(s[1]) && IS_CONTINUATION_BYTE(s[2]) &&
          (c >= 0xe1 || s[1] >= 0xa0)))
      return OB_CS_ILSEQ;
    *pwc = ((ob_wc_t)(c & 0x0f) << 12) |
           ((ob_wc_t)(s[1] ^ 0x80) << 6) |
           (ob_wc_t)(s[2] ^ 0x80);
    return 3;
  } else if (c < 0xf5) {
    if (s + 4 > e)
      return OB_CS_TOOSMALL4;
    if (!(IS_CONTINUATION_BYTE(s[1]) &&
          IS_CONTINUATION_BYTE(s[2]) &&
          IS_CONTINUATION_BYTE(s[3]) &&
          (c >= 0xf1 || s[1] >= 0x90) &&
          (c <= 0xf3 || s[1] <= 0x8F)))
      return OB_CS_ILSEQ;
    *pwc = ((ob_wc_t)(c & 0x07) << 18) |
           ((ob_wc_t)(s[1] ^ 0x80) << 12) |
           ((ob_wc_t)(s[2] ^ 0x80) << 6) |
           (ob_wc_t)(s[3] ^ 0x80);
    return 4;
  }
  return OB_CS_ILSEQ;
}

static inline int bincmp_utf8mb4(const uchar *s, const uchar *se,
                                 const uchar *t, const uchar *te) {
  int slen = (int)(se - s), tlen = (int)(te - t);
  int len = MY_MIN(slen, tlen);
  int cmp = memcmp(s, t, len);
  return cmp ? cmp : slen - tlen;
}

static inline void ob_tosort_unicode(ObUnicaseInfo *uni_plane, ob_wc_t *wc, uint flags) {
  if (*wc <= uni_plane->maxchar) {
    ObUnicaseInfoChar *page = NULL;
    if ((page = uni_plane->page[*wc >> 8]))
      *wc = (flags & OB_CS_LOWER_SORT) ?
            page[*wc & 0xFF].tolower :
            page[*wc & 0xFF].sort;
  } else {
    *wc = OB_CS_REPLACEMENT_CHARACTER;
  }
}

