    const uchar **s_, size_t slen,
    const uchar **t_, size_t tlen,
    const uchar **se_, const uchar **te_,
    ob_bool diff_if_only_endspace_difference, int *has_returned, int *res_) {
  const uchar *s = *s_;
  const uchar *t = *t_;
  const uchar *se = *se_;
  const uchar *te = *te_;
  int res = *res_;
  *has_returned = 0;
  int swap = 1;
  if (slen != tlen) {
    if (FALSE != diff_if_only_endspace_difference)
      res = 1;
    if (slen < tlen) {
      slen = tlen;
      s = t;
      se = te;
      swap = -1;
      res = -res;
    }
    for (; s < se; s++) {
      if (*s != ' ') {
        *has_returned = 1;
        break;
      }
    }
  }
  *s_ = s;
  *t_ = t;
  *se_ = se;
  *te_ = te;
  *res_ = res;
  if (*has_returned == 1) {
    return (*s < ' ') ? -swap : swap;
  }
  return 0;
}

static bool is_argument_valid(const char *str1, int64_t str_len1, const char *str2, int64_t str_len2) {
  bool is_arg_valid = true;
  if ((str_len1 < 0) ||
      (str_len2 < 0) ||
      (NULL == str1 && 0 != str_len1) ||
      (NULL == str2 && 0 != str_len2)) {
    is_arg_valid = false;
  }
  return is_arg_valid;
}

static int ob_strnncollsp_utf8mb4(const uchar *s, size_t slen,
                       const uchar *t, size_t tlen,
                       ob_bool diff_if_only_endspace_difference) {
  int res = 0;
  ob_wc_t s_wc = 0, t_wc = 0;
  const uchar *se = s + slen, *te = t + tlen;
  ObUnicaseInfo *uni_plane = &ob_unicase_default;
  s_wc = 0;
  t_wc = 0;

  while (s < se && t < te) {
    int s_res = ob_mb_wc_utf8mb4(&s_wc, s, se);
    int t_res = ob_mb_wc_utf8mb4(&t_wc, t, te);
    if (s_res <= 0 || t_res <= 0) {
      return bincmp_utf8mb4(s, se, t, te);
    }
    ob_tosort_unicode(uni_plane, &s_wc, state);
    ob_tosort_unicode(uni_plane, &t_wc, state);
    if (s_wc != t_wc) {
      return s_wc > t_wc ? 1 : -1;
    }
    s += s_res;
    t += t_res;
  }
  slen = (size_t)(se - s);
  tlen = (size_t)(te - t);
  res = 0;
  int has_returned = 0;
  int tmp = ob_strnncollsp_utf8mb4_help(
      &s, slen,
      &t, tlen,
      &se, &te,
      diff_if_only_endspace_difference, &has_returned, &res);
  return has_returned ? tmp : res;
}

int64_t jit_strcmpsp(const char *str1,
             int64_t str1_len,
             const char *str2,
             int64_t str2_len,
             bool cmp_endspace) {
  int64_t result = 0;
  if (is_argument_valid(str1, str1_len, str2, str2_len)) {
    result = (int64_t)ob_strnncollsp_utf8mb4(reinterpret_cast<const uchar *>(str1),
                                str1_len,
                                reinterpret_cast<const uchar *>(str2),
                                str2_len,
                                cmp_endspace);
  }
  return result;
}

