                {"__res", PyInit___res},
                {"sitecustomize", PyInit_sitecustomize},
                {nullptr, nullptr}
            };
            // Extend Python's internal init table with our modules
            PyImport_ExtendInittab(mods);
        }
    } REG;  // Global instance that triggers registration on startup
}

