static u64 dec_Fill(DecMode mode, DecParam d, DecParam s, shilop op, u32 extra = 0)
{
	return (((u64)extra)<<32)|(mode<<24)|(d<<16)|(s<<8)|op;
}
static u64 dec_Un_rNrN(shilop op)
{
	return dec_Fill(DM_UnaryOp, PRM_RN, PRM_RN, op);
