class Solution {
public:
    // Calculates minimum operations
    int minimumOperations(vector<int>& nums)
    {
        unordered_set<int> set;
        for(auto v: nums)
            if(v!=0)
                set.insert(v);
        // Return the count of unique non-zero elements
        return set.size();
    }
};

