// Helper function to parse a single hex character into integer value
static int parse_hex_char(int c) {
    if (c >= '0' && c <= '9') {
        return c - 0x30;
    }
    if (c >= 'a' && c <= 'f') {
        return c - 0x57;
    }
    if (c >= 'A' && c <= 'F') {
        return c - 0x37;
    }
    return -1;
}
// NOLINTEND(cppcoreguidelines-avoid-magic-numbers,readability-magic-numbers)

// Helper function to decode a hex string into binary data
static std::vector<uint8_t> decode_from_hex(std::string_view hex) {
    if (hex.size() & 1) {
        return {};
    }
    std::vector<uint8_t> result;
    result.reserve(hex.size() >> 1);
    for (size_t i = 0; i < hex.size(); i += 2) {
        int hi = parse_hex_char(hex[i]);
        int lo = parse_hex_char(hex[i + 1]);
        if (hi < 0 || lo < 0) {
            return {};
        }
        result.push_back((uint8_t) (hi << 4 | lo));
    }
    return result;
}

