// Converts SQL record to QVariantHash for JSON serialization
QVariantHash PerformerJsonJoiner(const QSqlRecord& record) {
  using namespace PERFORMER_DB_HEADER_KEY;
  return PerformerJsonJoiner(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    record.field(enu).value().sqlRecordToValueFunc(),
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
    nullptr);
}

// Overloaded PerformerJsonJoiner with field unpacking via macro
QVariantHash PerformerJsonJoiner(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    decltype(defaultValue) _##enu,
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
    void* P_DONT_USE_ME) {
  /* Ori can be:
     Science Fiction/Sci-Fi
     Adventure Movie
     Drama/Feature Movie
     Documentary
     Superhero Movie
     Horror Movie
     Action Movie
     Comedy
     Thriller
     Fantasy
  */
  using namespace PERFORMER_DB_HEADER_KEY;
  return {
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    {ENUM_2_STR(enu), _##enu}, //
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
  };
}

// Serializes cast values into PSON byte array
QByteArray CastValues2PsonStr(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    decltype(defaultValue) _##enu,
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
    void* P_DONT_USE_ME) {
  QVariantHash varHash{PerformerJsonJoiner(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    _##enu, //
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
    nullptr)};
  return JsonHelper::SerializedJsonDict2ByteArray(varHash);
}

