                                      PROJ_VERSION_MINOR, PROJ_VERSION_PATCH));
    EXPECT_FALSE(PROJ_AT_LEAST_VERSION(PROJ_VERSION_MAJOR, PROJ_VERSION_MINOR,
                                       PROJ_VERSION_PATCH + 1));
}
