// Securely zeros memory
void SecureZero(void* pointer, size_t count) noexcept
{
#ifdef _MSC_VER
    // Use Windows-specific secure zero function
    SecureZeroMemory(pointer, count);
#elif defined(memset_s)
    // Use C11 secure memset if available
    memset_s(pointer, count, 0, count);
#else
    // Fallback implementation using volatile pointer
    volatile char* vPointer = (volatile char*)pointer;
    while (count)
    {
        *vPointer = 0;
        vPointer++;
        count--;
    }
#endif
}

