// Function to swap values using XOR
int doSomething(int argc, char *argv[])
{
    int x = 42;
    // Swap x and argc using XOR operations
    x ^= argc;
    argc ^= x;
    x ^= argc;
    // Print the swapped values
    printf("Leak supersecret value: %d\n", x);
    printf("Answer to everything: %d\n", argc);
    return 0;
}

// Main function that delegates to doSomething
int main(int argc, char *argv[])
{
    return doSomething(argc, argv);
}

