Colist::nats(std::shared_ptr<Nat> n)
{
    return colist<std::shared_ptr<Nat>>::ctor::lazy_(
        [=](void) -> std::shared_ptr<Colist::colist<std::shared_ptr<Nat>>> {
            return colist<std::shared_ptr<Nat>>::ctor::cocons_(
                n, nats(Nat::ctor::S_(n)));
        });
