#include <vector>
#include <algorithm>

// Solution class to find maximum average of subarray of length k
class Solution {
public:
    double findMaxAverage(std::vector<int>& nums, int k) {
        int n = nums.size();
        double sum = 0;

        // Calculate sum of first k elements
        for(int i = 0; i < k; i++) {
            sum += nums[i];
        }

        double maxSum = sum;

        // Use sliding window technique to find maximum sum
        for(int i = k; i < n; i++) {
            sum = sum - nums[i - k] + nums[i];
            maxSum = std::max(sum, maxSum);
        }

        // Return average
        return maxSum / k;
    }
};

