#include <cstdint>
#include <cstdio>

#include "ckernel.h"
#include "llk_defs.h"

// Global variables
std::uint32_t unp_cfg_context          = 0;
std::uint32_t pack_sync_tile_dst_ptr   = 0;
std::uint32_t math_sync_tile_dst_index = 0;

#ifdef LLK_TRISC_UNPACK
    #include "llk_unpack_A.h"
    #include "llk_unpack_common.h"
    #include "params.h"

    // Run kernel for UNPACK section
    void run_kernel(const volatile struct RuntimeParams* params)
    {
        #ifdef RUNTIME_FORMATS
            const volatile FormatConfig& formats = params->formats;
        #endif

        // Configure unpack hardware
        _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
            formats.unpack_A_src,
            formats.unpack_B_src,
            formats.unpack_A_dst,
            formats.unpack_B_dst,
            FACE_R_DIM,
            FACE_R_DIM,
            4 /* num_faces */,
            4 /* num_faces */
        );

        // Initialize unpack A operation
        _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            0,
            0,
            FACE_R_DIM,
            4,
            formats.unpack_A_src,
            formats.unpack_A_dst
        );

        // Process each tile
        for (int i = 0; i < params->TILE_CNT; i++)
        {
            _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
                L1_ADDRESS(params->buffer_A[i]),
                formats.unpack_A_src,
                formats.unpack_A_dst
            );
        }
    }
#endif

#ifdef LLK_TRISC_MATH
    #include "ckernel_defs.h"
    #include "ckernel_sfpu.h"
    #include "llk_math_common.h"
    #include "llk_math_eltwise_binary_sfpu.h"
    #include "llk_math_eltwise_unary_datacopy.h"
    #include "params.h"
    #include "sfpu_operations.h"

    using namespace ckernel::sfpu;

    // Run kernel for MATH section
    void run_kernel(const volatile struct RuntimeParams* params)
    {
        const bool is_int_fpu_en = false;

        // Initialize pack sync and math hardware
        _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
        _llk_math_hw_configure_<is_fp32_dest_acc_en>(formats.math, formats.math);

        #ifdef ARCH_BLACKHOLE
            _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, is_int_fpu_en>(4, formats.math);
        #else
            _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, is_int_fpu_en>(4, formats.math);
        #endif

        // Wait for destination buffer availability
        _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

        // Process each tile
        for (int i = 0; i < params->TILE_CNT; i++)
        {
            LLK_ASSERT(
                (i < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()),
                "Block tile index exceeds maximum destination tiles"
            );

            _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
                i,
                formats.math,
                formats.math
            );
        }

        // Initialize SFPU binary operation: add1
        _llk_math_eltwise_binary_sfpu_init_<SfpuType::add1>();

        // Start SFPU binary computation
        // Argument: dest index of first operand
        _llk_math_eltwise_binary_sfpu_start_<DstSync::SyncHalf>(0);

        // Compute SFPU binary operation
        test_utils::call_binary_sfpu_operation<APPROX_MODE, SFPU_BINARY_OPERATION, 32, formats.math>(0, 1, 0);

        // Finalize SFPU binary operation
        _llk_math_eltwise_binary_sfpu_done_();

        // Mark destination section as done
        _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    }
#endif

#ifdef LLK_TRISC_PACK
    #include "llk_pack.h"
    #include "llk_pack_common.h"
    #include "params.h"

    // Run kernel for PACK section
    void run_kernel(const volatile struct RuntimeParams* params)
    {
        #ifdef ARCH_BLACKHOLE
            _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(formats.pack_src, formats.pack_dst, 16 * 16);
        #else
            _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(formats.pack_src, formats.pack_dst, 16 * 16);
        #endif

        // Initialize packer
        _llk_pack_init_<false, false>(formats.pack_dst);

        #ifdef ARCH_BLACKHOLE
            _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
        #else
            _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
        #endif

        // Wait for math operations to complete
        _llk_packer_wait_for_math_done_();

        // Pack each tile
        for (int i = 0; i < params->TILE_CNT; i++)
        {
            LLK_ASSERT(
                (i < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()),
                "Block tile index exceeds maximum destination tiles"
            );

            _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
                i,
                L1_ADDRESS(params->buffer_Res[i])
            );
        }

        // Mark pack destination section as done
        _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    }
#endif

