// Signal constructor
Signal::Signal(SignalKind kind)
    : m_kind(kind),
      m_notified() {}

// Poll method implementation
bool Signal::poll(Context& cx) {
    if (!m_notified) {
        m_notified.emplace(cx.runtime()->signalDriver().addSignal(m_kind).notified());
    }
    return m_notified->poll(cx);
}

