#include <ros/ros.h>
#include "init.h"
#include "init_serial.h"
#include "nlink_unpack/nlink_tofsensem_frame0.h"
#include "nlink_unpack/nlink_utils.h"
#include "protocol_extracter/nprotocol_extracter.h"
#include <chrono>
#include <thread>

// Main function for tofsensem parser node
int main(int argc, char **argv)
{
    ros::init(argc, argv, "tofsensem_parser");
    ros::NodeHandle nh;
    serial::Serial serial;

    // Initialize serial communication
    initSerial(&serial);

    NProtocolExtracter extracter;
    tofsensem::Init init(&extracter);

    ros::Rate loop_rate(1000);

    // Main processing loop
    while (ros::ok())
    {
        auto available_bytes = serial.available();
        std::string str_received;

        if (available_bytes)
        {
            serial.read(str_received, available_bytes);
            extracter.AddNewData(str_received);
        }
        else
        {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }

        ros::spinOnce();
        loop_rate.sleep();
    }

    return EXIT_SUCCESS;
}

