class Level;
class Random;

// Constructor for MineShaftStart
MineShaftStart::MineShaftStart(
    Level*  level,
    Random* random,
    int     chunkX,
    int     chunkZ
)
{
    // Create a new MineShaftRoom
    MineShaftPieces::MineShaftRoom* mineShaftRoom =
        new MineShaftPieces::MineShaftRoom(
            0,
            random,
            (chunkX << 4) + 2,
            (chunkZ << 4) + 2
        );

    // Add the room to the pieces list
    pieces.push_back(mineShaftRoom);

    // Add children to the room
    mineShaftRoom->addChildren(mineShaftRoom, &pieces, random);

    // Calculate bounding box and adjust below sea level
    calculateBoundingBox();
    moveBelowSeaLevel(level, random, 10);
}

