    UNIT_TEST(TestSwap16)
    UNIT_TEST(TestSwap32)
    UNIT_TEST(TestSwap64)
    UNIT_TEST_SUITE_END();

private:
    // Test 16-bit byte swap
    inline void TestSwap16() {
        UNIT_ASSERT_EQUAL((ui16)0x1234, SwapBytes((ui16)0x3412));
