////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_invalidAttributeAfterExpand) {
    std::string input = "foo[*]bar";
    std::vector<AttributeName> result;
    try {
        ParseAttributeString(input, result, false);
        EXPECT_TRUE(false);
    } catch (Exception& e) {
        EXPECT_EQ(e.code(), sdb::ERROR_BAD_PARAMETER);
