// Runs static constructors in the correct order
void MinecraftWorld_RunStaticCtors()
{
    // The ordering of these static ctors can be important. If they are within statement blocks then
    // DO NOT CHANGE the ordering - 4J Stu
    Packet::staticCtor();
    {
        MaterialColor::staticCtor();
        Material::staticCtor();
        Tile::staticCtor();
        HatchetItem::staticCtor();
        PickaxeItem::staticCtor();
        ShovelItem::staticCtor();
        BlockReplacements::staticCtor();
        Biome::staticCtor();
        MobEffect::staticCtor();
        Item::staticCtor();
        FurnaceRecipes::staticCtor();
        Recipes::staticCtor();    

#ifdef _DURANGO
        GenericStats::setInstance(new DurangoStats());
#else
        GenericStats::setInstance(new CommonStats());
        Stats::staticCtor();
#endif

        //Achievements::staticCtor(); // 4J Stu - This is now called from within the Stats::staticCtor()
        TileEntity::staticCtor();
        EntityIO::staticCtor();
        MobCategory::staticCtor();
        Item::staticInit();
        LevelChunk::staticCtor();
        LevelType::staticCtor();
        {
            StructureFeatureIO::staticCtor();
            MineShaftPieces::staticCtor();
            StrongholdFeature::staticCtor();
            VillagePieces::Smithy::staticCtor();
            VillageFeature::staticCtor();
            RandomScatteredLargeFeature::staticCtor();
        }
    }

    EnderMan::staticCtor();
    PotionBrewing::staticCtor();
    Enchantment::staticCtor();
    SharedConstants::staticCtor();
    ServerLevel::staticCtor();
    SparseLightStorage::staticCtor();
    CompressedTileStorage::staticCtor();
    SparseDataStorage::staticCtor();
    McRegionChunkStorage::staticCtor();
    Villager::staticCtor();
    GameType::staticCtor();
    BeaconTileEntity::staticCtor();
}

#include "autolink/time/duration.hpp"
#include "autolink/time/time.hpp"
#include "gtest/gtest.h"

namespace autolink {

// Test constructor functionality
TEST(DurationTest, constructor) {
    Duration duration(100);
    EXPECT_EQ(100, duration.ToNanosecond());

    duration = Duration(1.1);
    EXPECT_EQ(1100000000UL, duration.ToNanosecond());
    EXPECT_DOUBLE_EQ(1.1, duration.ToSecond());

    duration = Duration(1, 1);
    EXPECT_EQ(1000000001UL, duration.ToNanosecond());
    EXPECT_DOUBLE_EQ(1.000000001, duration.ToSecond());

    Duration d2(duration);
    EXPECT_EQ(duration, d2);
}

// Test operator overloads
TEST(DurationTest, operators) {
    Duration d1(100);
    Duration d2(200);
    Duration d3(300);

    EXPECT_NE(d1, d3);
    EXPECT_LT(d1, d3);
    EXPECT_LE(d1, d3);
    EXPECT_GT(d3, d1);
    EXPECT_GE(d3, d1);

    EXPECT_EQ(d1 + d2, d3);
    EXPECT_EQ(d2, d1 * 2);
    EXPECT_EQ(d3 - d2, d1);

    EXPECT_EQ(d1 += d2, d3);
    EXPECT_GE(d1, d3);
    EXPECT_LE(d1, d3);

    EXPECT_EQ(Duration(100), d1 -= d2);
    EXPECT_EQ(d2, d1 *= 2);
}

// Test IsZero functionality
TEST(DurationTest, is_zero) {
    Duration duration;
    EXPECT_TRUE(duration.IsZero());
}

}  // namespace autolink

