// Convert string from ISO 8859-1 to IBM 1047 EBCDIC
std::error_code
ConverterEBCDIC::convertToEBCDIC(StringRef Source,
                                 SmallVectorImpl<char> &Result) {
  assert(Result.empty() && "Result must be empty!");
  const unsigned char *Table = ISO88591ToIBM1047;
  const unsigned char *Ptr =
      reinterpret_cast<const unsigned char *>(Source.data());
  size_t Length = Source.size();
  Result.reserve(Length);

  while (Length--) {
    unsigned char Ch = *Ptr++;

    // Handle UTF-8 2-byte sequences in input
    if (Ch >= 128) {
      // Only two-byte sequences can be decoded
      if (Ch != 0xc2 && Ch != 0xc3)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      // Check for truncated sequence
      if (!Length)
        return std::make_error_code(std::errc::invalid_argument);

      unsigned char Ch2 = *Ptr++;
      // Validate continuation byte
      if ((Ch2 & 0xc0) != 0x80)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      Ch = Ch2 | (Ch << 6);
      Length--;
    }

    // Translate character using lookup table
    Ch = Table[Ch];
    Result.push_back(static_cast<char>(Ch));
  }

  return std::error_code();
}

// Convert string from IBM 1047 EBCDIC to UTF-8
void ConverterEBCDIC::convertToUTF8(StringRef Source,
                                    SmallVectorImpl<char> &Result) {
  assert(Result.empty() && "Result must be empty!");
  const unsigned char *Table = IBM1047ToISO88591;
  const unsigned char *Ptr =
      reinterpret_cast<const unsigned char *>(Source.data());
  size_t Length = Source.size();
  Result.reserve(Length);

  while (Length--) {
    unsigned char Ch = *Ptr++;

    // Translate character using lookup table
    Ch = Table[Ch];

    // Handle UTF-8 2-byte sequences in output
    if (Ch >= 128) {
      // First byte: prefix with 0xc0 and upper 6 bits
      Result.push_back(static_cast<char>(0xc0 | (Ch >> 6)));
      // Second byte: lower 6 bits with continuation marker
      Ch = Ch & 0xbf;
    }

    Result.push_back(static_cast<char>(Ch));
  }
}

