// Main function entry point
int main()
{
    std::cout << "=== variadic_args serialization/storage ==="
              << std::endl;

    sol::state lua;
    lua.open_libraries(sol::lib::base);

    // Storage for the function to be called later
    std::function<void()> function_storage;

    // Lambda to store a Lua function and its arguments
    auto store_routine = [&function_storage](sol::function f,
                          sol::variadic_args va) {
        // Convert variadic args to vector of sol::object
        function_storage =
             [f,
                  args = std::vector<sol::object>(va.begin(),
                       va.end())]() { f(sol::as_args(args)); };
    };

    // Expose store_routine to Lua
    lua.set_function("store_routine", store_routine);

    // First test case: store and call function 'a'
    lua.script(R"(
function a(name)
	print(name)
end
store_routine(a, "some name")
)");
    function_storage();

    // Second test case: store and call function 'b'
    lua.script(R"(
function b(number, text)
	print(number, "of", text)
end
store_routine(b, 20, "these apples")
)");
    function_storage();

    std::cout << std::endl;

    return 0;
}

