struct trace_sched_switch_args {
    u64 ignore;
    u8 prev_comm[16];
    u32 prev_pid;
    u32 prev_prio;
    u64 prev_state;
    u8 next_comm[16];
    u32 next_pid;
    u32 next_prio;
};

SEC("tracepoint/sched/sched_switch")
int trace_sched_switch(struct trace_sched_switch_args* ctx)
{
    // Get current thread ID
    u64 tgid = bpf_get_current_pid_tgid();

    // Print trace information
    BPF_PRINTK("Handling sched_switch %u -> %u (current thread: %u)\n", 
               ctx->prev_pid, 
               ctx->next_pid, 
               (u32)tgid);

    return 0;
}

