#include <stdio.h>

// Main function to handle matrix operations
int main()
{
    int a[10][10], i, j, r, c, s = 0;

    // Input matrix dimensions
    printf("enter total row and columns ");
    scanf("%d %d", &r, &c);

    // Input matrix elements
    for(i = 0; i < r; i++)
    {
        for(j = 0; j < c; j++)
        {
            printf(" enter [%d] [%d] element ", i, j);
            scanf("%d", &a[i][j]);
        }
    }

    // Print original matrix and calculate sum
    for(i = 0; i < r; i++)
    {
        for(j = 0; j < c; j++)
        {
            printf("%d", a[i][j]);
            s = s + a[i][j];
        }
        printf("\n");
    }

    // Print transpose of matrix and add elements again to sum
    printf(" transport of matrix\n");
    for(j = 0; j < c; j++)
    {
        for(i = 0; i < r; i++)
        {
            printf("%d", a[i][j]);
            s = s + a[i][j];
        }
        printf("\n");
    }

    // Output final sum
    printf("sum => %d \n", s);
    return 0;
}

