    int empno;
    float empname;
public:
    void input();
    void output();

    // Nested salary class
    class sal {
    private:
        int net, toatl;
        float bsal, hsal, fosl, pf;
    public:
        void input();
        void output();
        void cal();
    };
};

// Input method for emp class
void emp::input() {
    cout << "enter any num and empname";
    cin >> empname >> empno;
}

