    cout << "name of emp and empno";
    cin >> empno >> empname;
}

// Calculation method for sal class
void emp::sal::cal() {
    bsal = 10 * net;
    hsal = 10 * net;
    fosl = 10 * net;
    pf = 10 * net;
    toatl = bsal + hsal + fosl - pf;
}

// Output method for sal class
void emp::sal::output() {
    cout << "toatal sal of emp" << toatl;
}

