template <typename T>
bool contains_element(const std::vector<T>& collection,
                      boost::function<bool(const T&)> checkPredicate)
{
    return std::find_if(collection.begin(), collection.end(),
                        boost::bind(checkPredicate, _1)) != collection.end();
}

bool is_odd(const int& value)
{
    return value % 2 != 0;
}

void validate_contains_element()
{
    std::vector<int> values;
    values.push_back(3);
    assert(!contains_element<int>(values, is_odd));
    values.push_back(4);
    assert(contains_element<int>(values, is_odd));
    std::cout << "validate_contains_element: OK" << std::endl;
}

