// Safely add two integers with overflow checking
int safe_add(int first, int second)
{
    if (((second > 0) && (first > (numeric_limits<int>::max() - second))) ||
        ((second < 0) && (first < (numeric_limits<int>::min() - second))))
            error("safe_add(): integer addition overflows.");
    else
        return first + second;
}

// Generate Fibonacci-like sequence: store n terms in v starting with first and second
// Precondition: v must be empty and n >= 2
void generate_sequence(int first, int second, vector<int>& sequence, int count)
{
    if (sequence.size() != 0)
        error("generate_sequence(): Non-empty vector provided.");
    if (count < 2)
        error("generate_sequence(): count must be at least 2.");

    sequence.push_back(first);
    sequence.push_back(second);

    for (int index = 2; index < count; ++index)
        sequence.push_back(safe_add(sequence[index-2], sequence[index-1]));
}

