BadgeRegion::BadgeRegion(std::string badge_identifier, BadgeService* manager)
    : badge_manager_(manager)
    , badge_identifier_(badge_identifier)
{
    SetCollidable(true);
    SetDatabasePersisted(false);
    SetInSnapshot(true);
}

BadgeRegion::~BadgeRegion(void)
{
}

void BadgeRegion::OnCollisionEnter(std::shared_ptr<Object> entrant)
{
    if(entrant->HasController())
    {
        badge_manager_->GrantBadge(entrant, badge_identifier_);
    } else {
        entrant->ViewObjects(nullptr, 0, true, [this] (const std::shared_ptr<Object>& inner_object)
        {
            if(inner_object->HasController())
            {
                badge_manager_->GrantBadge(inner_object, badge_identifier_);
            }
        });
    }
}

