// Validate DNS-SD error codes and generate descriptive messages
inline void validate_dnsservice_result(DNSServiceErrorType& result, const std::string& operation) {
    std::string message(operation);
    message += ": ";
    switch (result) {
        case kDNSServiceErr_NoError:
            return;
        case kDNSServiceErr_NameConflict:
            message += "Name already in use, please select a different one";
            break;
        case kDNSServiceErr_Invalid:
            message += "Invalid index or invalid character provided";
            break;
        case kDNSServiceErr_BadReference:
            message += "Invalid service reference";
            break;
        case kDNSServiceErr_BadParam:
            message += "Incorrect parameter value supplied to function.";
            break;
        default:
            message += "Unrecognized error code... ";
            message += std::to_string(result);
    }
    throw std::runtime_error(message.c_str());
}

