// Exception handler demonstration 
extern void Y(void);
struct Alpha   {};
struct Beta    {};
struct Gamma   {};
struct Delta   {};
struct Epsilon {};
struct Zeta    {};

static void P(void) throw ()
{
  Y();
}

static void Q(void) throw (Beta)
{
  try { P(); } catch (Alpha) {}
}

