namespace EPITOME
{
	template <typename T>
	Room<T>::Room() {}
	template <typename T>
	Room<T>::~Room()
	{
		Clear();
	}
	template <typename T>
	Room<T>::Room(Room&& other)
	{
		contents = other.contents;
		other.contents.clear();
	}
	template<typename T>
	void Room<T>::Insert(T* element)
	{
		contents.push_back(element);
	}
	template <typename T>
	void Room<T>::Clear()
	{
		for (T* x : contents)
		{
			x->Release();
			delete x;
		}
		contents.clear();
	}
	template <typename T>
	Disposable<T>::Disposable(T value)
	{
		this->value = value;
	}
	template <typename T>
	void Disposable<T>::Release() {}
}

