// Constructor with explicit buffer handles and bounding data
VertexBuffer::VertexBuffer(GLuint bufferV, GLuint bufferI, GLuint bufferN, unsigned int count, std::tuple<glm::vec3, glm::vec3> range)
: vBO(bufferV), iBO(bufferI), nBO(bufferN), numIndices(count), extremes(range), bounds{new collisiondetection::AxisAlignedBoundingBox(range)} {
