#include <tiramisu/tiramisu.h>
using namespace tiramisu;

void compute_sum(std::string func_name, int dim, int input_a, int input_b)
{
    tiramisu::init(func_name);
    tiramisu::function *main_func = global::get_implicit_function();
    tiramisu::constant D("D", tiramisu::expr((int32_t) dim), p_int32, true, NULL, 0, main_func);

    // Define loop variables with bounds [0,10)
    tiramisu::var x("x", 0, 10), y("y", 0, 10);
    tiramisu::var x0("x0"), y0("y0"), x1("x1"), y1("y1");

    // Create computation that adds the two input values
    tiramisu::computation comp(tiramisu::expr((uint8_t) (input_a + input_b)), x, y);

    // comp.tile(x, y, 2, 2, x0, y0, x1, y1);  // Tiling disabled for now

    // Mark outer loop as parallel
    comp.tag_parallel_level(x);

    // Define output buffer
    tiramisu::buffer result_buf("result_buf", {dim, dim}, tiramisu::p_uint8, a_output, main_func);

    // Store computation result in buffer
    comp.store_in(&result_buf, {x, y});

    // Generate code
    main_func->codegen({&result_buf}, "build/generated_fct_test_114.o");
}

int main(int argc, char **argv)
{
