// Class to perform Caesar cipher decoding
class CCipher {
public:
  // Decodes the given cipher text by shifting letters backward
  std::string decode(std::string encrypted, int offset) {
    std::string result;
    for (char ch : encrypted) {
      result += 'A' + (ch - 'A' - offset + 26) % 26;
    }
    return result;
  }
};

int main() {
  CCipher cipher;
  // Test case: shift of 10 should map A-Z to QRSTUVWXYZABCDEFGHIJKLMNOP
  assert(cipher.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 10) == "QRSTUVWXYZABCDEFGHIJKLMNOP");
  return 0;
}

