    SECTION("excluding specific token types") {
        const auto [result_tokens, remaining_position] = lexer::tokenize(
            {
                {std::regex{"[[:alpha:]]+"}, "alpha"},
                {std::regex{"[[:digit:]]+"}, "digit"},
                {std::regex{"[[:space:]]+"}, "space"}
            },
            {},
