// Thread function to handle client connections
void thread_loop(UserHandler * clientHandler) {
    // Wait until handler is ready
    while (!clientHandler->isReady()) {
        usleep(50000);
    }

    try {
        clientHandler->loop();
    }
    catch (...) {
        try {
            JsonDict response;
            response.add("Error", new JsonString("Internal server error"));
            response.add("code", new JsonInt(500));
            clientHandler->writeToClient("error", &response);
