/**
 * Definition for a binary tree node.
 */
struct TreeNode {
    int value;
    TreeNode *leftChild;
    TreeNode *rightChild;
    TreeNode(int x) : value(x), leftChild(NULL), rightChild(NULL) {}
};

class Validator {
public:
    bool checkBST(TreeNode* node, int lowerBound, int upperBound)
    {
        if (node == NULL) {
            return true;
        }
	return (node->value > lowerBound &&
		node->value < upperBound &&
		checkBST(node->leftChild, lowerBound, node->value) &&
		checkBST(node->rightChild, node->value, upperBound));
    }
    bool validateBinarySearchTree(TreeNode* root) {

        return checkBST(root, INT_MIN, INT_MAX);
    }
};

