#include <opencv2/imgproc.hpp>
#include <opencv2/highgui.hpp>
#include <cstdio>
#include <stdexcept>

using namespace cv;

#if defined(_MSC_VER) || defined(WIN32) || defined(_WIN32) || defined(__WIN32__) \
    || defined(WIN64) || defined(_WIN64) || defined(__WIN64__)
# include <io.h>
# include <fcntl.h>
# define SET_BINARY_MODE(handle) _setmode(handle, _O_BINARY)
#else
# define SET_BINARY_MODE(handle) ((void)0)
#endif

#define BUFFER_SIZE 8192

int main(int argc, char** argv) {
    SET_BINARY_MODE(fileno(stdin));

    std::vector<uchar> buffer;
    bool ignoreData = true;
    bool frameComplete = false;
    bool markerFound = false;
    int bytesRead = -1;

    while (true) {
        uchar tempBuffer[BUFFER_SIZE];
        uchar currentByte;

        if (bytesRead != 0) {
            bytesRead = read(fileno(stdin), tempBuffer, BUFFER_SIZE);

            for (int idx = 0; idx < bytesRead; ++idx) {
                currentByte = tempBuffer[idx];

                // Detect start of JPEG (0xFFD8)
                if (markerFound && currentByte == 0xD8) {
                    ignoreData = false;
                    buffer.push_back(0xFF);
                }

                // Detect end of JPEG (0xFFD9)
                if (markerFound && currentByte == 0xD9) {
                    frameComplete = true;
                    buffer.push_back(0xD9);
                    ignoreData = true;
                }

                markerFound = (currentByte == 0xFF);

                if (!ignoreData) {
                    buffer.push_back(currentByte);
                }

                // Process complete frame
                if (frameComplete) {
                    if (!buffer.empty()) {
                        Mat bufferMat(buffer);
                        Mat decodedFrame = imdecode(bufferMat, IMREAD_COLOR);
                        imshow("Video Stream", decodedFrame);
                        waitKey(1);
                    } else {
                        fprintf(stderr, "Warning: empty frame data\n");
                    }

                    // Reset state for next frame
                    frameComplete = false;
                    ignoreData = true;
                    buffer.clear();
                }
            }
        } else {
            throw std::runtime_error("No bytes read from input stream");
        }
    }

    return 0;
}

