#include "ihex.h"
#include <stdlib.h>
#include <fstream>

int main(int argc, char* argv[]) {
    if (argc != 4) {
        std::cerr << argv[0] << " input.hex keyfile output.hex\n"
                  << "Encrypts or decrypts the data in an Intel Hex file.\n"
                  << "Addresses are unchanged, but checksum is updated.\n\n"
                  << "The [keyfile] is a raw binary file with the key data. The whole file is\n"
                  << "used as key data, and can be of arbitrary size.\n";
        exit(-1);
    }

    IntelHex hexFile;
    hexFile.Read(argv[1]);

    std::ifstream keyStream;
    keyStream.open(argv[2], std::ios::in | std::ios::binary | std::ios::ate);

    if (!keyStream.is_open()) {
        std::cerr << "Error reading keyfile.\n";
        exit(-2);
    }

    keyStream.seekg(0, std::ios::end);
    int keyLength = keyStream.tellg();
    keyStream.seekg(0, std::ios::beg);

    uint8_t* keyBuffer = new uint8_t[keyLength];
    keyStream.read(reinterpret_cast<char*>(keyBuffer), keyLength);
    keyStream.close();

    hexFile.Cipher(keyBuffer, keyLength);
    delete[] keyBuffer;

    hexFile.Write(argv[3]);
    return 0;
}

