// for best accuracy, getTime is implemented platform dependent.
// to avoid a global include of windows.h, this is a separate file.
#if defined(_WIN32)
#include <windows.h>
// returns a point in time in milliseconds (can only be used for time differences, not an absolute time)
double getCurrentTime() noexcept
{
    LARGE_INTEGER counter;
    QueryPerformanceCounter(&counter);
    LARGE_INTEGER frequency;
    QueryPerformanceFrequency(&frequency);
    return (static_cast<double>(counter.LowPart) * 1000.0) / static_cast<double>(frequency.LowPart);
}
#else
#include <sys/time.h>
double getCurrentTime() noexcept
{
    timeval timestamp;
    gettimeofday(&timestamp, nullptr);
    return (timestamp.tv_sec * 1000000.0 + timestamp.tv_usec) / 1000.0;
}
#endif

