#include <stdexcept>
#include <type_traits>
#include "fsm.h"

class finite_state_machine : public fsmlite::fsm<finite_state_machine> {
    friend class fsm;  // base class needs access to transition_table
public:
    enum states { Start, Terminate };
private:
    void handle_event(const int& data) {
        std::cout << "Handling event: " << data << "\n";
#ifdef NDEBUG
        if (data != 0) {
            throw std::logic_error("recursive invocation detected");
        }
#endif
        process_event(data + 1);
    }
private:
    typedef finite_state_machine self;
    using transition_table = table<
//              Start Event  Target Action
//  -----------+-----+------+------+-----------+-
    mem_fn_row< Start, int,   Terminate,  &self::handle_event >
//  -----------+-----+------+------+-----------+-
    >;
};

int main()
{
    finite_state_machine machine;
    try {
        machine.process_event(0);
    } catch (std::logic_error& e) {
        std::cerr << e.what() << "\n";
        return 0;
    }
    return 1;  /* LCOV_EXCL_LINE */
}

