#include "unittest/gtest.hpp"
#include "arch/streamed_tcp.hpp"

namespace unittest {
namespace {

/* `execute_in_thread_pool()` initiates a RethinkDB IO layer thread pool and executes
the provided callback within a coroutine running in that pool. */
struct executor_t : public thread_message_t {
    thread_pool_t *pool;
    boost::function<void()> callback;
    executor_t(thread_pool_t *pool, boost::function<void()> callback) : pool(pool), callback(callback) { }
    void execute() {
        callback();
        pool->stop();
    }
    void on_thread_change() {
        coro_t::spawn_now(boost::bind(&executor_t::execute, this));
    }
};
void execute_in_thread_pool(boost::function<void()> callback) {
    thread_pool_t pool(1);
    executor_t executor(&pool, callback);
    pool.start(&executor);
}
void process_echo_connection(boost::scoped_ptr<streamed_tcp_conn_t> &connection) {
    while (connection->get_input_stream().is_valid()) {
        // Read incoming data and echo it back
        std::string data;
        connection->get_input_stream() >> data;
        if (!connection->get_input_stream().bad()) {
            connection->get_output_stream() << data << std::endl; // flushes immediately
        }
    }
}

}   /* anonymous namespace */

void perform_tcp_stream_validation() {
    int server_port = 15000 + rand() % 30000;
    streamed_tcp_listener_t server(server_port, boost::bind(&process_echo_connection, _1));
    streamed_tcp_conn_t client("localhost", server_port);

    std::string message = "INIT";
    for (int iteration = 0; iteration < 4096 / 16; ++iteration, 
         message += std::string(16, static_cast<char>('A' + (iteration % 26)))) {

        client.get_output_stream() << message.substr(0, iteration);
        client.get_output_stream() << message.substr(iteration) << std::endl; // triggers flush

        std::string response;
        client.get_input_stream() >> response;

        EXPECT_TRUE(!client.get_input_stream().failed());
        EXPECT_EQ(response, message);
    }

    client.get_output_stream().flush();
}

TEST(TCPStreamTest, BasicFunctionality) {
    execute_in_thread_pool(&perform_tcp_stream_validation);
}

}

