std::mutex printMutex;

void workerFunction(unsigned int delaySeconds) {
    using std::chrono::seconds;
    using std::cout;
    using std::endl;
    using std::lock_guard;
    using std::mutex;

    std::this_thread::sleep_for(seconds(delaySeconds));

    {
        lock_guard<mutex> guard{printMutex};
        cout << delaySeconds << endl;
    }
}

int main(int argumentCount, char** argumentVector) {
    using std::cout;
    using std::endl;
    using std::string;
    using std::stringstream;
    using std::thread;
    using std::vector;

    vector<thread>::size_type threadCount = argumentCount - 1;
    vector<thread> threadList;
    threadList.reserve(threadCount);

    for (auto index = 1; index < argumentCount; ++index) {
        stringstream converter;
        converter << argumentVector[index];
        unsigned int parsedValue;

        if (!(converter >> parsedValue)) {
            cout << "Invalid input detected: " << argumentVector[index] << endl;
        } else {
            threadList.emplace_back(workerFunction, parsedValue);
        }
    }

    for (auto& activeThread : threadList) {
        activeThread.join();
    }

    return 0;
}

