KVProxy::KVProxy(QObject *parent, unsigned short localPort) :
	QObject(parent), p("127.0.0.1", localPort)
{
	// Set up the polling mechanism to trigger periodic proxy updates
	connect(&pollTimer, SIGNAL(timeout()), this, SLOT(updateProxy()));

	// Handle incoming HTTP connections via the private implementation
	p.on_connection([this](HttpProxy::Connection::Ptr connection) {
		proxyHandleConnection(this, connection);
	});

	// Log any proxy-related errors to the debug output
	p.on_error([](std::string errorMsg, bool /*ignored*/){
		qDebug() << "Proxy Error: " << errorMsg.c_str();
	});
}

