template <class T>
void visualizeTree(ostream& out, typename BinaryTree<T>::Inspector inspector, size_t nodeId)
{
    if (inspector.isEmpty())
    {
        out << nodeId << "[label=\"EMPTY\" shape=point];" << endl;
        return;
    }

    out << nodeId << "[label=\"" << inspector.getData() << "\"];" << endl;
    out << nodeId << " -> " << 2*nodeId + 1 << ";" << endl;
    visualizeTree<T>(out, inspector.left(), 2*nodeId + 1);

    out << nodeId << " -> " << 2*nodeId + 2 << ";" << endl;
    visualizeTree<T>(out, inspector.right(), 2*nodeId + 2);
}

template <class T>
void visualizeTree(ostream& out, const BinaryTree<T>& binaryTree)
{
    out << "digraph TreeStructure\n{\n";
    visualizeTree<T>(out, binaryTree.getInspector(), 0);
    out << "}\n";
}

