	// Compute element-wise differences between two arrays
	void diff_values(const float* src1, const float* src2, float* result, unsigned int len)
	{
		differences<float, float>(src1, src2, result, len);
	}

	// Add a scaled sum of two arrays: out = a + c * b
	void scale_and_add(const float* src1, const float* src2, const float& scale, float* dest, size_t elements)
	{
		add_multiple_of_sum<float, float>(src1, src2, scale, dest, elements);
	}

	// Assign multiple elements: out[i] = c for all i
	void fill_with_value(const float* source, const float& value, float* destination, unsigned int num_elements)
	{
		assign_multiple<float, float, float>(source, value, destination, num_elements);
	}

	// Compute inner product of two arrays
	double dot_product(const float* arr1, const float* arr2, unsigned int length)
	{
		return inner_product<float>(arr1, arr2, length);
	}

	// Compute sum of squared differences between arrays
double compute_ssd(const float* data1, const float* data2, size_t n)
	{
      return SumSquaredDifferences<double, float,float>::sum_squared_differences(data1,data2,n);
	}

	// Compute element-wise square of array
	void element_square(const float* input, float* output, size_t count)
	{
		square<float, float>(input, output, count);
	}

	// Subtract element-wise square from output: out[i] -= in[i]^2
	void subtract_element_square(const float* input, float* output, size_t count)
	{
		subtract_square<float, float>(input, output, count);
	}
