namespace {

const u32 Function_GetTechUseErrorMessage = 0x00491E80;

void __declspec(naked) techErrorMessageWrapper() {
  static CUnit *unitTarget;
  static u8 playerIndex;
  static u16 technologyId;
  static u16 errorResult;

  __asm {
    PUSHAD
    MOV EBP, ESP
    MOV unitTarget, EAX
    MOV playerIndex, BL
    MOV EAX, [ESP + 36]   ;// (PUSHAD saves 32) + (CALL saves 4) == 36
    MOV technologyId, AX
  }

  errorResult = hooks::techErrorMessageHook(unitTarget, playerIndex, technologyId);

  __asm {
    POPAD
    MOV AX, errorResult
    RETN 4
  }
}

} //Unnamed namespace

namespace hooks {

void applyTechTargetHooks() {
  jmpPatch(techErrorMessageWrapper, Function_GetTechUseErrorMessage);
}

u16 getTechUseErrorMessage(const CUnit *target, s8 castingPlayer, u16 techId) {
  u32 techId_ = techId;
  static u16 resultMessage;

  __asm {
    PUSHAD
    PUSH techId_
    MOV BL, castingPlayer
    MOV EAX, target
    CALL Function_GetTechUseErrorMessage
    MOV resultMessage, AX
    POPAD
  }

  return resultMessage;
}

} //hooks

