class key_handler {
    std::string prompt_text;
    std::map<char, std::function<void(contents&, boost::optional<int>)>> command_map;

public:
    key_handler(std::string text) : prompt_text(text) { }

    void add_mapping(char input, std::function<void(contents&, boost::optional<int>)> handler_function) {
        this->command_map[input] = handler_function;
    }

    void execute(contents& cont, boost::optional<int> op) {
        show_message(prompt_text + "-");
        char input_char = getch();
        auto lookup_result = command_map.find(input_char);

        if (lookup_result == command_map.end()) {
            show_message(std::string("Unknown key sequence: '")
                         + prompt_text + '-' + input_char + "'");
        } else {
            lookup_result->second(cont, op);
            showing_message = false;
        }
    }

    operator std::function<void(contents&, boost::optional<int>)>() {
        return std::function<void(contents&, boost::optional<int>)>(
            [this](contents& cont, boost::optional<int> op) {
                execute(cont, op);
            });
    }
};

