namespace opencl
{
using std::vector;
using cl::Platform;
using cl::Device;

void contextCallback(const char *errInfo, const void *privateData, size_t size, void *userData)
{
    printf("OpenCL Context Error: %s\n", errInfo);
    fflush(stdout);
}

const cl::Context&
getContext(unsigned char index)
{
    static std::vector<cl::Platform> availablePlatforms(0);
    static std::vector<cl::Context> deviceContexts(0);

    if(deviceContexts.empty()) {
        Platform::get(&availablePlatforms);
        for(auto platform : availablePlatforms) {
            vector<cl_context_properties> properties = {
                CL_CONTEXT_PLATFORM, 
                (cl_context_properties)platform(), 
                0
            };
            deviceContexts.emplace_back(CL_DEVICE_TYPE_DEFAULT, &properties.front(), contextCallback);
        }
    }
    return deviceContexts[index];
}

cl::CommandQueue&
getCommandQueue(unsigned char index) {
    static std::vector<cl::CommandQueue> commandQueues;
    if(commandQueues.empty()) {
        commandQueues.emplace_back(getContext(0));
    }
    return commandQueues[index];
}
}

