  img.magick(FUZZ_ENCODER);

  // Set file name with encoder prefix
  img.fileName(std::string(FUZZ_ENCODER) + ":");

  try {
    // Read the image from the blob
    img.read(blob);
  }
  catch (Magick::Exception &err) {
    return 0;
  }

#if FUZZ_IMAGEMAGICK_ENCODER_WRITE
  // Prepare output blob for writing
  Magick::Blob resultBlob;
  try {
    // Write the processed image to the output blob
    img.write(&resultBlob, FUZZ_ENCODER);
  }
  catch (Magick::Exception &err) {
    // Silently handle exceptions during write operation
  }
#endif

  return 0;
}

