// Compute the greatest common divisor using Euclidean algorithm
int compute_gcd(const int a, const int b)
{
    /* Ensure larger number is first */
    if (a < b) return compute_gcd(b, a); /* Swap arguments so that second is not larger than first */
    if (a % b == 0) return b; /* Second argument is the GCD */
    /* Recursive step */
    return compute_gcd(a % b, b);
}

int main(void)
{
    int value1, value2;
    printf("Enter first number: "); scanf("%d", &value1);
