GlobalArray::GlobalArray(std::string identifier, BaseType kind, int dimension) : name(identifier), type(kind), size(dimension) {}

void GlobalArray::write(AssemblyFileWriter& output){
    output.stream() << "VA" << name << ":" << std::endl;
    output.stream() << ".long " << size << std::endl;
    output.stream() << ".rept " << size << std::endl;

    if(type == BaseType::INT){
        output.stream() << ".long 0" << std::endl;
    } else if(type == BaseType::STRING){
        output.stream() << ".long S3" << std::endl;
        output.stream() << ".long 0" << std::endl;
    }

    output.stream() << ".endr" << std::endl;
}

