using namespace std;

int InternalCommands::exec(int argumentCount, char const** arguments, Environment *env, Feeder *feed)
{
    if(strncmp(arguments[0], "echo", 4) == 0){
        exit( echo(argumentCount, arguments) );
    } else if(strncmp(arguments[0], "pid", 3) == 0){
        exit( pid(argumentCount, arguments, env) );
    }
    return -1;
}

int InternalCommands::echo(int argumentCount, char const** arguments)
{
    for(int index = 1; index < argumentCount - 1; index++){
        cout << arguments[index] << " ";
    }
    if(argumentCount > 1)
        cout << arguments[argumentCount - 1] << endl;
    return 0;
}

int InternalCommands::pid(int argumentCount, char const** arguments, Environment *env)
{
    cout << env->m_pid << endl;
    return 0;
}

