#include "tac/OptimizerUtils.hpp"

using namespace eddic;

void tac::ReduceInStrength::operator()(std::shared_ptr<tac::Quadruple>& instruction){
    switch(instruction->op){
        case tac::Operator::MUL:
            if(*instruction->operand1 == 2){
                replaceRight(*this, instruction, *instruction->operand2, tac::Operator::ADD, *instruction->operand2);
            } else if(*instruction->operand2 == 2){
                replaceRight(*this, instruction, *instruction->operand1, tac::Operator::ADD, *instruction->operand1);
            }
            break;
        case tac::Operator::FMUL:
            if(*instruction->operand1 == 2.0){
                replaceRight(*this, instruction, *instruction->operand2, tac::Operator::FADD, *instruction->operand2);
            } else if(*instruction->operand2 == 2.0){
                replaceRight(*this, instruction, *instruction->operand1, tac::Operator::FADD, *instruction->operand1);
            }
            break;
        default:
            break;
    }
}

