NAN_METHOD(GenerateRandom) {
  NanScope();
  double randomValue = static_cast<double>(rand()) / (RAND_MAX + 1.0);
  NanReturnValue(NanNew<Number>(randomValue));
}

NAN_METHOD(GenerateInteger) {
  NanScope();
  NanReturnValue(NanNew<Integer>(rand()));
}

NAN_METHOD(SetSeed) {
  NanScope();

  if (args.Length() == 0) {
    NanThrowError(Exception::TypeError(NanNew<String>("Expected a numeric seed value")));
  }

  uint32_t seedValue = args[0]->Uint32Value();
  srand(seedValue);

  NanReturnValue(NanUndefined());
}

extern "C" void InitializeModule(Handle<Object> exports) {
  NODE_SET_METHOD(exports, "random", GenerateRandom);
  NODE_SET_METHOD(exports, "rand", GenerateInteger);
  NODE_SET_METHOD(exports, "srand", SetSeed);
  NODE_SET_METHOD(exports, "seed", SetSeed);

  NODE_DEFINE_CONSTANT(exports, RAND_MAX);
}

