void run_test() {
    typedef std::atomic<Type> AtomicType;
    static_assert(std::is_literal_type<AtomicType>::value, "");
    constexpr Type init_val(42);
    {
        constexpr AtomicType obj(init_val);
        assert(obj == init_val);
    }
    {
        constexpr AtomicType obj{init_val};
        assert(obj == init_val);
    }
    {
        constexpr AtomicType obj = ATOMIC_VAR_INIT(init_val);
        assert(obj == init_val);
    }
}

