#include <event/event_callback.h>
#include <event/event_handler.h>
#include <event/event_main.h>
#include <io/stream_handle.h>

class InputSink {
    LogHandle logger_;
    StreamHandle input_fd_;
    CallbackHandler shutdown_handler_;
    EventHandler read_event_handler_;

public:
    InputSink(int fd)
        : logger_("/input_sink"),
          input_fd_(fd),
          read_event_handler_()
    {
        read_event_handler_.handler(Event::Done, this, &InputSink::on_read_complete);
        read_event_handler_.handler(Event::EOS, this, &InputSink::on_end_of_stream);
        shutdown_handler_.handler(this, &InputSink::on_shutdown_complete);
        read_event_handler_.wait(input_fd_.read(0, read_event_handler_.callback()));
    }

    ~InputSink() { }

    void on_read_complete(Event)
    {
        read_event_handler_.wait(input_fd_.read(0, read_event_handler_.callback()));
    }

    void on_end_of_stream(Event)
    {
        shutdown_handler_.wait(input_fd_.close(shutdown_handler_.callback()));
    }

    void on_shutdown_complete(void) { }
};

int main(void)
{
    InputSink sink(STDIN_FILENO);
    event_main();
}

