class IncrementAndDoubling
{
    public:
        int processArray(vector<int> targetValues, int stepCount)
        {
            // Check if all elements are zero
            if(all_of(begin(targetValues), end(targetValues), [] (const int & value) {return value==0;}))
            {   
                return stepCount;
            }

            // Check if all elements are even
            if(all_of(begin(targetValues), end(targetValues), [] (int & value) {return value%2==0;}))
            {   
                for(auto & value : targetValues)
                {
                    value /= 2;
                }

                stepCount++;
            }
            else
            {   
                // Handle odd elements by decrementing
                for(auto & value : targetValues)
                {
                    if(value % 2 == 1)
                    {
                        value--;

                        stepCount++;
                    }
                }
            }

            return processArray(targetValues, stepCount);
        }

        int calculateMinSteps(vector<int> targetValues)
        {   
            int steps = 0;

            int finalResult = processArray(targetValues, steps);

            return finalResult;
        }
};

