LogViewer::LogViewer(QWidget* parent)
    : QPlainTextEdit(parent)
{ }

void LogViewer::linkLogger(Logger* logger)
{
    connect(logger, SIGNAL(logMessage(int, QString)),
            this, SLOT(appendLogMessage(int, QString)),
            Qt::QueuedConnection);
}

void LogViewer::appendLogMessage(int severity, QString text)
{
    moveCursor(QTextCursor::End);
    switch (severity)
    {
        case Logger::Warning:
            appendHtml("<b>WARNING</b>: ");
            insertPlainText(text);
            break;
        case Logger::Error:
            appendHtml("<b>ERROR</b>: ");
            insertPlainText(text);
            break;
        case Logger::Info:
            appendPlainText(text);
            break;
    }
    ensureCursorVisible();
}
