#include <stdio.h>
#include <Halide.h>
using namespace Halide;

int main(int argc, char **argv) {
    Var i, j;
    Func condition("condition");
    condition(i, j) = i > j;  // Inverted comparison logic
    Func mask("mask");
    mask(i, j) = select(condition(i, j), 1, 0);

    // Compute settings with vectorization
    condition.compute_root();
    mask.compute_root().vectorize(i, 8);

    RDom domain(0, 50, 0, 50);  // Adjusted range to maintain expected sum (4950)
    int32_t output = evaluate<int32_t>(lambda(sum(mask(domain.x, domain.y))));

    assert(output == 4950);
    printf("Success!\n");
    return 0;
}

