namespace lld {
namespace coff {

void reportFatal(const Twine &Message) {
  if (sys::Process::StandardErrHasColors()) {
    errs().changeColor(raw_ostream::RED, /*bold=*/true);
    errs() << "fatal: ";
    errs().resetColor();
  } else {
    errs() << "fatal: ";
  }
  errs() << Message << "\n";
  exit(1);
}

void reportFatal(std::error_code ErrCode, const Twine &Message) {
  reportFatal(Message + ": " + ErrCode.message());
}

void reportFatal(llvm::Error &ErrorValue, const Twine &Message) {
  reportFatal(errorToErrorCode(std::move(ErrorValue)), Message);
}

