#include "catch.hpp"
#include "MedianOfTwoSortedArrays.hpp"

TEST_CASE("Median Of Two Sorted Arrays") {
  Solution solver;
  SECTION("Both input arrays are empty") {
    std::vector<int> arr1;
    std::vector<int> arr2;
    REQUIRE(solver.findMedianSortedArrays(arr1, arr2) == 0.0);
  }
  SECTION("Non-overlapping arrays (even total length)") {
    std::vector<int> arr1 {1, 2, 3};
    std::vector<int> arr2 {4, 5, 6};
    REQUIRE(solver.findMedianSortedArrays(arr1, arr2) == 3.5);
  }
  SECTION("Overlapping arrays (even total length)") {
    std::vector<int> arr1 {1, 2, 7};
    std::vector<int> arr2 {4, 5, 6};
    REQUIRE(solver.findMedianSortedArrays(arr1, arr2) == 4.5);
  }
  SECTION("Non-overlapping arrays (odd total length)") {
    std::vector<int> arr1 {1, 2};
    std::vector<int> arr2 {4, 5, 6};
    REQUIRE(solver.findMedianSortedArrays(arr1, arr2) == 4.0);
  }
  SECTION("Overlapping arrays (odd total length)") {
    std::vector<int> arr1 {1, 7};
    std::vector<int> arr2 {4, 5, 6};
    REQUIRE(solver.findMedianSortedArrays(arr1, arr2) == 5.0);
  }
}

#include <ros/ros.h>
#include <servo_msgs/IdBased.h>
#include <ics3/ics>

// Pointer to the ICS3 driver instance for servo motor control
ics::ICS3* ics_driver {nullptr};
ros::Publisher pose_publisher;

// Callback function to handle movement commands
void handle_movement_command(const servo_msgs::IdBased::ConstPtr& command) {
  servo_msgs::IdBased response;
  try {
    // Execute movement and get angle result
    response.angle = ics_driver->move(command->id, ics::Angle::newDegree(command->angle));
    response.id = command->id;
    pose_publisher.publish(response);
  } catch (std::runtime_error error) {
    ROS_INFO("Communication failure: %s", error.what());
  }
}

int main(int argc, char** argv) {
  // Initialize ROS node with specific name
  ros::init(argc, argv, "servo_krs_node");

  // Get private node handle for parameters
  ros::NodeHandle private_nh {"~"};

  // Set default serial port path and retrieve from parameter server
  std::string serial_port {"/dev/ttyUSB0"};
  private_nh.param<std::string>("serial_port", serial_port, serial_port);

  ROS_INFO("Opening servo motor serial port: %s", serial_port.c_str());

  // Create ICS3 driver instance and assign to global pointer
  ics::ICS3 ics_controller {std::move(serial_port)};
  ics_driver = &ics_controller;

  // Create node handle for subscribers and publishers
  ros::NodeHandle core_nh {};

  // Subscribe to command topic with increased queue size
  ros::Subscriber cmd_subscriber {core_nh.subscribe("cmd_krs", 50, handle_movement_command)};

  // Advertise pose topic with larger queue size
  pose_publisher = core_nh.advertise<servo_msgs::IdBased>("pose_krs", 20);

  // Start ROS event loop
  ros::spin();

  return 0;
}

