#include <utility>
#include <iostream>
#include <string>

// Helper structure to hold values at compile-time indices
template <std::size_t Index, typename Type> struct storage { Type value; };

// Implementation details for our custom tuple type
template <typename Indices, typename... Types> struct tuple_data;
template <std::size_t... Idx, typename... Types>
struct tuple_data<std::index_sequence<Idx...>, Types...> : storage<Idx, Types>... {};

// Alias for our tuple type
template <typename... Types>
using my_tuple = tuple_data<std::make_index_sequence<sizeof...(Types)>, Types...>;

// Overloaded get functions to access tuple elements
template <std::size_t N, typename T> T& access(storage<N, T>& s) { return s.value; }
template <typename T, std::size_t N> T& access(storage<N, T>& s) { return s.value; }

// Function to demonstrate tuple operations
void demonstrate_tuple() {
  my_tuple<double, std::string> obj{3.14, "greeting"};
  std::cout << access<1>(obj) << "\n";
  std::cout << access<0>(obj) << "\n";
  access<double>(obj) = 2.71;
  access<std::string>(obj) = "salutation";
  std::cout << access<1>(obj) << "\n";
  std::cout << access<0>(obj) << "\n";
}

// Variant visitor helper using multiple inheritance
template <typename... Callables> struct visitor : Callables... { using Callables::operator()...; };
template <typename... Callables> visitor(Callables...)->visitor<Callables...>;

// Function to demonstrate variant with visitor pattern
void demonstrate_variant() {
  std::variant<int, std::string> var;
  var = std::string("message");
  std::visit(
      visitor{[](int num) { std::cout << num << " integer\n"; },
              [](const std::string& str) { std::cout << str << " text\n"; }},
      var);
}

int main() {
  demonstrate_tuple();
  demonstrate_variant();
}

