#include <exception>
#include <thread>
#include <iostream>
#include <cassert>

std::exception_ptr saved_exception;

void faulty_task()
{
  try
  {
    std::thread().detach(); // Mistake: detached thread without proper handling
  }
  catch ( ... )
  {
    saved_exception = std::current_exception();
  }
}

int main()
{
  assert( saved_exception == nullptr );
  assert( !saved_exception );

  std::thread worker( faulty_task );
  worker.join();

  assert( saved_exception != nullptr );
  assert( saved_exception );

  try
  {
    std::rethrow_exception( saved_exception );
  }
  catch ( std::exception & err )
  {
    std::cerr << "Worker process failed with exception: " << err.what() << "\n";
  }

  return 0;
}

