using namespace std;

/******************************************************/
/*solve the equation cosh(x)=exp(y), input y, return x*/
/******************************************************/
complex<double> solve_coshx_eq_expy(double inputY)
{
    complex<double> expY = { exp(inputY), 0.0 };
    complex<double> result = log( expY - sqrt( expY * expY - 1.0 ) );

    // Ensure result is purely real or purely imaginary
    if ( abs( result.real() ) < abs( result.imag() ) ) {
        result = complex<double>( 0.0, result.imag() );
    } else {
        result = complex<double>( result.real(), 0.0 );
    }

    return result;
}

