    }

    TEST(SerializeArticleWithSingleOutgoingLink)
    {
        ToJsonWriter serializer;
        Article doc("Garden");
        doc.addLink(new Article("Plant"));
        CHECK_EQUAL("{\"Garden\":{\"forward_links\":[\"Plant\"]}}", serializer.convertToJson(&doc));
    }

    TEST(SerializeArticleWithSeveralOutgoingLinks)
    {
        ToJsonWriter serializer;
        Article doc("Garden");
        doc.addLink(new Article("Plant"));
        doc.addLink(new Article("Tree"));
        doc.addLink(new Article("Flower"));
        CHECK_EQUAL("{\"Garden\":{\"forward_links\":[\"Plant\",\"Tree\",\"Flower\"]}}", serializer.convertToJson(&doc));
    }

    TEST(SerializeEmptyArticleCollection)
    {
        ToJsonWriter serializer;
        ArticleCollection collection;
        CHECK_EQUAL("{}", serializer.convertToJson(collection));
    }

    TEST(SerializeArticleCollectionWithOneDocument)
    {
        ToJsonWriter serializer;
        ArticleCollection collection;
        collection.add(new Article("Bar"));
        CHECK_EQUAL("{\"Bar\":{\"forward_links\":[]}}", serializer.convertToJson(collection));
    }
}

