// Check if message can be added to queue with space for terminator
bool tryEnqueueMessage(QUEUE_TYPE(uint8_t)* q, uint8_t* data, int length) {
    if(queue_available(q) < length + 2) {
        return false;
    }

    for(int idx = 0; idx < length; idx++) {
        QUEUE_PUSH(uint8_t, q, (uint8_t)data[idx]);
    }

    QUEUE_PUSH(uint8_t, q, (uint8_t)'\r');
    QUEUE_PUSH(uint8_t, q, (uint8_t)'\n');
    return true;
}

void transmitMessage(Listener* l, uint8_t* payload, int payloadLength) {
    if(!tryEnqueueMessage(&l->usb->sendQueue, payload, payloadLength)) {
        debug("USB transmission buffer overflow, discarding CAN message: %s\r\n", payload);
    }

    if(!tryEnqueueMessage(&l->serial->sendQueue, payload, payloadLength)) {
        debug("UART transmission buffer overflow, discarding CAN message: %s\r\n", payload);
    }
}

void handleListenerBuffers(Listener* listener) {
    // USB processing must always occur first as it includes MCU USB task handling
    processInputQueue(listener->usb);
    processInputQueue(listener->serial);
}

