namespace {
TEST(Timer, Additivity) {
  Timer T2("T2");
  EXPECT_TRUE(T2.isInitialized());
  T2.startTimer();
  T2.stopTimer();
  auto Time1 = T2.getTotalTime();
  T2.startTimer();
  std::this_thread::sleep_for(std::chrono::milliseconds(1));
  T2.stopTimer();
  auto Time2 = T2.getTotalTime();
  EXPECT_TRUE(Time1 < Time2);
}

TEST(Timer, CheckIfTriggered) {
  Timer T3("T3");
  EXPECT_FALSE(T3.hasTriggered());
  T3.startTimer();
  EXPECT_TRUE(T3.hasTriggered());
  T3.stopTimer();
  EXPECT_TRUE(T3.hasTriggered());
  T3.clear();
  EXPECT_FALSE(T3.hasTriggered());
}
