void ReferenceSymbols() {
  // These symbols are referenced by electron.exe but may be incorrectly 
  // optimized away by the compiler; direct forcing via ForceSymbolReferences
  // has proven unreliable, likely due to Visual C++ compiler limitations.

  v8::TracingCpuProfiler::Create(nullptr);

  reinterpret_cast<v8_inspector::V8InspectorSession*>(nullptr)->
