namespace fs = boost::filesystem;

BOOST_AUTO_TEST_CASE(path)
{
# define PATH_A "pif"
# define PATH_B "paf"
#ifdef _WIN32
# define ABS_PATH_A "c:\\pif"
# define ABS_PATH_B "c:/paf"
#else
# define ABS_PATH_A "/pif"
# define ABS_PATH_B "/paf"
#endif
    using namespace configure::utils;

    BOOST_CHECK_THROW(
        relative_path(PATH_A, ABS_PATH_B),
        configure::error::InvalidPath
    );

    BOOST_CHECK_THROW(
        relative_path(ABS_PATH_A, PATH_B),
        configure::error::InvalidPath
    );

    BOOST_CHECK_EQUAL(
        relative_path(ABS_PATH_A, ABS_PATH_B),
        fs::path("..") / PATH_A
    );

    BOOST_CHECK_EQUAL(
        relative_path(ABS_PATH_B, ABS_PATH_A),
        fs::path("..") / PATH_B
    );

    BOOST_CHECK_EQUAL(
        relative_path(ABS_PATH_A, ABS_PATH_A),
        "."
    );

    BOOST_CHECK_EQUAL(
        relative_path(ABS_PATH_B, ABS_PATH_B),
        "."
    );
}

