SocketServer::SocketServer(const ProtocolHandler *handler) :
    protocolHandler(handler),
    ioService(),
    acceptor(ioService) {
}

void SocketServer::listen(const port_type portNumber) {
    tcp::endpoint endpoint(tcp::v4(), portNumber);
    acceptor.open(endpoint.protocol());
    acceptor.set_option(tcp::acceptor::reuse_address(true));
    acceptor.set_option(tcp::no_delay(true));
    acceptor.bind(endpoint);
    acceptor.listen(1);
}

void SocketServer::acceptOnce() {
    tcp::iostream connectionStream;
    acceptor.accept(*connectionStream.rdbuf());
    handleConnection(connectionStream);
}

void SocketServer::handleConnection(tcp::iostream &stream) {
    std::string line;
    while (getline(stream, line)) {
        stream << protocolHandler->handle(line) << std::endl << std::flush;
    }
}

}
}

