// Returns the path to the gin_shell executable
base::FilePath GetGinShellExecutable() {
  base::FilePath exe_dir;
  PathService::Get(base::DIR_EXE, &exe_dir);
  return exe_dir.AppendASCII("gin_shell");
}

// Returns the path to hello_world.js
base::FilePath GetHelloWorldScriptPath() {
  base::FilePath src_root;
  PathService::Get(base::DIR_SOURCE_ROOT, &src_root);
  return src_root
    .AppendASCII("gin")
    .AppendASCII("shell")
    .AppendASCII("hello_world.js");
}

// Test that gin_shell executes hello_world.js and outputs "Hello World"
TEST(GinShellTest, HelloWorld) {
  base::FilePath shell_path(GetGinShellExecutable());
  base::FilePath script_path(GetHelloWorldScriptPath());

  ASSERT_TRUE(base::PathExists(shell_path));
  ASSERT_TRUE(base::PathExists(script_path));

  CommandLine cmd(shell_path);
  cmd.AppendArgPath(script_path);

  std::string result;
  ASSERT_TRUE(base::GetAppOutput(cmd, &result));

  std::string trimmed_output;
  base::TrimWhitespaceASCII(result, base::TRIM_ALL, &trimmed_output);
  ASSERT_EQ("Hello World", trimmed_output);
}

