      ThrowErrno("Failed to retrieve current time");
  return TimeValue(
    static_cast<TimeValue::SecondsType>( current_timeval.tv_sec ), 
    static_cast<TimeValue::NanoSecondsType>( current_timeval.tv_usec * 
      NANOSECONDS_PER_MICROSECOND ) );
