#include "ExecutableLauncherUnix.h"
#include <cstdio>
#include <cstdlib>
#include <sys/types.h>
#include <unistd.h>
#include <sys/wait.h>

using namespace clt::filesystem::operations;

void ExecutableLauncherUnix::execute(const entities::Path & filePath)
{
    pid_t childPid;

    childPid = fork();

    switch (childPid) {
        case -1: 
            perror("fork");
            break;

        case 0:
            execl(filePath.getValue().c_str(), filePath.getValue().c_str(), static_cast<char*>(nullptr));
            _exit(EXIT_FAILURE);
            break;

        default: 
            waitpid(childPid, nullptr, 0);
            break;
    }
}

