namespace {

// Determine if the current execution context is the browser process
// by checking if V8 locking mechanism is active.
inline bool IsBrowserProcess() {
  return v8::Locker::IsActive();
}

}  // namespace

v8::Local<v8::Value> DispatchEventWithArguments(v8::Isolate* isolate,
                                                v8::Local<v8::Object> target,
                                                ValueVector* parameters) {
  // Ensure JavaScript microtasks are checked after script execution.
  scoped_ptr<blink::WebScopedRunV8Script> script_guard(
      IsBrowserProcess() ? nullptr : new blink::WebScopedRunV8Script(isolate));

  // Delegate event emission to Node.js's callback mechanism,
  // which also processes pending tasks in the Node.js runtime.
  return node::MakeCallback(
      isolate, target, "emit", parameters->size(), &parameters->front());
}

}  // namespace internal
