#include "brents_fun.h"
using namespace std;

// Linear function: -2x + 1
double func_a(double value) {
  return -2.0 * value + 1.0;
}

// Quadratic function: x^2 - 2x - 3
double func_b(double value) {
  return value * value - 2.0 * value - 3.0;
}

// Partially applied quadratic: x^2 - 2x - 1 - y
double func_c(double x_val, double y_val) {
  return x_val * x_val - 2.0 * x_val - 1.0 - y_val;
}

void brents_fun_test() {
    double tolerance = 1e-8;
    double root_estimate;

    // Test with linear function
    root_estimate = brents_fun(func_a, -1.0, 5.0, tolerance);
    if (abs(root_estimate - 0.5) < tolerance) 
        cout << "brents_fun passed quadratic order test!\n";
    else 
        cout << "Warning!!!!brents_fun failed quadratic order test!!\n";

    // Test with first quadratic function
    root_estimate = brents_fun(func_b, 1.0, 5.0, tolerance);
    if (abs(root_estimate - 3.0) < tolerance) 
        cout << "brents_fun passed quadratic order test!\n";
    else 
        cout << "Warning!!!!brents_fun failed quadratic order test!!\n";

    // Test with partially applied function (y=7)
    root_estimate = brents_fun([](double x) { return func_c(x, 7.0); }, 0.0, 5.0, tolerance);
    if (abs(root_estimate - 4.0) < tolerance) 
        cout << "brents_fun passed partially function quadratic order test!\n";
    else 
        cout << "Warning!!!!brents_fun failed partially function quadratic order test!!\n";
}

