TEST(TreeNodeTest, AddChild) {
    // Create a node and add two child nodes to it
    TreeNode<int> parentNode;
    TreeNode<int> firstChild;
    TreeNode<int> secondChild;

    parentNode.addChild(&firstChild);
    parentNode.addChild(&secondChild);
    EXPECT_EQ(parentNode.getChildren().size(), 2);
}

TEST(TreeNodeTest, RemoveChild) {
    // Add children then remove them one by one
    TreeNode<int> parentNode;
    TreeNode<int> firstChild;
    TreeNode<int> secondChild;

    parentNode.addChild(&firstChild);
    parentNode.addChild(&secondChild);

    parentNode.removeChild(1);
    EXPECT_EQ(parentNode.getChildren().size(), 1);

    parentNode.removeChild(0);
    EXPECT_EQ(parentNode.getChildren().size(), 0);

    EXPECT_NO_THROW(parentNode.removeChild(0));
}

TEST(TreeNodeTest, SetParent) {
    // Assign and verify parent relationship
    TreeNode<int> rootNode;
    TreeNode<int> childNode;

    EXPECT_EQ(childNode.getParent(), nullptr);

    childNode.setParent(&rootNode);
    EXPECT_EQ(childNode.getParent(), &rootNode);
}

TEST(TreeNodeTest, RemoveParent) {
    // Set and then clear parent relationship
    TreeNode<int> rootNode;
    TreeNode<int> childNode;

    childNode.setParent(&rootNode);
    EXPECT_EQ(childNode.getParent(), &rootNode);

    childNode.removeParent();
    EXPECT_EQ(childNode.getParent(), nullptr);
}

TEST(TreeNodeTest, ValueAccess) {
    // Store and retrieve value in node
    TreeNode<int> testNode;

