    bool result = dist(gen);
}
// This code generates a random boolean value following a Bernoulli distribution.
//
// First, we instantiate a `std::random_device` (on [7]) to obtain non-deterministic
// randomness where supported by the system. This is used to seed the 
// Mersenne-Twister pseudo-random number generator `std::mt19937` (on [8]).
//
// Next, we construct a `std::bernoulli_distribution` (on [9]) configured with
// a success probability of 0.25—equivalent to flipping a coin that lands heads
// only 25% of the time.
//
// Finally, we invoke the distribution with the generator to produce a boolean
// result ([11]), which will be `true` with 25% likelihood and `false` otherwise.

#include <cstdio>
#include <cmath>
#include <string>
#include <sstream>

template <typename T> T convert_from_string(const std::string & input){
    std::istringstream stream(input);
    T result;
    stream >> result;
    return result;
}

void display(double value){
    printf("%.20f, %llX\n", value, *((unsigned long long *) &value));
}

int main(int argument_count, char **argument_vector){
    double x = convert_from_string<double>(argument_vector[1]);
    display(sqrt(-1));
    display(1.0/x);
    display(-1.0/x);
    display(0.0/x);
    display(-0.0/x);
    display((1.0/x)/(-1.0/x));
    display((1.0/x) + 5.0);
    display((-1.0/x) + 5.0);
    display(5.0/(1.0/x));
    return 0;
}

