template<typename Element, typename Index>
struct StaticArray {
    Element* buffer = nullptr;
    Index size = 0;

    ~StaticArray() {
        delete[] buffer;
    }

    void AllocateFrom(BinaryReader& stream) {
        stream.ReadLE(size);
        delete[] buffer;
        if (size > 0)
            buffer = new Element[size];
    }

    void LoadFrom(BinaryReader& stream) {
        for(Index idx = 0; idx < size; ++idx)
            buffer[idx].LoadFrom(stream);
    }

    void AllocateAndLoad(BinaryReader& stream) {
        AllocateFrom(stream);
        LoadFrom(stream);
    }
};

struct stringReference_t {
    uint32_t length = 0u;
    const char* text = nullptr;

    void LoadFrom(BinaryReader& stream) {
        assert(stream.ReadLE(length));
        assert(stream.ReadBytes(text, length));
    }
};

typedef StaticArray<stringReference_t, uint32_t> stringTable_t;

void DisplayStrings(stringTable_t& table) {
    for(uint32_t index = 0; index < table.size; ++index)
        printf("\"%.*s\"\n", table.buffer[index].length, table.buffer[index].text);
}

struct entryDescriptor_t {
    uint32_t field0;
    uint32_t field1;
    uint32_t field2;
    uint32_t field3;
    uint32_t field4;
    uint32_t field5;
    uint32_t field6;
    uint32_t field7;

    void LoadFrom(BinaryReader& stream) {
        stream.ReadLE(field0);
        stream.ReadLE(field1);
        stream.ReadLE(field2);
        stream.ReadLE(field3);
        stream.ReadLE(field4);
        stream.ReadLE(field5);
        stream.ReadLE(field6);
        stream.ReadLE(field7);
    }
};

struct headerSection_t {
    StaticArray<entryDescriptor_t, uint32_t> entries;
    uint32_t zeroValue;
    uint32_t worldEntityId;
    uint32_t primaryTableSize;

    void LoadFrom(BinaryReader& stream) {
        entries.AllocateFrom(stream);
        stream.ReadLE(zeroValue);
        assert(zeroValue == 0u);
        stream.ReadLE(worldEntityId);
        stream.ReadLE(primaryTableSize);
        entries.LoadFrom(stream);
    }
};

void AbortParsing(BinaryReader& stream) {
    printf("%zu\n", stream.GetPosition());
    assert(0);
    //std::cout << std::hex << std::setfill('0') << std::setw(16) << (const void*)(end - start) << std::endl;
}

struct StaticDataBlock
{
    headerSection_t mainHeader;
    stringTable_t tableA;
    stringTable_t tableB;

    void LoadFrom(BinaryReader& stream)
    {
        mainHeader.LoadFrom(stream);
        tableA.AllocateAndLoad(stream);
        assert(tableA.size == mainHeader.primaryTableSize);

        while (true)
        {
            uint32_t opcode, param0, param1;
            assert(stream.ReadLE(opcode));
            if (opcode == 0u) {
                stream.ReadLE(param0);
                stream.ReadLE(param1);
                assert(param0 == 0u && param1 == 0u);
            }
            else AbortParsing(stream);
        }
        //DisplayStrings(tableA);
        //const char* begin = stream.GetNext();
        //const char* end = stream.GetNext();
        //std::cout << std::hex << std::setfill('0') << std::setw(16) << (const void*)(end - begin) << std::endl;
    }
};

void StaticsParser::Parse(BinaryReader& stream)
{
    StaticDataBlock block;
    block.LoadFrom(stream);
}

