    std::for_each(updated_data.begin(), updated_data.end(), [&writer](const std::string& item) {
      WriteStr(writer, item.c_str(), item.size());
    });

    writer.Flush();
    ASSERT_GT(allocator.Counter(), 0);

    // Create input stream to verify written data
    MemoryIndexInput reader{buffer};
