        std::cout << std::endl << std::endl;
        std::cout << chat_engine->show_profile() << std::endl;

        normalized_input.images.clear();
        normalized_input.images.push_back("../../../tb_files/panda.png");
        std::cout << "Prompt: " << normalized_input.prompt << std::endl;
        std::cout << "Response: " << std::endl;

        chat_engine->start_total_timer();
