vector<ESection_Variable> ExtractVariables(LPBYTE& ptr, bool skip = false)
{
    vector<ESection_Variable> result;
    UINT count = GetData<UINT>(ptr);
    UINT length = GetData<UINT>(ptr);
    LPBYTE saved_ptr = ptr + length;
    if (!skip)
    {
        result = vector<ESection_Variable>(count);
        ETAG* tags = new ETAG[count];
        LPBYTE* offsets = new LPBYTE[count];
        for (size_t i = 0; i < count; i++)
            tags[i] = GetData<ETAG>(ptr);
        LPBYTE temp_ptr = ptr + count * sizeof(UINT);
        for (size_t i = 0; i < count; i++)
            offsets[i] = temp_ptr + GetData<UINT>(ptr);
        for (size_t i = 0; i < count; i++)
        {
            ESection_Variable sv;
            ptr = offsets[i];
            UINT size = GetData<UINT>(ptr);
            sv.Tag = tags[i];
            sv.DataType = GetData<DataType>(ptr);
            sv.Attributes = GetData<EVarAttr>(ptr);
            sv.ArrayInfo.Dimension = GetData<BYTE>(ptr);
            for (size_t n = 0; n < sv.ArrayInfo.Dimension; n++)
                sv.ArrayInfo.Subscript.push_back(GetData<UINT>(ptr));
            sv.Name = GetAutoString(ptr);
            sv.Remark = GetAutoString(ptr);
            result[i] = sv;
        }
        delete[] tags;
        delete[] offsets;
    }
    ptr = saved_ptr;
    return result;
}

vector<ESection_Program_Assembly> ExtractAssemblies(LPBYTE& ptr, bool isclass = true)
{
    vector<ESection_Program_Assembly> result;
    UINT length = GetData<UINT>(ptr) / 2;
    size_t count = length / sizeof(ETAG);
    ETAG* tags = new ETAG[count];
    for (size_t i = 0; i < count; i++)
        tags[i] = GetData<ETAG>(ptr);
    ptr += length;
    for (size_t i = 0; i < count; i++)
    {
        ESection_Program_Assembly spa;
        spa.Tag = tags[i];
        if (spa.Tag.Type2 == ETYPE::WindowClass)
        {
            spa.Base = GetData<ETAG>(ptr);
            ptr += 4;
        }
        else
        {
            spa.Status = GetData<EtagStatus>(ptr);
            if (isclass)
                spa.Base = GetData<ETAG>(ptr);
        }
        spa.Name = GetString(ptr);
        spa.Remark = GetString(ptr);
        if (isclass)
        {
            length = GetData<UINT>(ptr);
            size_t size = length / sizeof(ETAG);
            for (size_t n = 0; n < size; n++)
                spa.Methods.push_back(GetData<ETAG>(ptr));
        }
        spa.Variables = ExtractVariables(ptr);
        result.push_back(spa);
    }
    delete[] tags;
    return result;
}

vector<ESection_Program_Method> ExtractMethods(LPBYTE& ptr)
{
    vector<ESection_Program_Method> result;
    UINT length = GetData<UINT>(ptr) / 2;
    size_t count = length / sizeof(ETAG);
    ETAG* tags = new ETAG[count];
    for (size_t i = 0; i < count; i++)
        tags[i] = GetData<ETAG>(ptr);
    ptr += length;
    for (size_t i = 0; i < count; i++)
    {
        ESection_Program_Method spm;
        spm.Tag = tags[i];
        spm.Class = GetData<ETAG>(ptr);
        spm.Attributes = GetData<EMethodAttr>(ptr);
        spm.ReturnType = GetData<DataType>(ptr);
        spm.Name = GetString(ptr);
        spm.Remark = GetString(ptr);
        spm.Variables = ExtractVariables(ptr);
        spm.Parameters = ExtractVariables(ptr);
        spm.RowOffset = GetBytes(ptr);
        spm.FlowOffset = GetBytes(ptr);
        spm.MethodOffset = GetBytes(ptr);
        spm.VariableOffset = GetBytes(ptr);
        spm.ParameterOffset = GetBytes(ptr);
        spm.Code = GetBytes(ptr);
        result.push_back(spm);
    }
    delete[] tags;
    return result;
}

vector<ESection_Program_Dll> ExtractDlls(LPBYTE& ptr)
{
    vector<ESection_Program_Dll> result;
    UINT length = GetData<UINT>(ptr) / 2;
    size_t count = length / sizeof(ETAG);
    ETAG* tags = new ETAG[count];
    for (size_t i = 0; i < count; i++)
        tags[i] = GetData<ETAG>(ptr);
    ptr += length;
    for (size_t i = 0; i < count; i++)
    {
        ESection_Program_Dll spd;
        spd.Tag = tags[i];
        spd.Status = GetData<EtagStatus>(ptr);
        spd.ReturnType = GetData<DataType>(ptr);
        spd.ShowName = GetString(ptr);
        spd.Remark = GetString(ptr);
        spd.Lib = GetString(ptr);
        spd.Name = GetString(ptr);
        spd.Parameters = ExtractVariables(ptr);
        result.push_back(spd);
    }
    delete[] tags;
    return result;
}

void WriteVariableVector(ostream* stream, vector<ESection_Variable>& list)
{
    ostringstream tag_stream(NULL, 0, ios::binary);
    ostringstream offset_stream(NULL, 0, ios::binary);
    ostringstream data_stream(NULL, 0, ios::binary);
    for (ESection_Variable& item : list)
    {
        tag_stream.write(C(&item.Tag), sizeof(ETAG));
        UINT len = data_stream.pcount();
        offset_stream.write(C(&len), sizeof(UINT));
        ostringstream buffer(NULL, 0, ios::binary);
        buffer.write(C(&item.DataType), sizeof(DataType));
        buffer.write(C(&item.Attributes), sizeof(EVarAttr));
        buffer.write(C(&item.ArrayInfo.Dimension), sizeof(BYTE));
        buffer.write(C(item.ArrayInfo.Subscript.begin()._Ptr), item.ArrayInfo.Dimension * sizeof(UINT));
        WriteAutoString(&buffer, item.Name);
        WriteAutoString(&buffer, item.Remark);
        len = buffer.pcount();
        data_stream.write(C(&len), sizeof(UINT));
        data_stream.write(buffer.str(), len);
    }
    UINT len = list.size();
    stream->write(C(&len), sizeof(UINT));
    len = tag_stream.pcount() + offset_stream.pcount() + data_stream.pcount();
    stream->write(C(&len), sizeof(UINT));
    stream->write(tag_stream.str(), tag_stream.pcount());
    stream->write(offset_stream.str(), offset_stream.pcount());
    stream->write(data_stream.str(), data_stream.pcount());
}

void WriteAssemblyVector(ostream* stream, vector<ESection_Program_Assembly>& list)
{
    ostringstream tag_stream(NULL, 0, ios::binary);
    ostringstream offset_stream(NULL, 0, ios::binary);
    ostringstream data_stream(NULL, 0, ios::binary);
    for (ESection_Program_Assembly& item : list)
    {
        tag_stream.write(C(&item.Tag), sizeof(ETAG));
        UINT len = data_stream.pcount();
        offset_stream.write(C(&len), sizeof(UINT));
        if (item.Tag.Type2 == ETYPE::WindowClass)
        {
            data_stream.write(C(&item.Base), sizeof(ETAG));
            len = 0;
            data_stream.write(C(&len), sizeof(UINT));
        }
        else
        {
            data_stream.write(C(&item.Status), sizeof(EtagStatus));
            data_stream.write(C(&item.Base), sizeof(ETAG));
        }
        WriteString(&data_stream, item.Name);
        WriteString(&data_stream, item.Remark);
        len = item.Methods.size() * sizeof(ETAG);
        data_stream.write(C(&len), sizeof(UINT));
        data_stream.write(C(item.Methods.begin()._Ptr), len);
        WriteVariableVector(&data_stream, item.Variables);
    }
    UINT len = tag_stream.pcount() + offset_stream.pcount();
    stream->write(C(&len), sizeof(UINT));
    stream->write(tag_stream.str(), tag_stream.pcount());
    stream->write(offset_stream.str(), offset_stream.pcount());
    stream->write(data_stream.str(), data_stream.pcount());
}

void WriteMethodVector(ostream* stream, vector<ESection_Program_Method>& list)
{
    ostringstream tag_stream(NULL, 0, ios::binary);
    ostringstream offset_stream(NULL, 0, ios::binary);
    ostringstream data_stream(NULL, 0, ios::binary);
    for (ESection_Program_Method& item : list)
    {
        tag_stream.write(C(&item.Tag), sizeof(ETAG));
        UINT len = data_stream.pcount();
        offset_stream.write(C(&len), sizeof(UINT));
        data_stream.write(C(&item.Class), sizeof(ETAG));
        data_stream.write(C(&item.Attributes), sizeof(EMethodAttr));
        data_stream.write(C(&item.ReturnType), sizeof(DataType));
        WriteString(&data_stream, item.Name);
        WriteString(&data_stream, item.Remark);
        WriteVariableVector(&data_stream, item.Variables);
        WriteVariableVector(&data_stream, item.Parameters);
        len = item.RowOffset.size() * sizeof(BYTE);
        data_stream.write(C(&len), sizeof(UINT));
        data_stream.write(C(item.RowOffset.begin()._Ptr), len);
        len = item.FlowOffset.size() * sizeof(BYTE);
        data_stream.write(C(&len), sizeof(UINT));
        data_stream.write(C(item.FlowOffset.begin()._Ptr), len);
        len = item.MethodOffset.size() * sizeof(BYTE);
        data_stream.write(C(&len), sizeof(UINT));
        data_stream.write(C(item.MethodOffset.begin()._Ptr), len);
        len = item.VariableOffset.size() * sizeof(BYTE);
        data_stream.write(C(&len), sizeof(UINT));
        data_stream.write(C(item.VariableOffset.begin()._Ptr), len);
        len = item.ParameterOffset.size() * sizeof(BYTE);
        data_stream.write(C(&len), sizeof(UINT));
        data_stream.write(C(item.ParameterOffset.begin()._Ptr), len);
        len = item.Code.size() * sizeof(BYTE);
        data_stream.write(C(&len), sizeof(UINT));
        data_stream.write(C(item.Code.begin()._Ptr), len);
    }
    UINT len = tag_stream.pcount() + offset_stream.pcount();
    stream->write(C(&len), sizeof(UINT));
    stream->write(tag_stream.str(), tag_stream.pcount());
    stream->write(offset_stream.str(), offset_stream.pcount());
    stream->write(data_stream.str(), data_stream.pcount());
}

