RayTracerWindow::RayTracerWindow(GLuint width, GLuint height)
	: m_pCameraRaysImage{ nullptr }
{
}

RayTracerWindow::~RayTracerWindow()
{
}

void RayTracerWindow::init(SurfaceRenderer& renderer)
{
	tc::ivec2 size{ renderer.getWidth(), renderer.getHeight() };
	tc::gpu::GPUBackend gpuBackend;

	m_pCameraRaysImage = new tc::BufferResource<tc::cpu::RGBA8, tc::Dim::D2>{ size };
	gpuBackend.uploadImage<tc::InternalFormat::RGBA32F>(*m_pCameraRaysImage);
	m_RayTracerKernel.outData.attach(m_pCameraRaysImage);
	m_VisualizeRaysKernel.inData.attach(m_pCameraRaysImage);
	m_VisualizeRaysKernel.outData.attach(renderer.getRenderBuffer());
}

void RayTracerWindow::compute(SurfaceRenderer& renderer)
{
	tc::gpu::GPUBackend gpuBackend;
	//tc::CPUBackend gpuBackend;

	tc::ivec2 size{ renderer.getWidth(), renderer.getHeight() };

	gpuBackend.useKernel(m_RayTracerKernel);
	gpuBackend.bindImage(m_RayTracerKernel.outData);
	gpuBackend.bindUniform(m_RayTracerKernel.fieldOfView);
	gpuBackend.execute(m_RayTracerKernel, tc::uvec3{ size.x, size.y, 1 });
	gpuBackend.useKernel(m_VisualizeRaysKernel);
	gpuBackend.bindImage(m_VisualizeRaysKernel.inData);
	gpuBackend.bindImage(m_VisualizeRaysKernel.outData);
	gpuBackend.execute(m_VisualizeRaysKernel, tc::uvec3{ size.x, size.y, 1 });
}

