extern "C" int LLVMFuzzerTestOneInput(const uint8_t* Data, size_t Size);

int main(int argc, char* argv[]) {
  for (int index = 1; index < argc; ++index) {
    std::ifstream input_file(argv[index]);
    assert(input_file.is_open());

    input_file.seekg(0, std::ios_base::end);
    const auto file_size = input_file.tellg();
    assert(file_size >= 0);

    input_file.seekg(0, std::ios_base::beg);

    std::vector<char> buffer(static_cast<size_t>(file_size));
    input_file.read(buffer.data(), static_cast<long>(buffer.size()));
    assert(input_file.gcount() == file_size);

    LLVMFuzzerTestOneInput(fmt_fuzzer::as_bytes(buffer.data()), buffer.size());
  }
  return 0;
}

