using namespace testing;

TEST(IterateKeys, ConstMappingIteration) {
    const std::map<int, int> values{
        {1, 1},
        {2, 4},
        {3, 9},
    };
    EXPECT_THAT(
        IterateKeys(values),
        ElementsAre(1, 2, 3)
    );
}

TEST(IterateKeys, ConstMultiMappingIteration) {
    const std::multimap<int, int> pairs{
        {2, 2},
        {5, 3},
        {5, 5},
        {11, 7},
        {11, 11},
        {23, 13},
        {23, 17},
        {23, 23},
    };
    EXPECT_THAT(
        IterateKeys(pairs),
        ElementsAre(2, 5, 5, 11, 11, 23, 23, 23)
    );
}

