#include <ros/init.h>
#include <ros/package.h>
#include <ocs2_sqp/SqpMpc.h>
// #include <ocs2_ddp/GaussNewtonDDP_MPC.h>
#include <ocs2_ros_interfaces/mpc/MPC_ROS_Interface.h>
#include <ocs2_ros_interfaces/synchronized_module/RosReferenceManager.h>
#include <humanoid_wheel_interface/HumanoidWheelInterface.h>

using namespace ocs2;
using namespace mobile_manipulator;

int main(int argc, char** argv) {
  const std::string robotIdentifier = "mobile_manipulator";

  // Initialize ROS node
  ros::init(argc, argv, robotIdentifier + "_mpc");
  ros::NodeHandle nh;

  // Retrieve configuration parameters from the parameter server
  std::string taskConfigPath, libraryPath, robotDescriptionPath;
  nh.getParam("/taskFile", taskConfigPath);
  nh.getParam("/libFolder", libraryPath);
  nh.getParam("/urdfFile", robotDescriptionPath);

  std::cerr << "Loading task file: " << taskConfigPath << std::endl;
  std::cerr << "Loading library folder: " << libraryPath << std::endl;
  std::cerr << "Loading URDF file: " << robotDescriptionPath << std::endl;

  // Robot interface initialization
  HumanoidWheelInterface robotInterface(taskConfigPath, libraryPath, robotDescriptionPath);

  // Setup ROS-based reference manager
  std::shared_ptr<ocs2::RosReferenceManager> refManagerPtr(
      new ocs2::RosReferenceManager(robotIdentifier, robotInterface.getReferenceManagerPtr()));
  refManagerPtr->subscribe(nh);

  // MPC setup using SQP approach
  ocs2::SqpMpc mpcController(robotInterface.mpcSettings(), robotInterface.sqpSettings(),
                             robotInterface.getOptimalControlProblem(), robotInterface.getInitializer());
  mpcController.getSolverPtr()->setReferenceManager(refManagerPtr);

  // Launch MPC ROS interface
  MPC_ROS_Interface mpcRosNode(mpcController, robotIdentifier);
  mpcRosNode.launchNodes(nh);

  return 0;
}

