class ClassroomImplementation : public ClassroomBase
{
  SEN_NOCOPY_NOMOVE(ClassroomImplementation)
public:
  using ClassroomBase::ClassroomBase;
  ~ClassroomImplementation() override
  {
    if (sourceBus_)
    {
      sourceBus_->remove(pupils_);
      sourceBus_->remove(instructor_);
      pupils_.clear();
      instructor_.reset();
      sourceBus_.reset();
    }
  }

public:
  void registered(sen::kernel::RegistrationApi& api) override
  {
    // seed random generator
    srand(static_cast<unsigned>(time(nullptr)));
    // initialize communication channel
    sourceBus_ = api.getSource(getStudentsBus());
    // discover all students (including remote ones)
    studentList_ = api.selectAllFrom<StudentInterface>(getStudentsBus());

    // instantiate the teacher if configured
    if (getCreateTeacher())
    {
      auto [givenName, familyName, completeName] = generateFullName();
      instructor_ = std::make_shared<TeacherImpl>(completeName, givenName, familyName, studentList_);
      setNextTeacherName(completeName);
      // register the teacher on the bus
      sourceBus_->add(instructor_);
    }

    // listen for student events
    std::ignore = studentList_->list.onAdded(
      [&](const auto& iterators)
      {
        for (auto itr = iterators.typedBegin; itr != iterators.typedEnd; ++itr)
        {
          // when noise is detected, randomly select a student to react
          auto callback = [&](const std::string& sound, float32_t loudness)
          {
            pupils_.at(rand() % pupils_.size())->hearSomeNoise(sound, loudness);  // NOLINT
          };
          (*itr)->onMadeSomeNoise({this, std::move(callback)}).keep();
        }
      });

    // populate classroom if default size specified
    if (getDefaultSize() != 0U)
    {
      addStudents(getDefaultSize());
    }
  }

protected:
  void addStudentsImpl(uint32_t count) override
  {
    // prepare storage for new students
    std::vector<std::shared_ptr<StudentImpl>> incomingStudents;
    incomingStudents.reserve(count);

    // create each student
    for (uint32_t index = 0U; index < count; ++index)
    {
      auto [first, last, full] = generateFullName();
      incomingStudents.emplace_back(std::make_shared<StudentImpl>(full, last, first));
    }

    // register new students on bus
    sourceBus_->add(incomingStudents);
    pupils_.insert(pupils_.end(), incomingStudents.begin(), incomingStudents.end());
  }

  void removeStudentsImpl(uint32_t count) override
  {
    // collect students to be removed
    std::vector<std::shared_ptr<StudentImpl>> outgoingStudents;
    outgoingStudents.reserve(count);

    for (std::size_t idx = 0; idx < count && !pupils_.empty(); ++idx)
    {
      outgoingStudents.push_back(pupils_.back());
      pupils_.pop_back();
    }

    sourceBus_->remove(outgoingStudents);
  }

private:
  std::shared_ptr<sen::ObjectSource> sourceBus_;
  std::shared_ptr<TeacherImpl> instructor_;
  std::vector<std::shared_ptr<StudentImpl>> pupils_;
  std::shared_ptr<sen::Subscription<StudentInterface>> studentList_;
};

