// Check if a character is an alphabet letter
int main() {
    char inputChar;
    std::cout << "enter any character";
    std::cin >> inputChar;
    if ((inputChar >= 'A' && inputChar <= 'Z') || (inputChar >= 'a' && inputChar <= 'z'))
        std::cout << "this is an alphabet";
    else
        std::cout << "this is not alphabet";
    return 0;
}

