#include "length.h"
#include <library/cpp/testing/unittest/registar.h>
#include <util/generic/string.h>

Y_UNIT_TEST_SUITE(TestLengthIO_V2) {
    Y_UNIT_TEST(TestLengthLimitedInput_V2) {
        char buffer[32];
        TStringStream stream("xyzw");
        TLengthLimitedInput limiter(&stream, 3);
        UNIT_ASSERT_VALUES_EQUAL(limiter.Load(buffer, 5), 3);
        UNIT_ASSERT_VALUES_EQUAL(limiter.Read(buffer, 1), 0);
    }

    Y_UNIT_TEST(TestCountingInput_V2) {
        char tempBuffer[64];
        TStringStream inputStream("hello\nworld\n");
        TCountingInput counter(&inputStream);
        TString line;
        counter.ReadLine(line);
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 6);
        counter.Load(tempBuffer, 2);
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 8);
        counter.Skip(2);
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 10);
        counter.ReadLine(line);
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 16);
    }

    Y_UNIT_TEST(TestCountingOutput_V2) {
        TStringStream outputStream;
        TCountingOutput writer(&outputStream);
        writer.Write('X');
        UNIT_ASSERT_VALUES_EQUAL(writer.Counter(), 1);
        writer.Write(TString("TEST"));
        UNIT_ASSERT_VALUES_EQUAL(writer.Counter(), 5);
        TString data("DATA");
        IOutputStream::TPart segments[] = {{data.data(), data.size()}, {data.data(), data.size()}};
        writer.Write(segments, 2);
        UNIT_ASSERT_VALUES_EQUAL(writer.Counter(), 13);
