#include <vector>
#include <algorithm>

class Solution {
public:
    // Rotate the given n x n matrix 90 degrees clockwise in-place
    void rotate(std::vector<std::vector<int>>& grid) {
        int size = grid.size();

        // Transpose the matrix: swap elements across the main diagonal
        for (int row = 0; row < size; ++row) {
            for (int col = row + 1; col < size; ++col) {
                std::swap(grid[row][col], grid[col][row]);
            }
        }

        // Reverse each row to complete the 90-degree clockwise rotation
        for (int row = 0; row < size; ++row) {
            std::reverse(grid[row].begin(), grid[row].end());
        }
    }
};

