int main(int argc, char **argv) {
  ros::init(argc, argv, "tofsense_parser");
  ros::NodeHandle node_handle;
  serial::Serial device_serial;
  initSerial(&device_serial);
  NProtocolExtracter protocol_extractor;
  tofsense::Init initializer(&protocol_extractor, &device_serial);
  ros::Rate update_rate(1000);

  while (ros::ok()) {
    auto bytes_available = device_serial.available();
    std::string buffer_received;

    if (bytes_available) {
      device_serial.read(buffer_received, bytes_available);
      protocol_extractor.AddNewData(buffer_received);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

