    Y_UNIT_TEST(TestFileLocker) {
        TTempFileHandle tmp("./test_locker.locker");
        TFileLock lock1("./test_locker.locker");
        TFileLock lock2("./test_locker.locker");
        TFileLock sharedLock1("./test_locker.locker", EFileLockType::Shared);
        TFileLock sharedLock2("./test_locker.locker", EFileLockType::Shared);
        TFileLock sharedLock3("./test_locker.locker", EFileLockType::Shared);

        {
            TGuard<TFileLock> g(lock1);
        }

        {
            TTryGuard<TFileLock> tryG(lock1);
            UNIT_ASSERT(tryG.WasAcquired());
        }

        {
            TGuard<TFileLock> g1(lock1);
            TTryGuard<TFileLock> g2(lock2);
            UNIT_ASSERT(!g2.WasAcquired());
        }

        {
            TGuard<TFileLock> g1(sharedLock1);
            TTryGuard<TFileLock> g2(sharedLock2);
            TTryGuard<TFileLock> g3(sharedLock3);
            UNIT_ASSERT(g2.WasAcquired());
            UNIT_ASSERT(g3.WasAcquired());
        }

