namespace efsw {

// Constructor for WatcherGeneric that initializes directory watching
WatcherGeneric::WatcherGeneric(WatchID watchId, const std::string& dirPath, FileWatchListener* listener,
                               FileWatcherImpl* impl, bool isRecursive) :
    Watcher(watchId, dirPath, listener, isRecursive), 
    WatcherImpl(impl), 
    DirWatch(nullptr) {

    FileSystem::dirAddSlashAtEnd(Directory);
    DirWatch = new DirWatcherGeneric(nullptr, this, dirPath, isRecursive, false);
    DirWatch->addChilds(false);
}

// Destructor cleans up the DirWatcherGeneric instance
WatcherGeneric::~WatcherGeneric() {
    efSAFE_DELETE(DirWatch);
}

// Starts the directory watching process
void WatcherGeneric::watch() {
    DirWatch->watch();
}

// Adds or updates a watched directory path
void WatcherGeneric::watchDir(std::string dir) {
    DirWatch->watchDir(dir);
}

// Checks if a given path is already being monitored
bool WatcherGeneric::pathInWatches(std::string path) {
    return DirWatch->pathInWatches(path);
}

} // namespace efsw

