#include "basics/endian.h"
#include "gtest/gtest.h"
#include "rocksdb_engine_catalog/rocksdb_format.h"
using namespace sdb;
using namespace sdb::basics;

/// Test suite for RocksDBFormat functions
class RocksDBFormatTest : public ::testing::Test {
 protected:
  std::string _buffer;
};

TEST_F(RocksDBFormatTest, little_endian) {
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 1);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()),
            1);
  _buffer.clear();

  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 2048);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()),
            2048);
  _buffer.clear();

  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 999999);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()),
            999999);
  _buffer.clear();

  rocksutils::UintToPersistentLittleEndian<uint32_t>(_buffer, 77777);
  EXPECT_EQ(_buffer.size(), 4);
  EXPECT_EQ(rocksutils::UintFromPersistentLittleEndian<uint32_t>(_buffer.data()),
            77777);
  _buffer.clear();
}

TEST_F(RocksDBFormatTest, big_endian) {
  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 1);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::UintFromPersistentBigEndian<uint64_t>(_buffer.data()), 1);
  _buffer.clear();

  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 2048);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::UintFromPersistentBigEndian<uint64_t>(_buffer.data()),
            2048);
  _buffer.clear();

  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 999999);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::UintFromPersistentBigEndian<uint64_t>(_buffer.data()),
            999999);
  _buffer.clear();

  rocksutils::UintToPersistentBigEndian<uint32_t>(_buffer, 77777);
  EXPECT_EQ(_buffer.size(), 4);
  EXPECT_EQ(rocksutils::UintFromPersistentBigEndian<uint32_t>(_buffer.data()),
            77777);
  _buffer.clear();
}

TEST_F(RocksDBFormatTest, specialized_big_endian) {
  rocksutils::Uint32ToPersistent(_buffer, 1);
  EXPECT_EQ(_buffer.size(), 4);
  EXPECT_EQ(rocksutils::Uint32FromPersistent(_buffer.data()), 1);
  _buffer.clear();

  rocksutils::Uint16ToPersistent(_buffer, 2048);
  EXPECT_EQ(_buffer.size(), 2);
  EXPECT_EQ(rocksutils::Uint16FromPersistent(_buffer.data()), 2048);
  _buffer.clear();

  rocksutils::Uint64ToPersistent(_buffer, 999999);
  EXPECT_EQ(_buffer.size(), 8);
  EXPECT_EQ(rocksutils::Uint64FromPersistent(_buffer.data()), 999999);
  _buffer.clear();
}

