void PackedReadWriteCore(const std::vector<uint32_t>& source) {
  static constexpr size_t BLOCK_SIZE = 128;
  uint32_t temp_encoded[BLOCK_SIZE];
  const auto num_blocks = source.size() / BLOCK_SIZE;
  SDB_ASSERT(num_blocks);
  // compress data to stream
  irs::bstring buffer;
  irs::BytesOutput output(buffer);
  auto pack_func = [](const uint32_t* decoded, uint32_t* encoded,
                 const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + BLOCK_SIZE, encoded, bits);
  };
  auto unpack_func = [](uint32_t* decoded, const uint32_t* encoded,
                   const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + BLOCK_SIZE, encoded, bits);
  };
  // write first n compressed blocks
  {
    auto data_ptr = source.data();
    for (size_t block_idx = 0; block_idx < num_blocks; ++block_idx) {
      irs::bitpack::write_block32(pack_func, output, data_ptr, temp_encoded, BLOCK_SIZE);
      data_ptr += BLOCK_SIZE;
    }
  }
  // decompress data from stream
  std::vector<uint32_t> read_buffer(source.size());
  irs::BytesViewInput input(buffer);
  // read first n compressed blocks
  {
    auto read_ptr = read_buffer.data();
    for (size_t block_idx = 0; block_idx < num_blocks; ++block_idx) {
      irs::bitpack::read_block32(unpack_func, input, temp_encoded, read_ptr, BLOCK_SIZE);
      read_ptr += BLOCK_SIZE;
    }
  }
  ASSERT_EQ(source, read_buffer);
}
