                 const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + BLOCK_SIZE, encoded, bits);
  };
  auto unpack_func = [](uint32_t* decoded, const uint32_t* encoded,
                   const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + BLOCK_SIZE, encoded, bits);
  };
  // compress data to stream
  irs::bstring buffer;
  irs::BytesOutput output(buffer);
  irs::bitpack::write_block32(pack_func, output, source.data(), temp_encoded, BLOCK_SIZE);
  // decompress data from stream
  std::vector<uint32_t> read_buffer(source.size());
  irs::BytesViewInput input(buffer);
  irs::bitpack::read_block32(unpack_func, input, temp_encoded, read_buffer.data(), BLOCK_SIZE);
