template<typename T>
void ReadWriteCore(const std::vector<T>& source,
                   const std::function<T(DataInput&)>& reader,
                   const std::function<void(DataOutput&, T)>& writer) {
  irs::bstring buffer;
  irs::BytesOutput output(buffer);
  std::for_each(source.begin(), source.end(),
                [&output, &writer](const T& val) { writer(output, val); });
  BytesInput input(buffer);
  std::for_each(source.begin(), source.end(),
                [&input, &reader](const T& val) { ASSERT_EQ(val, reader(input)); });
}
