  auto pack_func = [&](const uint32_t* decoded, uint32_t* encoded,
                  const uint32_t bits) {
    irs::packed::Pack(decoded, decoded + size, encoded, bits);
  };
  auto unpack_func = [&](uint32_t* decoded, const uint32_t* encoded,
                    const uint32_t bits) {
    irs::packed::Unpack(decoded, decoded + size, encoded, bits);
  };
