// clang-format off
asm void __init_hardware(void)
{
    nofralloc
    mfmsr r0
    ori r0, r0, 0x2000
    mtmsr r0
    mflr r31
    bl __OSPSInit
    bl __OSFPRInit
    bl __OSCacheInit
    mtlr r31
    blr
}
// clang-format on

// clang-format off
asm void __flush_cache(register void *addr, register unsigned int len)
{
    nofralloc
    lis r5,  ~0
    ori r5, r5, ~14
    and r5, r5, r3
    subf r3, r5, r3
    add r4, r4, r3
loop:    
    dcbst r0, r5
    sync
    icbi r0, r5
    addic r5, r5, 8
    subic. r4, r4, 8    
    bge loop
    isync
    blr
}
// clang-format on

void __init_user()
{
    __init_cpp();
}

typedef void (*voidfunctionptr)(void); // pointer to function returning void

__declspec(section ".init") extern voidfunctionptr _ctors[];
__declspec(section ".init") extern voidfunctionptr _dtors[];

void __init_cpp(void)
{
    voidfunctionptr *constructor;
    /*
     *	call static initializers
     */
    for (constructor = _ctors; *constructor; constructor++) {
        (*constructor)();
    }
}

