UIScene_SettingsAudioMenu::UIScene_SettingsAudioMenu(int controllerID, void *initialData, UILayer *layerParent) : UIScene(controllerID, layerParent)
{
	// Initialize required Iggy references for this scene
	initialiseMovie();
	WCHAR Buffer[256];	
	swprintf(Buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_MUSIC), app.GetGameSettings(controllerID, eGameSetting_MusicVolume));	
	m_sliderMusic.init(Buffer, eControl_Music, 0, 100, app.GetGameSettings(controllerID, eGameSetting_MusicVolume));

	swprintf(Buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_SOUND), app.GetGameSettings(controllerID, eGameSetting_SoundFXVolume));	
	m_sliderSound.init(Buffer, eControl_Sound, 0, 100, app.GetGameSettings(controllerID, eGameSetting_SoundFXVolume));
	doHorizontalResizeCheck();
	if(app.GetLocalPlayerCount() > 1)
	{
#if TO_BE_IMPLEMENTED
		app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, controllerID);
#endif
	}
}

UIScene_SettingsAudioMenu::~UIScene_SettingsAudioMenu()
{
}

std::wstring UIScene_SettingsAudioMenu::getMoviePath()
{
	if(app.GetLocalPlayerCount() > 1)
	{
		return L"SettingsAudioMenuSplit";
	}
	else
	{
		return L"SettingsAudioMenu";
	}
}

void UIScene_SettingsAudioMenu::updateTooltips()
{
	ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
}

void UIScene_SettingsAudioMenu::updateComponents()
{
	bool bNotInGame = (Minecraft::GetInstance()->level == NULL);
	if(bNotInGame)
	{
		m_parentLayer->showComponent(m_iPad, eUIComponent_Panorama, true);
		m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, true);
	}
	else
	{
		m_parentLayer->showComponent(m_iPad, eUIComponent_Panorama, false);
		if(app.GetLocalPlayerCount() == 1)
			m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, true);
		else
			m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, false);
	}
}

void UIScene_SettingsAudioMenu::handleInput(int controllerID, int inputKey, bool isRepeat, bool isPressed, bool isReleased, bool &handled)
{
	ui.AnimateKeyPress(m_iPad, inputKey, isRepeat, isPressed, isReleased);
	switch(inputKey)
	{
	case ACTION_MENU_CANCEL:
		if(isPressed)
		{
			navigateBack();
		}
		break;
	case ACTION_MENU_OK:
#ifdef __ORBIS__
	case ACTION_MENU_TOUCHPAD_PRESS:
#endif
		sendInputToMovie(inputKey, isRepeat, isPressed, isReleased);
		break;
	case ACTION_MENU_UP:
	case ACTION_MENU_DOWN:
	case ACTION_MENU_LEFT:
	case ACTION_MENU_RIGHT:
		sendInputToMovie(inputKey, isRepeat, isPressed, isReleased);
		break;
	}
}

void UIScene_SettingsAudioMenu::handleSliderMove(F64 sliderIdentifier, F64 newValue)
{
	WCHAR Buffer[256];
	int value = static_cast<int>(newValue);
	switch(static_cast<int>(sliderIdentifier))
	{
	case eControl_Music:
		m_sliderMusic.handleSliderMove(value);
		app.SetGameSettings(m_iPad, eGameSetting_MusicVolume, value);	
		swprintf(Buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_MUSIC), value);	
		m_sliderMusic.setLabel(Buffer);
		break;
	case eControl_Sound:
		m_sliderSound.handleSliderMove(value);
		app.SetGameSettings(m_iPad, eGameSetting_SoundFXVolume, value);
		swprintf(Buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_SOUND), value);
		m_sliderSound.setLabel(Buffer);
		break;
	}
}

