  IO.mapRequired("ReferencedBy", RefData.FileRefs);
}

void ScalarBitSetTraits<eld::LDYAML::SegmentType>::bitset(
    IO &IO, eld::LDYAML::SegmentType &SegmentTypeInfo) {
  IO.bitSetCase(SegmentTypeInfo, "PT_PHDR", llvm::ELF::PT_PHDR);
  IO.bitSetCase(SegmentTypeInfo, "PT_INTERP", llvm::ELF::PT_INTERP);
  IO.bitSetCase(SegmentTypeInfo, "PT_LOAD", llvm::ELF::PT_LOAD);
  IO.bitSetCase(SegmentTypeInfo, "PT_NOTE", llvm::ELF::PT_NOTE);
  IO.bitSetCase(SegmentTypeInfo, "PT_DYNAMIC", llvm::ELF::PT_DYNAMIC);
  IO.bitSetCase(SegmentTypeInfo, "PT_TLS", llvm::ELF::PT_TLS);
}

void ScalarBitSetTraits<eld::LDYAML::SegmentPermissions>::bitset(
    IO &IO, eld::LDYAML::SegmentPermissions &SegPermissionFlags) {
  IO.bitSetCase(SegPermissionFlags, "READ", llvm::ELF::PF_R);
  IO.bitSetCase(SegPermissionFlags, "WRITE", llvm::ELF::PF_W);
  IO.bitSetCase(SegPermissionFlags, "EXECUTE", llvm::ELF::PF_X);
  IO.bitSetCase(SegPermissionFlags, "OS_SPECIFIC", llvm::ELF::PF_MASKOS);
  IO.bitSetCase(SegPermissionFlags, "PROCESSOR_SPECIFIC",
                llvm::ELF::PF_MASKPROC);
}

void ScalarEnumerationTraits<eld::LDYAML::InputUsed>::enumeration(
    IO &IO, eld::LDYAML::InputUsed &InputUsage) {
  IO.enumCase(InputUsage, "NotUsed", false);
  IO.enumCase(InputUsage, "Used", true);
}

void MappingTraits<std::shared_ptr<eld::LDYAML::InputFile>>::mapping(
    IO &IO, std::shared_ptr<eld::LDYAML::InputFile> &InputFilePtr) {
  if (InputFilePtr) {
    InputFilePtr->mapping(IO);
    return;
  }
  std::vector<llvm::StringRef> Keys = IO.keys();
  if (llvm::find(Keys, "Members") == Keys.end()) {
    InputFilePtr = std::make_shared<eld::LDYAML::RegularInput>();
  } else {
    InputFilePtr = std::make_shared<eld::LDYAML::Archive>();
  }
  InputFilePtr->mapping(IO);
}

void eld::LDYAML::RegularInput::mapping(IO &IO) {
  MappingTraits<eld::LDYAML::RegularInput>::mapping(IO, *this);
}

void MappingTraits<eld::LDYAML::RegularInput>::mapping(
    IO &IO, eld::LDYAML::RegularInput &RegInput) {
  IO.mapRequired("Path", RegInput.Name);
  IO.mapRequired("Used", RegInput.Used);
}

void eld::LDYAML::Archive::mapping(IO &IO) {
  MappingTraits<eld::LDYAML::Archive>::mapping(IO, *this);
}

void MappingTraits<eld::LDYAML::Archive>::mapping(IO &IO,
                                                  eld::LDYAML::Archive &ArchData) {
  IO.mapRequired("Path", ArchData.Name);
  IO.mapRequired("Used", ArchData.Used);
  IO.mapOptional("Members", ArchData.ArchiveMembers);
}

void eld::LDYAML::TrampolineInfo::mapping(IO &IO) {
  MappingTraits<eld::LDYAML::TrampolineInfo>::mapping(IO, *this);
}

void MappingTraits<eld::LDYAML::TrampolineInfo>::mapping(
    IO &IO, eld::LDYAML::TrampolineInfo &TrampInfo) {
  IO.mapRequired("OutputSection", TrampInfo.OutputSectionName);
  IO.mapRequired("Trampolines", TrampInfo.Trampolines);
}

void MappingTraits<eld::LDYAML::Trampoline>::mapping(
    IO &IO, eld::LDYAML::Trampoline &TrampData) {
  IO.mapRequired("Name", TrampData.Name);
  IO.mapRequired("From", TrampData.From);
  IO.mapOptional("FromSymbols", TrampData.FromSymbols);
  IO.mapRequired("Origin", TrampData.FromFile);
  IO.mapRequired("To", TrampData.To);
  IO.mapRequired("ToSection", TrampData.ToSection);
  IO.mapOptional("ToSymbols", TrampData.ToSymbols);
  IO.mapRequired("Destination", TrampData.ToFile);
  IO.mapOptional("Addend", TrampData.Addend);
  IO.mapOptional("Uses", TrampData.Uses);
}

void MappingTraits<eld::LDYAML::Reuse>::mapping(IO &IO, eld::LDYAML::Reuse &ReuseData) {
  IO.mapRequired("From", ReuseData.From);
  IO.mapOptional("Symbols", ReuseData.Symbols);
  IO.mapRequired("Origin", ReuseData.FromFile);
  IO.mapOptional("Addend", ReuseData.Addend);
}

