#define HIP_ERROR_CHECK(expr)                         \
{                                                     \
    const hipError_t err = (expr);                    \
    if (err != hipSuccess)                            \
    {                                                 \
        std::cerr << "HIP error " << err              \
                  << ": " << hipGetErrorString(err)   \
                  << " at " << __FILE__ << ":"        \
                  << __LINE__ << std::endl;           \
        std::exit(EXIT_FAILURE);                      \
    }                                                 \
}

int main() {
    int numDevices;
    HIP_ERROR_CHECK(hipGetDeviceCount(&numDevices));
    std::cout << "Total devices available: " << numDevices << std::endl;

    for (int devId = 0; devId < numDevices; ++devId) {
        hipDeviceProp_t deviceInfo;
        HIP_ERROR_CHECK(hipGetDeviceProperties(&deviceInfo, devId));

        std::cout << "Device " << devId << std::endl
                  << " Specifications:" << std::endl;
        std::cout << "  Model Name: " << deviceInfo.name << std::endl;
        std::cout << "  Global Memory: " << deviceInfo.totalGlobalMem / (1024 * 1024) << " MiB" << std::endl;
        std::cout << "  Shared Memory per Block: " << deviceInfo.sharedMemPerBlock / 1024 << " KiB" << std::endl;
        std::cout << "  Registers per Block: " << deviceInfo.regsPerBlock << std::endl;
        std::cout << "  Warp Size: " << deviceInfo.warpSize << std::endl;
        std::cout << "  Max Threads in a Block: " << deviceInfo.maxThreadsPerBlock << std::endl;
        std::cout << "  Max Threads per Multiprocessor: " << deviceInfo.maxThreadsPerMultiProcessor << std::endl;
        std::cout << "  Multiprocessor Count: " << deviceInfo.multiProcessorCount << std::endl;
        std::cout << "  Max Thread Dimensions: ["
                  << deviceInfo.maxThreadsDim[0] << ", "
                  << deviceInfo.maxThreadsDim[1] << ", "
                  << deviceInfo.maxThreadsDim[2] << "]" << std::endl;
        std::cout << "  Max Grid Dimensions: ["
                  << deviceInfo.maxGridSize[0] << ", "
                  << deviceInfo.maxGridSize[1] << ", "
                  << deviceInfo.maxGridSize[2] << "]" << std::endl;
        std::cout << std::endl;
    }

    return EXIT_SUCCESS;
}

