Here's the cloned version:

```cpp
#include "bitpacking.h"
#include <cstdint>
#include <type_traits>

namespace {
// Unpack single value for 8-bit input when bits fit in one byte
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) < 8>::type extract_value(const uint8_t *__restrict source,
                                                                 uint8_t *__restrict destination) {
  *destination = ((*source) >> SHIFT) % (1 << BITS);
}

// Unpack single value for 8-bit input when bits span two bytes
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) >= 8>::type extract_value(const uint8_t *__restrict &source,
                                                                  uint8_t *__restrict destination) {
  *destination = (*source) >> SHIFT;
  ++source;
  static const uint8_t NEXT_SHIFT = SHIFT + BITS - 8;
  *destination |= ((*source) % (1U << NEXT_SHIFT)) << (8 - SHIFT);
}

// Unpack single value for 16-bit input when bits fit in one word
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) < 16>::type extract_value(const uint16_t *__restrict source,
                                                                  uint16_t *__restrict destination) {
  *destination = ((*source) >> SHIFT) % (1 << BITS);
}

// Unpack single value for 16-bit input when bits span two words
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) >= 16>::type extract_value(const uint16_t *__restrict &source,
                                                                   uint16_t *__restrict destination) {
  *destination = (*source) >> SHIFT;
  ++source;
  static const uint8_t NEXT_SHIFT = SHIFT + BITS - 16;
  *destination |= ((*source) % (1U << NEXT_SHIFT)) << (16 - SHIFT);
}

// Unpack single value for 32-bit input when bits fit in one word
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) < 32>::type extract_value(
    const uint32_t *__restrict source, uint32_t *__restrict destination) {
  *destination = ((*source) >> SHIFT) % (1 << BITS);
}

// Unpack single value for 32-bit input when bits span two words
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) >= 32>::type extract_value(
    const uint32_t *__restrict &source, uint32_t *__restrict destination) {
  *destination = (*source) >> SHIFT;
  ++source;
  static const uint8_t NEXT_SHIFT = SHIFT + BITS - 32;
  *destination |= ((*source) % (1U << NEXT_SHIFT)) << (32 - SHIFT);
}

// Unpack single value for 32-bit input to 64-bit output when bits fit in one word
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) < 32>::type extract_value(
    const uint32_t *__restrict source, uint64_t *__restrict destination) {
  *destination = ((static_cast<uint64_t>(*source)) >> SHIFT) % (1ULL << BITS);
}

// Unpack single value for 32-bit input to 64-bit output when bits span two words
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) >= 32 && (BITS + SHIFT) < 64>::type
extract_value(const uint32_t *__restrict &source,
              uint64_t *__restrict destination) {
  *destination = static_cast<uint64_t>(*source) >> SHIFT;
  ++source;
  if (BITS + SHIFT > 32) {
    static const uint8_t NEXT_SHIFT = SHIFT + BITS - 32;
    *destination |= static_cast<uint64_t>((*source) % (1U << NEXT_SHIFT)) << (32 - SHIFT);
  }
}

// Unpack single value for 32-bit input to 64-bit output when bits span three words
template <uint8_t BITS, uint8_t SHIFT>
typename std::enable_if<(BITS + SHIFT) >= 64>::type extract_value(
    const uint32_t *__restrict &source, uint64_t *__restrict destination) {
  *destination = static_cast<uint64_t>(*source) >> SHIFT;
  ++source;
  *destination |= static_cast<uint64_t>(*source) << (32 - SHIFT);
  ++source;
  if (BITS + SHIFT > 64) {
    static const uint8_t NEXT_SHIFT = BITS + SHIFT - 64;
    *destination |= static_cast<uint64_t>((*source) % (1U << NEXT_SHIFT)) << (64 - SHIFT);
  }
}

// Pack single value into 32-bit output when bits fit in one word
template <uint16_t BITS, uint16_t SHIFT, uint32_t MASK>
    typename std::enable_if <
    BITS + SHIFT < 32>::type insert_value(const uint32_t value,
                                         uint32_t *__restrict target) {
  if (SHIFT == 0) {
    *target = value & MASK;
  } else {
    *target |= (value & MASK) << SHIFT;
  }
}

// Pack single value into 32-bit output when bits span two words
template <uint16_t BITS, uint16_t SHIFT, uint32_t MASK>
typename std::enable_if<BITS + SHIFT >= 32>::type insert_value(
    const uint32_t value, uint32_t *__restrict &target) {
  *target |= value << SHIFT;
  ++target;
  if (BITS + SHIFT > 32) {
    *target = (value & MASK) >> (32 - SHIFT);
  }
}

