}

// Unroller for 8-bit data with template recursion
template <uint16_t BITS, uint16_t INDEX = 0>
struct Unroller8 {
  static void Extract(const uint8_t *__restrict &source, uint8_t *__restrict dest) {
    extract_value<BITS, (BITS * INDEX) % 8>(source, dest + INDEX);
    Unroller8<BITS, INDEX + 1>::Extract(source, dest);
  }
  static void Insert(const uint8_t *__restrict source, uint8_t *__restrict dest) {
    insert_value<BITS, (BITS * INDEX) % 8, (1U << BITS) - 1>(source[INDEX], dest);
    Unroller8<BITS, INDEX + 1>::Insert(source, dest);
  }
};

// Specialization for last element in 8-bit unroller
template <uint16_t BITS>
struct Unroller8<BITS, 7> {
  enum { SHIFT = (BITS * 7) % 8 };
  static void Extract(const uint8_t *__restrict source, uint8_t *__restrict dest) {
    dest[7] = (*source) >> SHIFT;
  }
  static void Insert(const uint8_t *__restrict source, uint8_t *__restrict dest) {
    *dest |= (source[7] << SHIFT);
  }
};

