	extract_value<BITS, (BITS * INDEX) % 16>(source, dest + INDEX);
	Unroller16<BITS, INDEX + 1>::Extract(source, dest);
  }
  static void Insert(const uint16_t *__restrict source, uint16_t *__restrict dest) {
