// General unroller for 32-bit data with template recursion
template <uint16_t BITS, uint16_t INDEX = 0>
struct Unroller {
  static void Extract(const uint32_t *__restrict &source,
                     uint32_t *__restrict dest) {
    extract_value<BITS, (BITS * INDEX) % 32>(source, dest + INDEX);
    Unroller<BITS, INDEX + 1>::Extract(source, dest);
  }
  static void Extract(const uint32_t *__restrict &source,
                     uint64_t *__restrict dest) {
    extract_value<BITS, (BITS * INDEX) % 32>(source, dest + INDEX);
    Unroller<BITS, INDEX + 1>::Extract(source, dest);
  }
  static void Insert(const uint32_t *__restrict source,
                   uint32_t *__restrict dest) {
    insert_value<BITS, (BITS * INDEX) % 32, (1U << BITS) - 1>(source[INDEX],
                                                                    dest);
    Unroller<BITS, INDEX + 1>::Insert(source, dest);
  }
  static void Insert(const uint64_t *__restrict source,
                   uint32_t *__restrict dest) {
    insert_value64<BITS, (BITS * INDEX) % 32, (1ULL << BITS) - 1>(
        source[INDEX], dest);
    Unroller<BITS, INDEX + 1>::Insert(source, dest);
  }
  static void InsertNoMask(const uint32_t *__restrict source,
                         uint32_t *__restrict dest) {
    insert_value<BITS, (BITS * INDEX) % 32, uint32_t(-1)>(source[INDEX], dest);
    Unroller<BITS, INDEX + 1>::InsertNoMask(source, dest);
  }
  static void InsertNoMask(const uint64_t *__restrict source,
                         uint32_t *__restrict dest) {
    insert_value64<BITS, (BITS * INDEX) % 32, uint64_t(-1)>(source[INDEX],
                                                                 dest);
    Unroller<BITS, INDEX + 1>::InsertNoMask(source, dest);
  }
};

// Specialization for last element in general unroller
template <uint16_t BITS>
struct Unroller<BITS, 31> {
  enum { SHIFT = (BITS * 31) % 32 };
  static void Extract(const uint32_t *__restrict source,
                     uint32_t *__restrict dest) {
    dest[31] = (*source) >> SHIFT;
  }
  static void Extract(const uint32_t *__restrict source,
                     uint64_t *__restrict dest) {
    dest[31] = (*source) >> SHIFT;
    if (BITS > 32) {
      ++source;
      dest[31] |= static_cast<uint64_t>(*source) << (32 - SHIFT);
    }
  }
  static void Insert(const uint32_t *__restrict source,
                   uint32_t *__restrict dest) {
    *dest |= (source[31] << SHIFT);
  }
  static void Insert(const uint64_t *__restrict source,
                   uint32_t *__restrict dest) {
    *dest |= (source[31] << SHIFT);
    if (BITS > 32) {
      ++dest;
      *dest = static_cast<uint32_t>(source[31] >> (32 - SHIFT));
    }
  }
  static void InsertNoMask(const uint32_t *__restrict source,
                         uint32_t *__restrict dest) {
    *dest |= (source[31] << SHIFT);
  }
  static void InsertNoMask(const uint64_t *__restrict source,
                         uint32_t *__restrict dest) {
    *dest |= (source[31] << SHIFT);
    if (BITS > 32) {
      ++dest;
      *dest = static_cast<uint32_t>(source[31] >> (32 - SHIFT));
    }
  }
};
