SubscriberListener::SubscriberListener(const NewMsgCallback& cb) : callback_(cb) {}

SubscriberListener::~SubscriberListener() {
  std::lock_guard<std::mutex> guard(mutex_);
  callback_ = nullptr;
}

void SubscriberListener::onNewDataMessage(eprosima::fastrtps::Subscriber* subscriber) {
  RETURN_IF_NULL(callback_);
  std::lock_guard<std::mutex> lock(mutex_);
  eprosima::fastrtps::SampleInfo_t sample_info;
  autolink::transport::UnderlayMessage message;
  RETURN_IF(!subscriber->takeNextData(reinterpret_cast<void*>(&message), &sample_info));
  RETURN_IF(sample_info.sampleKind != eprosima::fastrtps::rtps::ALIVE);
  callback_(message.data());
}

void SubscriberListener::onSubscriptionMatched(eprosima::fastrtps::Subscriber* sub,
                                               eprosima::fastrtps::rtps::MatchingInfo& match_info) {
  (void)sub;
  (void)match_info;
}

