#include "test.h"
TEST_CASE("log::Levels") {
    SECTION("Conversion from string") {
        for (auto level : LevelSet{}) {
            REQUIRE(log::mapLogLevel(_ts(EnumIndex(level))) == level);
        }
    }
    SECTION("Case-insensitive conversion from string") {
        for (auto level : LevelSet{}) {
            REQUIRE(log::mapLogLevel(_ts(EnumIndex(level)).upperCase()) == level);
        }
    }
    SECTION("Basic test") {
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Error));
        log::enableLevel("dev,perf");
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Error));
    }
    SECTION("Enable/disable single level") {
        log::enableLevel(Lvl::Work);
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        log::disableLevel(Lvl::Work);
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
    }
    SECTION("Sticky bit behavior") {
        log::enableLevel<true>(Lvl::Work);
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        log::disableAllLevels();
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        log::disableLevel(Lvl::Work);
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
    }
    SECTION("Multiple enable calls") {
        log::enableLevel(Lvl::Work, Lvl::Work);
        log::disableLevel(Lvl::File);
        REQUIRE(log::isLevelEnabled(Lvl::Work, Lvl::Work));
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work, Lvl::File));
        SECTION("Multiple disable calls") {
            log::disableLevel(Lvl::Work, Lvl::Work, Lvl::File);
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work, Lvl::File));
        }
    }
    SECTION("Multiple name-based enable") {
        log::enableLevel("WORK", "WORK");
        log::disableLevel("CONNECTION");
        REQUIRE(log::isLevelEnabled("WORK", "WORK"));
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));
        SECTION("Multiple name-based disable") {
            log::disableLevel("WORK", "WORK", "CONNECTION");
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));
        }
    }
    SECTION("Name-based enable with leading/trailing whitespace") {
        log::enableLevel(" WORK", " WORK ");
        log::disableLevel(" CONNECTION");
        REQUIRE(log::isLevelEnabled("WORK", "WORK"));
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));
        SECTION(
            "Name-based disable with leading/trailing whitespace") {
            log::disableLevel(" WORK ", " WORK ", " CONNECTION ");
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));
        }
    }
}

#include <stdio.h>

int main() {
    int firstNumber, secondNumber, result, tempValue, choice;

    printf("Select an operation:\n");
    printf("1. Addition of two numbers\n");
    printf("2. Subtraction of two numbers\n");
    printf("3. Square of a number\n");
    printf("4. Cube of a number\n");
    printf("5. Division by 2\n");
    printf("Enter your choice: ");
    scanf("%d", &choice);

    switch(choice) {
        case 1:
            printf("Enter two numbers: ");
            scanf("%d %d", &firstNumber, &secondNumber);
            result = firstNumber + secondNumber;
            printf("Sum = %d\n", result);
            break;

        case 2:
            printf("Enter two numbers: ");
            scanf("%d %d", &firstNumber, &secondNumber);
            result = firstNumber - secondNumber;
            printf("Difference = %d\n", result);
            break;

        case 3:
            printf("Enter a number: ");
            scanf("%d", &tempValue);
            result = tempValue * tempValue;
            printf("Square = %d\n", result);
            break;

        case 4:
            printf("Enter a number: ");
            scanf("%d", &tempValue);
            result = tempValue * tempValue * tempValue;
            printf("Cube = %d\n", result);
            break;

        case 5:
            printf("Enter a number: ");
            scanf("%d", &firstNumber);
            result = firstNumber / 2;
            printf("Result = %d\n", result);
            break;

        default:
            printf("Invalid option selected!\n");
            break;
    }

    return 0;
}

