#include <vector>
#include "test_config.h"

int main(int argc, char** argv) {
    testing_config::TestSizeConfig parameters{};
    CLI::App program{"SUROGATE unit tests"};
    program.allow_extras();
    program.add_option("-B, --batch", parameters.B, "Batch size (B)");
    program.add_option("-T, --seq",   parameters.T, "Sequence length (T)");
    program.add_option("-C, --channels", parameters.C, "Channel size (C)");
    program.add_option("--query-heads", parameters.Nq, "Query heads (Nq)");
    program.add_option("--kv-heads", parameters.Nkv, "Key/Value heads (Nkv)");

    std::vector<std::string> leftover;
    try {
        program.parse(argc, argv);
        leftover = program.remaining();
    } catch (const CLI::ParseError &err) {
        return program.exit(err);
    }

    testing_config::set_test_config(parameters);

    // Pass remaining arguments to Catch2
    std::vector<const char*> arg_list;
    arg_list.reserve(1 + leftover.size());
    arg_list.push_back(argv[0]);
    for (const auto& str : leftover) {
        arg_list.push_back(str.c_str());
    }

    return Catch::Session().run((int)arg_list.size(), const_cast<char**>(arg_list.data()));
}

