#include "valdi_protobuf/FullyQualifiedName.hpp"
#include "gtest/gtest.h"
#include <algorithm>
#include <google/protobuf/descriptor.pb.h>
using namespace Valdi;
namespace {
TEST(FullyQualifiedName, canInitializeWithSinglePackage) {
    Protobuf::FullyQualifiedName fqname("com");
    ASSERT_EQ("", fqname.getLeadingComponents());
    ASSERT_EQ("com", fqname.getLastComponent());
}
TEST(FullyQualifiedName, canInitializeWithNestedPackage) {
    Protobuf::FullyQualifiedName fqname("com.valdi");
    ASSERT_EQ("com", fqname.getLeadingComponents());
    ASSERT_EQ("valdi", fqname.getLastComponent());
    fqname = Protobuf::FullyQualifiedName("com.valdi.MyType");
    ASSERT_EQ("com.valdi", fqname.getLeadingComponents());
    ASSERT_EQ("MyType", fqname.getLastComponent());
}
TEST(FullyQualifiedName, supportsAppendOperation) {
    Protobuf::FullyQualifiedName fqname;
    ASSERT_EQ("", fqname.getLeadingComponents());
    ASSERT_EQ("", fqname.getLastComponent());
    fqname.append("com");
    ASSERT_EQ("", fqname.getLeadingComponents());
    ASSERT_EQ("com", fqname.getLastComponent());
    fqname.append("valdi");
    ASSERT_EQ("com", fqname.getLeadingComponents());
    ASSERT_EQ("valdi", fqname.getLastComponent());
    fqname.append("nested.MyType");
    ASSERT_EQ("com.valdi.nested", fqname.getLeadingComponents());
    ASSERT_EQ("MyType", fqname.getLastComponent());
}
TEST(FullyQualifiedName, canStripLastComponent) {
    Protobuf::FullyQualifiedName fqname("com.valdi.MyType");
    ASSERT_EQ("com.valdi", fqname.getLeadingComponents());
    ASSERT_EQ("MyType", fqname.getLastComponent());
    ASSERT_TRUE(fqname.canRemoveLastComponent());
    fqname = fqname.removingLastComponent();
    ASSERT_EQ("com", fqname.getLeadingComponents());
    ASSERT_EQ("valdi", fqname.getLastComponent());
    ASSERT_TRUE(fqname.canRemoveLastComponent());
    fqname = fqname.removingLastComponent();
    ASSERT_EQ("", fqname.getLeadingComponents());
    ASSERT_EQ("com", fqname.getLastComponent());
    ASSERT_FALSE(fqname.canRemoveLastComponent());
}
TEST(FullyQualifiedName, canSerializeToString) {
    Protobuf::FullyQualifiedName fqname("com.valdi.MyType");
    ASSERT_EQ("com.valdi.MyType", fqname.toString());
    fqname = Protobuf::FullyQualifiedName("MyType");
    ASSERT_EQ("MyType", fqname.toString());
}
} // namespace

