#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_A.h"
#include "llk_unpack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
    // Configure unpack hardware with face dimensions and number of faces
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        formats.unpack_A_src, formats.unpack_B_src, formats.unpack_A_dst, formats.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, 4U /* num_faces */, 4U /* num_faces */);

    // Initialize unpack A operation for tensor A
    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        0U, 0U, FACE_R_DIM, 4U, formats.unpack_A_src, formats.unpack_A_dst);

    // Process each tile in the input buffer
    for (int tile_idx = 0; tile_idx < params->TILE_CNT; ++tile_idx)
    {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(params->buffer_A[tile_idx]), formats.unpack_A_src, formats.unpack_A_dst);
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "ckernel_sfpu.h"
#include "llk_math_common.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "llk_math_eltwise_unary_sfpu.h"
#include "params.h"

using namespace ckernel;
using namespace ckernel::sfpu;

void run_kernel(const volatile struct RuntimeParams* params)
{
    // Copy source A to destination register
#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(4U, formats.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(4U, formats.math);
#endif

    // Initialize packer synchronization and configure math unit
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(formats.math, formats.math);

    // Wait until destination buffer is ready
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Process each tile: copy data from src to dest
    for (std::uint32_t tile_id = 0; tile_id < params->TILE_CNT; ++tile_id)
    {
        LLK_ASSERT(
            (tile_id < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()),
            "Block tile index exceeds maximum destination tiles");
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tile_id, formats.math, formats.math);
    }

    // Initialize Sfpu reduce operation
    _llk_math_eltwise_unary_sfpu_init_<SfpuType::reduce>();
    ckernel::sfpu::_init_reduce_<POOL_TYPE, static_cast<DataFormat>(formats.math)>();

    if (REDUCE_DIM == ReduceDim::REDUCE_COL)
    {
        // Column-wise reduction: process each tile individually
        for (std::uint32_t tile_num = 0; tile_num < params->TILE_CNT; ++tile_num)
        {
            LLK_ASSERT(
                (tile_num < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()),
                "Block tile index exceeds maximum destination tiles");
            _llk_math_eltwise_unary_sfpu_start_<DstSync::SyncHalf>(tile_num);
            ckernel::sfpu::_calculate_reduce_<POOL_TYPE, REDUCE_DIM, static_cast<DataFormat>(formats.math)>();
        }
    }
    else if (REDUCE_DIM == ReduceDim::REDUCE_ROW)
    {
        // Row-wise reduction: single call with full block dimensions
        _llk_math_eltwise_unary_sfpu_start_<DstSync::SyncHalf>(0U);
        ckernel::sfpu::_calculate_reduce_<POOL_TYPE, REDUCE_DIM, static_cast<DataFormat>(formats.math)>(
            BLOCK_CT_DIM, BLOCK_RT_DIM);
    }

#ifdef ADD_TOP_ROW
    // Add top row accumulation step
    _llk_math_eltwise_binary_sfpu_init_<SfpuType::add_top_row>();
    _llk_math_eltwise_binary_sfpu_start_<DstSync::SyncHalf>(0U);
    ckernel::sfpu::_init_add_top_row_();
    for (int tile_offset = 1; tile_offset < params->TILE_CNT; ++tile_offset)
    {
        LLK_ASSERT(
            (tile_offset < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()),
            "Block tile index exceeds maximum destination tiles");
        // Accumulate top rows into tile at index 0
        ckernel::sfpu::_calculate_add_top_row_<static_cast<DataFormat>(formats.math)>(0U, tile_offset, 0U);
    }
#endif

    // Finalize sfpu operations and mark destination section as complete
    _llk_math_eltwise_unary_sfpu_done_();
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(formats.pack_src, formats.pack_dst, 16U * 16U * 4U);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(formats.pack_src, formats.pack_dst, 16U * 16U * 4U);
#endif

    // Initialize packer module
    _llk_pack_init_<false, false>(formats.pack_dst);

#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    // Wait until math processing completes before packing
    _llk_packer_wait_for_math_done_();

    // Pack each tile to output buffer
    for (int out_tile_idx = 0; out_tile_idx < params->TILE_CNT; ++out_tile_idx)
    {
        LLK_ASSERT(
            (out_tile_idx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()),
            "Block tile index exceeds maximum destination tiles");
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            out_tile_idx, L1_ADDRESS(params->buffer_Res[out_tile_idx]));
    }

    // Signal end of destination section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

