class LinearLayoutConversionsTest : public ::testing::Test {
public:
  void SetUp() { context.getOrLoadDialect<TritonGPUDialect>(); }

  BlockedEncodingAttr createBlocked(ArrayRef<unsigned> elementsPerThread,
                                    ArrayRef<unsigned> threadsPerWarp,
                                    ArrayRef<unsigned> warpsPerBlock,
                                    ArrayRef<unsigned> ctaGroups,
                                    ArrayRef<unsigned> ctaSplitNum,
                                    ArrayRef<unsigned> order,
                                    ArrayRef<unsigned> ctaOrder) {
    return BlockedEncodingAttr::get(
        &context, elementsPerThread, threadsPerWarp, warpsPerBlock, order,
        CTALayoutAttr::get(&context, ctaGroups, ctaSplitNum, ctaOrder));
  }

  NvidiaMmaEncodingAttr createMma(unsigned majorVersion, unsigned minorVersion,
                                  ArrayRef<unsigned> instructionShape,
                                  ArrayRef<unsigned> warpsPerBlock,
                                  ArrayRef<unsigned> ctaGroups,
                                  ArrayRef<unsigned> ctaSplitNum,
                                  ArrayRef<unsigned> ctaOrder) {
    return NvidiaMmaEncodingAttr::get(
        &context, majorVersion, minorVersion, warpsPerBlock,
        CTALayoutAttr::get(&context, ctaGroups, ctaSplitNum, ctaOrder),
        instructionShape);
  }

  SliceEncodingAttr createSlice(Attribute parentLayout, int axis) {
    return SliceEncodingAttr::get(&context, axis, parentLayout);
  }

  StringAttr makeString(StringRef text) {
    return StringAttr::get(&context, text);
  }

protected:
  MLIRContext context;
};

// Helper function to generate expected string representation for comparison
static inline std::string toString(const LinearLayout& layout) {
  std::ostringstream oss;
  oss << layout;
  return oss.str();
}

TEST_F(LinearLayoutConversionsTest, BasicBlockedLayout) {
  auto layout = toLinearLayout({16}, createBlocked({1}, {4}, {4}, {1}, {1}, {0}, {0}));
  EXPECT_EQ(layout, LinearLayout(
                        {
                            {makeString("register"), {}},
                            {makeString("lane"), {{1}, {2}}},
                            {makeString("warp"), {{4}, {8}}},
                            {makeString("block"), {}},
                        },
                        {makeString("dim0")}));
}

TEST_F(LinearLayoutConversionsTest, CTAReplicationCase) {
  auto layout = toLinearLayout(
      {32}, createBlocked({1}, {4}, {4}, /*ctaGroups=*/{4}, /*ctaSplitNum=*/{2}, {0}, {0}));
  EXPECT_EQ(layout, LinearLayout(
                        {
                            {makeString("register"), {}},
                            {makeString("lane"), {{1}, {2}}},
                            {makeString("warp"), {{4}, {8}}},
                            {makeString("block"), {{16}, {0}}},
                        },
                        {makeString("dim0")}));
}

TEST_F(LinearLayoutConversionsTest, MultipleDimensionsWithBroadcast) {
  auto layout =
      toLinearLayout({64, 128}, createBlocked({8, 1}, {8, 4}, {1, 4}, {1, 2}, {1, 2},
