  EXPECT_EQ(
      layout,
      LinearLayout({{makeString("register"), {{1, 0}, {2, 0}, {4, 0}, {0, 16}, {0, 32}}},
                    {makeString("lane"), {{8, 0}, {16, 0}, {32, 0}, {0, 1}, {0, 2}}},
                    {makeString("warp"), {{0, 4}, {0, 8}}},
                    {makeString("block"), {{0, 64}}}},
