TEST_F(LinearLayoutConversionsTest, MMAv3MultipleWarps) {
  auto mmaLayout = createMma(3, 0, {16, 32, 16}, {4, 2}, {1, 1}, {1, 1}, {1, 0});
  EXPECT_EQ(toLinearLayout({64, 32}, mmaLayout),
            LinearLayout({{makeString("register"), {{0, 1}, {8, 0}, {0, 8}, {0, 16}}},
                          {makeString("lane"), {{0, 2}, {0, 4}, {1, 0}, {2, 0}, {4, 0}}},
                          {makeString("warp"), {{16, 0}, {32, 0}, {0, 0}}},
                          {makeString("block"), {}}},
                         {makeString("dim0"), makeString("dim1")}));
  EXPECT_EQ(toLinearLayout({64, 64}, mmaLayout),
            LinearLayout({{makeString("register"), {{0, 1}, {8, 0}, {0, 8}, {0, 16}}},
                          {makeString("lane"), {{0, 2}, {0, 4}, {1, 0}, {2, 0}, {4, 0}}},
                          {makeString("warp"), {{16, 0}, {32, 0}, {0, 32}}},
                          {makeString("block"), {}}},
                         {makeString("dim0"), makeString("dim1")}));
  EXPECT_EQ(
      toLinearLayout({128, 64}, mmaLayout),
      LinearLayout({{makeString("register"), {{0, 1}, {8, 0}, {0, 8}, {0, 16}, {64, 0}}},
                    {makeString("lane"), {{0, 2}, {0, 4}, {1, 0}, {2, 0}, {4, 0}}},
                    {makeString("warp"), {{16, 0}, {32, 0}, {0, 32}}},
                    {makeString("block"), {}}},
                   {makeString("dim0"), makeString("dim1")}));
  EXPECT_EQ(
      toLinearLayout({256, 64}, mmaLayout),
      LinearLayout({{makeString("register"),
                     {{0, 1}, {8, 0}, {0, 8}, {0, 16}, {64, 0}, {128, 0}}},
                    {makeString("lane"), {{0, 2}, {0, 4}, {1, 0}, {2, 0}, {4, 0}}},
                    {makeString("warp"), {{16, 0}, {32, 0}, {0, 32}}},
                    {makeString("block"), {}}},
                   {makeString("dim0"), makeString("dim1")}));
}

