//,DEC_D_RN|DEC_S_RM|DEC_OP(shop_and)
static u64 BuildEntry(DecMode mode,DecParam d,DecParam s,shilop op,u32 extra=0)
{
	return (((u64)extra)<<32)|(mode<<24)|(d<<16)|(s<<8)|op;
}
static u64 BuildUnary_rNrN(shilop op)
{
	return BuildEntry(DM_UnaryOp,PRM_RN,PRM_RN,op);
}
static u64 BuildUnary_rNrM(shilop op)
{
	return BuildEntry(DM_UnaryOp,PRM_RN,PRM_RM,op);
}
static u64 BuildUnary_frNfrN(shilop op)
{
	return BuildEntry(DM_UnaryOp,PRM_FRN,PRM_FRN,op);
}
static u64 BuildUnary_frNfrM(shilop op)
{
	return BuildEntry(DM_UnaryOp,PRM_FRN,PRM_FRM,op);
}
static u64 BuildBinary_frNfrM(shilop op, u32 haswrite=1)
{
	return BuildEntry(DM_BinaryOp,PRM_FRN,PRM_FRM,op,haswrite);
}
static u64 BuildBinary_rNrM(shilop op, u32 haswrite=1)
{
	return BuildEntry(DM_BinaryOp,PRM_RN,PRM_RM,op,haswrite);
}
static u64 BuildMul(u32 type)
{
	//return 0;
	return BuildEntry(DM_MUL,PRM_RN,PRM_RM,shop_mul_s16,type);
}
static u64 BuildBinary_S8R(shilop op, u32 haswrite=1)
{
	return BuildEntry(DM_BinaryOp,PRM_RN,PRM_SIMM8,op,haswrite);
}
static u64 BuildBinary_r0u8(shilop op, u32 haswrite=1)
{
	return BuildEntry(DM_BinaryOp,PRM_R0,PRM_UIMM8,op,haswrite);
}
static u64 BuildShift(s32 offset,bool arithm)
{
	if (offset>0)
	{
		//left shift
		return BuildEntry(DM_Shift,PRM_RN,PRM_RN,shop_shl,offset);
	}
	else
	{
		return BuildEntry(DM_Shift,PRM_RN,PRM_RN,arithm?shop_sar:shop_shr,-offset);
	}

}

static u64 BuildCmp(shilop op, DecParam s1,DecParam s2)
{
	return BuildEntry(DM_WriteTOp,s1,s2,op);
}

static u64 BuildLoad(DecParam d)	{ return BuildEntry(DM_UnaryOp,d,PRM_RN,shop_mov32); }
static u64 BuildLoadM(DecParam d)	{ return BuildEntry(DM_ReadM,d,PRM_RN,shop_readm,-4); }
static u64 BuildStore(DecParam d)	{ return BuildEntry(DM_UnaryOp,PRM_RN,d,shop_mov32); }
static u64 BuildStoreM(DecParam d)	{ return BuildEntry(DM_WriteM,PRM_RN,d,shop_writem,-4); }

//d=reg to read into
static u64 BuildMemRead(DecParam d,DecParam s,u32 sz) { return BuildEntry(DM_ReadM,d,s,shop_readm,sz); }
//d= reg to read from
static u64 BuildMemWrite(DecParam d,DecParam s,u32 sz) { return BuildEntry(DM_WriteM,d,s,shop_writem,sz); }

//use this to disable opcodes :p
static u64 BuildNull(...) { return 0; }

