#include <vector>
#include <unordered_set>

class Solution {
public:
    int minimumOperations(std::vector<int>& nums) {
        std::unordered_set<int> uniqueValues;
        for (int value : nums) {
            if (value != 0) {
                uniqueValues.insert(value);
            }
        }
        return uniqueValues.size();
    }
};

#include <iostream>
#include <string>
#include <stdio.h>
#include "stringwrapper.h"
#ifdef OLD_WPDS_INDICES
#   include "wpds.h"
#else
#   include "WPDS.h"
#endif

int main() {
    // Initialize semirings and WPDS instances
    wpds::Semiring< StringWrapper > ring(StringWrapper::one());
    wpds::Semiring< StringWrapper > ringR(StringWrapper::one(), false);
    wpds::WPDS< StringWrapper > system1(ring);
    wpds::WPDS< StringWrapper > system2(ring);
    wpds::CA< StringWrapper > analyzer(ring);
    wpds::CA< StringWrapper > analyzer2(ring);

    /* Define WPDS symbols */
    wpds::wpds_key_t nt1 = str2key("p");
    wpds::wpds_key_t N1 = str2key("A");
    wpds::wpds_key_t N2 = str2key("B");
    wpds::wpds_key_t N3 = str2key("C");
    wpds::wpds_key_t N4 = str2key("D");
    wpds::wpds_key_t empty = str2key("lambda");
    wpds::wpds_key_t final_state = str2key("accept");

    /* Add rules to system1 */
    system1.add_rule(nt1, empty, nt1, N1, new StringWrapper("a"));
    system1.add_rule(nt1, N1,   nt1, N2, new StringWrapper("b"));
    system1.add_rule(nt1, N2,   nt1, N3, new StringWrapper("c"));
    system1.add_rule(nt1, N3,   nt1, N4, new StringWrapper("d"));
    system1.add_rule(nt1, N1,   nt1, N1, N2, new StringWrapper("w"));

    /* Define symbols for system2 */
    wpds::wpds_key_t nt2 = str2key("p'");
    wpds::wpds_key_t var1 = str2key("x");
    wpds::wpds_key_t var1_prime = str2key("x'");
    wpds::wpds_key_t var2_prime = str2key("x''");

    /* Add rules to system2 */
    system2.add_rule( nt2, var1,      nt1,      N1,  StringWrapper::one());
    system2.add_rule( nt2, var1_prime, nt2,      var1,  N2,  StringWrapper::one());
    system2.add_rule( nt2, var2_prime, nt2,      var1_prime, N2,  StringWrapper::one());

    /* Set initial configuration */
    analyzer.add(nt1, empty, final_state, StringWrapper::one());

    std::cout << "Final state weight is ";
    // analyzer.state_weight( final_state )->print(std::cout) << std::endl;

    std::cout << system1 << std::endl << std::endl;
    std::cout << "*** BEFORE ***\n" << analyzer << std::endl;

    /* Compute post* */
    wpds::CA< StringWrapper > result_after =
        wpds::poststar< StringWrapper >(system1, analyzer, ring);

    std::cout << "*** AFTER  ***\n" << result_after << std::endl;

    /* Compute pre* on system2 */
    wpds::CA< StringWrapper > result_before =
        wpds::prestar< StringWrapper >(system2, result_after, ringR);

    wpds::CA< StringWrapper >::catrans_t target;
    target = result_before.find(nt2, var2_prime, final_state);

    std::cout << "\n\n AFTER PRESTAR ON SYSTEM2\n" << result_before << std::endl;
    // std::cout << target << std::endl;
    target->print(std::cout) << std::endl;

#if 1
    result_before.add_final_state(final_state);
    std::cout << "Calling path_summary...\n";
    std::set< wpds::wpds_key_t > nonterm_set;
    nonterm_set.insert(N2);

    // std::cout << "final state weight: " << result_before.state_weight(final_state) << std::endl;
    result_before.path_summary(nonterm_set);
    std::cout << "Final state weight is ";
    result_before.state_weight(final_state)->print(std::cout) << std::endl;

    // std::cout << "nt1 weight: " << result_before.state_weight(nt1) << std::endl;
    std::cout << "nt1 weight is ";
    result_before.state_weight(nt1)->print(std::cout) << std::endl;
#endif

    return 0;
}
