static std::vector<uint8_t> ConvertStringToBytes(std::string_view str) {
    return std::vector<uint8_t>{(uint8_t *)str.data(), (uint8_t *)str.data() + str.length() + 1};
}

// NOLINTBEGIN(cppcoreguidelines-avoid-magic-numbers,readability-magic-numbers)
static int ConvertHexCharacter(int c) {
    if (c >= '0' && c <= '9') {
        return c - 0x30;
    }
    if (c >= 'a' && c <= 'f') {
        return c - 0x57;
    }
    if (c >= 'A' && c <= 'F') {
        return c - 0x37;
    }
    return -1;
}
// NOLINTEND(cppcoreguidelines-avoid-magic-numbers,readability-magic-numbers)

static std::vector<uint8_t> ParseHexString(std::string_view hex_string) {
    if (hex_string.size() & 1) {
        return {};
    }
    std::vector<uint8_t> output_bytes;
    output_bytes.reserve(hex_string.size() >> 1);
    for (size_t i = 0; i < hex_string.size(); i += 2) {
        int high_nibble = ConvertHexCharacter(hex_string[i]);
        int low_nibble = ConvertHexCharacter(hex_string[i + 1]);
        if (high_nibble < 0 || low_nibble < 0) {
            return {};
        }
        output_bytes.push_back((uint8_t)(high_nibble << 4 | low_nibble));
    }
    return output_bytes;
}

