// Process different operations based on the provided operation type
void handleOperation(Operation action, AppContext *appContext)
{
    switch(action) {
    case Convert:
        performConvert(appContext);
        break;
    case Save:
        performSave(appContext);
        break;
    case Initialization:
        performInitialize(appContext);
        break;
    case Validation:
        performValidation(appContext);
        break;
    case Swap:
        performSwap(appContext);
        break;
    case ConvertAddCode:
        performConvertAddCode(appContext);
        break;
    case ChekingAddCode:
        performChekingAddCode(appContext);
        break;
    }
}

