void LCAlloc(void* addr, u32 size) {
    u32 blockCount = size >> 5;
    u32 hid2 = PPCMfhid2();
    ASSERTMSGLINE(1319, !((u32)addr & 31), "LCAlloc(): addr must be 32 byte aligned");
    ASSERTMSGLINE(1321, !((u32)size & 31), "LCAlloc(): nBytes must be 32 byte aligned");
    if ((hid2 & 0x10000000) == 0) {
        LCEnable();
    }
    LCAllocTags(TRUE, addr, blockCount);
}
void LCAllocNoInvalidate(void* addr, u32 size) {
    u32 blockCount = size >> 5;
    u32 hid2 = PPCMfhid2();
    ASSERTMSGLINE(1366, !((u32)addr & 31), "LCAllocNoFlush(): addr must be 32 byte aligned");
    ASSERTMSGLINE(1368, !((u32)size & 31), "LCAllocNoFlush(): nBytes must be 32 byte aligned");
    if ((hid2 & 0x10000000) == 0) {
        LCEnable();
    }
    LCAllocTags(FALSE, addr, blockCount);
}
u32 LCLoadData(void* destAddr, void* srcAddr, u32 size) {
    u32 blockCount = (size + 31) / 32;
    u32 transactionCount = (blockCount + 128 - 1) / 128;
    ASSERTMSGLINE(1426, !((u32)srcAddr & 31), "LCLoadData(): srcAddr not 32 byte aligned");
    ASSERTMSGLINE(1428, !((u32)destAddr & 31), "LCLoadData(): destAddr not 32 byte aligned");
    while (blockCount > 0) {
        if (blockCount < 128) {
            LCLoadBlocks(destAddr, srcAddr, blockCount);
            blockCount = 0;
        } else {
            LCLoadBlocks(destAddr, srcAddr, 0);
            blockCount -= 128;
            destAddr = (void*)((u32)destAddr + 4096);
            srcAddr = (void*)((u32)srcAddr + 4096);
        }
    }
    return transactionCount;
}
u32 LCStoreData(void* destAddr, void* srcAddr, u32 size) {
    u32 blockCount = (size + 31) / 32;
    u32 transactionCount = (blockCount + 128 - 1) / 128;
    ASSERTMSGLINE(1494, !((u32)srcAddr & 31), "LCStoreData(): srcAddr not 32 byte aligned");
    ASSERTMSGLINE(1496, !((u32)destAddr & 31), "LCStoreData(): destAddr not 32 byte aligned");
    while (blockCount > 0) {
        if (blockCount < 128) {
            LCStoreBlocks(destAddr, srcAddr, blockCount);
            blockCount = 0;
        } else {
            LCStoreBlocks(destAddr, srcAddr, 0);
            blockCount -= 128;
            destAddr = (void*)((u32)destAddr + 4096);
            srcAddr = (void*)((u32)srcAddr + 4096);
        }
    }
    return transactionCount;
}
