  return PsonPath(basePath, data[ENUM_2_STR(Ori)].toString(), data[ENUM_2_STR(Name)].toString());
}

QVariantHash PerformerDataAggregator(const QSqlRecord& record) {
  using namespace PERFORMER_DB_HEADER_KEY;
  return PerformerDataAggregator(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) record.field(enu).value().sqlRecordToValueFunc(),
      PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
      nullptr);
}

QVariantHash PerformerDataAggregator(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) decltype(defaultValue) _##enu,
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
    void* UNUSED_PARAMETER) {
  // Possible values for 'Ori':
  // Science Fiction/Sci-Fi
  // Adventure Movie
  // Drama/Feature Movie
  // Documentary
  // Superhero Movie
  // Horror Movie
  // Action Movie
  // Comedy
  // Thriller
  // Fantasy
  using namespace PERFORMER_DB_HEADER_KEY;
  return {
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) {ENUM_2_STR(enu), _##enu}, //
      PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
  };
}

QByteArray ConvertValuesToPsonString(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) decltype(defaultValue) _##enu,
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
    void* UNUSED_PARAMETER) {
  QVariantHash dataMap{PerformerDataAggregator(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) _##enu, //
      PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
      nullptr)};
  return JsonHelper::SerializedJsonDict2ByteArray(dataMap);
}

