/*--------------------------------------------------------------------------
 NAME
    H5Rget_obj_type1
 PURPOSE
    Retrieves the type of object that an object reference points to
 USAGE
    H5G_obj_t H5Rget_obj_type1(id, ref_type, ref)
        hid_t id;       IN: Dataset reference object is in or location ID of
                            object that the dataset is located within.
        H5R_type_t ref_type;    IN: Type of reference to query
        void *ref;          IN: Reference to query.
 RETURNS
    Success:	An object type defined in H5Gpublic.h
    Failure:	H5G_UNKNOWN
 DESCRIPTION
    Given a reference to some object, this function returns the type of object
    pointed to.
 GLOBAL VARIABLES
 COMMENTS, BUGS, ASSUMPTIONS
 EXAMPLES
 REVISION LOG
--------------------------------------------------------------------------*/
H5G_obj_t
H5Rget_obj_type1(hid_t loc_id, H5R_type_t ref_kind, const void *ref_ptr)
{
    H5G_loc_t obj_loc;              /* Object location */
    H5O_type_t found_obj_type;      /* Object type */
    H5G_obj_t result_value;         /* Return value */
    FUNC_ENTER_API(H5G_UNKNOWN)
    H5TRACE3("Go", "iRt*x", loc_id, ref_kind, ref_ptr);
    /* Check args */
    if(H5G_loc(loc_id, &obj_loc) < 0)
        HGOTO_ERROR(H5E_ARGS, H5E_BADTYPE, H5G_UNKNOWN, "not a location")
    if(ref_kind <= H5R_BADTYPE || ref_kind >= H5R_MAXTYPE)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, H5G_UNKNOWN, "invalid reference type")
    if(ref_ptr == NULL)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, H5G_UNKNOWN, "invalid reference pointer")
    /* Get the object information */
    if(H5R_get_obj_type(obj_loc.oloc->file, H5AC_ind_dxpl_id, ref_kind, ref_ptr, &found_obj_type) < 0)
	HGOTO_ERROR(H5E_REFERENCE, H5E_CANTINIT, H5G_UNKNOWN, "unable to determine object type")
    /* Set return value */
    result_value = H5G_map_obj_type(found_obj_type);
done:
    FUNC_LEAVE_API(result_value)
}   /* end H5Rget_obj_type1() */
#endif /* H5_NO_DEPRECATED_SYMBOLS */

