// Register semaphore classes for Python bindings
void register_semaphore(nb::module_& m) {
  // Host2DeviceSemaphore class binding
  nb::class_<Host2DeviceSemaphore> host2DevSem(m, "Host2DeviceSemaphore");
  host2DevSem
      .def(nb::init<Communicator&, std::shared_ptr<Connection>>(), nb::arg("comm"), nb::arg("conn"))
      .def("connection", &Host2DeviceSemaphore::connection)
      .def("signal", &Host2DeviceSemaphore::signal)
      .def("device_handle", &Host2DeviceSemaphore::deviceHandle);

  // Nested DeviceHandle class for Host2DeviceSemaphore
  nb::class_<Host2DeviceSemaphore::DeviceHandle>(host2DevSem, "DeviceHandle")
      .def(nb::init<>())
      .def_rw("inbound_semaphore_id", &Host2DeviceSemaphore::DeviceHandle::inboundSemaphoreId)
      .def_rw("expected_inbound_semaphore_id", &Host2DeviceSemaphore::DeviceHandle::expectedInboundSemaphoreId)
      .def_prop_ro("raw", [](const Host2DeviceSemaphore::DeviceHandle& handle) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&handle), sizeof(handle));
      });

  // Host2HostSemaphore class binding
  nb::class_<Host2HostSemaphore> host2HostSem(m, "Host2HostSemaphore");
  host2HostSem
      .def(nb::init<Communicator&, std::shared_ptr<Connection>>(), nb::arg("comm"), nb::arg("conn"))
      .def("connection", &Host2HostSemaphore::connection)
      .def("signal", &Host2HostSemaphore::signal)
      .def("poll", &Host2HostSemaphore::poll)
      .def("wait", &Host2HostSemaphore::wait, nb::call_guard<nb::gil_scoped_release>(),
           nb::arg("max_spins") = 10000000);

  // SmDevice2DeviceSemaphore class binding
  nb::class_<SmDevice2DeviceSemaphore> smDev2DevSem(m, "SmDevice2DeviceSemaphore");
  smDev2DevSem
      .def(nb::init<Communicator&, std::shared_ptr<Connection>>(), nb::arg("comm"), nb::arg("conn"))
      .def("device_handle", &SmDevice2DeviceSemaphore::deviceHandle);

  // Nested DeviceHandle class for SmDevice2DeviceSemaphore
  nb::class_<SmDevice2DeviceSemaphore::DeviceHandle>(smDev2DevSem, "DeviceHandle")
      .def(nb::init<>())
      .def_rw("inboundSemaphoreId", &SmDevice2DeviceSemaphore::DeviceHandle::inboundSemaphoreId)
      .def_rw("outboundSemaphoreId", &SmDevice2DeviceSemaphore::DeviceHandle::outboundSemaphoreId)
      .def_rw("remoteInboundSemaphoreId", &SmDevice2DeviceSemaphore::DeviceHandle::remoteInboundSemaphoreId)
      .def_rw("expectedInboundSemaphoreId", &SmDevice2DeviceSemaphore::DeviceHandle::expectedInboundSemaphoreId)
      .def_prop_ro("raw", [](const SmDevice2DeviceSemaphore::DeviceHandle& handle) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&handle), sizeof(handle));
      });
}

