#include <bpf/bpf.h>

// Tracepoint structure for scheduler switch event
struct sched_switch_event {
    u64 reserved;
    u8 previous_task_name[16];
    u32 previous_process_id;
    u32 previous_priority;
    u64 previous_state_flag;
    u8 next_task_name[16];
    u32 next_process_id;
    u32 next_priority;
};

// Structure to hold a large buffer (e.g., for data collection)
struct large_data_buffer {
    u8 data_area[2048];
};

BTF_EXPORT(struct large_data_buffer);

// Define a BPF map for storing large buffers
BPF_MAP_STRUCT(buffer_map, BPF_MAP_TYPE_ARRAY, u32, struct large_data_buffer, 512 * 1024, 0);

// Nested map structure using array of maps
struct {
    BPF_MAP_DEF_UINT(type, BPF_MAP_TYPE_ARRAY_OF_MAPS);
    BPF_MAP_DEF_UINT(key_size, sizeof(u32));
    BPF_MAP_DEF_UINT(max_entries, 2048);
    BPF_MAP_DEF_ARRAY(inner_maps, struct buffer_map);
} multi_buffers SEC(BPF_SEC_BTF_MAPS);

// Attach to the scheduler switch tracepoint
SEC("tracepoint/sched/sched_switch")
int handle_sched_switch(struct sched_switch_event* event) {
    BPF_PRINTK("Scheduler switch: %d -> %d\n", event->previous_process_id, event->next_process_id);
    return 0;
}

