#include <vector>
using namespace std;

// Perform selection sort on the given vector
void selectionSort(vector<int>& data, int size) {
    for (int outerLoop = 0; outerLoop < size - 1; outerLoop++) {
        int smallest = outerLoop;
        for (int innerLoop = outerLoop + 1; innerLoop < size; innerLoop++) {
            if (data[innerLoop] < data[smallest]) {
                smallest = innerLoop;
            }
        }
        swap(data[smallest], data[outerLoop]);
    }
}

