// Securely zero out a memory region
void ClearMemory(void* buffer, size_t length) noexcept {
#ifdef _MSC_VER
    SecureZeroMemory(buffer, length);
#elif defined(memset_s)
    memset_s(buffer, length, 0, length);
#else
    volatile char* tempPtr = (volatile char*)buffer;
    while (length > 0) {
        *tempPtr = '\0';
        ++tempPtr;
        --length;
    }
#endif
}

