[[noreturn]] void CrashHandler::crash(std::string_view reason) {
  std::cerr << "[LightCrashHandler] " << reason << std::endl;
  std::flush(std::cerr);
  std::terminate();
};

[[noreturn]] void CrashHandler::assertionFailure(const char* filename, int lineno,
                                                 const char* function,
                                                 const char* condition,
                                                 const char* details) {
  std::string error_msg;
  absl::strings_internal::OStringStream err{&error_msg};
  err << "Assertion failed in file " << filename << ":" << lineno << ", expression "
      << condition << " with message ";
  if (details) {
    err << details;
  }
  err << std::endl;
  CrashHandler::crash(error_msg);
}

