// Function to exchange and display two integer values using XOR swap
int transformAndPrint(int inputCount, char *arguments[]) {
    int value1 = 17;
    int value2 = inputCount;

    // Perform XOR swap algorithm
    value1 ^= value2;
    value2 ^= value1;
    value1 ^= value2;

    printf("Revealed secret: %d\n", value1);
    printf("Calculated result: %d\n", value2);
    return 0;
}

int main(int argc, char *argv[]) { 
    return transformAndPrint(argc, argv); 
}

