using namespace std;

UNIT_TEST(SortAndMergeIntervals_SingleRange)
{
    vector<pair<int64_t, int64_t>> input;
    input.push_back(make_pair(1ULL, 2ULL));
    TEST_EQUAL(covering::SortAndMergeIntervals(input), input, ());
}

UNIT_TEST(SortAndMergeIntervals_TwoUnsortedNonOverlapping)
{
    vector<pair<int64_t, int64_t>> input;
    input.push_back(make_pair(5ULL, 6ULL));
    input.push_back(make_pair(3ULL, 4ULL));

    vector<pair<int64_t, int64_t>> expected;
    expected.push_back(make_pair(3ULL, 4ULL));
    expected.push_back(make_pair(5ULL, 6ULL));

    TEST_EQUAL(covering::SortAndMergeIntervals(input), expected, ());
}

UNIT_TEST(SortAndMergeIntervals_AdjacentMerge)
{
    vector<pair<int64_t, int64_t>> input;
    input.push_back(make_pair(2ULL, 4ULL));
    input.push_back(make_pair(4ULL, 6ULL));

    vector<pair<int64_t, int64_t>> expected;
    expected.push_back(make_pair(2ULL, 6ULL));

    TEST_EQUAL(covering::SortAndMergeIntervals(input), expected, ());
}

UNIT_TEST(SortAndMergeIntervals_OverlappingMerge)
{
    vector<pair<int64_t, int64_t>> input;
    input.push_back(make_pair(3ULL, 7ULL));
    input.push_back(make_pair(5ULL, 9ULL));

    vector<pair<int64_t, int64_t>> expected;
    expected.push_back(make_pair(3ULL, 9ULL));

    TEST_EQUAL(covering::SortAndMergeIntervals(input), expected, ());
}

UNIT_TEST(SortAndMergeIntervals_FullContainment)
{
    vector<pair<int64_t, int64_t>> input;
    input.push_back(make_pair(4ULL, 6ULL));
    input.push_back(make_pair(2ULL, 8ULL));

    vector<pair<int64_t, int64_t>> expected;
    expected.push_back(make_pair(2ULL, 8ULL));

    TEST_EQUAL(covering::SortAndMergeIntervals(input), expected, ());
}

UNIT_TEST(SortAndMergeIntervals_ContainWithSharedBoundary)
{
    vector<pair<int64_t, int64_t>> input;
    input.push_back(make_pair(2ULL, 5ULL));
    input.push_back(make_pair(2ULL, 7ULL));

    vector<pair<int64_t, int64_t>> expected;
    expected.push_back(make_pair(2ULL, 7ULL));

    TEST_EQUAL(covering::SortAndMergeIntervals(input), expected, ());
}

