namespace snap {
namespace {
// Global flag controlling release assertions - active by default in dev builds
std::atomic_bool gReleaseAssertionsActive{kAssertsCompiledIn};
// Global flag for fused assertion functionality - inactive by default
// Used only when integrated into Snapchat application
std::atomic_bool gFusedAssertionFeature{false};
} // namespace

bool areReleaseAssertionsActive() {
    return gReleaseAssertionsActive.load(std::memory_order_relaxed);
}

void setReleaseAssertionsActive(bool state) {
    gReleaseAssertionsActive.store(state, std::memory_order_relaxed);
}

bool isFusedAssertionEnabled() {
    return gFusedAssertionFeature.load(std::memory_order_relaxed);
}

void enableFusedAssertion(bool flag) {
    gFusedAssertionFeature.store(flag, std::memory_order_relaxed);
}
} // namespace snap

