// Recipe mapping for ore blocks to their component items
void OreRecipies::_init() {
    recipeMap = new std::vector<Object*>[MAX_RECIPE_COUNT];

    // Gold block conversion: 1 block → 9 gold ingots
    ADD_OBJECT(recipeMap[0], Tile::goldBlock);
    ADD_OBJECT(recipeMap[0], new ItemInstance(Item::goldIngot, 9));

    // Iron block conversion: 1 block → 9 iron ingots
    ADD_OBJECT(recipeMap[1], Tile::ironBlock);
    ADD_OBJECT(recipeMap[1], new ItemInstance(Item::ironIngot, 9));

    // Diamond block conversion: 1 block → 9 diamonds
    ADD_OBJECT(recipeMap[2], Tile::diamondBlock);
    ADD_OBJECT(recipeMap[2], new ItemInstance(Item::diamond, 9));

    // Emerald block conversion: 1 block → 9 emeralds
    ADD_OBJECT(recipeMap[3], Tile::emeraldBlock);
    ADD_OBJECT(recipeMap[3], new ItemInstance(Item::emerald, 9));

    // Lapis block conversion: 1 block → 9 blue dye
    ADD_OBJECT(recipeMap[4], Tile::lapisBlock);
    ADD_OBJECT(
        recipeMap[4],
        new ItemInstance(Item::dye_powder, 9, DyePowderItem::BLUE)
    );
}

// Register ore-to-ingot and ingot-to-block crafting recipes
void OreRecipies::addRecipes(Recipes* r) {
    for (int index = 0; index < MAX_RECIPE_COUNT; ++index) {
        Tile*         sourceTile = (Tile*)recipeMap[index].at(0)->tile;
        ItemInstance* resultItem = (ItemInstance*)recipeMap[index].at(1)->iteminstance;

        // Block → Ingot recipe (9:1 reduction)
        r->addShapedRecipy(
            new ItemInstance(sourceTile),
            L"sssczg",
            L"###", //
            L"###", //
            L"###", //
            L'#',
            resultItem,
            L'D'
        );

        // Ingot → Block recipe (1:9 expansion)
        r->addShapedRecipy(
            resultItem,
            L"sctg",
            L"#", //
            L'#',
            sourceTile,
            L'D'
        );
    }
}

