#include <vector>
#include <algorithm>

class Solution {
public:
    double findMaximumAverage(std::vector<int>& values, int windowSize) {
        int length = values.size();
        double currentSum = 0;

        // Calculate sum of first window
        for (int index = 0; index < windowSize; ++index) {
            currentSum += values[index];
        }

        double highestSum = currentSum;

        // Slide the window and update max sum
        for (int index = windowSize; index < length; ++index) {
            currentSum = currentSum - values[index - windowSize] + values[index];
            highestSum = std::max(currentSum, highestSum);
        }

        return highestSum / windowSize;
    }
};

