// Copy the sign of y to x
double copysign(double x, double y) {
    union {double f; uint64_t i;} val_x = {x}, val_y = {y};
    val_x.i &= (0xFFFFFFFFFFFFFFFFULL >> 1);
    val_x.i |= (val_y.i & (1ULL << 63));
    return val_x.f;
}

