void test_zdotu_n_1(void)
{
	int length = 1, strideX = 1, strideY = 1;
	double vecX_start[] = {1.0, 1.0};
	double vecY_start[] = {1.0, 2.0};
	double vecX_ref[] = {1.0, 1.0};
	double vecY_ref[] = {1.0, 2.0};
	double _Complex computed_result = 0.0;
	double _Complex reference_result = 0.0;

	// OpenBLAS computation
	computed_result = BLASFUNC(zdotu)(&length, vecX_start, &strideX, vecY_start, &strideY);

	// Reference implementation
	reference_result = BLASFUNC_REF(zdotu)(&length, vecX_ref, &strideX, vecY_ref, &strideY);

	CU_ASSERT_DOUBLE_EQUAL(creal(computed_result), creal(reference_result), CHECK_EPS);
	CU_ASSERT_DOUBLE_EQUAL(cimag(computed_result), cimag(reference_result), CHECK_EPS);
}

void test_zdotu_offset_1(void)
{
	int length = 1, strideX = 1, strideY = 1;
	double inputX[] = {1.0, 2.0, 3.0, 4.0};
	double inputY[] = {5.0, 6.0, 7.0, 8.0};
	double refX[] = {1.0, 2.0, 3.0, 4.0};
	double refY[] = {5.0, 6.0, 7.0, 8.0};
	double _Complex test_result = 0.0;
	double _Complex expected_result = 0.0;

	// OpenBLAS with offset
	test_result = BLASFUNC(zdotu)(&length, inputX + 1, &strideX, inputY + 1, &strideY);

	// Reference with same offset
	expected_result = BLASFUNC_REF(zdotu)(&length, refX + 1, &strideX, refY + 1, &strideY);

	CU_ASSERT_DOUBLE_EQUAL(creal(test_result), creal(expected_result), CHECK_EPS);
	CU_ASSERT_DOUBLE_EQUAL(cimag(test_result), cimag(expected_result), CHECK_EPS);
}

