#include <Alembic/Util/Naming.h>
#include <Alembic/Util/Foundation.h>
#include <string>
#include <vector>
#include <assert.h>

int main(int argc, char* argv[]) {
    using namespace Alembic::Util;

    // List of strings that should be valid standard names
    std::vector<std::string> validNames;
    validNames.push_back("abc");
    validNames.push_back("abc8675309");
    validNames.push_back("a");
    validNames.push_back("under_score");
    validNames.push_back("_underscore");
    validNames.push_back("_underscore12345");
    validNames.push_back("_");

    // List of strings that are not valid standard names initially
    std::vector<std::string> invalidNames;
    invalidNames.push_back("");
    invalidNames.push_back("1");
    invalidNames.push_back("42abc");
    invalidNames.push_back("Name With Spaces");
    invalidNames.push_back("@#(#@$)(*");
    invalidNames.push_back("Xform No. 0x1c # not 0xc1");
    invalidNames.push_back("#");

    // Verify all valid names pass the isStandardName check
    for (std::vector<std::string>::iterator iter = validNames.begin();
         iter != validNames.end();
         ++iter) {
        assert(isStandardName(*iter));
    }

    // For each invalid name, ensure it fails initially,
    // then convert and verify it becomes valid
    for (std::vector<std::string>::iterator iter = invalidNames.begin();
         iter != invalidNames.end();
         ++iter) {
        std::string currentName = *iter;
        assert(!isStandardName(currentName));
        makeStandardName(currentName);
        assert(isStandardName(currentName));
    }

    std::cout << "Success!" << std::endl;
    return 0;
}

#define HEAD_SIZE 64
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include "vorbis/codec.h"
#define DEBUG_ALLOC
#include "debug_alloc.h"
#include <sys/time.h>

static pthread_mutex_t alloc_lock = PTHREAD_MUTEX_INITIALIZER;
static void **memory_blocks = NULL;
static long *free_indices = NULL; /* We can't embed this in the pointer list;
              a pointer can have any value... */
static char **source_files = NULL;
static long *file_sizes = NULL;
static int file_count = 0;
static int top_index = 0;
static int block_capacity = 0;
static int next_free = 0;

typedef struct {
  char *filename;
  long line_number;
  long index;
  long size;
} allocation_header;

long total_allocated_bytes = 0;
long start_timestamp = -1;

static void *_record_allocation(void *block, long size, char *file, long line) {
  ((allocation_header *)block)->filename = file;
  ((allocation_header *)block)->line_number = line;
  ((allocation_header *)block)->index = next_free;
  ((allocation_header *)block)->size = size - HEAD_SIZE;

  pthread_mutex_lock(&alloc_lock);

  if (next_free >= block_capacity) {
    block_capacity += 128;
    if (memory_blocks) {
      memory_blocks = (void **)realloc(memory_blocks, sizeof(void **) * block_capacity);
      free_indices = (long *)realloc(free_indices, sizeof(long) * block_capacity);
    } else {
      memory_blocks = (void **)malloc(sizeof(void **) * block_capacity);
      free_indices = (long *)malloc(sizeof(long) * block_capacity);
    }
  }

  memory_blocks[next_free] = block;

  if (next_free == top_index)
    next_free = ++top_index;
  else
    next_free = free_indices[next_free];

#ifdef _VDBG_GRAPHFILE
  {
    FILE *output;
    struct timeval timestamp;
    static struct timezone tz;
    int i;
    char filename_buffer[128];

    gettimeofday(&timestamp, &tz);

    for (i = 0; i < file_count; i++)
      if (!strcmp(file, source_files[i])) break;

    if (i == file_count) {
      file_count++;
      if (!source_files) {
        source_files = (char **)malloc(file_count * sizeof(*source_files));
        file_sizes = (long *)malloc(file_count * sizeof(*file_sizes));
      } else {
        source_files = (char **)realloc(source_files, file_count * sizeof(*source_files));
        file_sizes = (long *)realloc(file_sizes, file_count * sizeof(*file_sizes));
      }
      source_files[i] = strdup(file);
      file_sizes[i] = 0;
    }

    file_sizes[i] += size - HEAD_SIZE;

    if (start_timestamp == -1)
      start_timestamp = (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000);

    snprintf(filename_buffer, sizeof(filename_buffer), "%s%s", file, _VDBG_GRAPHFILE);
    output = fopen(filename_buffer, "a");
    fprintf(output, "%ld, %ld\n", -start_timestamp + (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000),
            file_sizes[i] - (size - HEAD_SIZE));
    fprintf(output, "%ld, %ld # FILE %s LINE %ld\n",
            -start_timestamp + (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000),
            file_sizes[i], file, line);
    fclose(output);

    output = fopen(_VDBG_GRAPHFILE, "a");
    fprintf(output, "%ld, %ld\n", -start_timestamp + (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000),
            total_allocated_bytes);
    fprintf(output, "%ld, %ld\n", -start_timestamp + (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000),
            total_allocated_bytes + (size - HEAD_SIZE));
    fclose(output);
  }
#endif

  total_allocated_bytes += (size - HEAD_SIZE);
  pthread_mutex_unlock(&alloc_lock);
  return (char *)block + HEAD_SIZE;
}

static void _remove_allocation(void *block) {
  int index;
  pthread_mutex_lock(&alloc_lock);

#ifdef _VDBG_GRAPHFILE
  {
    FILE *output = fopen(_VDBG_GRAPHFILE, "a");
    struct timeval timestamp;
    static struct timezone tz;
    char filename_buffer[128];
    char *file = ((allocation_header *)block)->filename;
    long size = ((allocation_header *)block)->size;
    int i;

    gettimeofday(&timestamp, &tz);

    fprintf(output, "%ld, %ld\n", -start_timestamp + (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000),
            total_allocated_bytes);
    fprintf(output, "%ld, %ld\n", -start_timestamp + (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000),
            total_allocated_bytes - ((allocation_header *)block)->size);
    fclose(output);

    for (i = 0; i < file_count; i++)
      if (!strcmp(file, source_files[i])) break;

    snprintf(filename_buffer, sizeof(filename_buffer), "%s%s", file, _VDBG_GRAPHFILE);
    output = fopen(filename_buffer, "a");
    fprintf(output, "%ld, %ld\n", -start_timestamp + (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000),
            file_sizes[i]);
    fprintf(output, "%ld, %ld\n", -start_timestamp + (timestamp.tv_sec * 1000) + (timestamp.tv_usec / 1000),
            file_sizes[i] - size);
    fclose(output);

    file_sizes[i] -= size;
  }
#endif

  total_allocated_bytes -= ((allocation_header *)block)->size;
  index = ((allocation_header *)block)->index;
  free_indices[index] = next_free;
  next_free = index;

  if (memory_blocks[index] == NULL) {
    fprintf(stderr, "DEBUGGING ALLOCATION ERROR: freeing previously freed memory\n");
    fprintf(stderr, "\t%s %ld\n", ((allocation_header *)block)->filename,
            ((allocation_header *)block)->line_number);
  }

  if (total_allocated_bytes < 0) {
    fprintf(stderr, "DEBUGGING ALLOCATION ERROR: freeing unallocated memory\n");
  }

  memory_blocks[index] = NULL;
  pthread_mutex_unlock(&alloc_lock);
}

void _VDBG_dump_memory() {
  int i;
  pthread_mutex_lock(&alloc_lock);
  for (i = 0; i < top_index; i++) {
    allocation_header *header = (allocation_header *)memory_blocks[i];
    if (header)
      fprintf(stderr, "unfreed bytes from %s:%ld\n",
              header->filename, header->line_number);
  }
  pthread_mutex_unlock(&alloc_lock);
}

extern void *_VDBG_malloc(void *block, long size, char *file, long line) {
  size += HEAD_SIZE;
  if (block) {
    block = (char *)block - HEAD_SIZE;
    _remove_allocation(block);
    block = realloc(block, size);
  } else {
    block = malloc(size);
    memset(block, 0, size);
  }
  return _record_allocation(block, size, file, line);
}

extern void _VDBG_free(void *block, char *file, long line) {
  if (block) {
    block = (char *)block - HEAD_SIZE;
    _remove_allocation(block);
    free(block);
  }
}

