using namespace AscendC;
using namespace CamMoeDispatchNormalImpl;

#define TILING_KEY_UNQUANTIZED 20001
#define TILING_KEY_QUANTIZED   20003

extern "C" __global__ __aicore__ void cam_moe_dispatch_normal(
    GM_ADDR inputTensor, 
    GM_ADDR expertIndices, 
    GM_ADDR sendByteOffsets, 
    GM_ADDR sendTokenPositions, 
    GM_ADDR recvByteOffsets, 
    GM_ADDR recvCounts,
    GM_ADDR expertGlobalOffsets, 
    GM_ADDR srcRankInExpertOffsets, 
    GM_ADDR rInSrcRankOffsets, 
    GM_ADDR expandedOutput,
    GM_ADDR scaleFactorsOut, 
    GM_ADDR combineAssistInfo, 
    GM_ADDR recvTimingStats, 
    GM_ADDR workspaceGlobalMem,
    GM_ADDR tilingBuffer)
{
    REGISTER_TILING_DEFAULT(CamMoeDispatchNormalTilingData);
    TPipe pipeline;

#if (ORIG_DTYPE_RECV_X == DT_BF16 || ORIG_DTYPE_RECV_X == DT_FLOAT16)
    if (TILING_KEY_IS(TILING_KEY_UNQUANTIZED)) {
        GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, tilingParam, tilingBuffer);
        CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, false, false, false> dispatcher;
        dispatcher.Init(inputTensor, expertIndices, sendByteOffsets, sendTokenPositions, recvByteOffsets, recvCounts,
                        expertGlobalOffsets, srcRankInExpertOffsets, rInSrcRankOffsets, expandedOutput, scaleFactorsOut,
                        combineAssistInfo, recvTimingStats, workspaceGlobalMem, &pipeline, &tilingParam);
        dispatcher.Run();
        return;
    }
#elif (ORIG_DTYPE_RECV_X == DT_INT8)
    if (TILING_KEY_IS(TILING_KEY_QUANTIZED)) {
        GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, tilingParam, tilingBuffer);
        CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, true, false, false> dispatcher;
        dispatcher.Init(inputTensor, expertIndices, sendByteOffsets, sendTokenPositions, recvByteOffsets, recvCounts,
                        expertGlobalOffsets, srcRankInExpertOffsets, rInSrcRankOffsets, expandedOutput, scaleFactorsOut,
                        combineAssistInfo, recvTimingStats, workspaceGlobalMem, &pipeline, &tilingParam);
        dispatcher.Run();
        return;
    }
#endif
}

