// Global arrays for timing measurements
double start_times[32];
double total_elapsed[32];

// Get current time from system
double get_current_time(void)
{
    double timestamp;
    wtime(&timestamp);
    return (timestamp);
}

/*****************************************************************/
/******            T  I  M  E  R  _  C  L  E  A  R          ******/
/*****************************************************************/
void reset_timer(int timer_id)
{
    total_elapsed[timer_id] = 0.0;
}

/*****************************************************************/
/******            T  I  M  E  R  _  S  T  A  R  T          ******/
/*****************************************************************/
void begin_timing(int timer_id)
{
    start_times[timer_id] = get_current_time();
}

/*****************************************************************/
/******            T  I  M  E  R  _  S  T  O  P             ******/
/*****************************************************************/
void end_timing(int timer_id)
{
    double delta;
    double current_time = get_current_time();
    delta = current_time - start_times[timer_id];
    total_elapsed[timer_id] += delta;
}

/*****************************************************************/
/******            T  I  M  E  R  _  R  E  A  D             ******/
/*****************************************************************/
double get_elapsed_time(int timer_id)
{
    return (total_elapsed[timer_id]);
}

