TEST(JsonUtils, GetTransform) {
  auto tform = projectairsim::JsonUtils::GetTransform(
      "{ \"origin\": { \"xyz\": \"2 3 4\", \"rpy\": \"40 40 40\" } }"_json,
      "origin");
  auto quaternion = projectairsim::TransformUtils::ToQuaternion(40, 40, 40);
  EXPECT_EQ(tform.translation_, projectairsim::Vector3(2, 3, 4));
  EXPECT_EQ(tform.rotation_.w(), quaternion.w());
  EXPECT_EQ(tform.rotation_.x(), quaternion.x());
  EXPECT_EQ(tform.rotation_.y(), quaternion.y());
  EXPECT_EQ(tform.rotation_.z(), quaternion.z());
  // invalid translation tag, expect default translation of 0
  tform = projectairsim::JsonUtils::GetTransform(
      "{ \"origin\": { \"xz\": \"2 3 4\", \"rpy\": \"40 40 40\" } }"_json,
      "origin");
  EXPECT_EQ(tform.translation_, projectairsim::Vector3(0, 0, 0));
  EXPECT_EQ(tform.rotation_.w(), quaternion.w());
  EXPECT_EQ(tform.rotation_.x(), quaternion.x());
  EXPECT_EQ(tform.rotation_.y(), quaternion.y());
  EXPECT_EQ(tform.rotation_.z(), quaternion.z());
  // invalid rotation tag, expect default rotation of 0
  tform = projectairsim::JsonUtils::GetTransform(
      "{ \"origin\": { \"xyz\": \"2 3 4\", \"py\": \"40 40 40\" } }"_json,
      "origin");
  EXPECT_EQ(tform.translation_, projectairsim::Vector3(2, 3, 4));
  EXPECT_EQ(tform.rotation_.w(), 1);
  EXPECT_EQ(tform.rotation_.x(), 0);
  EXPECT_EQ(tform.rotation_.y(), 0);
  EXPECT_EQ(tform.rotation_.z(), 0);
  // test degrees
  tform = projectairsim::JsonUtils::GetTransform(
      "{ \"origin\": { \"xyz\": \"2 3 4\", \"rpy-deg\": \"460 460 460\" } }"_json,
      "origin");
  auto ang_rad = projectairsim::MathUtils::deg2Rad(460);
  quaternion =
      projectairsim::TransformUtils::ToQuaternion(ang_rad, ang_rad, ang_rad);
  EXPECT_EQ(tform.translation_, projectairsim::Vector3(2, 3, 4));
  EXPECT_FLOAT_EQ(tform.rotation_.w(), quaternion.w());
  EXPECT_NEAR(tform.rotation_.x(), quaternion.x(), 1e-6);
  EXPECT_FLOAT_EQ(tform.rotation_.y(), quaternion.y());
  EXPECT_NEAR(tform.rotation_.z(), quaternion.z(), 1e-6);
  // invalid rotation tag, expect default rotation of 0
  tform = projectairsim::JsonUtils::GetTransform(
      "{ \"origin\": { \"xyz\": \"2 3 4\", \"py-deg\": \"460 460 460\" } }"_json,
      "origin");
  EXPECT_EQ(tform.translation_, projectairsim::Vector3(2, 3, 4));
  EXPECT_EQ(tform.rotation_.w(), 1);
  EXPECT_EQ(tform.rotation_.x(), 0);
  EXPECT_EQ(tform.rotation_.y(), 0);
  EXPECT_EQ(tform.rotation_.z(), 0);
  EXPECT_THROW(
      projectairsim::JsonUtils::GetTransform("{ \"key\": \"xyz\" }"_json, "key"),
      projectairsim::Error);
  EXPECT_THROW(
      projectairsim::JsonUtils::GetTransform("{ \"key\": 3 }"_json, "key"),
      projectairsim::Error);
  EXPECT_THROW(
      projectairsim::JsonUtils::GetTransform("{ \"key\": false }"_json, "key"),
      projectairsim::Error);
  EXPECT_THROW(
      projectairsim::JsonUtils::GetTransform("{ \"key\": [] }"_json, "key"),
      projectairsim::Error);
}

