#include <iostream>
#include "sophus/geometry.hpp"

int main() {
  // Compute combined rotation using SO(3) group operations
  const double PI_VAL = Sophus::Constants<double>::pi();
  Sophus::SO3d rotX_axis = Sophus::SO3d::rotX(PI_VAL / 4.0);
  Sophus::SO3d rotY_axis = Sophus::SO3d::rotY(PI_VAL / 6.0);
  Sophus::SO3d rotZ_axis = Sophus::SO3d::rotZ(-PI_VAL / 3.0);

  std::cout << "Rotation matrices:" << std::endl;
  std::cout << "R_x:\n" << rotX_axis.matrix() << std::endl;
  std::cout << "R_y:\n" << rotY_axis.matrix() << std::endl;
  std::cout << "R_z:\n" << rotZ_axis.matrix() << std::endl;
  std::cout << "Combined rotation R_x * R_y * R_z:\n"
            << (rotX_axis * rotY_axis * rotZ_axis).matrix() << std::endl;
  std::cout << std::endl;

  // Apply rotations to a test vector
  Eigen::Vector3d test_vector;
  test_vector << 0.0, 0.0, 1.0;
  std::cout << "Vector transformation under rotations:" << std::endl;
  std::cout << "Original vector:\n" << test_vector << std::endl;
  std::cout << "R_y * test_vector:\n" << rotY_axis * test_vector << std::endl;
  std::cout << "R_x * (R_y * test_vector):\n" << rotX_axis * (rotY_axis * test_vector) << std::endl;
  std::cout << "(R_x * R_y) * test_vector:\n" << (rotX_axis * rotY_axis) * test_vector << std::endl;
  std::cout << std::endl;

  // Display internal representation as unit quaternion
  std::cout << "R_x in matrix form:\n" << rotX_axis.matrix() << std::endl;
  std::cout << "R_x as unit quaternion (i, j, k, r):\n"
            << rotX_axis.unit_quaternion().coeffs() << std::endl;
  // Note: Eigen uses (imaginary_part_x, imaginary_part_y, imaginary_part_z, real_part)
  std::cout << std::endl;
}

