namespace FFBEngineTests {
TEST_CASE(test_channel_stats_average, "Performance") {
    ChannelStats channelStats;
    channelStats.Update(15.0);
    channelStats.Update(25.0);
    channelStats.Update(35.0);

    ASSERT_NEAR(channelStats.Avg(), 25.0, 0.001);
}
TEST_CASE(test_channel_stats_resets, "Performance") {
    ChannelStats channelStats;

    // First measurement period
    channelStats.Update(12.0);
    channelStats.Update(120.0);
    ASSERT_NEAR(channelStats.session_max, 120.0, 0.001);

    channelStats.ResetInterval();
    ASSERT_NEAR(channelStats.interval_sum, 0.0, 0.001);
    ASSERT_NEAR(channelStats.l_max, 120.0, 0.001); // Latched session max

    // Second measurement period
    channelStats.Update(24.0);
    channelStats.Update(60.0);

    ASSERT_NEAR(channelStats.interval_sum, 84.0, 0.001);
    ASSERT_NEAR(channelStats.session_max, 120.0, 0.001); // Still 120 from first period

    channelStats.Update(180.0);
    ASSERT_NEAR(channelStats.session_max, 180.0, 0.001);
}
TEST_CASE(test_channel_stats_empty_reset, "Performance") {
    ChannelStats channelStats;
    channelStats.ResetInterval();
    ASSERT_NEAR(channelStats.l_avg, 0.0, 0.001);
}
} // namespace FFBEngineTests

