#include <cstdint>
#include <cstdio>
#include "ckernel.h"
#include "llk_defs.h"

// Global configuration state
std::uint32_t unp_cfg_context          = 0u;
std::uint32_t pack_sync_tile_dst_ptr   = 0u;
std::uint32_t math_sync_tile_dst_index = 0u;

#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_A.h"
#include "llk_unpack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& layout = params->formats;
#endif

    // Configure unpack hardware for two inputs and two outputs
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        layout.unpack_A_src, layout.unpack_B_src, layout.unpack_A_dst, layout.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, 8 /* num_faces */, 8 /* num_faces */);

    // Initialize unpack A operation
    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        0, 0, FACE_R_DIM, 8, layout.unpack_A_src, layout.unpack_A_dst);

    // Process each tile in sequence
    for (int idx = 0; idx < params->TILE_CNT; ++idx)
    {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(params->buffer_A[idx]), layout.unpack_A_src, layout.unpack_A_dst);
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "ckernel_defs.h"
#include "ckernel_sfpu.h"
#include "llk_math_common.h"
#include "llk_math_eltwise_binary_sfpu.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "params.h"
#include "sfpu_operations.h"

using namespace ckernel::sfpu;

void run_kernel(const volatile struct RuntimeParams* params)
{
    const bool int_fpu_enabled = false;

    // Initialize pack sync and math hardware
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(params->formats.math, params->formats.math);

#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, int_fpu_enabled>(8, params->formats.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, int_fpu_enabled>(8, params->formats.math);
#endif

    // Wait until destination buffer space is available
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Copy tiles from input to accumulator
    for (int tile_id = 0; tile_id < params->TILE_CNT; ++tile_id)
    {
        LLK_ASSERT(
            (tile_id < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()),
            "Block tile index exceeds maximum destination tiles");

        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tile_id, params->formats.math, params->formats.math);
    }

    // Setup SFPU binary operation (add1)
    _llk_math_eltwise_binary_sfpu_init_<SfpuType::add1>();

    // Start binary SFPU computation using dest indices 0 and 1
    _llk_math_eltwise_binary_sfpu_start_<DstSync::SyncHalf>(0);
    test_utils::call_binary_sfpu_operation<APPROX_MODE, SFPU_BINARY_OPERATION, 32, params->formats.math>(0, 1, 0);

    // Finalize SFPU operation
    _llk_math_eltwise_binary_sfpu_done_();
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(params->formats.pack_src, params->formats.pack_dst, 16 * 16);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(params->formats.pack_src, params->formats.pack_dst, 16 * 16);
#endif

    // Initialize packer module
    _llk_pack_init_<false, false>(params->formats.pack_dst);

#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    // Ensure math operations have completed before packing
    _llk_packer_wait_for_math_done_();

    // Pack output tiles
    for (int out_idx = 0; out_idx < params->TILE_CNT; ++out_idx)
    {
        LLK_ASSERT(
            (out_idx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()),
            "Block tile index exceeds maximum destination tiles");

        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            out_idx, L1_ADDRESS(params->buffer_Res[out_idx]));
    }

    // Signal end of destination section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

