// Test fixture for EnumIntAction behavior across different enums and policies
class EnumIntActionTest : public PlainTestSuite {
  Q_OBJECT

 public:
  // Generic helper to validate EnumIntAction with given enum values and policy
  template <typename ENUM_T>
  void ValidateEnumAction(ENUM_T lowVal, ENUM_T highVal, ENUM_T invalidVal, QActionGroup::ExclusionPolicy policy) {
    QAction action1{"alpha item bigger"};
    action1.setCheckable(true);
    QAction action2{"beta item smaller"};
    QVERIFY(action1.text() > action2.text());

    action2.setCheckable(true);
    QVERIFY(lowVal < highVal);

    if (policy == QActionGroup::ExclusionPolicy::Exclusive) {
      action2.setChecked(true);
    }

    EnumIntAction<ENUM_T> tester;
    QCOMPARE(tester, false);  // Initially not initialized

    tester.init({{&action1, lowVal}, {&action2, highVal}}, invalidVal, policy);
    QCOMPARE(tester, true);   // Now initialized

    QCOMPARE(tester.defVal(), invalidVal);

    if (policy == QActionGroup::ExclusionPolicy::Exclusive) {
      QCOMPARE(tester.curVal(), highVal);
    } else {
      QCOMPARE(tester.curVal(), invalidVal);
    }

    auto* grp = tester.getActionGroup();
    QVERIFY(grp != nullptr);
    QCOMPARE(grp->actions().size(), 2);

    // Order depends on init container — no strict expectation here
    QCOMPARE(tester.getActionEnumAscendingList(), (QList<QAction*>{&action1, &action2}));
    QCOMPARE(tester.getActionNameAscendingList(), (QList<QAction*>{&action2, &action1}));

    QCOMPARE(tester.act2Enum(&action1), lowVal);
    QCOMPARE(tester.act2Enum((const QAction*)&action1), lowVal);
    QCOMPARE(tester.intVal2Enum((int)lowVal), lowVal);

    QCOMPARE(tester.act2Enum(&action2), highVal);
    QCOMPARE(tester.act2Enum((const QAction*)&action2), highVal);
    QCOMPARE(tester.intVal2Enum((int)highVal), highVal);

    QCOMPARE(tester.setCheckedIfActionExist((int)highVal), &action2);
    QCOMPARE(tester.setCheckedIfActionExist(highVal), &action2);

    if (policy != QActionGroup::ExclusionPolicy::None) {
      QCOMPARE(tester.curVal(), highVal);
    }
  }

 private slots:
  void test_exclusive_mode_all_types() {
    ValidateEnumAction<ViewTypeTool::ViewType>(
        ViewTypeTool::ViewType::TABLE,
        ViewTypeTool::ViewType::SEARCH,
        ViewTypeTool::DEFAULT_VIEW_TYPE,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<Style::StyleE>(
        Style::StyleE::STYLE_WINDOWS_VISTA,
        Style::StyleE::STYLE_FUSION,
        Style::StyleE::STYLE_WINDOWS_VISTA,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<Style::StyleSheetE>(
        Style::StyleSheetE::STYLESHEET_DEFAULT_LIGHT,
        Style::StyleSheetE::STYLESHEET_DARK_THEME_MOON_FOG,
        Style::StyleSheetE::STYLESHEET_DEFAULT_LIGHT,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<SearchTools::SearchModeE>(
        SearchTools::SearchModeE::REGEX,
        SearchTools::SearchModeE::FILE_CONTENTS,
        SearchTools::DEFAULT_SEARCH_MODE,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<BytesRangeTool::BytesRangeE>(
        BytesRangeTool::BytesRangeE::FIRST_16_BYTES,
        BytesRangeTool::BytesRangeE::ENTIRE_FILE,
        BytesRangeTool::DEFAULT_BYTE_RANGE,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<QCryptographicHash::Algorithm>(
        QCryptographicHash::Algorithm::Md5,
        QCryptographicHash::Algorithm::Sha256,
        QCryptographicHash::Algorithm::Md5,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<DuplicateImageDetectionCriteria::DICriteriaE>(
        DuplicateImageDetectionCriteria::DICriteriaE::LIBRARY,
        DuplicateImageDetectionCriteria::DICriteriaE::MD5,
        DuplicateImageDetectionCriteria::DEFAULT_DI_CRITERIA_E,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<FileStructurePolicy::FileStuctureModeE>(
        FileStructurePolicy::FileStuctureModeE::PRESERVE,
        FileStructurePolicy::FileStuctureModeE::FLATTEN,
        FileStructurePolicy::FileStuctureModeE::QUERY,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<SceneSortOrderHelper::SortDimE>(
        SceneSortOrderHelper::SortDimE::MOVIE_PATH,
        SceneSortOrderHelper::SortDimE::MOVIE_SIZE,
        SceneSortOrderHelper::DEFAULT_SCENE_SORT_ORDER,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<Qt::TextElideMode>(
        Qt::TextElideMode::ElideLeft,
        Qt::TextElideMode::ElideRight,
        Qt::TextElideMode::ElideNone,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<QHeaderView::ResizeMode>(
        QHeaderView::ResizeMode::Interactive,
        QHeaderView::ResizeMode::Stretch,
        QHeaderView::ResizeMode::Interactive,
        QActionGroup::ExclusionPolicy::Exclusive);

    ValidateEnumAction<Qt::ScrollBarPolicy>(
        Qt::ScrollBarPolicy::ScrollBarAsNeeded,
        Qt::ScrollBarPolicy::ScrollBarAlwaysOff,
        Qt::ScrollBarPolicy::ScrollBarAsNeeded,
        QActionGroup::ExclusionPolicy::Exclusive);
  }

  void test_exclusive_optional_mode() {
    ValidateEnumAction<PreviewTypeTool::PREVIEW_TYPE_E>(
        PreviewTypeTool::PREVIEW_TYPE_E::CATEGORY,
        PreviewTypeTool::PREVIEW_TYPE_E::PROGRESSIVE_LOAD,
        PreviewTypeTool::DEFULT_PREVIEW_TYPE_E,
        QActionGroup::ExclusionPolicy::ExclusiveOptional);
  }

  void test_no_exclusion_mode() {
    ValidateEnumAction<ScenePageNaviHelper::PageNaviE>(
        ScenePageNaviHelper::PageNaviE::FRONT,
        ScenePageNaviHelper::PageNaviE::PREVIOUS,
        ScenePageNaviHelper::PageNaviE::BEGIN_DEFAULT,
        QActionGroup::ExclusionPolicy::None);
  }
