#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include "lbug.h"

int main() {
    lbug_database database;
    lbug_connection connection;

    // Initialize database with default configuration
    lbug_database_init("" /* specify database path */, lbug_default_system_config(), &database);
    lbug_connection_init(&database, &connection);

    // Define schema for Person node
    lbug_query_result queryResult;
    lbug_connection_query(
        &connection, "CREATE NODE TABLE Person(name STRING, age INT64, PRIMARY KEY(name));", &queryResult);
    lbug_query_result_destroy(&queryResult);

    // Insert sample data
    lbug_connection_query(&connection, "CREATE (:Person {name: 'Alice', age: 25});", &queryResult);
    lbug_query_result_destroy(&queryResult);
    lbug_connection_query(&connection, "CREATE (:Person {name: 'Bob', age: 30});", &queryResult);
    lbug_query_result_destroy(&queryResult);

    // Execute a query to retrieve all Person nodes
    lbug_connection_query(&connection, "MATCH (p:Person) RETURN p.name AS NAME, p.age AS AGE;", &queryResult);

    // Process each result row
    lbug_flat_tuple currentTuple;
    lbug_value currentValue;

    while (lbug_query_result_has_next(&queryResult)) {
        lbug_query_result_get_next(&queryResult, &currentTuple);

        // Extract name field
        lbug_flat_tuple_get_value(&currentTuple, 0, &currentValue);
        char* personName;
        lbug_value_get_string(&currentValue, &personName);

        // Extract age field
        lbug_flat_tuple_get_value(&currentTuple, 1, &currentValue);
        int64_t personAge;
        lbug_value_get_int64(&currentValue, &personAge);

        printf("name: %s, age: %" PRIi64 "\n", personName, personAge);

        // Clean up dynamically allocated string
        lbug_destroy_string(personName);
    }

    // Cleanup resources
    lbug_value_destroy(&currentValue);
    lbug_flat_tuple_destroy(&currentTuple);

    // Output formatted result representation
    char* outputString = lbug_query_result_to_string(&queryResult);
    printf("%s", outputString);
    lbug_destroy_string(outputString);

    lbug_query_result_destroy(&queryResult);
    lbug_connection_destroy(&connection);
    lbug_database_destroy(&database);

    return 0;
}

