      int current_line = 0;
      input_file.open(tokenizer.current_file);
      while(current_line < line_number && std::getline(input_file, file_line)) {
        current_line++;
      }
      input_file.close();
      printf("%s", file_line.c_str());
    }

    std::cout << std::endl;
