#include <nanobind/nanobind.h>
#include <nanobind/stl/string.h>
#include <mscclpp/errors.hpp>

namespace nb = nanobind;
using namespace mscclpp;

// Exception translator registration macro
#define BIND_EXCEPTION_TRANSLATOR(exc_type_)                                                                         \
  nb::register_exception_translator(                                                                                 \
      [](const std::exception_ptr &ptr, void *user_data) {                                                           \
        try {                                                                                                        \
          std::rethrow_exception(ptr);                                                                               \
        } catch (const exc_type_ &err) {                                                                             \
          PyErr_SetObject(reinterpret_cast<PyObject *>(user_data),                                                   \
                          PyTuple_Pack(2, PyLong_FromLong(static_cast<long>(err.getErrorCode())),                    \
                                       PyUnicode_FromString(err.what())));                                         \
        }                                                                                                            \
      },                                                                                                             \
      m.attr(#exc_type_).ptr());

void bind_error_types(nb::module_ &mod) {
  // Define ErrorCode enum
  nb::enum_<ErrorCode>(mod, "ErrorCode")
      .value("SystemError", ErrorCode::SystemError)
      .value("InternalError", ErrorCode::InternalError)
      .value("RemoteError", ErrorCode::RemoteError)
      .value("InvalidUsage", ErrorCode::InvalidUsage)
      .value("Timeout", ErrorCode::Timeout)
      .value("Aborted", ErrorCode::Aborted)
      .value("ExecutorError", ErrorCode::ExecutorError);

  // Bind BaseError and its translators
  nb::exception<BaseError>(mod, "BaseError");
  BIND_EXCEPTION_TRANSLATOR(BaseError);

  // Bind derived exceptions with inheritance
  nb::exception<Error>(mod, "Error", mod.attr("BaseError").ptr());
  BIND_EXCEPTION_TRANSLATOR(Error);

  nb::exception<SysError>(mod, "SysError", mod.attr("BaseError").ptr());
  BIND_EXCEPTION_TRANSLATOR(SysError);

  nb::exception<CudaError>(mod, "CudaError", mod.attr("BaseError").ptr());
  BIND_EXCEPTION_TRANSLATOR(CudaError);

  nb::exception<CuError>(mod, "CuError", mod.attr("BaseError").ptr());
  BIND_EXCEPTION_TRANSLATOR(CuError);

  nb::exception<IbError>(mod, "IbError", mod.attr("BaseError").ptr());
  BIND_EXCEPTION_TRANSLATOR(IbError);
}

