const SignalKind SignalKind::User2{SIGUSR2};
#endif

// Constructor initializes the signal object with its kind and no notification yet
Signal::Signal(SignalKind type)
    : m_kind(type),
      m_notified() {}

// Poll method checks if the signal has been received
bool Signal::poll(Context& ctx) {
    if (!m_notified) {
        // Register the signal with the runtime's signal driver if not already done
        m_notified.emplace(ctx.runtime()->signalDriver().addSignal(m_kind).notified());
    }
    return m_notified->poll(ctx);
}

