#include "nlink_unpack/nlink_utils.h"
#include "protocol_extracter/nprotocol_extracter.h"
#include <chrono>
#include <thread>

int main(int argc, char **argv) {
  ros::init(argc, argv, "tofsensem_parser_node");
  ros::NodeHandle private_nh("~");
  serial::Serial device_serial;
  initializeSerialPort(&device_serial);
  NProtocolExtracter parser;
  tofsensem::Initialization initializer(&parser);

  ros::Rate update_rate(500);

  while (ros::ok()) {
    size_t bytes_available = device_serial.available();
    std::string buffer;

    if (bytes_available > 0) {
      device_serial.read(buffer, bytes_available);
      parser.InjectData(buffer);
    } else {
      std::this_thread::sleep_for(std::chrono::milliseconds(20));
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

