// Function to display array elements and calculate their sum
int processArray(int *ptr, int size) {
    int index, result = 0;

    // First loop: display current values and compute sum
    for(index = 0; index < size; index++) {
        printf("value %d address %u\n", *ptr, ptr);
        printf("%d\n", *ptr);
        result = result + *ptr;
        ptr++;
    }

    printf("enter total element");
    scanf("%d", &size);

    // Second loop: read new elements into array
    for(index = 0; index < size; index++) {
        printf("enter %d element ", index);
        scanf("%d", &arr[index]);
    }

    processArray(&arr[0], size);
    return 0;
}

