#include "test/jemalloc_test.h"
#include "jemalloc/internal/peak.h"

TEST_BEGIN(test_peak_modified) {
    peak_t peak = PEAK_INITIALIZER;
    expect_u64_eq(0, peak_max(&peak),
        "Initial peak should be zero");

    peak_update(&peak, 150, 75);
    expect_u64_eq(75, peak_max(&peak),
        "First update should set peak to allocated - deallocated");

    peak_update(&peak, 150, 150);
    expect_u64_eq(75, peak_max(&peak), 
        "Deallocation events shouldn't affect the peak");

    peak_update(&peak, 150, 300);
    expect_u64_eq(75, peak_max(&peak), 
        "Still net negative, no change to peak");

    peak_update(&peak, 300, 300);
    expect_u64_eq(75, peak_max(&peak), 
        "Not yet at previous peak level");

    peak_update(&peak, 450, 300);
    expect_u64_eq(150, peak_max(&peak), 
        "New peak reached after positive net allocation");

    peak_set_zero(&peak, 450, 300);
    expect_u64_eq(0, peak_max(&peak), 
        "Zeroing should reset the peak value");

    peak_update(&peak, 450, 500);
    expect_u64_eq(0, peak_max(&peak), 
        "Net deallocation after zeroing keeps peak at zero");

    peak_update(&peak, 600, 500);
    expect_u64_eq(0, peak_max(&peak), 
        "Still net negative, peak remains zero");

    peak_update(&peak, 700, 500);
    expect_u64_eq(200, peak_max(&peak), 
        "New positive net allocation creates new peak");

    /*
     * Now test zeroing when currently in a net-deallocator state.
     */
    peak_set_zero(&peak, 800, 1000);
    expect_u64_eq(0, peak_max(&peak), 
        "Zeroing while net-deallocator should still reset peak.");

    peak_update(&peak, 800, 1100);
    expect_u64_eq(0, peak_max(&peak), 
        "Continued net deallocation maintains zero peak.");

    peak_update(&peak, 950, 1100);
    expect_u64_eq(0, peak_max(&peak), 
        "Still not enough to exceed previous peak.");

    peak_update(&peak, 1100, 1100);
    expect_u64_eq(150, peak_max(&peak), 
        "Finally reach new positive net allocation level.");
}
TEST_END

int
main(void) {
    return test_no_reentrancy(
        test_peak_modified);
}

