using sen::components::rest::HttpHeader;
using sen::components::rest::HttpResponse;

std::string getCorsHeaders()
{
  return "Access-Control-Allow-Origin: *\r\n"
         "Access-Control-Allow-Headers: *\r\n"
         "Access-Control-Allow-Methods: GET, POST, DELETE, PUT, OPTIONS\r\n";
}

/// @test
/// Verify the default state of an HTTP response object
/// @requirements(SEN-1061)
TEST(Rest, default_response)
{
  HttpResponse resp;
  EXPECT_EQ(resp.getStatusCode(), 404);
  EXPECT_EQ(resp.getReasonPhrase(), "Not Found");
  EXPECT_EQ(resp.toBuffer(), "HTTP/1.1 404 Not Found\r\n" + getCorsHeaders() + "Content-Length: 0\r\n\r\n");
}

/// @test
/// Validate reason phrases associated with various HTTP status codes
/// @requirements(SEN-1061)
TEST(Rest, status_code)
{
  {
    HttpResponse resp(200);
    EXPECT_EQ(resp.getStatusCode(), 200);
    EXPECT_EQ(resp.getReasonPhrase(), "OK");
  }
  {
    HttpResponse resp(403);
    EXPECT_EQ(resp.getStatusCode(), 403);
    EXPECT_EQ(resp.getReasonPhrase(), "Forbidden");
  }
  {
    HttpResponse resp(502);
    EXPECT_EQ(resp.getStatusCode(), 502);
    EXPECT_EQ(resp.getReasonPhrase(), "Bad Gateway");
  }
}

/// @test
/// Confirm correct serialization of HTTP headers in responses
/// @requirements(SEN-1061)
TEST(Rest, serialization_headers)
{
  {
    HttpResponse resp(200);
    EXPECT_EQ(resp.toBuffer(), "HTTP/1.1 200 OK\r\n" + getCorsHeaders() + "Content-Length: 0\r\n\r\n");
  }
  {
    HttpResponse resp(200, std::vector<HttpHeader> {{"Content-Type", "text/javascript; charset=utf-8"}});
    EXPECT_EQ(resp.toBuffer(),
              "HTTP/1.1 200 OK\r\n"
              "Content-Type: text/javascript; charset=utf-8\r\n" +
                getCorsHeaders() + "Content-Length: 0\r\n\r\n");
  }
  {
    HttpResponse resp(200,
                      std::vector<HttpHeader> {{"Cache-Control", "max-age=604800"},
                                               {"Content-Type", "text/javascript; charset=utf-8"}});
    EXPECT_EQ(resp.toBuffer(),
              "HTTP/1.1 200 OK\r\n"
              "Cache-Control: max-age=604800\r\nContent-Type: text/javascript; "
              "charset=utf-8\r\n" +
                getCorsHeaders() + "Content-Length: 0\r\n\r\n");
  }
}

/// @test
/// Ensure proper handling and serialization of message body content
/// @requirements(SEN-1061)
TEST(Rest, body)
{
  std::string payload = "hello world";
  HttpResponse resp(200, std::vector<HttpHeader> {{"Content-Type", "text/plain; charset=utf-8"}}, "hello world");
  EXPECT_EQ(resp.toBuffer(),
            "HTTP/1.1 200 OK\r\n"
            "Content-Type: text/plain; charset=utf-8\r\n" +
              getCorsHeaders() + "Content-Length: " + std::to_string(payload.length()) + "\r\n\r\n" + payload);
}

/// @test
/// Validate response behavior when CORS headers are explicitly disabled
/// @requirements(SEN-1061)
TEST(Rest, no_cors_headers)
{
  HttpResponse resp(200, {}, "", false);
  EXPECT_EQ(resp.toBuffer(),
            "HTTP/1.1 200 OK\r\n"
            "Content-Length: 0\r\n\r\n");
}

