// Program to check if a number is prime
int main() {
    int number, divisor;
    std::cout << "enter your number to check: ";
    std::cin >> number;

    if (number <= 1) {
        std::cout << "it is not prime" << std::endl;
    } else {
        bool isPrime = true;
        for (divisor = 2; divisor * divisor <= number; divisor++) {
            if (number % divisor == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            std::cout << "it is prime" << std::endl;
        } else {
            std::cout << "it is not prime" << std::endl;
        }
    }

    return 0;
}

