namespace http {
namespace server {

connection_manager::connection_manager()
{
}

void connection_manager::add_connection(connection_ptr conn)
{
  active_connections_.insert(conn);
  conn->start();
}

void connection_manager::remove_connection(connection_ptr conn)
{
  active_connections_.erase(conn);
  conn->stop();
}

void connection_manager::shutdown_all()
{
  for (auto conn : active_connections_) {
    conn->stop();
  }
  active_connections_.clear();
}

