using json = nlohmann::json;

int main()
{
    // Build a JSON object from flattened representation
    json data_map =
    {
        {"/project/status", "active"},
        {"/config/debug", true},
        {"/items/0", 10},
        {"/items/1", 20},
        {"/items/2", 30},
        {"/author/name", "Alice"},
        {"/metadata/empty", nullptr},
        {"/settings/mode", "production"},
        {"/settings/version", 1.5},
        {"/constant/euler", 2.718}
    };

    // Convert flattened structure back to nested form
    std::cout << std::setfill(' ') << std::setw(4) << data_map.unflatten() << '\n';

