    json data = json::parse(R"({"uint64": 18446744073709551615})");

    std::cout << "operator[]:                " << data["uint64"] << '\n'
              << "default value (int):       " << data.value("uint64", 0) << '\n'
              << "default value (uint64_t):  " << data.value("uint64", static_cast<std::uint64_t>(0)) << '\n'
