// Wrapper for pread system call with 64-bit offset support
ssize_t pread_wrapper(int fd, void *buffer, size_t count, off_t offset)
{
	return syscall_cp(SYS_pread, fd, buffer, count, __SYSCALL_LL_PRW(offset));
}

