#include <QtTest>
#include <QCoreApplication>
#include "PlainTestSuite.h"
#include "SortedUniqStrLst.h"

class SortedUniqStrLstTest : public PlainTestSuite {
  Q_OBJECT
 public:
  SortedUniqStrLstTest() : PlainTestSuite{} {}
 private slots:
  void insertOneElementFromHint() {
    // leading/trailing space will not process
    // only if format called
    QString inputString{"  X Y,   Z W "};
    SortedUniqStrLst collection;
    collection.insertOneElementFromHint(inputString);
    QStringList expectedList{inputString};
    QCOMPARE(collection.join(), inputString);
    QCOMPARE(collection.toSortedList(), expectedList);
    QStringList expectedList2{"X Y", "Z W"};
    collection.format();
    QCOMPARE(collection.join(), "X Y,Z W");
    QCOMPARE(collection.toSortedList(), expectedList2);
  }
  void test_Sentence2StringList() {
    QString text{" A, \nB, C ,,\r\n,  D,  \n, E, G   "};
    QStringList expectedList{"A", "B", "C", "D", "E", "G"};
    QCOMPARE(SortedUniqStrLst::Sentence2StringList(text), expectedList);
  }
  void test_operateIncDecEq() {
    SortedUniqStrLst s45{QStringList{"4", "5"}};
    SortedUniqStrLst s10{QStringList{"1", "0"}};
    SortedUniqStrLst s6{QStringList{"6"}};
    SortedUniqStrLst emptyLst;
    QCOMPARE(emptyLst.join(), "");
    emptyLst += s6;
    QCOMPARE(emptyLst.join(), "6");
    emptyLst += s45;
    QCOMPARE(emptyLst.join(), "4,5,6");
    emptyLst += s45;
    QCOMPARE(emptyLst.join(), "4,5,6");
    emptyLst += s10;
    QCOMPARE(emptyLst.join(), "0,1,4,5,6");
    emptyLst -= "1";
    QCOMPARE(emptyLst.join(), "0,4,5,6");
    emptyLst -= "6";
    QCOMPARE(emptyLst.join(), "0,4,5");
    emptyLst -= "0";
    QCOMPARE(emptyLst.join(), "4,5");
    emptyLst -= "4,5";
    QCOMPARE(emptyLst.join(), "4,5");
    emptyLst -= "4";
    emptyLst -= "4";
    QCOMPARE(emptyLst.join(), "5");
    emptyLst -= "5";
    QCOMPARE(emptyLst.join(), "");
  }
  void test_contruct_and_copy_construct() {
    SortedUniqStrLst emptyLst;
    QCOMPARE(emptyLst.isEmpty(), true);
    QCOMPARE(emptyLst.count(), 0);
    SortedUniqStrLst singleItem{"Z"};
    SortedUniqStrLst singleItemAlso{QStringList{"Z"}};
    QCOMPARE(singleItem.isEmpty(), false);
    QCOMPARE(singleItem.count(), 1);
    QCOMPARE(singleItem.join(), "Z");
    QCOMPARE(singleItem.toSortedList(), (QStringList{"Z"}));
    SortedUniqStrLst sortedLst{"D,A,C,B"};
    const QStringList expectedList{"A", "B", "C", "D"};
    QCOMPARE(sortedLst.join(), "A,B,C,D");
    QCOMPARE(sortedLst.toSortedList(), expectedList);
    QCOMPARE(sortedLst.count(), 4);
    QCOMPARE(sortedLst.isEmpty(), false);
    SortedUniqStrLst sortedLstAlso{QStringList{"B", "D", "A", "C"}};
    QCOMPARE(sortedLst, sortedLstAlso);
    SortedUniqStrLst partialLst{"B,A,C"};
    QVERIFY(partialLst != sortedLst);
    QCOMPARE(partialLst.count(), 3);
    QCOMPARE(partialLst.isEmpty(), false);
    QCOMPARE(partialLst.join(), "A,B,C");
    QCOMPARE(partialLst.toSortedList(), (QStringList{"A", "B", "C"}));
    SortedUniqStrLst partialLstAlso{QStringList{"A", "C", "B"}};
    QCOMPARE(partialLst, partialLstAlso);
    QStringList expect7{"0", "1", "2", "3", "4", "5", "6"};
    SortedUniqStrLst lst7{"0,5,2,1,4,3,6"};
    SortedUniqStrLst lst7Also{expect7};
    QCOMPARE(lst7.count(), 7);
    QCOMPARE(lst7.isEmpty(), false);
    QCOMPARE(lst7.join(), "0,1,2,3,4,5,6");
    QCOMPARE(lst7.toSortedList(), expect7);
    QCOMPARE(lst7, lst7Also);
    SortedUniqStrLst lst7Copy{lst7};
    QCOMPARE(lst7Copy, lst7);
    QVERIFY(!(lst7Copy != lst7));
  }
  void test_toLowerSets() {
    SortedUniqStrLst mixedCaseLst{"Test Case, TEST CASE"};
    QCOMPARE(mixedCaseLst.toLowerSets(), (QSet<QString>{"test case"}));
  }
  void test_remove() {
    QStringList initialItems{"9", "2", "4", "6", "3", "0"};
    SortedUniqStrLst lst{initialItems};
    QCOMPARE(lst.join(), "0,2,3,4,6,9");
    QCOMPARE(lst.remove("8"), false);
    QCOMPARE(lst.join(), "0,2,3,4,6,9");
    QCOMPARE(lst.remove("4"), true);
    QCOMPARE(lst.join(), "0,2,3,6,9");
    QCOMPARE(lst.remove("0"), true);
    QCOMPARE(lst.join(), "2,3,6,9");
    QCOMPARE(lst.remove("9"), true);
    QCOMPARE(lst.join(), "2,3,6");
    QCOMPARE(lst.remove("2"), true);
    QCOMPARE(lst.join(), "3,6");
    QCOMPARE(lst.remove("3"), true);
    QCOMPARE(lst.join(), "6");
    QCOMPARE(lst.remove("6"), true);
    QCOMPARE(lst.join(), "");
    QCOMPARE(lst.remove("0"), false);
    QCOMPARE(lst.join(), "");
  }
  void test_clear() {
    SortedUniqStrLst lst{"10,20,30,40,50"};
    QCOMPARE(lst.isEmpty(), false);
    lst.clear();
    QCOMPARE(lst.join(), "");
    QCOMPARE(lst.isEmpty(), true);
  }
};
