/// @test
/// Verify Remote interest subscription behavior when no objects exist yet
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processANewRemoteSubscriptionWhenThereAreNoObjects)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  handler.addSubscriber(InterestId(1), &participant, true);
  ASSERT_EQ(handler.remotesUpdatesBMMap.size<RemoteParticipant*>(), 0);
  ASSERT_EQ(handler.remotesToInterestsUpdatesMap.size(), 0);
  ASSERT_TRUE(handler.remotesInterestsBMMap.contains(&participant));
}

/// @test
/// Validate Remote interest handling when an object is added after subscriber registration
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processANewObjectWhenASubscriberWasAdded)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addSubscriber(InterestId(1), &participant);
  handler.addObject(InterestId(1), &update);
  ASSERT_TRUE(handler.interestsUpdatesBMMap.contains(InterestId(1)));
  ASSERT_TRUE(handler.remotesUpdatesBMMap.contains(&participant));
  ASSERT_EQ(handler.remotesToInterestsUpdatesMap.size(), 1);
}

/// @test
/// Test Remote interest with multiple objects after a single subscriber registration
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, processTwoObjectWhenASubscriberWasAdded)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate obj1;
  ObjectUpdate obj2;
  handler.addSubscriber(InterestId(1), &participant);
  handler.addObject(InterestId(1), &obj1);
  handler.addObject(InterestId(1), &obj2);

  const auto* ptr1 = handler.interestsUpdatesBMMap.tryGet(InterestId(1));
  ASSERT_NE(nullptr, ptr1);
  EXPECT_EQ(ptr1->size(), 2);

  const auto* ptr2 = handler.remotesUpdatesBMMap.tryGet(&participant);
  ASSERT_NE(nullptr, ptr2);
  EXPECT_EQ(ptr2->size(), 2);
}

/// @test
/// Confirm Remote interest subscription occurs when object is registered first
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registersANewRemoteSubscriptionAfterObjectWasAdded)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(1), &update);
  handler.addSubscriber(InterestId(1), &participant);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.contains(&participant));
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.at(&participant).contains(InterestId(1)));
}

/// @test
/// Check Remote interest handling with two subscribers after object registration
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registersTwoSubscriptionsAfterObjectWasAdded)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate update;
  handler.addObject(InterestId(1), &update);
  handler.addSubscriber(InterestId(1), &p1);
  handler.addSubscriber(InterestId(1), &p2);
  EXPECT_EQ(handler.remotesUpdatesBMMap.size<RemoteParticipant*>(), 2);
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 2);
}

/// @test
/// Verify complete removal of subscriber and associated updates
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, removesSubscriptionWithUpdates)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(1), &update);
  handler.addSubscriber(InterestId(1), &participant);
  handler.removeSubscriber(InterestId(1), &participant);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
}

/// @test
/// Ensure object remains when one subscriber is removed but others remain
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, keepsTheObjectInterestWhenAInterestedSubscriptionRemains)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate update;
  handler.addObject(InterestId(1), &update);
  handler.addSubscriber(InterestId(1), &p1);
  handler.addSubscriber(InterestId(1), &p2);
  handler.removeSubscriber(InterestId(1), &p1);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.contains(&p2));
  EXPECT_TRUE(!handler.remotesUpdatesBMMap.contains(&p1));
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 1);
  EXPECT_TRUE(handler.interestsUpdatesBMMap.contains(InterestId(1)));
}

/// @test
/// Validate complete cleanup after object removal affects all interested remotes
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregistersObjectAfterObjectRemoval)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate update;
  handler.addObject(InterestId(1), &update);
  handler.addSubscriber(InterestId(1), &p1);
  handler.addSubscriber(InterestId(1), &p2);
  handler.removeObject(&update);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
  EXPECT_TRUE(handler.interestsUpdatesBMMap.empty());
}

/// @test
/// Check partial cleanup when removing one object among multiple
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregistersOneOfTwoObjectFromInterestedRemotes)
{
  RemoteInterestsHandler handler;
  RemoteParticipant p1;
  RemoteParticipant p2;
  ObjectUpdate obj1;
  ObjectUpdate obj2;
  handler.addObject(InterestId(1), &obj1);
  handler.addObject(InterestId(1), &obj2);
  handler.addSubscriber(InterestId(1), &p1);
  handler.addSubscriber(InterestId(1), &p2);

  {
    const auto* ptr = handler.interestsUpdatesBMMap.tryGet(InterestId(1));
    ASSERT_NE(nullptr, ptr);
    EXPECT_EQ(ptr->size(), 2);
  }

  handler.removeObject(&obj1);
  EXPECT_EQ(handler.remotesUpdatesBMMap.size<RemoteParticipant*>(), 2);
  EXPECT_EQ(handler.remotesToInterestsUpdatesMap.size(), 2);

  {
    const auto* ptr = handler.interestsUpdatesBMMap.tryGet(InterestId(1));
    ASSERT_NE(nullptr, ptr);
    EXPECT_EQ(ptr->size(), 1);
  }
}

/// @test
/// Confirm multiple interests can reference the same object
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, registerTwoInterestsToTheSameObject)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(1), &update);
  handler.addObject(InterestId(2), &update);
  handler.addSubscriber(InterestId(1), &participant);
  handler.addSubscriber(InterestId(2), &participant);
  auto& registeredInterests = handler.remotesToInterestsUpdatesMap.at(&participant);
  EXPECT_TRUE(registeredInterests.contains(InterestId(1)));
  EXPECT_TRUE(registeredInterests.contains(InterestId(2)));
}

/// @test
/// Verify object persistence when one interest is removed but another remains
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, keepsObjectForRemoteWhenAInterestRemains)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(1), &update);
  handler.addObject(InterestId(2), &update);
  handler.addSubscriber(InterestId(1), &participant);
  handler.addSubscriber(InterestId(2), &participant);
  handler.removeSubscriber(InterestId(1), &participant);
  auto& registeredInterests = handler.remotesToInterestsUpdatesMap.at(&participant);
  EXPECT_TRUE(registeredInterests.contains(&update));
  EXPECT_TRUE(registeredInterests.contains(InterestId(2)));
  EXPECT_TRUE(!registeredInterests.contains(InterestId(1)));
  EXPECT_TRUE(handler.remotesUpdatesBMMap.contains(&update));
}

/// @test
/// Ensure full cleanup when all interests are removed from a remote
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregisterObjectForRemoteAfterNoInterestsRemain)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate update;
  handler.addObject(InterestId(1), &update);
  handler.addObject(InterestId(2), &update);
  handler.addSubscriber(InterestId(1), &participant);
  handler.addSubscriber(InterestId(2), &participant);
  handler.removeSubscriber(InterestId(1), &participant);
  handler.removeSubscriber(InterestId(2), &participant);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
}

/// @test
/// Validate complete removal of remote participant and its associations
/// @requirements(SEN-369)
TEST(ARemoteInterestHandler, deregistersRemoteAndItsReferencesWhenRemoved)
{
  RemoteInterestsHandler handler;
  RemoteParticipant participant;
  ObjectUpdate obj1;
  ObjectUpdate obj2;
  handler.addObject(InterestId(1), &obj1);
  handler.addObject(InterestId(2), &obj2);
  handler.addSubscriber(InterestId(1), &participant);
  handler.addSubscriber(InterestId(2), &participant);
  handler.removeSubscriber(&participant);
  EXPECT_TRUE(handler.remotesUpdatesBMMap.empty());
  EXPECT_TRUE(handler.remotesToInterestsUpdatesMap.empty());
  EXPECT_TRUE(handler.remotesInterestsBMMap.empty());
  EXPECT_FALSE(handler.interestsUpdatesBMMap.empty());
}

