// Function to perform BLAS operations based on TRANS value
int CNAME(blas_arg_t *params, BLASLONG *range_m, BLASLONG *range_n, FLOAT *sa, FLOAT *sb, BLASLONG thread_id) {
#if TRANS == 1
    LASWP_PLUS (params -> n, 1, params -> m, ZERO, ZERO, params -> b, params -> ldb, NULL, 0, params -> c, 1);
    TRSM_LNLU(params, range_m, range_n, sa, sb, 0);
    TRSM_LNUN(params, range_m, range_n, sa, sb, 0); 
#elif TRANS == 2
    TRSM_LTUN(params, range_m, range_n, sa, sb, 0);
    TRSM_LTLU(params, range_m, range_n, sa, sb, 0);

    LASWP_MINUS(params -> n, 1, params -> m, ZERO, ZERO, params -> b, params -> ldb, NULL, 0, params -> c, -1);
#elif TRANS == 3
    LASWP_PLUS (params -> n, 1, params -> m, ZERO, ZERO, params -> b, params -> ldb, NULL, 0, params -> c, 1);
    TRSM_LRLU(params, range_m, range_n, sa, sb, 0);
    TRSM_LRUN(params, range_m, range_n, sa, sb, 0);
#else
    TRSM_LCUN(params, range_m, range_n, sa, sb, 0);
    TRSM_LCLU(params, range_m, range_n, sa, sb, 0);
    LASWP_MINUS(params -> n, 1,    params -> m, ZERO, ZERO, params -> b, params -> ldb, NULL, 0, params -> c, -1);
#endif
   return 0;
}

