void UModularSynthComponent::SetSynthPreset(const FModularSynthPreset& SynthPresetData)
{
	SynthCommand([this, SynthPresetData]()
	{
		EpicSynth1.SetMonoMode(!SynthPresetData.bEnablePolyphony);
		EpicSynth1.SetOscType(0, (Audio::EOsc::Type)SynthPresetData.Osc1Type);
		EpicSynth1.SetOscGain(0, SynthPresetData.Osc1Gain);
		EpicSynth1.SetOscOctave(0, SynthPresetData.Osc1Octave);
		EpicSynth1.SetOscSemitones(0, SynthPresetData.Osc1Semitones);
		EpicSynth1.SetOscCents(0, SynthPresetData.Osc1Cents);
		EpicSynth1.SetOscPulseWidth(0, SynthPresetData.Osc1PulseWidth);
		EpicSynth1.SetOscType(1, (Audio::EOsc::Type)SynthPresetData.Osc2Type);
		EpicSynth1.SetOscGain(1, SynthPresetData.Osc2Gain);
		EpicSynth1.SetOscOctave(1, SynthPresetData.Osc2Octave);
		EpicSynth1.SetOscSemitones(1, SynthPresetData.Osc2Semitones);
		EpicSynth1.SetOscCents(1, SynthPresetData.Osc2Cents);
		EpicSynth1.SetOscPulseWidth(1, SynthPresetData.Osc2PulseWidth);
		EpicSynth1.SetOscPortamento(SynthPresetData.Portamento);
		EpicSynth1.SetOscUnison(SynthPresetData.bEnableUnison);
		EpicSynth1.SetOscSync(SynthPresetData.bEnableOscillatorSync);
		EpicSynth1.SetOscSpread(SynthPresetData.Spread);
		EpicSynth1.SetPan(SynthPresetData.Pan);
		EpicSynth1.SetLFOFrequency(0, SynthPresetData.LFO1Frequency);
		EpicSynth1.SetLFOGain(0, SynthPresetData.LFO1Gain);
		EpicSynth1.SetLFOType(0, (Audio::ELFO::Type)SynthPresetData.LFO1Type);
		EpicSynth1.SetLFOMode(0, (Audio::ELFOMode::Type)SynthPresetData.LFO1Mode);
		EpicSynth1.SetLFOPatch(0, SynthPresetData.LFO1PatchType);
		EpicSynth1.SetLFOFrequency(1, SynthPresetData.LFO2Frequency);
		EpicSynth1.SetLFOGain(1, SynthPresetData.LFO2Gain);
		EpicSynth1.SetLFOType(1, (Audio::ELFO::Type)SynthPresetData.LFO2Type);
		EpicSynth1.SetLFOMode(1, (Audio::ELFOMode::Type)SynthPresetData.LFO2Mode);
		EpicSynth1.SetLFOPatch(1, SynthPresetData.LFO2PatchType);
		EpicSynth1.SetGainDb(SynthPresetData.GainDb);

		EpicSynth1.SetEnvAttackTime(SynthPresetData.AttackTime);
		EpicSynth1.SetEnvDecayTime(SynthPresetData.DecayTime);
		EpicSynth1.SetEnvSustainGain(SynthPresetData.SustainGain);
		EpicSynth1.SetEnvReleaseTime(SynthPresetData.ReleaseTime);
		EpicSynth1.SetModEnvPatch(SynthPresetData.ModEnvPatchType);
		EpicSynth1.SetModEnvBiasPatch(SynthPresetData.ModEnvBiasPatchType);
		EpicSynth1.SetModEnvInvert(SynthPresetData.bInvertModulationEnvelope);
		EpicSynth1.SetModEnvBiasInvert(SynthPresetData.bInvertModulationEnvelopeBias);
		EpicSynth1.SetModEnvDepth(SynthPresetData.ModulationEnvelopeDepth);
		EpicSynth1.SetModEnvAttackTime(SynthPresetData.ModulationEnvelopeAttackTime);
		EpicSynth1.SetModEnvDecayTime(SynthPresetData.ModulationEnvelopeDecayTime);
		EpicSynth1.SetModEnvSustainGain(SynthPresetData.ModulationEnvelopeSustainGain);
		EpicSynth1.SetModEnvReleaseTime(SynthPresetData.ModulationEnvelopeReleaseTime);
		EpicSynth1.SetEnvLegatoEnabled(SynthPresetData.bLegato);
		EpicSynth1.SetEnvRetriggerMode(SynthPresetData.bRetrigger);
		EpicSynth1.SetFilterFrequency(SynthPresetData.FilterFrequency);
		EpicSynth1.SetFilterQ(SynthPresetData.FilterQ);
		EpicSynth1.SetFilterType((Audio::EFilter::Type)SynthPresetData.FilterType);
		EpicSynth1.SetFilterAlgorithm(SynthPresetData.FilterAlgorithm);
		EpicSynth1.SetStereoDelayIsEnabled(SynthPresetData.bStereoDelayEnabled);
		EpicSynth1.SetStereoDelayMode((Audio::EStereoDelayMode::Type)SynthPresetData.StereoDelayMode);
		EpicSynth1.SetStereoDelayTimeMsec(SynthPresetData.StereoDelayTime);
		EpicSynth1.SetStereoDelayFeedback(SynthPresetData.StereoDelayFeedback);
		EpicSynth1.SetStereoDelayWetLevel(SynthPresetData.StereoDelayWetlevel);
		EpicSynth1.SetStereoDelayRatio(SynthPresetData.StereoDelayRatio);
		EpicSynth1.SetChorusEnabled(SynthPresetData.bChorusEnabled);
		EpicSynth1.SetChorusDepth(Audio::EChorusDelays::Left, SynthPresetData.ChorusDepth);
		EpicSynth1.SetChorusDepth(Audio::EChorusDelays::Center, SynthPresetData.ChorusDepth);
		EpicSynth1.SetChorusDepth(Audio::EChorusDelays::Right, SynthPresetData.ChorusDepth);
		EpicSynth1.SetChorusFeedback(Audio::EChorusDelays::Left, SynthPresetData.ChorusFeedback);
		EpicSynth1.SetChorusFeedback(Audio::EChorusDelays::Center, SynthPresetData.ChorusFeedback);
		EpicSynth1.SetChorusFeedback(Audio::EChorusDelays::Right, SynthPresetData.ChorusFeedback);
		EpicSynth1.SetChorusFrequency(Audio::EChorusDelays::Left, SynthPresetData.ChorusFrequency);
		EpicSynth1.SetChorusFrequency(Audio::EChorusDelays::Center, SynthPresetData.ChorusFrequency);
		EpicSynth1.SetChorusFrequency(Audio::EChorusDelays::Right, SynthPresetData.ChorusFrequency);
		// Clear existing patches first
		EpicSynth1.ClearPatches();
		// Then apply all new patches from the preset
		for (const FEpicSynth1Patch& Patch : SynthPresetData.Patches)
		{
			if (Patch.PatchCables.Num() > 0)
			{
				EpicSynth1.CreatePatch(Patch.PatchSource, Patch.PatchCables, true);
			}
		}
	});
}

