  void setup() { GlobalMockObject::reset(); }
  void teardown() { GlobalMockObject::verify(); }

  void copyTextAction_valid() {
    const QString clipboardContent{"Sample text for testing"};
    MOCKER(FileTool::CopyTextToSystemClipboard) //
        .expects(exactly(1))
        .with(eq(clipboardContent)) //
        .will(returnValue(true));    //

    CommandsPreview viewer("TestViewer CopyText");
    viewer.setPlainText(clipboardContent);
    QVERIFY(viewer.COPY_TEXT != nullptr);
    emit viewer.COPY_TEXT->triggered();
  }

  void testAlwaysOnTopFeature() {
    CommandsPreview viewer("TestViewer AlwaysOnTop");
    viewer.show();

    QVERIFY(!viewer.windowFlags().testFlag(Qt::WindowStaysOnTopHint));
    QVERIFY(!viewer.STAY_ON_TOP->isChecked());

    viewer.STAY_ON_TOP->setChecked(true);
    emit viewer.STAY_ON_TOP->toggled(true);

    QVERIFY(viewer.windowFlags().testFlag(Qt::WindowStaysOnTopHint));
    QVERIFY(viewer.STAY_ON_TOP->isChecked());

    viewer.STAY_ON_TOP->setChecked(false);
    emit viewer.STAY_ON_TOP->toggled(false);

    QVERIFY(!viewer.windowFlags().testFlag(Qt::WindowStaysOnTopHint));
    QVERIFY(!viewer.STAY_ON_TOP->isChecked());
    viewer.close();
  }
};

