// Calculate area of square
void calculateSquareArea(int side) {
    int area = side * side;
    std::cout << "area of square= " << area << std::endl;
}

// Calculate perimeter of rectangle
void calculateRectanglePerimeter(int length, int width) {
    int perimeter = 2 * (length + width);
    std::cout << "perimeter of rectangle= " << perimeter << std::endl;
}

// Calculate area of circle
void calculateCircleArea(int radius) {
    const double PI = 3.14159;
    double area = PI * radius * radius;
    std::cout << "area of circle= " << area << std::endl;
}

// Find maximum of 3 numbers
void findMaxOfThree(int x, int y, int z) {
    int max = x;
    if (y > max) max = y;
    if (z > max) max = z;
    std::cout << "max of 3 nos= " << max << std::endl;
}

// Print multiplication table
void printMultiplicationTable(int number) {
    std::cout << "table of " << number << ":" << std::endl;
    for (int i = 1; i <= 10; ++i) {
        std::cout << number << " * " << i << " = " << (number * i) << std::endl;
    }
}

int main() {
    int choice = 0;
    int side, length, width, radius, num1, num2, num3;

    while (choice != 6) {
        system("cls");
        std::cout << "1. area of square" << std::endl;
        std::cout << "2. perimeter of rectangle" << std::endl;
        std::cout << "3. area of circle" << std::endl;
        std::cout << "4. max of 3 nos" << std::endl;
        std::cout << "5. table of number" << std::endl;
        std::cout << "6. exit" << std::endl;
        std::cout << "enter any choice: ";
        std::cin >> choice;

        switch (choice) {
            case 1:
                std::cout << "enter any side: ";
                std::cin >> side;
                calculateSquareArea(side);
                break;

            case 2:
                std::cout << "enter length and breadth: ";
                std::cin >> length >> width;
                calculateRectanglePerimeter(length, width);
                break;

            case 3:
                std::cout << "enter radius: ";
                std::cin >> radius;
                calculateCircleArea(radius);
                break;

            case 4:
                std::cout << "enter three numbers: ";
                std::cin >> num1 >> num2 >> num3;
                findMaxOfThree(num1, num2, num3);
                break;

            case 5:
                std::cout << "enter number: ";
                std::cin >> num1;
                printMultiplicationTable(num1);
                break;

            case 6:
                std::cout << "Exiting..." << std::endl;
                break;

            default:
                std::cout << "Invalid choice! Please try again." << std::endl;
        }

        // Pause before clearing screen (optional)
        system("pause");
    }

    return 0;
}

#include "test/jemalloc_test.h"
#define MILLION UINT64_C(1000000000)
TEST_BEGIN(test_nstime_initialization) {
	nstime_t time_val;
	nstime_init(&time_val, 84000000086);
	expect_u64_eq(nstime_ns(&time_val), 84000000086, "nanoseconds read incorrectly");
	expect_u64_eq(nstime_sec(&time_val), 84, "seconds read incorrectly");
	expect_u64_eq(nstime_nsec(&time_val), 86, "nanoseconds part read incorrectly");
}
TEST_END

TEST_BEGIN(test_nstime_initialization2) {
	nstime_t time_val;
	nstime_init2(&time_val, 84, 86);
	expect_u64_eq(nstime_sec(&time_val), 84, "seconds read incorrectly");
	expect_u64_eq(nstime_nsec(&time_val), 86, "nanoseconds read incorrectly");
}
TEST_END

TEST_BEGIN(test_nstime_copy_operation) {
	nstime_t src_time, dst_time;
	nstime_init2(&src_time, 84, 86);
	nstime_init_zero(&dst_time);
	nstime_copy(&dst_time, &src_time);
	expect_u64_eq(nstime_sec(&dst_time), 84, "seconds copied incorrectly");
	expect_u64_eq(nstime_nsec(&dst_time), 86, "nanoseconds copied incorrectly");
}
TEST_END

TEST_BEGIN(test_nstime_comparison) {
	nstime_t time_a, time_b;
	nstime_init2(&time_a, 84, 86);
	nstime_copy(&time_b, &time_a);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0, "Times should be equal");
	expect_d_eq(nstime_compare(&time_b, &time_a), 0, "Times should be equal");

	nstime_init2(&time_b, 84, 85);
	expect_d_eq(nstime_compare(&time_a, &time_b), 1,
	    "time_a should be greater than time_b");
	expect_d_eq(nstime_compare(&time_b, &time_a), -1,
	    "time_b should be less than time_a");

	nstime_init2(&time_b, 84, 87);
	expect_d_eq(nstime_compare(&time_a, &time_b), -1,
	    "time_a should be less than time_b");
	expect_d_eq(nstime_compare(&time_b, &time_a), 1,
	    "time_b should be greater than time_a");

	nstime_init2(&time_b, 83, MILLION - 1);
	expect_d_eq(nstime_compare(&time_a, &time_b), 1,
	    "time_a should be greater than time_b");
	expect_d_eq(nstime_compare(&time_b, &time_a), -1,
	    "time_b should be less than time_a");

	nstime_init2(&time_b, 85, 0);
	expect_d_eq(nstime_compare(&time_a, &time_b), -1,
	    "time_a should be less than time_b");
	expect_d_eq(nstime_compare(&time_b, &time_a), 1,
	    "time_b should be greater than time_a");
}
TEST_END

TEST_BEGIN(test_nstime_addition) {
	nstime_t time_a, time_b;
	nstime_init2(&time_a, 84, 86);
	nstime_copy(&time_b, &time_a);
	nstime_add(&time_a, &time_b);
	nstime_init2(&time_b, 168, 172);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect addition result");

	nstime_init2(&time_a, 84, MILLION - 1);
	nstime_copy(&time_b, &time_a);
	nstime_add(&time_a, &time_b);
	nstime_init2(&time_b, 169, MILLION - 2);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect addition result");
}
TEST_END

TEST_BEGIN(test_nstime_iadd_operation) {
	nstime_t time_a, time_b;
	nstime_init2(&time_a, 84, MILLION - 1);
	nstime_iadd(&time_a, 1);
	nstime_init2(&time_b, 85, 0);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect addition result");

	nstime_init2(&time_a, 84, 1);
	nstime_iadd(&time_a, MILLION + 1);
	nstime_init2(&time_b, 85, 2);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect addition result");
}
TEST_END

TEST_BEGIN(test_nstime_subtraction) {
	nstime_t time_a, time_b;
	nstime_init2(&time_a, 84, 86);
	nstime_copy(&time_b, &time_a);
	nstime_subtract(&time_a, &time_b);
	nstime_init_zero(&time_b);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect subtraction result");

	nstime_init2(&time_a, 84, 86);
	nstime_init2(&time_b, 83, 87);
	nstime_subtract(&time_a, &time_b);
	nstime_init2(&time_b, 0, MILLION - 1);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect subtraction result");
}
TEST_END

TEST_BEGIN(test_nstime_isubtract_operation) {
	nstime_t time_a, time_b;
	nstime_init2(&time_a, 84, 86);
	nstime_isubtract(&time_a, 84*MILLION + 86);
	nstime_init_zero(&time_b);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect subtraction result");

	nstime_init2(&time_a, 84, 86);
	nstime_isubtract(&time_a, 83*MILLION + 87);
	nstime_init2(&time_b, 0, MILLION - 1);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect subtraction result");
}
TEST_END

TEST_BEGIN(test_nstime_multiplication) {
	nstime_t time_a, time_b;
	nstime_init2(&time_a, 84, 86);
	nstime_imultiply(&time_a, 10);
	nstime_init2(&time_b, 840, 860);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect multiplication result");

	nstime_init2(&time_a, 84, 666666666);
	nstime_imultiply(&time_a, 3);
	nstime_init2(&time_b, 253, 999999998);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect multiplication result");
}
TEST_END

TEST_BEGIN(test_nstime_division_operation) {
	nstime_t time_a, time_b;
	nstime_init2(&time_a, 84, 86);
	nstime_copy(&time_b, &time_a);
	nstime_imultiply(&time_a, 10);
	nstime_idivide(&time_a, 10);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect division result");

	nstime_init2(&time_a, 84, 666666666);
	nstime_copy(&time_b, &time_a);
	nstime_imultiply(&time_a, 3);
	nstime_idivide(&time_a, 3);
	expect_d_eq(nstime_compare(&time_a, &time_b), 0,
	    "Incorrect division result");
}
TEST_END

TEST_BEGIN(test_nstime_exact_division) {
	nstime_t time_a, time_b, time_c;
	nstime_init2(&time_a, 84, 86);
	nstime_copy(&time_b, &time_a);
	nstime_imultiply(&time_a, 10);
	expect_u64_eq(nstime_divide(&time_a, &time_b), 10,
	    "Incorrect division result");

	nstime_init2(&time_a, 84, 86);
	nstime_copy(&time_b, &time_a);
	nstime_imultiply(&time_a, 10);
	nstime_init(&time_c, 1);
	nstime_add(&time_a, &time_c);
	expect_u64_eq(nstime_divide(&time_a, &time_b), 10,
	    "Incorrect division result");

	nstime_init2(&time_a, 84, 86);
	nstime_copy(&time_b, &time_a);
	nstime_imultiply(&time_a, 10);
	nstime_init(&time_c, 1);
	nstime_subtract(&time_a, &time_c);
	expect_u64_eq(nstime_divide(&time_a, &time_b), 9,
	    "Incorrect division result");
}
TEST_END

static void
test_nstime_elapsed_once(nstime_t *timestamp) {
	nstime_t prev_timestamp;
	nstime_copy(&prev_timestamp, timestamp);
	uint64_t ns_elapsed = nstime_ns_since(timestamp);
	nstime_update(timestamp);
	nstime_t curr_timestamp;
	nstime_copy(&curr_timestamp, timestamp);
	nstime_subtract(&curr_timestamp, &prev_timestamp);
	expect_u64_ge(nstime_ns(&curr_timestamp), ns_elapsed,
	    "Incorrect elapsed time result");
}

TEST_BEGIN(test_nstime_ns_since) {
	nstime_t timestamp;
	nstime_init_update(&timestamp);
	for (uint64_t iteration = 0; iteration < 10000; iteration++) {
		test_nstime_elapsed_once(&timestamp);
	}
}
TEST_END

TEST_BEGIN(test_nstime_monotonic_check) {
	nstime_monotonic();
}
TEST_END

int
main(void) {
	return test(
	    test_nstime_initialization,
	    test_nstime_initialization2,
	    test_nstime_copy_operation,
	    test_nstime_comparison,
	    test_nstime_addition,
	    test_nstime_iadd_operation,
	    test_nstime_subtraction,
	    test_nstime_isubtract_operation,
	    test_nstime_multiplication,
	    test_nstime_division_operation,
	    test_nstime_exact_division,
	    test_nstime_ns_since,
	    test_nstime_monotonic_check);
}

