void MySubClassImpl::update(sen::kernel::RunApi& context)
{
  MyClassImpl::update(context);
  std::chrono::duration<double> elapsed = context.getTime().sinceEpoch().toChrono();
  setNextADouble(cos(elapsed.count()) * 50.0 + 100.0);

  int modCycle = cycle_++ % 5;
  switch (modCycle)
  {
    case 0:
      setNextAVariant(MyEnum::third);
      setNextASequence({1.0f});
      break;
    case 1:
      setNextAVariant(MyEnum::first);
      setNextASequence({2.5f, 3.5f, 4.5f});
      break;
    case 2:
      setNextAVariant("another text");
      setNextASequence({-1.0f, -2.0f, -3.0f});
      break;
    case 3:
      setNextAVariant("yet another string");
      setNextASequence({7.7f, 8.8f, 9.9f, 10.1f});
      break;
    case 4:
      setNextAFloat(getAFloat() - 2.17f);
      setNextASequence({0.0f, 0.5f, 1.5f, 2.5f});
      break;
  }
}

