#include "print_vector.h"
#include <iostream>
#include <vector>

// Overloaded function to print a 1D vector
template <typename T>
IGL_INLINE void igl::print_vector( std::vector<T>& data )
{
  using namespace std;
  for (int index = 0; index < data.size(); ++index)
    std::cerr << data[index] << " ";
  std::cerr << std::endl;
}

// Overloaded function to print a 2D vector
template <typename T>
IGL_INLINE void igl::print_vector( std::vector< std::vector<T> >& matrix )
{
  using namespace std;
  for (int row = 0; row < matrix.size(); ++row)
  {
    std::cerr << row << ": ";
    for (int col = 0; col < matrix[row].size(); ++col)
      std::cerr << matrix[row][col] << " ";
    std::cerr << std::endl;
  }
}

// Overloaded function to print a 3D vector
template <typename T>
IGL_INLINE void igl::print_vector( std::vector< std::vector< std::vector<T> > >& cube )
{
  using namespace std;
  for (int depth = 0; depth < cube.size(); ++depth)
  {
    std::cerr << "Matrix " << depth << std::endl;
    for (int row = 0; row < cube[depth].size(); ++row)
    {
      std::cerr << row << ": ";
      for (int col = 0; col < cube[depth][row].size(); ++col)
        std::cerr << cube[depth][row][col] << " ";
      std::cerr << std::endl;
    }

    std::cerr << "---- end " << depth << std::endl;
  }
}
