using asio::ip::tcp;

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: daytime_client <hostname>" << std::endl;
      return 1;
    }

    tcp::iostream connection(argv[1], "daytime");

    if (!connection)
    {
      std::cout << "Connection failed: " << connection.error().message() << std::endl;
      return 1;
    }

    std::string time_string;
    std::getline(connection, time_string);
    std::cout << time_string << std::endl;
  }
  catch (std::exception& error)
  {
    std::cout << "Error occurred: " << error.what() << std::endl;
  }

  return 0;
}

