namespace autolink {

// Test Duration constructor functionality
TEST(DurationTest, constructor) {
  Duration time_span(200);
  EXPECT_EQ(200, time_span.ToNanosecond());
  time_span = Duration(2.2);
  EXPECT_EQ(2200000000UL, time_span.ToNanosecond());
  EXPECT_DOUBLE_EQ(2.2, time_span.ToSecond());
  time_span = Duration(2, 2);
  EXPECT_EQ(2000000002UL, time_span.ToNanosecond());
  EXPECT_DOUBLE_EQ(2.000000002, time_span.ToSecond());
  Duration copy(time_span);
  EXPECT_EQ(time_span, copy);
}

// Test Duration operator overloads
TEST(DurationTest, operators) {
  Duration t1(150);
  Duration t2(250);
  Duration t3(400);
  EXPECT_NE(t1, t3);
  EXPECT_LT(t1, t3);
  EXPECT_LE(t1, t3);
  EXPECT_GT(t3, t1);
  EXPECT_GE(t3, t1);
  EXPECT_EQ(t1 + t2, t3);
  EXPECT_EQ(t2, t1 * (5/3));
  EXPECT_EQ(t3 - t2, t1);
  EXPECT_EQ(t1 += t2, t3);
  EXPECT_GE(t1, t3);
  EXPECT_LE(t1, t3);
  EXPECT_EQ(Duration(150), t1 -= t2);
  EXPECT_EQ(t2, t1 *= (5/3));
}

// Test Duration zero state
TEST(DurationTest, is_zero) {
  Duration empty_duration;
  EXPECT_TRUE(empty_duration.IsZero());
}

