/*
 * Ore recipe mappings for converting between ore blocks and their component items.
 * Each entry contains a block tile followed by the corresponding item instance.
 */
void OreRecipies::_init()
{
    // Initialize the recipe map with maximum capacity
    recipeMap = new std::vector<Object*>[MAX_RECIPE_COUNT];

    // Gold ore processing recipes
    ADD_OBJECT(recipeMap[0], Tile::goldBlock);
    ADD_OBJECT(recipeMap[0], new ItemInstance(Item::goldIngot, 9));

    // Iron ore processing recipes
    ADD_OBJECT(recipeMap[1], Tile::ironBlock);
    ADD_OBJECT(recipeMap[1], new ItemInstance(Item::ironIngot, 9));

    // Diamond ore processing recipes
    ADD_OBJECT(recipeMap[2], Tile::diamondBlock);
    ADD_OBJECT(recipeMap[2], new ItemInstance(Item::diamond, 9));

    // Emerald ore processing recipes
    ADD_OBJECT(recipeMap[3], Tile::emeraldBlock);
    ADD_OBJECT(recipeMap[3], new ItemInstance(Item::emerald, 9));

    // Lapis lazuli ore processing recipes
    ADD_OBJECT(recipeMap[4], Tile::lapisBlock);
    ADD_OBJECT(recipeMap[4], new ItemInstance(Item::dye_powder, 9, DyePowderItem::BLUE));
}

void OreRecipies::addRecipes(Recipes* r)
{
    // Register both compression and decompression recipes for each ore type
    for (int index = 0; index < MAX_RECIPE_COUNT; ++index)
    {
        // Extract source block and result item from recipe map
        Tile* sourceTile = (Tile*)recipeMap[index].at(0)->tile;
        ItemInstance* resultItem = (ItemInstance*)recipeMap[index].at(1)->iteminstance;

        // Add recipe: block → 9 items (compression)
        r->addShapedRecipy(new ItemInstance(sourceTile),
            L"sssczg",
            L"###",
            L"###",
            L"###",
            L'#', resultItem,
            L'D');

        // Add recipe: 9 items → block (decompression)
        r->addShapedRecipy(resultItem,
            L"sctg",
            L"#",
            L'#', sourceTile,
            L'D');
    }
}

