void patcher::ApplyPatch(void* targetLocation, const std::vector<BYTE>* patchData)
{
    DWORD previousProtection;
    VirtualProtect(targetLocation, patchData->size(), PAGE_EXECUTE_READWRITE, &previousProtection);
    std::memcpy(targetLocation, patchData->data(), patchData->size());
    VirtualProtect(targetLocation, patchData->size(), previousProtection, &previousProtection);
    FlushInstructionCache(GetCurrentProcess(), targetLocation, patchData->size());
}

