namespace sdb {

/// Create a formatted timestamp string in the provided buffer
void GenerateTimestampReplication(char* buffer, size_t buffer_size) {
  struct tm time_info;
  time_t current_time = time(nullptr);
  utilities::GetGmtime(current_time, &time_info);
  strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", &time_info);
}

/// Create a formatted timestamp string from a given timestamp value
void GenerateTimestampReplication(double timestamp_value, char* output_buffer, size_t output_buffer_size) {
  struct tm time_info;
  time_t converted_time = static_cast<time_t>(timestamp_value);
  utilities::GetGmtime(converted_time, &time_info);
  strftime(output_buffer, output_buffer_size, "%Y-%m-%dT%H:%M:%SZ", &time_info);
}

}  // namespace sdb

