#include <iostream>
#include <unordered_map>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

int main()
{
    // Construct a JSON object containing various data types
    json data_object =
    {
        {"flag", true},
        {
            "numeric", {
                {"whole", 42},
                {"decimal", 17.23}
            }
        },
        {"text", "Hello, world!"},
        {"list", {1, 2, 3, 4, 5}},
        {"empty", nullptr}
    };

    bool result_bool;
    int result_int;
    short result_short;
    float result_float;
    int result_int2;
    std::string result_string;
    std::vector<short> result_vector;
    std::unordered_map<std::string, json> result_map;

    // Extract values using explicit conversions
    data_object["flag"].get_to(result_bool);
    data_object["numeric"]["whole"].get_to(result_int);
    data_object["numeric"]["whole"].get_to(result_short);
    data_object["numeric"]["decimal"].get_to(result_float);
    data_object["numeric"]["decimal"].get_to(result_int2);
    data_object["text"].get_to(result_string);
    data_object["list"].get_to(result_vector);
    data_object.get_to(result_map);

    // Output the extracted values
    std::cout << result_bool << '\n';
    std::cout << result_int << ' ' << result_short << '\n';
    std::cout << result_float << ' ' << result_int2 << '\n';
    std::cout << result_string << '\n';

    for (auto item : result_vector)
    {
        std::cout << item << ' ';
    }
    std::cout << "\n\n";

    for (auto& pair : result_map)
    {
        std::cout << pair.first << ": " << pair.second << '\n';
    }

    return 0;
}

