#define NOINLINE __attribute__((noinline))
#define LOG_TAG "ThreadLeakTest"
#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)

static NOINLINE void ThreadLeakTest(int64_t timeout) {
  std::thread worker_thread([timeout]() {
    pthread_setname_np(pthread_self(), "worker_thread");
    LOGI("worker_thread started");

    std::thread* child_thread_1;
    std::thread* child_thread_2;

    child_thread_1 = new std::thread([]() {
      pthread_setname_np(pthread_self(), "child_thread_1");
      LOGI("child_thread_1 running");
    });

    child_thread_2 = new std::thread([]() {
      pthread_setname_np(pthread_self(), "child_thread_2");
      LOGI("child_thread_2 running");
    });

    std::this_thread::sleep_for(std::chrono::milliseconds(timeout));

    child_thread_1->detach();
    LOGI("child_thread_1 detached");

    child_thread_2->join();
    LOGI("child_thread_2 joined");
  });

  worker_thread.detach();
}

extern "C"
JNIEXPORT void JNICALL
Java_com_kwai_koom_demo_threadleak_ThreadLeakTest_triggerLeak(
    JNIEnv* env,
    jclass, jlong timeout) {
  ThreadLeakTest(timeout);
}

