using namespace mlir;
using namespace mlir::equivalence;
using namespace mlir::ematch;

int main(int argc, char **argv) {
  // Register timing command-line options for Tamagoyaki
  tamagoyaki::registerTimingCLOptions();

  // Register all standard MLIR passes
  mlir::registerAllPasses();

  // Register equivalence-specific passes
  mlir::equivalence::registerEquivalencePasses();

  // Register ematch-specific passes
  mlir::ematch::registerEmatchPasses();

  // Set up dialect registry
  mlir::DialectRegistry dialectRegistry;
  dialectRegistry.insert<mlir::equivalence::EquivalenceDialect,
                         mlir::ematch::EmatchDialect>();
  registerAllDialects(dialectRegistry);

  // Run the optimization driver
  int exitCode = mlir::asMainReturnCode(
      mlir::MlirOptMain(argc, argv, "Tamagoyaki optimizer driver\n", dialectRegistry));

  // Print timing statistics before exiting
  tamagoyaki::printTimingReport();
  return exitCode;
}

