std::error_code
ConverterEBCDIC::convertToEBCDIC(StringRef InputData,
                                 SmallVectorImpl<char> &OutputBuffer) {
  assert(OutputBuffer.empty() && "Output buffer must be empty!");

  const unsigned char *LookupTable = Latin1ToEBCDIC;
  const unsigned char *CurrentByte =
      reinterpret_cast<const unsigned char *>(InputData.data());
  size_t RemainingBytes = InputData.size();

  OutputBuffer.reserve(RemainingBytes);

  while (RemainingBytes--) {
    unsigned char ByteValue = *CurrentByte++;

    // Process UTF-8 multi-byte sequences in input
    if (ByteValue >= 128) {
      // Only support two-byte UTF-8 sequences
      if (ByteValue != 0xc2 && ByteValue != 0xc3)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      // Check if we have enough bytes remaining
      if (!RemainingBytes)
        return std::make_error_code(std::errc::invalid_argument);

      unsigned char NextByte = *CurrentByte++;

      // Validate continuation byte format
      if ((NextByte & 0xc0) != 0x80)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      ByteValue = NextByte | (ByteValue << 6);
      RemainingBytes--;
    }

    // Apply translation lookup
    ByteValue = LookupTable[ByteValue];
    OutputBuffer.push_back(static_cast<char>(ByteValue));
  }

  return std::error_code();
}

void ConverterEBCDIC::convertToUTF8(StringRef InputData,
                                    SmallVectorImpl<char> &OutputBuffer) {
  assert(OutputBuffer.empty() && "Output buffer must be empty!");

  const unsigned char *LookupTable = EBCDICToLatin1;
  const unsigned char *CurrentByte =
      reinterpret_cast<const unsigned char *>(InputData.data());
  size_t RemainingBytes = InputData.size();

  OutputBuffer.reserve(RemainingBytes);

  while (RemainingBytes--) {
    unsigned char ByteValue = *CurrentByte++;

    // First apply EBCDIC-to-Latin1 translation
    ByteValue = LookupTable[ByteValue];

    // Handle UTF-8 encoding for characters above ASCII range
    if (ByteValue >= 128) {
      // Generate first byte of UTF-8 sequence
      OutputBuffer.push_back(static_cast<char>(0xc0 | (ByteValue >> 6)));
      // Second byte is masked to keep lower 6 bits
      ByteValue = ByteValue & 0xbf;
    }

    OutputBuffer.push_back(static_cast<char>(ByteValue));
  }
}

