#include <sol/sol.hpp>

#include <iostream>
#include <functional>

int main() {
    std::cout << "=== capturing variadic arguments ==="
              << std::endl;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    std::function<void()> captured_callback;

    auto capture_handler = [&captured_callback](sol::function func,
                                               sol::variadic_args args) {
        captured_callback =
            [func,
             stored_args = std::vector<sol::object>(args.begin(),
                                                    args.end())]() {
                func(sol::as_args(stored_args));
            };
    };

    lua_vm.set_function("capture_handler", capture_handler);

    lua_vm.script(R"(
function greet_user(username)
    print(username)
end
capture_handler(greet_user, "Alice")
)");
    captured_callback();

    lua_vm.script(R"(
function display_info(count, message)
    print(count, "items:", message)
end
capture_handler(display_info, 5, "apples")
)");
    captured_callback();

    std::cout << std::endl;

    return 0;
}

