#include <bpf/bpf.h>

// Tracepoint structure for scheduler switch event
struct sched_switch_event {
    u64 reserved;
    u8 previous_task_name[16];
    u32 previous_process_id;
    u32 previous_priority;
    u64 previous_state_flag;
    u8 next_task_name[16];
    u32 next_process_id;
    u32 next_priority;
};

SEC("tracepoint/sched/sched_switch")
int handle_sched_switch(struct sched_switch_event* event_context) {
    u64 current_thread_group_id = bpf_get_current_pid_tgid();
    BPF_PRINTK("Processing scheduler switch %u -> %u (current thread: %u)\n", 
               event_context->previous_process_id, 
               event_context->next_process_id, 
               (u32)current_thread_group_id);
    return 0;
}
