#include <stdio.h>

int main() {
    int matrix[20][20], row, col, i, j, total = 0;

    printf("enter total rows and columns ");
    scanf("%d %d", &row, &col);

    // Input the matrix elements
    for(i = 0; i < row; i++) {
        for(j = 0; j < col; j++) {
            printf("enter [%d] [%d] element ", i, j);
            scanf("%d", &matrix[i][j]);
        }
    }

    // Print original matrix and calculate sum
    for(i = 0; i < row; i++) {
        for(j = 0; j < col; j++) {
            printf("%d", matrix[i][j]);
            total = total + matrix[i][j];
        }
        printf("\n");
    }

    printf("transpose of matrix\n");

    // Print transpose and add to sum again
    for(j = 0; j < col; j++) {
        for(i = 0; i < row; i++) {
            printf("%d", matrix[i][j]);
            total = total + matrix[i][j];
        }
        printf("\n");
    }

    printf("sum => %d \n", total);
    return 0;
}

