#include "NL/nlEndian.h"
#include "types.h"

/**
 * Function to swap endianness of a 16-bit unsigned integer
 * Input: in - original value
 * Output: out - pointer to store the swapped result
 */
void nlSwapEndian(unsigned short input, unsigned short* output)
{
    *output = 0;
    *output |= (input << 8U) & 0xFF00;
    *output |= (input >> 8) & 0xFF;
}

