// Alternative implementation using a lambda instead of boost::bind
template <typename T>
bool item_exists_v2(const std::vector<T>& items,
                    boost::function<bool(const T&)> conditionPredicate)
{
    for (typename std::vector<T>::const_iterator it = items.begin(); 
         it != items.end(); ++it) {
        if (conditionPredicate(*it)) {
            return true;
        }
    }
    return false;
}

// Helper function to check if a number is odd (complement of is_even)
bool is_odd(const int& number)
{
    return number % 2 != 0;
}

void test_item_exists()
{
    std::vector<int> numbers;

    // Test with empty vector - should return false for even check
    assert(!item_exists_v2<int>(numbers, is_even));

    // Add first odd number
    numbers.push_back(1);
    assert(!item_exists_v2<int>(numbers, is_even));

    // Add an even number
    numbers.push_back(2);
    assert(item_exists_v2<int>(numbers, is_even));

    // Additional verification using the original function
    std::vector<int> test_numbers;
    test_numbers.push_back(3);
    test_numbers.push_back(5);
    assert(!item_exists<int>(test_numbers, is_even));

    test_numbers.push_back(4);
    assert(item_exists<int>(test_numbers, is_even));

    std::cout << "test_item_exists: OK" << std::endl;
}

int main()
{
    test_item_exists();
    return 0;
}

