// Safe integer addition with overflow detection
int safe_add(int first, int second)
{
    // Check for overflow conditions before performing addition
    if ((second > 0 && first > numeric_limits<int>::max() - second) ||
        (second < 0 && first < numeric_limits<int>::min() - second))
        error("safe_add(): integer addition would overflow.");

    return first + second;
}

// Generate Fibonacci-like sequence starting with two initial values
void generate_fibonacci(int start1, int start2, vector<int>& result, int length)
{
    // Validate preconditions: non-empty vector and sufficient length
    if (!result.empty())
        error("generate_fibonacci(): Input vector must be empty.");
    if (length < 2)
        error("generate_fibonacci(): Length must be at least 2.");

    // Initialize sequence with starting values
    result.push_back(start1);
    result.push_back(start2);

    // Compute remaining terms using safe addition
    for (int index = 2; index < length; ++index)
        result.push_back(safe_add(result[index-2], result[index-1]));
}

