void signalHandler(int sigNumber) {
    void *stackFrames[100];
    size_t frameCount;

    // Capture stack frames
    frameCount = backtrace(stackFrames, 100);

    // Output error information to standard error
    fprintf(stderr, "Signal received: %d\n", sigNumber);
    backtrace_symbols_fd(stackFrames, frameCount, STDERR_FILENO);

    _exit(1);  // Use _exit to avoid potential issues in signal handler
}
