// Wait until the global thread pool completes all pending tasks
static void awaitThreadPoolCompletion(QThreadPool *pool) {
    QEventLoop eventLoop;
    while (!pool->waitForDone(20)) {
        eventLoop.processEvents();
    }
}

int main(int argc, char *argv[]) {
#if defined(Q_OS_MAC) || defined(Q_OS_LINUX)
    signal(SIGSEGV, signalHandler);
#endif

    QCoreApplication application(argc, argv);
    TestRunner testRunner;

    // Register test suites
    testRunner.add<AsyncFutureTests>();
    testRunner.add<BugTests>();
    testRunner.add<Example>();

    // Run tests and capture result
    bool hasErrors = testRunner.exec(application.arguments());

    if (!hasErrors) {
        qDebug() << "All test cases passed successfully!";
    }

    // Ensure all background tasks are completed before exiting
    awaitThreadPoolCompletion(QThreadPool::globalInstance());

    return hasErrors ? 1 : 0;
}

#include <pthread.h>
#include <cstdlib>

// Thread function that simply returns
void* WorkerThread(void*) {
    return nullptr;
}

int main() {
    pthread_t thread_id;
    const size_t stack_size = 1024 * 1024;

    // Allocate memory for the thread stack
    void* stack_memory = malloc(stack_size);

    pthread_attr_t attributes;
    pthread_attr_init(&attributes);

    // Set the custom stack for the thread
    pthread_attr_setstack(&attributes, stack_memory, stack_size);

    // Create and run the thread
    pthread_create(&thread_id, &attributes, WorkerThread, nullptr);
    pthread_join(thread_id, nullptr);

    // Clean up allocated resources
    free(stack_memory);
    return 0;
}

