// Validate DNS-SD service errors and generate descriptive messages
void verify_dns_service_result(DNSServiceErrorType result, const std::string& operation) {
    if (kDNSServiceErr_NoError == result) {
        return;
    }

    std::string message = operation + ": ";

    switch (result) {
        case kDNSServiceErr_NameConflict:
            message += "Name already in use, select a different name";
            break;
        case kDNSServiceErr_Invalid:
            message += "Invalid parameter: incorrect index or character detected";
            break;
        case kDNSServiceErr_BadReference:
            message += "Invalid service reference provided";
            break;
        case kDNSServiceErr_BadParam:
            message += "Function received invalid parameter value";
            break;
        default:
            message += "Unrecognized error encountered (code: ";
            message += std::to_string(result);
            message += ")";
    }

    throw std::runtime_error(message);
}

