#include "collisiondetection/axisalignedboundingbox.hpp"

using namespace modelloader;

// Move constructor for VertexBuffer - transfers ownership of resources
VertexBuffer::VertexBuffer(VertexBuffer&& other) noexcept 
    : vBO{other.vBO}, iBO{other.iBO}, nBO{other.nBO}, 
      vao(other.vao), numIndices(other.numIndices), 
      extremes(other.extremes), bounds(std::exchange(other.bounds, nullptr)) {
    // Reset source object's handles to avoid double-free
    other.vBO = 0;
    other.iBO = 0;
    other.nBO = 0;
    other.vao = 0;
}

// Constructor that initializes VAO, buffers, and computes bounding box from extremes
VertexBuffer::VertexBuffer(GLuint myVBO, GLuint myIBO, GLuint myNBO, 
                           unsigned int myNumIndices, 
                           std::tuple<glm::vec3, glm::vec3> myExtremes)
    : vBO(myVBO), iBO(myIBO), nBO(myNBO), 
      numIndices(myNumIndices), extremes(myExtremes), 
      bounds{std::make_unique<collisiondetection::AxisAlignedBoundingBox>(myExtremes)} {

    // Create and configure VAO
    glGenVertexArrays(1, &vao);
    glBindVertexArray(vao);

    // Bind vertex positions buffer and set up attribute pointer
    glBindBuffer(GL_ARRAY_BUFFER, vBO);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 0, nullptr);
    glEnableVertexAttribArray(0);

    // Bind normals buffer and set up attribute pointer
    glBindBuffer(GL_ARRAY_BUFFER, myNBO);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, 0, nullptr);
    glEnableVertexAttribArray(1);

    // Unbind VAO to prevent accidental modifications
    glBindVertexArray(0);
}

// Bind the VAO and element index buffer for rendering
void VertexBuffer::bindBuffers() const {
    glBindVertexArray(vao);
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, iBO);
}

