    tiramisu::function *main_func = global::get_implicit_function();
    tiramisu::constant M("M", tiramisu::expr((int32_t) dim_size), p_int32, true, NULL, 0, main_func);
    tiramisu::var row("row", 0, 10), col("col", 0, 10);
    tiramisu::var row0("row0"), col0("col0"), row1("row1"), col1("col1");
