    op.tag_parallel_level(row);
    tiramisu::buffer output_buf("output_buf", {dim_size, dim_size}, tiramisu::p_uint8, a_output, main_func);
    op.store_in(&output_buf, {row, col});
    main_func->codegen({&output_buf}, "build/generated_fct_test_114.o");
