// Class to perform Caesar cipher decoding
class CCipher {
public:
  std::string decode(std::string cipherText, int shift) {
    std::string original;
    for (int i = 0; i < cipherText.length(); ++i) {
      char currentChar = cipherText[i];
      // Calculate the decoded character with wrap-around handling
      int offset = (currentChar - 'A' - shift) % 26;
      if (offset < 0) {
        offset += 26;
      }
      original += static_cast<char>('A' + offset);
    }
    return original;
  }
};

int main() {
  CCipher cc;
  std::string result = cc.decode("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 10);
  assert(result == "QRSTUVWXYZABCDEFGHIJKLMNOP");

  // Optional: print result for verification
  std::cout << result << std::endl;

  return 0;
}

