// Wrapper that delegates to implementation objects
template <template <typename> class Strategy, typename Config>
class Executor {
private:
    Strategy<Config> m_strategy;
public:
    Executor(const Config& cfg) : m_strategy(cfg) {}

    void Perform() { m_strategy.Act(); }
    void Update(const Config& new_cfg) { m_strategy.SetConfig(new_cfg); }
};

// First strategy - uses Configure method for setup
template <typename T>
class ImplementationA {
private:
    T m_config;
public:
    ImplementationA(const T& val) : m_config(val) {
        std::cout << "ImplementationA : constructor." << std::endl;
    }

    void SetConfig(const std::vector<std::string>&) {
        std::cout << "ImplementationA : vector<string> setup." << std::endl;
    }
};

// Second strategy - has its own execution method
template <typename T>
class ImplementationB {
private:
    T m_data;
public:
    ImplementationB(const T& val) : m_data(val) {
        std::cout << "ImplementationB : int vector constructor" << std::endl;
    }

    void Act() { std::cout << "ImplementationB : execute ()" << std::endl; }
};

int main() {
    // Create first executor with string parameter
    Executor<ImplementationA, std::string> exec1("ImplementationA");

    // Create second executor with vector<string> and update it
    Executor<ImplementationA, std::vector<std::string>> exec2(std::vector<std::string>());
    exec2.Update(std::vector<std::string>());

