namespace LilWrapper
{
  MutexImpl::MutexImpl()
  {
    // Initialize the critical section for thread synchronization
    InitializeCriticalSection(&this->_mutex);
  }

  MutexImpl::~MutexImpl()
  {
    // Clean up the critical section resources
    DeleteCriticalSection(&this->_mutex);
  }

  void MutexImpl::acquire()
  {
    // Block until the critical section is owned
    EnterCriticalSection(&this->_mutex);
  }

  void MutexImpl::release()
  {
    // Release ownership of the critical section
    LeaveCriticalSection(&this->_mutex);
  }

  bool MutexImpl::attemptLock()
  {
    // Try to acquire the critical section without blocking
    return (TryEnterCriticalSection(&this->_mutex) != 0);
  }
}

