#include "executor_metrics.h"

namespace proton {

void ExecutorMetrics::refresh(const vespalib::ThreadStackExecutorBase::Stats &data) {
    // Update maximum pending tasks observed so far
    if (data.queueSize.max() > maxPending.get()) {
        maxPending.set(data.queueSize.max());
    }

    // Increment counters for accepted and rejected tasks
    accepted.add(data.acceptedTasks);
    rejected.add(data.rejectedTasks);

    // Batch update queue size statistics
    const auto& qStats = data.queueSize;
    queueSize.updateBatch(qStats.average(), qStats.count(), qStats.min(), qStats.max());
}

ExecutorMetrics::ExecutorMetrics(const std::string &label, metrics::MetricSet *owner)
    : metrics::MetricSet(label, {}, "Metrics for a specific thread executor instance", owner),
      maxPending("max_pending", {}, "Peak count of pending tasks (active + queued)", this),
      accepted("tasks_accepted", {}, "Total number of tasks accepted by the executor", this),
      rejected("tasks_rejected", {}, "Total number of tasks rejected due to capacity limits", this),
      queueSize("queue_length", {}, "Distribution of task queue sizes over time", this)
{
}

ExecutorMetrics::~ExecutorMetrics() = default;

