#include "../../source/thewizardplusplus/wizard_parser/lexer/tokenize.hpp"
#include "../../source/thewizardplusplus/wizard_parser/lexer/token.hpp"
#include "../vendor/catch/catch.hpp"
#include <regex>

TEST_CASE("lexer::tokenize() behavior with and without skipping whitespace", "[lexer]") {
    using namespace thewizardplusplus::wizard_parser;

    SECTION("default mode - includes all tokens") {
        const auto [result_tokens, final_offset] = lexer::tokenize(
            {
                {std::regex{"[[:alpha:]]+"}, "alpha"},
                {std::regex{"[[:digit:]]+"}, "digit"},
                {std::regex{"[[:space:]]+"}, "space"}
            },
            {},
            "test 23"
        );

        REQUIRE(result_tokens.size() == 3);
        CHECK(result_tokens[0].type == "alpha");
        CHECK(result_tokens[0].value == "test");
        CHECK(result_tokens[1].type == "space");
        CHECK(result_tokens[1].value == " ");
        CHECK(result_tokens[1].position == 4);
        CHECK(result_tokens[2].type == "digit");
        CHECK(result_tokens[2].value == "23");
        CHECK(result_tokens[2].position == 5);

        CHECK(final_offset == 7);
    }

    SECTION("exclusion mode - skips space tokens") {
        const auto [result_tokens, final_offset] = lexer::tokenize(
            {
                {std::regex{"[[:alpha:]]+"}, "alpha"},
                {std::regex{"[[:digit:]]+"}, "digit"},
                {std::regex{"[[:space:]]+"}, "space"}
            },
            {"space"},
            "test 23"
        );

        REQUIRE(result_tokens.size() == 2);
        CHECK(result_tokens[0].type == "alpha");
        CHECK(result_tokens[0].value == "test");
        CHECK(result_tokens[1].type == "digit");
        CHECK(result_tokens[1].value == "23");
        CHECK(result_tokens[1].position == 5);

        CHECK(final_offset == 7);
    }
}

