  // Check if panels are enabled via command line flag
  bool panels_enabled = CommandLine::ForCurrentProcess()->HasSwitch(
      switches::kEnablePanels);

  BrowserNonClientFrameView* result = nullptr;

  if (type == Browser::TYPE_PANEL && panels_enabled) {
    result = new PanelBrowserFrameView(
        frame, static_cast<PanelBrowserView*>(browser_view));
  } else if (type == Browser::TYPE_POPUP) {
