// Thread function to handle user connection with retry and error handling
void thread_loop(UserHandler * handler) {
    // Wait until handler is ready, polling with small delay
    while (!handler->isReady()) {
        usleep(10000);
    }

    try {
        // Execute the main handler loop
        handler->loop();
    }
    catch (...) {
        // Attempt to send generic error response to client
        try {
            JsonDict errorResponse;
            errorResponse.add("Error", new JsonString("Unknown error"));
            errorResponse.add("code", new JsonInt(500));
            handler->writeToClient("error", &errorResponse);
        }
        catch (...) {
            // Silently ignore any further exceptions during error reporting
        }

        std::cerr << "Uncought exception, this is bad !" << std::endl;
    }

    // Clean up handler resource
    delete handler;
    std::cout << "Client disconnected." << std::endl;
}

