// Helper function to reinterpret bit patterns as floats
extern "C" {
    // Define inline attributes for the following functions
    #define INLINE inline __attribute__((weak)) __attribute__((used)) __attribute__((always_inline)) __attribute__((nothrow)) __attribute__((pure))

    // Convert raw 32-bit integer representation to float
    INLINE float float_from_bits(uint32_t bits) {
        union {
            uint32_t as_int;
            float as_float;
        } converter;
        converter.as_int = bits;
        return converter.as_float;
    }

    // Generate NaN (Not-a-Number) value for 32-bit float
    INLINE float nan_f32() {
        return float_from_bits(0x7fc00000);
    }

    // Generate negative infinity for 32-bit float
    INLINE float neg_inf_f32() {
        return float_from_bits(0xff800000);
    }

    // Generate positive infinity for 32-bit float
    INLINE float inf_f32() {
        return float_from_bits(0x7f800000);
    }
}

