// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    bool validateBST(TreeNode* node, long lowerBound, long upperBound) {
        if (node == nullptr) {
            return true;
        }

        // Check current node value is within valid range
        bool currentValid = (static_cast<long>(node->val) > lowerBound) &&
                            (static_cast<long>(node->val) < upperBound);

        // Recursively validate left and right subtrees with updated bounds
        bool leftSubtreeValid = validateBST(node->left, lowerBound, static_cast<long>(node->val));
        bool rightSubtreeValid = validateBST(node->right, static_cast<long>(node->val), upperBound);

        return currentValid && leftSubtreeValid && rightSubtreeValid;
    }

    bool isValidBST(TreeNode* root) {
        // Use long to avoid overflow issues with INT_MIN and INT_MAX
        return validateBST(root, static_cast<long>(INT_MIN) - 1, static_cast<long>(INT_MAX) + 1);
    }
};

