using namespace cv;

#if defined(_MSC_VER) || defined(WIN32) || defined(_WIN32) || defined(__WIN32__) \
    || defined(WIN64) || defined(_WIN64) || defined(__WIN64__)
# include <io.h>
# include <fcntl.h>
# define SET_BINARY_MODE(handle) _setmode(_fileno(handle), _O_BINARY)
#else
# define SET_BINARY_MODE(handle) ((void)0)
#endif

const size_t BUFFER_SIZE = 10240;

int main(int argc, char** argv) {
    SET_BINARY_MODE(stdin);

    std::vector<uchar> imageBuffer;
    bool skipNext = true;
    bool foundStart = false;
    bool endOfImage = false;
    ssize_t bytesRead = -1;

    while (true) {
        unsigned char buffer[BUFFER_SIZE];

        bytesRead = read(STDIN_FILENO, buffer, BUFFER_SIZE);

        if (bytesRead == 0) {
            throw std::runtime_error("No data received");
        }

        for (int i = 0; i < bytesRead; ++i) {
            unsigned char currentByte = buffer[i];

            // Detect JPEG start marker (0xFFD8)
            if (foundStart && currentByte == 0xD8) {
                skipNext = false;
                imageBuffer.push_back(0xFF);
            }

            // Detect JPEG end marker (0xFFD9)
            if (foundStart && currentByte == 0xD9) {
                endOfImage = true;
                imageBuffer.push_back(0xD9);
                skipNext = true;
            }

            // Track previous byte for detecting 0xFF
            foundStart = (currentByte == 0xFF);

            // Add byte to buffer if not skipping
            if (!skipNext) {
                imageBuffer.push_back(currentByte);
            }

            // Process complete image when end marker is found
            if (endOfImage) {
                if (!imageBuffer.empty()) {
                    Mat imgData(imageBuffer);
                    Mat decodedFrame = imdecode(imgData, IMREAD_COLOR);

                    if (!decodedFrame.empty()) {
                        imshow("Video Stream", decodedFrame);
                        waitKey(1);
                    }
                } else {
                    fprintf(stderr, "Warning: Empty image buffer\n");
                }

                // Reset state for next image
                endOfImage = false;
                skipNext = true;
                imageBuffer.clear();
            }
        }
    }

    return 0;
}

