// Test: Echo server functionality via TCP client interaction
TEST_F(EngineEchoTest, EchoServerRespondsCorrectly) {
    // Start engine in background thread
    std::thread engine_thread([this]() {
        engine_->run();
    });

    // Give engine time to initialize and create server socket
    std::this_thread::sleep_for(std::chrono::milliseconds(200));

    // Create TCP client and connect to localhost on default echo port (e.g., 9000)
    int client_fd = socket(AF_INET, SOCK_STREAM, 0);
    ASSERT_NE(client_fd, -1);

    struct sockaddr_in server_addr{};
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(9000); // assume default echo port is 9000
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    int conn_result = connect(client_fd, reinterpret_cast<sockaddr*>(&server_addr), sizeof(server_addr));
    ASSERT_EQ(conn_result, 0);

    // Send test message
    const char* msg = "Hello, Echo!";
    ssize_t sent = send(client_fd, msg, strlen(msg), 0);
    ASSERT_EQ(sent, static_cast<ssize_t>(strlen(msg)));

    // Receive response
    char buffer[256] = {0};
    ssize_t received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    ASSERT_GT(received, 0);

    // Verify echoed content matches original
    EXPECT_STREQ(buffer, msg);

    // Close client socket
    close(client_fd);

    // Signal engine to stop
    emulate_sigint();
    engine_->stop();
    engine_thread.join();
}

