#include "ihex.h"
#include <fstream>
#include <iostream>

int main(int argumentCount, char* arguments[]) {
    if (argumentCount != 4) {
        std::cerr << arguments[0] << " input.hex keyfile output.hex\n"
                  << "Encrypts or decrypts the data in an Intel Hex file.\n"
                  << "Addresses remain unchanged, only checksum is recalculated.\n\n"
                  << "The [keyfile] should be a raw binary file containing the key data.\n"
                  << "All contents of the file are used as the key, and its length can vary.\n";
        return -1;
    }

    IntelHex hexFile;
    if (!hexFile.Read(arguments[1])) {
        std::cerr << "Failed to read input hex file.\n";
        return -3;
    }

    std::ifstream keyStream(arguments[2], std::ios::binary | std::ios::ate);
    if (!keyStream.is_open()) {
        std::cerr << "Error: Unable to open keyfile.\n";
        return -2;
    }

    // Determine size of key file
    keyStream.seekg(0, std::ios::end);
    long keyLength = keyStream.tellg();
    keyStream.seekg(0, std::ios::beg);

    // Allocate buffer for key data
    uint8_t* keyBuffer = new uint8_t[keyLength];
    keyStream.read(reinterpret_cast<char*>(keyBuffer), keyLength);
    keyStream.close();

    // Apply cipher operation
    hexFile.Cipher(keyBuffer, keyLength);
    delete[] keyBuffer;

    // Write result to output file
    if (!hexFile.Write(arguments[3])) {
        std::cerr << "Error writing output hex file.\n";
        return -4;
    }

    return 0;
}

