#include "gettime.h"

// Platform-specific implementation for high-resolution time measurement
// Returns elapsed time in milliseconds since an arbitrary starting point
#if defined(_WIN32)
    #include <windows.h>

    double getTime() noexcept
    {
        LARGE_INTEGER currentTime;
        QueryPerformanceCounter(&currentTime);

        LARGE_INTEGER frequency;
        QueryPerformanceFrequency(&frequency);

        // Convert to milliseconds using 64-bit arithmetic for precision
        return (static_cast<double>(currentTime.QuadPart) * 1000.0) / 
               static_cast<double>(frequency.QuadPart);
    }
#else
    #include <sys/time.h>

    double getTime() noexcept
    {
        timeval current_time;
        gettimeofday(&current_time, nullptr);

        // Convert seconds and microseconds to total milliseconds
        double milliseconds = static_cast<double>(current_time.tv_sec) * 1000.0 +
                            static_cast<double>(current_time.tv_usec) / 1000.0;
        return milliseconds;
    }
#endif

