    client.setCallback(&dump, "error");

    // Set up two callbacks for 'output' events
    urbi::UCallbackID idA = client.setCallback(&dump, "output");
    urbi::UCallbackID idB = client.setCallback(&dump, "output");

    // Trigger output event: both callbacks should fire
    SEND("output << 1;");
    //= D output 1
    //= D output 1

    dumpSem--;
    dumpSem--;

    // Trigger error event (ping)
    SEND("error << 2;");
    //= D error 2
    dumpSem--;

    // Remove first output callback
    client.deleteCallback(idA);

    // Now only one callback remains for 'output'
    SEND("output << 3;");
    //= D output 3

    // Another error ping
    SEND("error << 4;");
    //= D error 4
    dumpSem--;
    dumpSem--;

    // Remove second output callback
    client.deleteCallback(idB);

    // No callbacks left for 'output', so this won't be printed
    SEND("output << 5;");

    // Error ping again
    SEND("error << 6;");
    //= D error 6
    dumpSem--;

    // Install a new callback that removes itself when value is zero
    client.setCallback(&removeOnZero, "output");

    // Output 7: normal callback invocation
    SEND("output << 7;");
    //= D output 7

    // Output 0: triggers self-removal
    SEND("output << 0;");
    //= D output 0

    // Output 9: no longer handled (callback was removed on previous step)
    SEND("output << 9;");

    // Final error ping
    SEND("error << 10;");
    //= D error 10

    // Allow time for async operations to complete
