DigitalPlatform::DigitalPlatform() {
  // Initialize output pins for digital channels
  palSetPadMode(GPIOA, 4, PAL_MODE_OUTPUT_PUSHPULL);
  palSetPadMode(GPIOA, 5, PAL_MODE_OUTPUT_PUSHPULL);
  palSetPadMode(GPIOC, 4, PAL_MODE_OUTPUT_PUSHPULL);
  palSetPadMode(GPIOC, 5, PAL_MODE_OUTPUT_PUSHPULL);
  palSetPadMode(GPIOA, 12, PAL_MODE_OUTPUT_PUSHPULL);
  palSetPadMode(GPIOA, 15, PAL_MODE_OUTPUT_PUSHPULL);
  palSetPadMode(GPIOB, 2, PAL_MODE_OUTPUT_PUSHPULL);

  // Ensure all outputs start in low state
  palClearPad(GPIOA, 4);
  palClearPad(GPIOA, 5);
  palClearPad(GPIOC, 4);
  palClearPad(GPIOC, 5);
  palClearPad(GPIOA, 12);
  palClearPad(GPIOA, 15);
  palClearPad(GPIOB, 2);
}

void DigitalPlatform::set(std::uint8_t channel, bool state) {
  // Map logical channel to physical GPIO pin based on channel number
  switch (channel) {
    case 0:  palWritePad(GPIOA, 4, state);  break;
    case 1:  palWritePad(GPIOA, 5, state);  break;
    case 2:  palWritePad(GPIOC, 4, state);  break;
    case 3:  palWritePad(GPIOC, 5, state);  break;
    case 4:  palWritePad(GPIOA, 12, state); break;
    case 5:  palWritePad(GPIOA, 15, state); break;
    case 6:  palWritePad(GPIOB, 2, state);  break;
    default: /* Ignore invalid channel numbers */ break;
  }
}

