#include "cell_refine.hpp"
#include <viennagrid/algorithm/refine.hpp>

// Triangular refinement implementation for 2D Cartesian domains
tuple TriangularCartesian2D_Domain_cell_refine(TriangularCartesian2D_Domain domain_in, 
                                              TriangularCartesian2D_Segmentation segmentation_in, 
                                              bool (*predicate)(const TriangularCartesian2D_Cell &))
{
    // Initialize output domain and segmentation
    TriangularCartesian2D_Domain          refined_domain;
    TriangularCartesian2D_Segmentation    refined_segmentation(refined_domain);

    // Create container and field for marking cells to refine
    CellRefinementFlagContainerType     refinement_flags;
    viennagrid::result_of::field<CellRefinementFlagContainerType,
                                 TriangularCartesian2D_Cell_t>::type   
        flag_field(refinement_flags);

    // Iterate over all cells and mark those satisfying the predicate
    TriangularCartesian2D_CellRange_t cell_range = viennagrid::elements(domain_in.get_domain());
    for (TriangularCartesian2D_CellRange_t::iterator cell_it = cell_range.begin();
         cell_it != cell_range.end(); 
         ++cell_it)
    {
        if (predicate(TriangularCartesian2D_Cell(*cell_it)))
            flag_field(*cell_it) = true;
    }

    // Perform the actual refinement based on marked cells
    viennagrid::cell_refine(domain_in.get_domain(),
                            segmentation_in.get_segmentation(),
                            refined_domain.get_domain(),
                            refined_segmentation.get_segmentation(),
                            flag_field);

    // Return the refined domain and segmentation as a tuple
    return make_tuple<TriangularCartesian2D_Domain, TriangularCartesian2D_Segmentation>(
        refined_domain, refined_segmentation);
}

