#include <iostream>
#include <stdexcept>
#include <type_traits>
#include "fsm.h"

class event_processor : public fsmlite::fsm<event_processor> {
    friend class fsm;  // base class requires access to transition_table
public:
    enum machine_states { Start, Terminate };
private:
    void handle_event(const int& evt) {
        std::cout << "Handling event: " << evt << "\n";
#ifdef NDEBUG
        if (evt != 0) {
            throw std::logic_error("recursive call detected");
        }
#endif
        dispatch_event(evt + 1);
    }
private:
    using self = event_processor;
    using transition_rules = table<
//              Initial State | Event Type | Target State | Action Handler
//  ------------+-------------+------------+--------------+-----------------
    mem_fn_row< Start, int, Terminate, &self::handle_event >
//  ------------+-------------+------------+--------------+-----------------
    >;
};

int main() {
    event_processor processor;
    try {
        processor.dispatch_event(0);
    } catch (const std::logic_error& error) {
        std::cerr << error.what() << "\n";
        return 0;
    }
    return 1;  /* LCOV_EXCL_LINE */
}

