#include "paddle/platform/place.h"
#include <sstream>
#include "gtest/gtest.h"

// Test equality and comparison of different place types
TEST(Place, Equality_Variant) {
  paddle::platform::CpuPlace cpu;
  paddle::platform::GpuPlace gpu0(0), gpu1(1), gpu0_alias(0);

  // Check reflexive equality
  EXPECT_EQ(cpu, cpu);
  EXPECT_EQ(gpu0, gpu0);
  EXPECT_EQ(gpu1, gpu1);

  // Check alias equality (same device ID)
  EXPECT_EQ(gpu0, gpu0_alias);

  // Check inequality between different devices
  EXPECT_NE(gpu0, gpu1);

  // Class type checks
  EXPECT_TRUE(paddle::platform::places_are_same_class(gpu0, gpu0_alias));
  EXPECT_FALSE(paddle::platform::places_are_same_class(gpu0, cpu));
}

// Test default place functionality
TEST(Place, Default_Variant) {
  // Verify default GPU and CPU places are correctly identified
  EXPECT_TRUE(paddle::platform::is_gpu_place(paddle::platform::get_place()));
  EXPECT_TRUE(paddle::platform::is_gpu_place(paddle::platform::default_gpu()));
  EXPECT_TRUE(paddle::platform::is_cpu_place(paddle::platform::default_cpu()));

  // Change default place to CPU and verify
  paddle::platform::set_place(paddle::platform::CpuPlace());
  EXPECT_TRUE(paddle::platform::is_cpu_place(paddle::platform::get_place()));
}

// Test string representation of places
TEST(Place, Print_Variant) {
  // Test GPU place output format
  {
    std::stringstream stream;
    stream << paddle::platform::GpuPlace(1);
    EXPECT_EQ("GpuPlace(1)", stream.str());
  }

  // Test CPU place output format
  {
    std::stringstream stream;
    stream << paddle::platform::CpuPlace();
    EXPECT_EQ("CpuPlace", stream.str());
  }
}

