        std::strcpy(ownerName, name);
        std::strcpy(accountNumber, id);
        balance = initialBalance;
    }

    void display() {
        std::cout << "Owner: " << ownerName << '\n'
                  << "Account Number: " << accountNumber << '\n'
                  << "Balance: " << balance << '\n';
