// Global pointer to the ICS driver instance
ics::ICS3* ics_driver {nullptr};
ros::Publisher pose_publisher;

// Callback function to handle incoming movement commands
void handle_servo_command(const servo_msgs::IdBased::ConstPtr& request) {
    servo_msgs::IdBased response;
    response.id = request->id;

    try {
        // Perform the move operation and store resulting angle
        auto target_angle = ics::Angle::newDegree(request->angle);
        response.angle = ics_driver->move(request->id, target_angle);

        // Publish the updated pose
        pose_publisher.publish(response);
    } catch (const std::runtime_error& err) {
        ROS_WARN("Communication failure: %s", err.what());
    }
}

