    ros::NodeHandle priv_nh{"~"};

    // Default serial port path; override via parameter if provided
    std::string serial_port{"/dev/ttyUSB0"};
    priv_nh.param<std::string>("serial_port", serial_port, serial_port);

    // Construct and assign driver
    ics::ICS3 device{std::move(serial_port)};
    ics_driver = &device;

    // Public node handle for topics
    ros::NodeHandle pub_nh{};

    // Subscriber for command messages
    ros::Subscriber cmd_subscriber{
        pub_nh.subscribe("cmd_krs", 100, handle_servo_command)
    };

