PatternPostureGenerator::PatternPostureGenerator() {}

PatternPostureGenerator::PatternPostureGenerator(ros::NodeHandle& node_handle) {
  if (!node_handle.getParam("pattern", pattern_map)) {
    ROS_WARN("Failed to load pattern map from parameter server.");
    return;
  }
  ROS_INFO("Loaded pattern map: parent -> child names.");

  // Iterate over each entry in the pattern map
  for (const auto& entry : pattern_map) {
    const std::string& key = entry.first;
    const std::string& pattern_name = entry.second;

    std::vector<double> joint_values;
    const std::string param_path = "pattern/" + pattern_name;

    if (!node_handle.getParam(param_path, joint_values)) {
      ROS_WARN("Failed to load posture data for pattern '%s' at param '%s'. Skipping.", 
               pattern_name.c_str(), param_path.c_str());
      continue;  // Skip this pattern instead of returning early
    }

    // Store the posture data under the pattern name key
    posture_data_store[pattern_name] = joint_values;
    ROS_INFO("Loaded posture data for pattern: %s", pattern_name.c_str());
  }

  // Advertise the service
  posture_key_service = node_handle.advertiseService(
      "getPostureKey", &PatternPostureGenerator::handleGetPostureKey, this);
  ROS_INFO("Service 'getPostureKey' is now active.");
}

bool PatternPostureGenerator::handleGetPostureKey(
    pattern_posture_generator::PatternKeyPosture::Request& request,
    pattern_posture_generator::PatternKeyPosture::Response& response) {

  auto it = posture_data_store.find(request.name);
  if (it == posture_data_store.end()) {
    ROS_WARN("Requested posture '%s' not found.", request.name.c_str());
    return false;
  }

  // Copy posture data into response
  response.posture = it->second;
  return true;
}

