// Alternative implementation of thread pool executor
class pool_runner : public thread_message_t {
public:
    thread_pool_t* pool_ptr;
    boost::function<void()> task_func;

    pool_runner(thread_pool_t* p, boost::function<void()> f) 
        : pool_ptr(p), task_func(f) { }

    void execute() {
        task_func();
        pool_ptr->stop();
    }

    void transition() override {
        coro_t::launch_now([this]() { execute(); });
    }
};

// Launches a function in a single-threaded RethinkDB IO context
void execute_in_io_context(boost::function<void()> func) {
    thread_pool_t io_pool(1);
    pool_runner runner(&io_pool, func);
    io_pool.dispatch(&runner);
}

// Echo server connection handler - reads and echoes back lines
void process_echo_session(boost::scoped_ptr<streamed_tcp_conn_t>& socket) {
    while (socket->input_stream().good()) {
        std::string message;
        socket->input_stream() >> message;

        if (!socket->input_stream().bad()) {
            socket->output_stream() << message << std::endl;
        }
    }
}

// Main test logic for TCP streaming
void perform_stream_validation() {
    const int base_port = 10000;
    const int port_range = 20000;
    int chosen_port = base_port + (rand() % port_range);

    streamed_tcp_acceptor_t server(chosen_port, 
                                   boost::bind(&process_echo_session, _1));

    streamed_tcp_conn_t client("localhost", chosen_port);

    std::string payload = "0";
    for (int idx = 0; idx < (8192 / 32); ++idx) {
        char cycle_char = static_cast<char>('a' + (idx % 26));
        payload.append(32, cycle_char);

        std::string part1 = payload.substr(0, idx);
        std::string part2 = payload.substr(idx);

        client.output_stream() << part1 << part2 << std::endl;

        std::string response;
        client.input_stream() >> response;

        ASSERT_FALSE(client.input_stream().fail());
        ASSERT_EQ(response, payload);
    }

    client.output_stream().flush();
}

TEST(TCPStreamTest, StartStop) {
    execute_in_io_context(&perform_stream_validation);
}

