namespace {
   // A type with a noexcept move constructor
   struct NothrowMoveConstructibleType {
      NothrowMoveConstructibleType(NothrowMoveConstructibleType&&) noexcept = default;
   };

   // A type with a potentially throwing move constructor
   struct ThrowMoveConstructibleType {
      ThrowMoveConstructibleType(ThrowMoveConstructibleType&&) {}
   };

   // A type with a noexcept move assignment operator
   struct NothrowMoveAssignableType {
      NothrowMoveAssignableType& operator=(NothrowMoveAssignableType&&) noexcept {
         return *this;
      }
   };

   // A type with a potentially throwing move assignment operator
   struct ThrowMoveAssignableType {
      ThrowMoveAssignableType& operator=(ThrowMoveAssignableType&&) {
         return *this;
      }
   };
} // namespace

// Verify compile-time detection of nothrow move construction
TEST(TestOfStdTypeTraits, CheckNothrowMoveConstruction) {
   static_assert(std2::is_nothrow_move_constructible_v<NothrowMoveConstructibleType>,
      "NothrowMoveConstructibleType correctly identified as nothrow move constructible");
   static_assert(!std2::is_nothrow_move_constructible_v<ThrowMoveConstructibleType>,
      "ThrowMoveConstructibleType correctly identified as not nothrow move constructible");
}

// Verify compile-time detection of nothrow move assignment
TEST(TestOfStdTypeTraits, CheckNothrowMoveAssignment) {
   static_assert(std2::is_nothrow_move_assignable_v<NothrowMoveAssignableType>,
      "NothrowMoveAssignableType correctly identified as nothrow move assignable");
   static_assert(!std2::is_nothrow_move_assignable_v<ThrowMoveAssignableType>,
      "ThrowMoveAssignableType correctly identified as not nothrow move assignable");
}

