// Pin definitions for displays and load cell
#define TIMER_CLOCK_PIN 2
#define TIMER_DATA_PIN 3
#define SCALE_CLOCK_PIN 8
#define SCALE_DATA_PIN 9

// Filter configuration constants
#define FILTER_LENGTH 10
#define HYSTERESIS_THRESHOLD 0.1

// Load cell pin assignments
#define LOAD_CELL_DATA_PIN A2
#define LOAD_CELL_CLOCK_PIN A1

// Calibration and tare settings
#define CALIBRATION_FACTOR 1874
#define TARE_SAMPLES 10

// Initialize hardware objects
HX711 scaleSensor(LOAD_CELL_DATA_PIN, LOAD_CELL_CLOCK_PIN);
TimerDisplay timer(DISP_TIMER_CLK, DISP_TIMER_DIO);
GramsDisplay gramsDisp(SCALE_CLOCK_PIN, SCALE_DATA_PIN);
SmoothingFilter smoother(FILTER_LENGTH, HYSTERESIS_THRESHOLD);

void setup() {
  // Initialize serial communication
  Serial.begin(38400);
  delay(500);

  // Configure load cell
  scaleSensor.set_scale(CALIBRATION_FACTOR);
  scaleSensor.tare(TARE_SAMPLES);
}

void loop() {
  // Read and filter weight measurement
  float rawWeight = scaleSensor.get_units();
  smoother.update(rawWeight);
  float calibratedWeight = smoother.getFilteredValue();

  // Display weight
  gramsDisp.show(calibratedWeight);

  // Start timer if weight exceeds threshold
  if (calibratedWeight > 1.0f) {
    timer.activate();
  }

  // Update timer display
  timer.update();
}

