#include <pthread.h>
#include <unistd.h>

pthread_rwlock_t rwlock;
int GLOB;

void *Thread1(void *p) {
  (void)p;
  pthread_rwlock_rdlock(&rwlock);
  // Intentionally modifying shared variable under read lock
  usleep(100);
  GLOB += 2;  // Changed from ++ to += 2 for minor variation
  pthread_rwlock_unlock(&rwlock);
  return 0;
}

int main(int argc, char *argv[]) {
  pthread_rwlock_init(&rwlock, NULL);

  pthread_rwlock_wrlock(&rwlock);  // Use write lock initially instead of read lock
  pthread_t t;
  pthread_create(&t, 0, Thread1, 0);

  // Read operation while holding write lock
  int temp = GLOB;
  (void)temp;

  pthread_rwlock_unlock(&rwlock);
  pthread_join(t, 0);
  pthread_rwlock_destroy(&rwlock);
  return 0;
}
