int main(int argc, char* argv[]) {
    // Skip the program name and process arguments starting from index 1
    int argument_count = argc - 1;

    if (argument_count <= 0) {
        return 0;
    }

    std::vector<std::thread> thread_pool;
    thread_pool.reserve(argument_count);

    for (int i = 1; i < argc; ++i) {
        std::istringstream parser(argv[i]);
        unsigned int parsed_value;

        if (!(parser >> parsed_value)) {
            std::cerr << "Invalid input: '" << argv[i] << "' is not an integer." << std::endl;
        } else {
            thread_pool.emplace_back(worker_thread, parsed_value);
        }
    }

    // Wait for all threads to complete execution
    for (auto& worker : thread_pool) {
        if (worker.joinable()) {
            worker.join();
        }
    }

    return 0;
}

