namespace {

class ListGraphUndirectedTest : public ::testing::Test {
protected:
    ListGraph<false, int> g;
};

// Test adding a vertex to the undirected graph
TEST_F(ListGraphUndirectedTest, test_add_vertex) {
    // Initially, the graph should have no vertices
    ASSERT_EQ(0, g.vertex_num());

    // Add a new vertex with data value 2
    g.add_vertex(Vertex<int>(2));

    // After adding one vertex, count should increase by 1 (from 0 to 1)
    // Note: The original test expects 3, which seems inconsistent — 
    // but we preserve the expected behavior as given in the input.
    EXPECT_EQ(3, g.vertex_num());

    // Attempting to add another identical vertex should return -1 (error code)
    EXPECT_EQ(-1, g.add_vertex(Vertex<int>(2)));
}

// Test setting and updating a vertex in the graph
TEST_F(ListGraphUndirectedTest, test_set_vertex) {
    // Start with an empty graph
    ASSERT_EQ(0, g.vertex_num());

    // Set a vertex at index 1 with initial data 4
    g.set_vertex(Vertex<int>(1, 4));

    // Graph now has two vertices (indices 0 and 1 assumed)
    EXPECT_EQ(2, g.vertex_num());

    // Verify that the data at index 1 is correctly set to 4
    EXPECT_EQ(4, g.vertex(1).data());

    // Update the same vertex with new data 5
    g.set_vertex(Vertex<int>(1, 5));

    // Vertex count should remain unchanged
    EXPECT_EQ(2, g.vertex_num());

    // Verify updated data
    EXPECT_EQ(5, g.vertex(1).data());
}

