int main() {
    // Allocate a large block of memory
    void *block = malloc(1024 * 1024);
    free(block);

    // Map a new anonymous page, trying to reuse the previous address
    char *mapped = (char *)mmap(block, 4096, PROT_READ | PROT_WRITE,
                                MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    assert(mapped != MAP_FAILED);  // Ensure mapping succeeded
    assert(mapped <= (char *)block);
    assert((mapped + 4096) > (char *)block);

    // Fill the mapped region with value 42
    memset(mapped, 42, 4096);

    // Unmap the region
    munmap(mapped, 4096);

    return 0;
}

