typedef __char32_t char32_t;
typedef long unsigned int size_t;

template <class _CharT>
struct __attribute__((__type_visibility__("default"))) char_traits;

template <>
struct __attribute__((__type_visibility__("default"))) char_traits<char32_t> {
  typedef char32_t char_type;

  static void assign(char_type& __dest, const char_type& __src) throw() {
    __dest = __src;
  }

  static char_type* move(char_type* __dest, const char_type* __src, size_t __count);
};

char32_t* char_traits<char32_t>::move(char_type* __dest, const char_type* __src,
                                      size_t __count) {
  if (__count > 0) {
    // Handle potential overlap by copying from end to beginning
    char_type* __end_dest = __dest + __count;
    const char_type* __end_src = __src + __count;

    while (__count-- > 0) {
      assign(*--__end_dest, *--__end_src);
    }
  }
  return __dest;
}
