       clEnumValEnd),
    cl::init(linear_scan));
}

FunctionPass *llvm::createRegisterAllocator() {
  switch (AllocatorChoice) {
  default:
    std::cerr << "Error: no valid register allocator specified" << std::endl;
    std::abort();
  case simple_alloc:
    return createSimpleRegisterAllocator();
  case local_alloc:
    return createLocalRegisterAllocator();
  case linear_scan:
    return createLinearScanRegisterAllocator();
  case iterative_scan:
    return createIterativeScanRegisterAllocator();
  }
}

