#include "binarytree.h"
#include <iostream>
#include <stack>
#include <utility>

using namespace std;

// Helper function to output a single node in DOT format
template <class T>
void emitNode(ostream& out, typename BinaryTree<T>::Inspector inspector, size_t nodeId) {
    if (inspector.isEmpty()) {
        out << nodeId << " [shape=point];\n";
    } else {
        out << nodeId << " [label=\"" << inspector.getData() << "\"];\n";
    }
}

// Iterative DOT generation for binary tree
template <class T>
void generateDotGraph(ostream& out, const BinaryTree<T>& tree) {
    out << "digraph G {\n";

    auto inspector = tree.getInspector();
    if (inspector.isEmpty()) {
        out << "0 [shape=point];\n";
        out << "}\n";
        return;
    }

    // Stack stores pairs: {node_inspector, node_id}
    stack<pair<typename BinaryTree<T>::Inspector, size_t>> nodeStack;
    nodeStack.push({inspector, 0});
    size_t nextId = 1;

    while (!nodeStack.empty()) {
        auto [currentInspector, currentId] = nodeStack.top();
        nodeStack.pop();

        // Emit current node
        emitNode(out, currentInspector, currentId);

        // Process left child
        auto leftInspector = currentInspector.left();
        if (!leftInspector.isEmpty()) {
            out << currentId << " -> " << nextId << ";\n";
            nodeStack.push({leftInspector, nextId++});
        } else {
            out << currentId << " -> " << nextId << ";\n";
            emitNode(out, leftInspector, nextId++);
        }

        // Process right child
        auto rightInspector = currentInspector.right();
        if (!rightInspector.isEmpty()) {
            out << currentId << " -> " << nextId << ";\n";
            nodeStack.push({rightInspector, nextId++});
        } else {
            out << currentId << " -> " << nextId << ";\n";
            emitNode(out, rightInspector, nextId++);
        }
    }

    out << "}\n";
}

int main() {
    BinaryTree<int> tree;
    auto transformer = tree.getTransformer();

    transformer.addData(5);
    transformer.goLeft();
    transformer.addData(2);
    transformer.goToParent();
    transformer.goRight();
    transformer.addData(3);

    generateDotGraph(cout, tree);
    return 0;
}

