#include "gtest/gtest.h"

/* Queue data structure test suite
 * Interface methods under test:
 * - enqueue: adds element to back
 * - dequeue: removes and returns front element (or nullptr if empty)
 * - size: returns number of elements
 * - clear: removes all elements
 * - empty: checks if queue is empty
 */
class QueueTest : public testing::Test {
 protected:
  // Override virtual setup/teardown from Test base class
  void SetUp() override {
    q1_.enqueue(1);
    q1_.enqueue(2);
    q2_.enqueue(1);
    q2_.enqueue(3);
  }

  void TearDown() override {
    // Cleanup handled automatically by destructors
  }

  // Test fixtures: different queue states
  Queue<int> emptyQ_;
  Queue<int> twoItemQ1_;
  Queue<int> twoItemQ2_;
};

// Verify default constructor creates empty queue
TEST_F(QueueTest, DefaultConstructor) {
  EXPECT_EQ(0u, emptyQ_.size());
}

// Test enqueue functionality and size tracking
TEST_F(QueueTest, EnqueueOperation) {
  EXPECT_EQ(2u, twoItemQ1_.size());
  EXPECT_EQ(2u, twoItemQ2_.size());

  twoItemQ2_.enqueue(100);
  EXPECT_EQ(3u, twoItemQ2_.size());
}

// Test clearing the queue
TEST_F(QueueTest, ClearOperation) {
  twoItemQ2_.clear();
  EXPECT_TRUE(twoItemQ2_.empty());
}

// Test dequeue behavior including edge cases
TEST_F(QueueTest, DequeueOperation) {
  int* first = twoItemQ1_.dequeue();
  EXPECT_EQ(1, *first);
  EXPECT_EQ(1u, twoItemQ1_.size());
  delete first;

  int* second = twoItemQ1_.dequeue();
  EXPECT_EQ(2, *second);
  EXPECT_TRUE(twoItemQ1_.empty());
  delete second;

  // Attempt to dequeue from empty queue
  int* result = twoItemQ1_.dequeue();
  EXPECT_EQ(nullptr, result);
}

