namespace {

// Address of the original function that retrieves tech use error messages
constexpr u32 Original_GetTechUseErrorMessage = 0x00491E80;

// Wrapper to intercept calls to the original function
void __declspec(naked) techErrorMessageInterceptor() {
    // Local storage for intercepted parameters and result
    static CUnit* unitTarget;
    static u8 playerIndex;
    static u16 techIdentifier;
    static u16 errorResult;

    __asm {
        PUSHAD                    // Save all general-purpose registers
        MOV EBP, ESP              // Set up stack frame
        MOV unitTarget, EAX       // First param: target unit pointer
        MOVZX EBX, BL             // Zero-extend BL into EBX to avoid partial-register issues
        MOV playerIndex, BL       // Second param: casting player index
        MOV EAX, [ESP + 36]       // Third param: tech ID (offset after PUSHAD(32) + CALL(4))
        MOVZX EAX, AX             // Zero-extend AX into EAX
        MOV techIdentifier, AX
    }

    // Call the hook implementation
    errorResult = hooks::interceptedTechErrorMessage(unitTarget, playerIndex, techIdentifier);

    __asm {
        POPAD                     // Restore registers
        MOVZX EAX, errorResult    // Zero-extend return value into EAX (AX)
        RETN 4                    // Return and pop 4 bytes from stack (callee cleanup)
    }
}

} // anonymous namespace

namespace hooks {

// Install the hook by redirecting execution flow
void installTechTargetHooks() {
    jmpPatch(techErrorMessageInterceptor, Original_GetTechUseErrorMessage);
}

// Hooked version: wraps the original function call with custom logic
u16 interceptedTechErrorMessage(const CUnit* unit, s8 player, u16 techId) {
    u32 techIdExt = techId; // Extend for stack alignment/push
    u16 resultMsg;

    __asm {
        PUSHAD                  // Preserve register state
        PUSH techIdExt          // Push third argument (tech ID)
        MOV BL, player          // Second argument: player index
        MOV EAX, unit           // First argument: target unit
        CALL Original_GetTechUseErrorMessage  // Call original function
        MOVZX resultMsg, AX     // Store low 16 bits of return in resultMsg
        POPAD                   // Restore registers
    }

    return resultMsg;
}

} // namespace hooks

