class InstructionParser
{
public:
  class InvalidInstructionException : public std::runtime_error
  {
  public:
    InvalidInstructionException(const std::string& msg) : std::runtime_error{msg}
    {}
  };

  void validateInstruction(const std::string& instr)
  {
    const std::vector<std::string> validInstructions = {"ld a,", "out (0),a"};

    bool found = false;
    for (const auto& valid : validInstructions) {
      if (instr == valid) {
        found = true;
        break;
      }
    }

    if (!found) {
      throw InvalidInstructionException{"Invalid instruction: " + instr};
    }
  }
};

TEST(InstructionParser, RejectsUnknownInstruction)
{
  InstructionParser parser;
  EXPECT_THROW(parser.validateInstruction("halt"), InstructionParser::InvalidInstructionException);
}

TEST(InstructionParser, AcceptsLoadInstruction)
{
  InstructionParser parser;
  EXPECT_NO_THROW(parser.validateInstruction("ld a,"));
}

TEST(InstructionParser, AcceptsOutputInstruction)
{
  InstructionParser parser;
  EXPECT_NO_THROW(parser.validateInstruction("out (0),a"));
}

