namespace opencl
{
using std::vector;
using cl::Platform;
using cl::Device;

// Context error callback function
void contextErrorHandler(const char *errInfo, const void *privateData, size_t size, void *userData)
{
    printf("OpenCL Context Error: %s\n", errInfo);
    fflush(stdout);
}

// Retrieve OpenCL context by index with lazy initialization
const cl::Context&
getContext(unsigned char index)
{
    static vector<Platform> platformsList;
    static vector<cl::Context> contextList;

    if (contextList.empty()) {
        Platform::get(&platformsList);

        for (const auto& platform : platformsList) {
            // Build context properties list
            vector<cl_context_properties> props = {
                CL_CONTEXT_PLATFORM,
                (cl_context_properties)platform(),
                0
            };

            contextList.emplace_back(
                CL_DEVICE_TYPE_DEFAULT,
                props.data(),
                contextErrorHandler
            );
        }
    }

    return contextList[index];
}

// Create and retrieve command queue associated with the first context
cl::CommandQueue&
getCommandQueue(unsigned char index)
{
    static vector<cl::CommandQueue> commandQueues;

    if (commandQueues.empty()) {
        commandQueues.emplace_back(getContext(0));
    }

    return commandQueues[index];
}
}

