int getNumberOfThreads()
{
    // Determine thread count with a minimum of 2 threads
    size_t hardwareThreads = std::thread::hardware_concurrency();
    size_t minThreads = static_cast<size_t>(2);

    // Use max function to ensure at least 2 threads are returned
    return static_cast<int>(std::max(hardwareThreads, minThreads));
}
