void run() 
{
  Timer timer;
  CONSOLE("measuring elapsed time with Timer::current_time() every 10 milliseconds:");

  size_t count = 0;
  while (count < 10) {
    CONSOLE("  timestamp: " + str(Timer::current_time(), 16)
        + " (system time: " + str(time(nullptr)) + ")");
    usleep(10000);
    ++count;
  }

  double total_time = timer.elapsed();
  CONSOLE("first phase completed in " + str(total_time, 6) + " seconds");

  timer.reset();
  timer.start();

  CONSOLE("verifying IntervalTimer behavior over 10 cycles of 0.2s:");
  IntervalTimer interval_timer(0.2);

  size_t ticks = 0;
  while (ticks < 10) {
    if (interval_timer) {
      CONSOLE("  pulse");
      ++ticks;
    }
  }

  CONSOLE("second phase duration: " + str(timer.elapsed(), 6) + " seconds");
}

