// Control logic for elevator movement with limit switch protection
void ElevatorSubsystem::DriveElevator(float speed) {
	// Prevent motion when:
	// - Lower limit is triggered and trying to move down (speed > 0)
	// - Upper limit is triggered and trying to move up (speed < 0)
	bool canMoveDown = !(lowerLimitSensor.Get() && speed > 0);
	bool canMoveUp   = !(upperLimitSensor.Get() && speed < 0);

	if (canMoveDown && canMoveUp) {
		pullMotorLeft.Set(speed);
		pullMotorRight.Set(speed);
	}
}

