// Global instance for job identification
JobIdentifier global_job_id;

// Helper to fetch host name safely
static std::string acquire_hostname() {
#if defined(HAVE_GETHOSTNAME) && !defined(DEBUG)
    char buffer[100];
    gethostname(buffer, sizeof(buffer) - 1);
    return std::string(buffer);
#else
    return "unknown";
#endif
}

// Constructor: builds the identifier string
JobIdentifier::JobIdentifier() {
    // Get current time
    time_t now = std::time(nullptr);

    // Start building the ID from program identifier
    std::string base_id = program_id();

    // Append hostname or placeholder
    base_id += acquire_hostname();
    base_id += " ";

    // Append human-readable time string (including newline usually)
    std::string time_str = std::ctime(&now);
    // Remove trailing newline if present for cleaner concatenation
    if (!time_str.empty() && time_str.back() == '\n') {
        time_str.pop_back();
    }
    base_id += time_str;

    // Store final result
    id = base_id;
}

// Accessor: returns the full identifier
const std::string& JobIdentifier::operator()() const {
    return id;
}

