class MyCustomClient : public SleepyDiscord::DiscordClient {
public:
    using SleepyDiscord::DiscordClient::DiscordClient;

    void onMessage(SleepyDiscord::Message message) override {
        // Check if the message starts with the trigger phrase
        if (message.content.find("whcg hello") == 0) {
            std::string response = "Hello " + message.author.username;
            sendMessage(message.channelID, response);
        }
    }
};

int main() {
    MyCustomClient bot("token", SleepyDiscord::USER_CONTROLED_THREADS);
    bot.run();
    return 0;
}

