// Helper macro to define singleton-like accessor functions with lazy initialization
#define CREATE_ACCESSOR(Name, Type, InitArgs)     \
  namespace {                                     \
    vw::RunOnce Name ## _init_once = VW_RUNONCE_INIT; \
    Type* Name ## _instance_ptr = nullptr;        \
    void construct_ ## Name() {                   \
      Name ## _instance_ptr = new Type InitArgs;  \
    }                                             \
  }                                               \
  Type& vw::vw_ ## Name() {                       \
    Name ## _init_once.run(construct_ ## Name);   \
    return *Name ## _instance_ptr;                \
  }

