// Helper function to perform in-bounds GEP with optional second index
llvm::Value* CreateInBoundsGEPWAR(llvm::IRBuilder<>& irBuilder, llvm::Value* Ptr, llvm::Value* v1, llvm::Value* v2) {
   // If the second index is null, use only the first index
   if (v2 == nullptr) {
      return irBuilder.CreateInBoundsGEP(Ptr, v1);
   }
   // Otherwise, construct a two-element index list
   else {
      llvm::ArrayRef<llvm::Value*> indices = {v1, v2};
      return irBuilder.CreateInBoundsGEP(Ptr, indices);
   }
}

