namespace libport
{
  // Handle various CLI error scenarios with different message types
  void 
  handle_cli_error(const std::string& option, const std::string& issue_type, const std::string& extra = "")
  {
    std::string message;

    if (issue_type == "requires_arg")
      message = "requires an argument";
    else if (issue_type == "missing_arg")
      message = "missing argument";
    else if (issue_type == "invalid_opt")
      message = "invalid option";
    else if (issue_type == "invalid_val")
      message = "invalid argument: " + extra;
    else
      message = issue_type;

    std::cerr << program_name << ": " << option << ": " << message << std::endl
              << "Try `" << program_name << " --help' for more information." << std::endl;

    libport::exit(EX_USAGE);
  }

  // Specific error handlers using the unified approach
  void 
  usage_error(const std::string& opt, const std::string& err)
  {
    handle_cli_error(opt, err);
  }

  void 
  required_argument(const std::string& opt)
  {
    handle_cli_error(opt, "requires_arg");
  }

  void 
  missing_argument(const std::string& opt)
  {
    handle_cli_error(opt, "missing_arg");
  }

  void 
  invalid_option(const std::string& opt)
  {
    handle_cli_error(opt, "invalid_opt");
  }

  void 
  invalid_option_val(const std::string& opt, const std::string& arg)
  {
    handle_cli_error(opt, "invalid_val", arg);
  }
}

