// Wrapper for rand() that returns a double in [0, 1)
NAN_METHOD(RandomDouble) {
  NanScope();
  double randomValue = static_cast<double>(rand()) / (RAND_MAX + 1.0);
  NanReturnValue(NanNew<Number>(randomValue));
}

// Wrapper for rand() that returns an integer
NAN_METHOD(RandInteger) {
  NanScope();
  NanReturnValue(NanNew<Integer>(rand()));
}

// Wrapper for srand() with validation and error handling
NAN_METHOD(SeedRandom) {
  NanScope();

  if (args.Length() == 0 || !args[0]->IsUint32()) {
    NanThrowTypeError("Usage: seed(n) where n is a non-negative integer");
    NanReturnUndefined();
  }

  unsigned int seedValue = args[0]->Uint32Value();
  srand(seedValue);
  NanReturnValue(NanUndefined());
}

// Module initialization function
extern "C" void init(Handle<Object> exports) {
  NODE_SET_METHOD(exports, "random", RandomDouble);
  NODE_SET_METHOD(exports, "rand", RandInteger);
  NODE_SET_METHOD(exports, "srand", SeedRandom);
  NODE_SET_METHOD(exports, "seed", SeedRandom);

  // Expose RAND_MAX constant
  NODE_SET_METHOD(exports, "getMaxRand", [](const Arguments& args) {
    NanScope();
    NanReturnValue(NanNew<Integer>(RAND_MAX));
  });
}

NODE_MODULE(srand_module, init)

