#include <atomic>
#include <type_traits>
#include <cassert>

struct CustomData {
    int value;
    CustomData() noexcept {}
    constexpr explicit CustomData(int d) noexcept : value(d) {}
    friend bool operator==(const CustomData& x, const CustomData& y) {
        return x.value == y.value;
    }
};

template <typename T>
bool verify_atomic_initialization(const T& initial_value) {
    typedef std::atomic<T> AtomicType;

    // Test direct initialization
    constexpr AtomicType obj1(initial_value);
    if (!(obj1 == initial_value)) return false;

    // Test brace initialization
    constexpr AtomicType obj2{initial_value};
    if (!(obj2 == initial_value)) return false;

    // Test ATOMIC_VAR_INIT initialization
    constexpr AtomicType obj3 = ATOMIC_VAR_INIT(initial_value);
    if (!(obj3 == initial_value)) return false;

    return true;
}

template <typename T>
void run_test() {
    static_assert(std::is_literal_type<std::atomic<T>>::value, "");
    constexpr T test_value(42);
    assert(verify_atomic_initialization(test_value));
}

int main() {
    run_test<int>();
    run_test<CustomData>();
    return 0;
}

