#include <vector>
#include <unordered_set>
#include <algorithm>
#include <string>

class Solution {
public:
    bool closeStrings(std::string word1, std::string word2) {
        // Frequency arrays for characters 'a' to 'z'
        std::vector<int> freq1(26, 0), freq2(26, 0);
        // Sets to track unique characters in each word
        std::unordered_set<char> chars1, chars2;

        // Count frequencies and collect unique characters for word1
        for (char ch : word1) {
            freq1[ch - 'a']++;
            chars1.insert(ch);
        }

        // Count frequencies and collect unique characters for word2
        for (char ch : word2) {
            freq2[ch - 'a']++;
            chars2.insert(ch);
        }

        // Sort frequency vectors to compare pattern of frequencies
        std::sort(freq1.begin(), freq1.end());
        std::sort(freq2.begin(), freq2.end());

        // Two conditions must be satisfied:
        // 1. Same set of unique characters
        // 2. Same frequency distribution (when sorted)
        return (chars1 == chars2) && (freq1 == freq2);
    }
};

