// Constructor: default initialization
PatternPostureGenerator::PatternPostureGenerator() {}

// Constructor: initializes from ROS parameter server
PatternPostureGenerator::PatternPostureGenerator(ros::NodeHandle& nh) {
  // Retrieve list of pattern names from parameter server
  if (!nh.getParam("pattern", pattern_names)) return;

  // Iterate over each pattern name entry
  for (const auto& pair : pattern_names) {
    const std::string& key = pair.first;
    const std::string& path_suffix = pair.second;

    // Load posture data for this pattern
    std::vector<double> raw_posture;
    const std::string full_param_name = std::string("pattern/") + path_suffix;
    if (!nh.getParam(full_param_name, raw_posture)) return;

    // Store the posture data under the corresponding key
    posture_datas[key] = raw_posture;  // Direct assignment instead of back_inserter
  }

  // Advertise the service to request posture keys
  key_srv = nh.advertiseService("getPostureKey", &PatternPostureGenerator::getPostureKey, this);
}

// Service callback: returns stored posture for given pattern name
bool PatternPostureGenerator::getPostureKey(
    pattern_posture_generator::PatternKeyPosture::Request& req,
    pattern_posture_generator::PatternKeyPosture::Response& res) {

  // Find the requested posture in the map
  auto it = posture_datas.find(req.name);
  if (it != posture_datas.end()) {
    res.posture = it->second;  // Direct copy assignment
  } else {
    res.posture.clear();       // Ensure empty on failure
  }

  return true;
}

int main(int argc, char* argv[]) {
  ros::init(argc, argv, "pattern_posture_generator");
  ros::NodeHandle node_handle;
  PatternPostureGenerator generator(node_handle);
  ros::spin();
  return 0;
}

