#include <io/stream_handle.h>

class DataSink {
    LogHandle logger_;
    StreamHandle stream_;
    CallbackHandler termination_handler_;
    EventHandler input_handler_;

public:
    DataSink(int fd)
    : logger_("/sink"),
      stream_(fd),
      input_handler_()
    {
        input_handler_.register_handler(Event::Done, this, &DataSink::handle_input);
        input_handler_.register_handler(Event::EOS, this, &DataSink::handle_end_of_stream);
        termination_handler_.register_handler(this, &DataSink::on_termination);

        input_handler_.schedule(stream_.read(0, input_handler_.get_callback()));
    }

    ~DataSink() { }

    void handle_input(Event)
    {
        input_handler_.schedule(stream_.read(0, input_handler_.get_callback()));
    }

    void handle_end_of_stream(Event)
    {
        termination_handler_.schedule(stream_.close(termination_handler_.get_callback()));
    }

    void on_termination(void)
    { }
};

int main(void)
{
    DataSink sink(STDIN_FILENO);
    event_main();
}

