using namespace std;

class IncrementAndDoubling {
public:
    int getMinHelper(vector<int> DesiredArray, int Moves) {
        // Check if all elements are zero
        bool allZero = true;
        for (int element : DesiredArray) {
            if (element != 0) {
                allZero = false;
                break;
            }
        }

        if (allZero) {
            return Moves;
        }

        // Check if all elements are even
        bool allEven = true;
        for (int element : DesiredArray) {
            if (element % 2 != 0) {
                allEven = false;
                break;
            }
        }

        if (allEven) {
            // Divide all elements by 2
            for (int &element : DesiredArray) {
                element /= 2;
            }
            Moves++;
        } else {
            // Subtract 1 from all odd elements
            for (int &element : DesiredArray) {
                if (element % 2 == 1) {
                    element--;
                    Moves++;
                }
            }
        }

        return getMinHelper(DesiredArray, Moves);
    }

    int getMin(vector<int> DesiredArray) {
        int moves = 0;
        int result = getMinHelper(DesiredArray, moves);
        return result;
    }
};

