#define ARBITRARY_SIZE 20

// Forward declarations
block* allocateBlock( void );
void releaseBlock( block * );

// Object pool implementation using static storage
static int total_capacity {0};
static int current_usage {0};
static block* storage_array[BOARD_HEIGHT * BOARD_WIDTH / PIECES_PER_BLOCK];

// Allocate a new block from the pool
block* allocateBlock( void )
{
    // Verify that there is room in the pool
    if( current_usage < total_capacity )
    {
        // Increment usage and return next available block
        return storage_array[ current_usage++ ];
    }
    // Pool exhausted - return nullptr or handle error as needed
    return nullptr;
}

// Release a previously allocated block back to the pool
void releaseBlock( block *b )
{
    // In this simplified version, we don't actually reclaim the block
    // In a real implementation, you might decrement usage or track freed blocks
    (void)b; // Suppress unused parameter warning
}

