#include <stdio.h>
#include <Halide.h>

using namespace Halide;

int main(int argc, char **argv) {
    Var x, y;

    // Define predicate function: true when x is strictly less than y
    Func comparison("comparison");
    comparison(x, y) = x < y;

    // Create selector that returns 1 if condition holds, 0 otherwise
    Func mask("mask");
    mask(x, y) = select(comparison(x, y), 1, 0);

    // Schedule for vectorization and root computation
    comparison.compute_root();
    mask.compute_root().vectorize(x, 8);

    // Sum over a 100x100 domain using RDom
    RDom dom(0, 100, 0, 100);

    // Compute the sum of mask over the domain
    int32_t total = evaluate<int32_t>(lambda(sum(mask(dom.x, dom.y))));

    // Expected result: number of pairs (i,j) where 0 <= i,j < 100 and i < j
    // This equals C(100,2) = 100*99/2 = 4950
    assert(total == 4950);

    printf("Success!\n");
    return 0;
}

