    Solution s;

    SECTION("Both input arrays are empty") {
        std::vector<int> arr1 {};
        std::vector<int> arr2 {};
        REQUIRE(s.findMedianSortedArrays(arr1, arr2) == 0.0);
    }

    SECTION("Non-overlapping arrays with even total length") {
        std::vector<int> first {1, 2, 3};
        std::vector<int> second {4, 5, 6};
        REQUIRE(s.findMedianSortedArrays(first, second) == 3.5);
