        std::vector<int> data1 {1, 2, 7};
        std::vector<int> data2 {4, 5, 6};
        REQUIRE(s.findMedianSortedArrays(data1, data2) == 4.5);
    }

    SECTION("Non-overlapping arrays with odd total length") {
        std::vector<int> input1 {1, 2};
        std::vector<int> input2 {4, 5, 6};
        REQUIRE(s.findMedianSortedArrays(input1, input2) == 4.0);
