#include <ros/ros.h>
#include <servo_msgs/IdBased.h>
#include <ics3/ics>

// Global driver instance and publisher
ics::ICS3* motor_driver = nullptr;
ros::Publisher pose_publisher;

// Callback function to handle movement commands
void execute_servo_command(const servo_msgs::IdBased::ConstPtr& command) {
  servo_msgs::IdBased response;
  try {
    // Perform the movement using the driver and convert angle to degrees
    response.angle = motor_driver->move(command->id, ics::Angle::newDegree(command->angle));
    response.id = command->id;
    pose_publisher.publish(response);
  } catch (const std::runtime_error& error) {
    ROS_WARN("Communication failure: %s", error.what());
  }
}

int main(int argc, char** argv) {
  // Initialize ROS node
  ros::init(argc, argv, "servo_krs_node");

  // Get private node handle for parameters
  ros::NodeHandle private_nh{"~"};

  // Default serial port path
  std::string serial_port_path = "/dev/ttyUSB0";
  private_nh.param<std::string>("serial_port", serial_port_path, serial_port_path);

  ROS_INFO("Initializing servo motor connection on: %s", serial_port_path.c_str());

  // Create and assign ICS3 driver instance
  ics::ICS3 controller{std::move(serial_port_path)};
  motor_driver = &controller;

  // Set up subscriber and publisher
  ros::NodeHandle core_nh{};
  ros::Subscriber command_subscriber = core_nh.subscribe("cmd_krs", 100, execute_servo_command);
  pose_publisher = core_nh.advertise<servo_msgs::IdBased>("pose_krs", 10);

  // Enter main event loop
  ros::spin();
  return 0;
}

