#include <utility>
#include <iostream>
#include <string>

// Helper structure to hold a value at a specific index
template <std::size_t Index, typename Type>
struct storage {
    Type value;
};

// Implementation of tuple using multiple inheritance and index sequences
template <typename Indices, typename... Types>
struct tuple_base;

// Specialization that creates the actual tuple by inheriting from storage<Index, Type> for each type
template <std::size_t... Indices, typename... Types>
struct tuple_base<std::index_sequence<Indices...>, Types...> 
    : storage<Indices, Types>... {};

// Alias template for the final tuple type
template <typename... Types>
using my_tuple = tuple_base<std::make_index_sequence<sizeof...(Types)>, Types...>;

// Overloaded get functions: one using index, one using type
template <std::size_t Index, typename Type>
Type& get(storage<Index, Type>& s) {
    return s.value;
}

template <typename Type, std::size_t Index>
Type& get(storage<Index, Type>& s) {
    return s.value;
}

// Function demonstrating tuple usage
void demonstrate_tuple() {
    my_tuple<int, std::string> t{42, "initial"};

    // Access elements using index-based get
    std::cout << get<1>(t) << "\n";
    std::cout << get<0>(t) << "\n";

    // Modify elements using type-based get
    get<int>(t) = 100;
    get<std::string>(t) = "modified";

    // Print updated values
    std::cout << get<1>(t) << "\n";
    std::cout << get<0>(t) << "\n";
}

// Variant visitor implementation using overload pattern
template <typename... Visitors>
struct variant_visitor : Visitors... {
    using Visitors::operator()...;
};

// Deduction guide for variant_visitor
template <typename... Visitors>
variant_visitor(Visitors...)->variant_visitor<Visitors...>;

// Function demonstrating variant with overloaded visitors
void demonstrate_variant() {
    std::variant<int, std::string> var;
    var = std::string("greeting");

    std::visit(
        variant_visitor{
            [](int num) { std::cout << num << " is integer\n"; },
            [](const std::string& str) { std::cout << str << " is string\n"; }
        },
        var
    );
}

int main() {
    demonstrate_tuple();
    demonstrate_variant();
    return 0;
}

