std::exception_ptr saved_exception;

void faulty_operation()
{
    try
    {
        std::thread().detach(); // Intentionally problematic
    }
    catch (...)
    {
        saved_exception = std::current_exception();
    }
}

int main()
{
    assert(saved_exception == nullptr);
    assert(!saved_exception);

    std::thread worker(faulty_operation);
    worker.join();

    assert(saved_exception != nullptr);
    assert(saved_exception);

    try
    {
        std::rethrow_exception(saved_exception);
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Operation failed with exception: " << ex.what() << "\n";
    }
}

