#include "GlobalContext.hpp"
#include "ast/SourceFile.hpp"
#include "parser/SpiritParser.hpp"

int main(int argc, char* args[])
{
    // Convert command line arguments to string vector
    const std::vector<std::string> filenames(args + 1, args + argc);

    using namespace eddic;
    using namespace eddic::parser;

    // Repeat parsing process 100 times as required
    int iteration = 0;
    while (iteration < 100)
    {
        // Process each input file in the arguments
        auto fileIterator = filenames.begin();
        while (fileIterator != filenames.end())
        {
            SpiritParser parserInstance;
            eddic::ast::SourceFile parsedProgram;
            parserInstance.parse(*fileIterator, parsedProgram, 
                               std::make_shared<GlobalContext>(Platform::INTEL_X86_64));
            ++fileIterator;
        }
        ++iteration;
    }

    return 0;
}

