// ANSI color codes for terminal output
#define COLOR_LIGHTRED  "\033[31;1m"
#define COLOR_RED       "\033[31m"
#define COLOR_LIGHTBLUE "\033[34;1m"
#define COLOR_BLUE      "\033[34m"
#define COLOR_GREEN     "\033[32;1m"
#define COLOR_YELLOW    "\033[33;1m"
#define COLOR_ORANGE    "\033[0;33m"
#define COLOR_WHITE     "\033[37;1m"
#define COLOR_LIGHTCYAN "\033[36;1m"
#define COLOR_CYAN      "\033[36m"
#define COLOR_RESET     "\033[0m"
#define COLOR_HIGH      "\033[1m"

// Macro to format and write log messages with timestamp and color
#define LOG_OUTPUT(OUT, COLOR_CODE, LEVEL_TAG, TEXT) \
    OUT << COLOR_CODE << QTime::currentTime().toString("hh:mm:ss:zzz").toStdString() \
        << " " LEVEL_TAG " " << COLOR_RESET << TEXT << "\n"

// Custom log handler function to process Qt logging messages
static void EmsCustomLogWriter(QtMsgType type, const QMessageLogContext &context, const QString &msg)
{
    switch (type)
    {
        case QtWarningMsg:
            LOG_OUTPUT(std::cout, COLOR_YELLOW, "WARN", msg.toStdString());
            break;
        case QtCriticalMsg:
            LOG_OUTPUT(std::cout, COLOR_RED, "CRIT", msg.toStdString());
            break;
        case QtFatalMsg:
            LOG_OUTPUT(std::cout, COLOR_ORANGE, "FATAL", msg.toStdString());
            break;
        case QtDebugMsg:
            LOG_OUTPUT(std::cout, COLOR_CYAN, "DEBUG", msg.toStdString());
            break;
        default:
            // Treat unknown message types as debug
            LOG_OUTPUT(std::cout, COLOR_CYAN, "DEBUG", msg.toStdString());
            break;
    }
}

int main(int argc, char *argv[])
{
    // Install custom message handler for Qt logging
    qInstallMessageHandler(EmsCustomLogWriter);

    Application app(argc, argv);

    return app.exec();
}

#include "math_container.h"
using namespace std;

/******************************************************/
/*solve the equation cosh(x)=exp(y), input y, return x*/
/******************************************************/
complex<double> coshx_eq_expy(double y)
{
    complex<double> expY(exp(y), 0.0);
    complex<double> discriminant = sqrt(expY * expY - 1.0);
    complex<double> temp = expY - discriminant;
    complex<double> result = log(temp);

    // Normalize result to be purely real or purely imaginary
    if (abs(result.real()) <= abs(result.imag())) {
        result = complex<double>(0.0, result.imag());
    } else {
        result = complex<double>(result.real(), 0.0);
    }

    return result;
}

