#include "chrome/browser/in_process_webkit/webkit_thread.h"
#include "testing/gtest/include/gtest/gtest.h"

// Test case for WebKitThread initialization and ChromeThread::DeleteSoon behavior
TEST(WebKitThreadTest, DISABLED_ExposedInChromeThread) {
  // Use a null pointer to assist template type deduction
  int* dummy_null_ptr = nullptr;

  // Before creating WebKitThread, DeleteSoon should return false
  EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, dummy_null_ptr));

  {
    // Create and initialize WebKitThread
    WebKitThread webkit_instance;

    // Still before initialization - DeleteSoon should return false
    EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, dummy_null_ptr));

    // Initialize the thread
    webkit_instance.Initialize();

    // After initialization, DeleteSoon should succeed (return true)
    EXPECT_TRUE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, dummy_null_ptr));
  }

  // After WebKitThread goes out of scope, DeleteSoon should again return false
  EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, dummy_null_ptr));
}

#include "simplegameworld.h"
#include <vector>

void SimpleGameWorld::addEntity(shared_ptr<gamefw::Entity> entity)
{
    m_entity_list.emplace_back(entity);
}

void SimpleGameWorld::update()
{
    for (size_t i = 0; i < m_entity_list.size(); ++i) {
        auto& entity = m_entity_list[i];

        // Compute orientation in radians once to avoid repeated conversion
        float angle_rad = glm::radians(entity->m_orientation.x);
        float cos_a = glm::cos(angle_rad);
        float sin_a = glm::sin(angle_rad);

        // Update position using local velocity and orientation
        float dx = entity->m_velocity_local.x * cos_a - entity->m_velocity_local.z * sin_a;
        float dz = entity->m_velocity_local.x * sin_a + entity->m_velocity_local.z * cos_a;

        entity->m_position.x += dx;
        entity->m_position.z += dz;
        entity->m_position.y += entity->m_velocity_local.y;

        // Update angular orientation
        entity->m_orientation += entity->m_angular_velocity;
    }
}

