namespace sky {
namespace compositor {

OpacityLayer::OpacityLayer() : alpha_(0xFF) {}

OpacityLayer::~OpacityLayer() {}

void OpacityLayer::Paint(PaintContext::ScopedFrame& frame) {
  // Create paint with specified alpha for transparency effect
  SkPaint layer_paint;
  uint8_t opacity = static_cast<uint8_t>(alpha_);
  layer_paint.setARGB(opacity, 0, 0, 0);
  layer_paint.setBlendMode(SkBlendMode::kSrcOver);

  SkCanvas& target_canvas = frame.canvas();

  // Apply layer with optional bounds constraint
  const SkRect* bounds_ptr = nullptr;
  if (has_paint_bounds()) {
    bounds_ptr = &paint_bounds();
  }

  target_canvas.saveLayer(bounds_ptr, &layer_paint);

  // Render all child layers
  PaintChildren(frame);

  // Restore canvas to previous state
  target_canvas.restore();
}

