SUITE(ArticleToJsonSerializationTests)
{
    TEST(SerializeSingleArticleNoOutgoingLinks)
    {
        ToJsonWriter serializer;
        Article article("Farm");
        CHECK_EQUAL("{\"Farm\":{\"forward_links\":[]}}", serializer.serialize(&article));
    }

    TEST(SerializeSingleArticleWithOneLink)
    {
        ToJsonWriter serializer;
        Article article("Farm");
        article.addLink(new Article("Animal"));
        CHECK_EQUAL("{\"Farm\":{\"forward_links\":[\"Animal\"]}}", serializer.serialize(&article));
    }

    TEST(SerializeSingleArticleWithMultipleLinks)
    {
        ToJsonWriter serializer;
        Article article("Farm");
        article.addLink(new Article("Animal"));
        article.addLink(new Article("Pig"));
        article.addLink(new Article("Equality"));
        CHECK_EQUAL("{\"Farm\":{\"forward_links\":[\"Animal\",\"Pig\",\"Equality\"]}}", serializer.serialize(&article));
    }

    TEST(SerializeEmptyArticleCollection)
    {
        ToJsonWriter serializer;
        ArticleCollection collection;
        CHECK_EQUAL("{}", serializer.serialize(collection));
    }

    TEST(SerializeArticleCollectionWithOneItem)
    {
        ToJsonWriter serializer;
        ArticleCollection collection;
        collection.add(new Article("Foo"));
        CHECK_EQUAL("{\"Foo\":{\"forward_links\":[]}}", serializer.serialize(collection));
    }
}

