// Attempt to add a message with line termination to the queue
bool tryAddMessageToQueue(QUEUE_TYPE(uint8_t)* targetQueue, const uint8_t* data, 
                         int length) {
    // Check if sufficient space exists (message + 2 termination bytes)
    if(queue_available(targetQueue) < static_cast<size_t>(length + 2)) {
        return false;
    }

    // Copy each byte of the message
    for(int idx = 0; idx < length; ++idx) {
        QUEUE_PUSH(uint8_t, targetQueue, data[idx]);
    }

    // Append carriage return and line feed terminators
    QUEUE_PUSH(uint8_t, targetQueue, '\r');
    QUEUE_PUSH(uint8_t, targetQueue, '\n');

    return true;
}

// Send message via all available output interfaces
void broadcastMessage(Listener* device, const uint8_t* payload, int size) {
    // Try sending over USB interface first
    if(!tryAddMessageToQueue(&device->usb->sendQueue, payload, size)) {
        debug("USB send buffer overflow, discarding CAN message: %s\r\n", payload);
    }

    // Then attempt to send over serial interface
    if(!tryAddMessageToQueue(&device->serial->sendQueue, payload, size)) {
        debug("UART send buffer overflow, discarding CAN message: %s\r\n", payload);
    }
}

// Handle incoming data from all communication channels
void handleListenerBuffers(Listener* controller) {
    // Process USB communication (required for MCU USB stack operation)
    processInputQueue(controller->usb);

    // Process serial communication
    processInputQueue(controller->serial);
}

