// Custom comparator for sorting by value (descending)
struct CompareByValue {
    template<typename T>
    bool operator()(const T& a, const T& b) const {
        return a.second > b.second;
    }
};

int main() {
    std::map<std::string, int> word_count;
    std::string current_word;

    // Read and count words
    while (std::cin >> current_word) {
        ++word_count[current_word];
    }

    // Convert map to vector for sorting
    std::vector<std::pair<std::string, int>> word_vector;
    word_vector.reserve(word_count.size());
    for (const auto& pair : word_count) {
        word_vector.push_back(pair);
    }

    // Sort by frequency (descending)
    std::sort(word_vector.begin(), word_vector.end(), CompareByValue());

    // Output top 10 words
    int count = 0;
    for (const auto& entry : word_vector) {
        if (count >= 10) break;
        std::cout << entry.second << ": " << entry.first << '\n';
        ++count;
    }

    return 0;
}

