// Helper function to simulate f() behavior with A object creation/destruction
int simulate_f(const int& value) {
    // In original code, f takes const A&, but we're using int for simplicity
    // The CHECK lines indicate two calls to f(3), each creating and destroying an A object
    return value; 
}

// Template function similar to g<T>, but using while loop instead of direct array declarations
template<typename T> void modified_g() {
    int temp_result = 0;
    int counter = 0;

    // First "array" simulation - equivalent to int a[f(3)]
    while (counter < 1) {  // Simulating one allocation of size f(3)
        temp_result = simulate_f(3);
        counter++;
    }

    // Second "array" simulation - equivalent to int b[f(3)]
    counter = 0;
    while (counter < 1) {  // Simulating second allocation of size f(3)
        temp_result = simulate_f(3);
        counter++;
    }

    // Just to use the result and avoid compiler optimization removing the calls
    std::cout << temp_result << std::endl;
}

int main() { 
    modified_g<int>(); 
    return 0; 
}

