#include "llvm/Support/Timer.h"
#include "llvm/Support/Thread.h"
#include "gtest/gtest.h"
#include <chrono>

using namespace llvm;

namespace {

// Test that timer accumulates time correctly across multiple start/stop cycles
TEST(Timer, Additivity) {
  Timer T1("T1");
  ASSERT_TRUE(T1.isInitialized());

  // First measurement cycle
  T1.startTimer();
  T1.stopTimer();
  auto initialTime = T1.getTotalTime();

  // Second measurement cycle with a delay
  T1.startTimer();
  std::this_thread::sleep_for(std::chrono::milliseconds(1));
  T1.stopTimer();
  auto updatedTime = T1.getTotalTime();

  // Verify that accumulated time increased after the second cycle
  EXPECT_LT(initialTime, updatedTime);
}

// Test the trigger state behavior of the timer
TEST(Timer, CheckIfTriggered) {
  Timer T1("T1");

  // Initially, timer should not be triggered
  EXPECT_FALSE(T1.hasTriggered());

  // After starting, timer should be considered triggered
  T1.startTimer();
  EXPECT_TRUE(T1.hasTriggered());

  // Even after stopping, it should remain triggered
  T1.stopTimer();
  EXPECT_TRUE(T1.hasTriggered());

  // After clearing, the trigger state should reset
  T1.clear();
  EXPECT_FALSE(T1.hasTriggered());
}

