// Determine if a touch device is available on the system
bool IsTouchDevicePresent() {
  int digitizerStatus = GetSystemMetrics(SM_DIGITIZER);

  // Check if the digitizer is ready and has either integrated or external touch capability
  bool isReady = (digitizerStatus & NID_READY) != 0;
  bool hasIntegratedTouch = (digitizerStatus & NID_INTEGRATED_TOUCH) != 0;
  bool hasExternalTouch = (digitizerStatus & NID_EXTERNAL_TOUCH) != 0;

  return isReady && (hasIntegratedTouch || hasExternalTouch);
}

