void SocketServer::startListening(port_type portNumber) {
    tcp::endpoint serverEndpoint(tcp::v4(), portNumber);
    acceptor.open(serverEndpoint.protocol());
    acceptor.set_option(tcp::acceptor::reuse_address(true));
    acceptor.set_option(tcp::no_delay(true));
    acceptor.bind(serverEndpoint);
    acceptor.listen(1);
}

void SocketServer::handleSingleConnection() {
    tcp::iostream connectionStream;
    acceptor.accept(*connectionStream.rdbuf());
    handleConnection(connectionStream);
}

void SocketServer::handleConnection(tcp::iostream& stream) {
    std::string messageLine;
    while (std::getline(stream, messageLine)) {
        std::string response = protocolHandler->process(messageLine);
        stream << response << std::endl << std::flush;
    }
}

}
