// Helper function to locate the gin_shell executable
base::FilePath LocateGinShell() {
  base::FilePath exe_dir;
  PathService::Get(base::DIR_EXE, &exe_dir);
  return exe_dir.AppendASCII("gin_shell");
}

// Helper function to locate the hello_world.js test script
base::FilePath LocateHelloWorldScript() {
  base::FilePath src_root;
  PathService::Get(base::DIR_SOURCE_ROOT, &src_root);
  return src_root
      .AppendASCII("gin")
      .AppendASCII("shell")
      .AppendASCII("hello_world.js");
}

// Test that verifies gin_shell executes hello_world.js and outputs "Hello World"
TEST(GinShellTest, HelloWorld) {
  base::FilePath shell_path(LocateGinShell());
  base::FilePath script_path(LocateHelloWorldScript());

  // Ensure both files exist before proceeding
  ASSERT_TRUE(base::PathExists(shell_path));
  ASSERT_TRUE(base::PathExists(script_path));

  // Construct command line to run gin_shell with the script
  CommandLine cmd(shell_path);
  cmd.AppendArgPath(script_path);

  // Capture output from the executed process
  std::string raw_output;
  ASSERT_TRUE(base::GetAppOutput(cmd, &raw_output));

  // Clean up whitespace (leading/trailing spaces, newlines, etc.)
  std::string trimmed_output;
  base::TrimWhitespaceASCII(raw_output, base::TRIM_ALL, &trimmed_output);

  // Verify the output matches expected result
  EXPECT_EQ("Hello World", trimmed_output);
}

