using namespace sys;

// Linux-specific implementation of current time retrieval
TimeValue TimeValue::now() {
  struct timeval current_time;
  timerclear(&current_time);

  if (::gettimeofday(&current_time, nullptr) != 0) {
    ThrowErrno("Couldn't obtain time of day");
  }

  return TimeValue(
    static_cast<TimeValue::SecondsType>(current_time.tv_sec),
    static_cast<TimeValue::NanoSecondsType>(current_time.tv_usec * NANOSECONDS_PER_MICROSECOND)
  );
}
