#include "ExecutableLauncherUnix.h"
#include <cstdio>
#include <cstdlib>
#include <sys/types.h>
#include <unistd.h>
#include <sys/wait.h>

using namespace clt::filesystem::operations;

void ExecutableLauncherUnix::execute(const entities::Path& path) {
    pid_t childPid = fork();

    if (childPid == -1) {
        perror("fork");
        return;
    }

    if (childPid == 0) {
        // Child process: attempt to execute the program
        execl(path.getValue().c_str(), path.getValue().c_str(), static_cast<char*>(nullptr));
        // If execl returns, it failed
        _exit(EXIT_FAILURE);
    } else {
        // Parent process: wait for child to complete
        int status;
        waitpid(childPid, &status, 0);
    }
}

