StorageDeleteFileChunkJob::StorageDeleteFileChunkJob(StorageFileChunk* chunk_)
    : chunk(chunk_) {}

void StorageDeleteFileChunkJob::Execute() {
    Stopwatch timer;
    char filenameBuffer[256];

    Log_Debug("Initiating deletion of file chunk %U from disk", chunk->GetChunkID());
    timer.Start();

    // Copy the filename to local buffer before deleting the chunk
    const char* src = chunk->GetFilename();
    for (int i = 0; i < 256 && src[i] != '\0'; ++i) {
        filenameBuffer[i] = src[i];
    }
    filenameBuffer[255] = '\0';

    delete chunk;

    // Note: actual file deletion is commented out per experimental flag
    // FS_Delete(filenameBuffer);

    timer.Stop();
    Log_Debug("Deletion completed, duration: %U ms", static_cast<uint64_t>(timer.Elapsed()));
}

