// Store loaded plugin filenames
static ManagedStatic<std::vector<std::string>> PluginList;

// Load a plugin from the given filename
void PluginLoader::operator=(const std::string& filepath) {
    std::string error_msg;

    // Attempt to load the dynamic library permanently
    if (sys::DynamicLibrary::LoadLibraryPermanently(filepath.c_str(), &error_msg)) {
        // Report failure and ignore the request
        cerr << "Error opening '" << filepath << "': " << error_msg
             << "\n  -load request ignored.\n";
    } else {
        // Successfully loaded, store the filename
        PluginList->push_back(filepath);
    }
}

// Get the number of currently loaded plugins
unsigned PluginLoader::getNumPlugins() {
    return PluginList.isConstructed() ? PluginList->size() : 0;
}

// Retrieve a specific plugin by index
std::string& PluginLoader::getPlugin(unsigned index) {
    // Ensure the plugin list is constructed and index is valid
    assert(PluginList.isConstructed() && index < PluginList->size() &&
           "Asking for an out-of-bounds plugin");
    return (*PluginList)[index];
}

