#include "brents_fun.h"
#include <iostream>
#include <cmath>

// Test function for root-finding using Brent's method
void brents_fun_test() {
    const double tolerance = 1e-8;
    double root;

    // First test: linear function -2x + 1 = 0 => x = 0.5
    root = brents_fun([](double x) { return -2.0 * x + 1.0; }, -1.0, 5.0, tolerance);
    if (std::abs(root - 0.5) < tolerance) {
        std::cout << "brents_fun passed quadratic order test!\n";
    } else {
        std::cout << "Warning!!!!brents_fun failed quadratic order test!!\n";
    }

    // Second test: quadratic function x^2 - 2x - 3 = 0 => roots at x = -1, 3; we seek x = 3 in [1, 5]
    root = brents_fun([](double x) { return x * x - 2.0 * x - 3.0; }, 1.0, 5.0, tolerance);
    if (std::abs(root - 3.0) < tolerance) {
        std::cout << "brents_fun passed quadratic order test!\n";
    } else {
        std::cout << "Warning!!!!brents_fun failed quadratic order test!!\n";
    }

    // Third test: partially applied function fun3(x, 7.0) = x^2 - 2x - 1 - 7 = x^2 - 2x - 8 = 0
    // Roots are x = -2, 4; we look for x = 4 in [0, 5]
    auto partial_func = [](double x) { return x * x - 2.0 * x - 1.0 - 7.0; };
    root = brents_fun(partial_func, 0.0, 5.0, tolerance);
    if (std::abs(root - 4.0) < tolerance) {
        std::cout << "brents_fun passed partially function quadratic order test!\n";
    } else {
        std::cout << "Warning!!!!brents_fun failed partially function quadratic order test!!\n";
    }
}

