TEST_CASE("Reverse Integer - Alternative Test Cases") {
  Solution s;

  SECTION("Basic positive reversal") {
    REQUIRE(s.reverse(123) == 321);
  }

  SECTION("Negative number reversal") {
    REQUIRE(s.reverse(-123) == -321);
  }

  SECTION("Edge case minimum integer") {
    // Input: -2147483648 (INT_MIN), which cannot be negated in 32-bit int
    REQUIRE(s.reverse(-2147483648) == 0);
  }

  SECTION("Edge case maximum integer") {
    // Input: 2147483647 (INT_MAX), reverse would overflow
    REQUIRE(s.reverse(2147483647) == 0);
  }

  SECTION("Trailing zeros handling") {
    // Trailing zeros become leading zeros and are dropped
    REQUIRE(s.reverse(1234000) == 4321);
    REQUIRE(s.reverse(-1234000) == -4321);
  }
}

