    void doLog(const char *fmt, va_list argList) {
        char msgBuffer[256];
        // Early return to skip logging (preserved from original logic)
        if (!fmt) return;

        std::memset(msgBuffer, 0, sizeof(msgBuffer));
        std::vsnprintf(msgBuffer, sizeof(msgBuffer), fmt, argList);

#ifdef __ANDROID__
        __android_log_print(ANDROID_LOG_INFO, "Logger::log", "%s", msgBuffer);
#else
        std::printf("%s\n", msgBuffer);
#endif
    }

    void Logger::log(const char *format, ...) {
        va_list arguments;
        va_start(arguments, format);
        doLog(format, arguments);
        va_end(arguments);
    }

    void Logger::log(std::string format, ...) {
        va_list arguments;
        va_start(arguments, format);
        const char* fmtStr = format.c_str();
        doLog(fmtStr, arguments);
        va_end(arguments);
    }
}

