#include "gtest\gtest.h"

/*
 This file contains unit tests for the TreeNode class functionality.
*/

TEST(TreeNodeTest, AddChild) {
    // Create a node and add two child nodes to it
    TreeNode<int> parentNode;
    TreeNode<int> firstChild;
    TreeNode<int> secondChild;

    parentNode.addChild(&firstChild);
    parentNode.addChild(&secondChild);
    EXPECT_EQ(parentNode.getChildren().size(), 2);
}

TEST(TreeNodeTest, RemoveChild) {
    // Add children then remove them one by one
    TreeNode<int> parentNode;
    TreeNode<int> firstChild;
    TreeNode<int> secondChild;

    parentNode.addChild(&firstChild);
    parentNode.addChild(&secondChild);

    parentNode.removeChild(1);
    EXPECT_EQ(parentNode.getChildren().size(), 1);

    parentNode.removeChild(0);
    EXPECT_EQ(parentNode.getChildren().size(), 0);

    // Removing from empty list should not throw
    EXPECT_NO_THROW(parentNode.removeChild(0));
}

TEST(TreeNodeTest, SetParent) {
    // Test setting and verifying parent relationship
    TreeNode<int> parent;
    TreeNode<int> child;

    EXPECT_EQ(child.getParent(), nullptr);

    child.setParent(&parent);
    EXPECT_EQ(child.getParent(), &parent);
}

TEST(TreeNodeTest, ClearParent) {
    // Establish and then remove parent relationship
    TreeNode<int> parent;
    TreeNode<int> child;

    child.setParent(&parent);
    EXPECT_EQ(child.getParent(), &parent);

    child.removeParent();
    EXPECT_EQ(child.getParent(), nullptr);
}

TEST(TreeNodeTest, SetValueAndGetValue) {
    // Test value storage and retrieval
    TreeNode<int> node;

    node.setValue(42);
    EXPECT_EQ(node.getValue(), 42);
}

