#include <random>

int main() {
    // Initialize random number generation components
    std::random_device device;
    std::mt19937 engine{device()};

    // Define a Bernoulli distribution with 25% success probability
    std::bernoulli_distribution distribution{0.25};

    // Generate a single random boolean outcome
    bool result = distribution(engine);
}
// This program simulates a biased coin toss where the probability of 
// getting true (heads) is 25% and false (tails) is 75%.
//
// First, we create a non-deterministic random seed source using 
// [`std::random_device`](cpp/numeric/random/random_device), which 
// provides entropy from hardware or OS sources when available.
//
// Next, we initialize the Mersenne Twister pseudo-random generator 
// [`std::mt19937`](cpp/numeric/random/mersenne_twister_engine) with 
// this seed to ensure high-quality randomness.
//
// Then, we configure a [`std::bernoulli_distribution`](cpp/numeric/random/bernoulli_distribution) 
// with parameter p=0.25, modeling an event that occurs one-fourth of the time.
//
// Finally, applying the distribution to the engine yields a boolean 
// value: `true` with probability 0.25 and `false` otherwise.

#include <cstdio>
#include <cmath>
#include <string>
#include <sstream>

// Template function to convert string to numeric type
template <typename T> 
T parse_number(const std::string& input) {
    std::istringstream stream(input);
    T result;
    stream >> result;
    return result;
}

// Print double value with high precision and its bit representation
void display(double value) {
    printf("%.20f, %llX\n", value, *reinterpret_cast<unsigned long long*>(&value));
}

int main(int argc, char** argv) {
    // Parse the input argument as a double
    double divisor = parse_number<double>(argv[1]);

    // Perform various operations involving infinity and NaN
    display(sqrt(-1.0));           // NaN
    display(1.0 / divisor);        // ±Infinity depending on sign of divisor
    display(-1.0 / divisor);       // ∓Infinity
    display(0.0 / divisor);        // +0.0
    display(-0.0 / divisor);       // -0.0
    display((1.0 / divisor) / (-1.0 / divisor));  // -1.0 (since Infinity/(-Infinity) = -1)
    display((1.0 / divisor) + 3.0);               // ±Infinity
    display((-1.0 / divisor) + 3.0);              // ∓Infinity
    display(3.0 / (1.0 / divisor));               // divisor (if finite and non-zero)

    return 0;
}

