// Test that verifies mock time functionality and mode switching
TEST(TimeTest, MockTime) {
  // Initially, the clock should be in SYSTEM mode
  EXPECT_EQ(Clock::SYSTEM, Clock::mode());

  // Switch to MOCK mode
  Clock::SetMode(Clock::MOCK);
  EXPECT_EQ(Clock::MOCK, Clock::mode());

  // After setting to MOCK mode, Now() should return epoch (0 microseconds)
  EXPECT_EQ(0, absl::ToUnixMicros(Clock::Now()));

  // Set current time to 1 nanosecond after epoch
  Clock::SetNow(absl::FromUnixNanos(1));
  EXPECT_EQ(1, absl::ToUnixNanos(Clock::Now()));

  // Set time using seconds with fractional part
  Clock::SetNowInSeconds(123.456);
  EXPECT_DOUBLE_EQ(123.456, Clock::NowInSeconds());
}

