template<typename ElementType, typename IndexType>
struct StaticArray {
    ElementType* buffer = nullptr;
    IndexType size = 0;

    ~StaticArray() {
        delete[] buffer;
    }

    void AllocateFrom(BinaryReader& stream) {
        stream.ReadLE(size);
        delete[] buffer;
        if (size > 0) {
            buffer = new ElementType[size];
        }
    }

    void LoadFrom(BinaryReader& stream) {
        for (IndexType idx = 0; idx < size; ++idx) {
            buffer[idx].ReadFrom(stream);
        }
    }

    void AllocateAndLoad(BinaryReader& stream) {
        AllocateFrom(stream);
        LoadFrom(stream);
    }
};

struct StringView {
    uint32_t len = 0;
    const char* chars = nullptr;

    void ReadFrom(BinaryReader& stream) {
        assert(stream.ReadLE(len));
        assert(stream.ReadBytes(chars, len));
    }
};

using StringArray = StaticArray<StringView, uint32_t>;

void DumpTable(StringArray& table) {
    for (uint32_t i = 0; i < table.size; ++i) {
        printf("\"%.*s\"\n", table.buffer[i].len, table.buffer[i].chars);
    }
}

struct RecordHeader {
    uint32_t field0;
    uint32_t field1;
    uint32_t field2;
    uint32_t field3;
    uint32_t field4;
    uint32_t field5;
    uint32_t field6;
    uint32_t field7;

    void ReadFrom(BinaryReader& stream) {
        stream.ReadLE(field0);
        stream.ReadLE(field1);
        stream.ReadLE(field2);
        stream.ReadLE(field3);
        stream.ReadLE(field4);
        stream.ReadLE(field5);
        stream.ReadLE(field6);
        stream.ReadLE(field7);
    }
};

struct HeaderSection {
    StaticArray<RecordHeader, uint32_t> records;
    uint32_t zeroFlag;
    uint32_t worldEntityId;
    uint32_t primaryTableSize;

    void ReadFrom(BinaryReader& stream) {
        records.AllocateFrom(stream);
        stream.ReadLE(zeroFlag);
        assert(zeroFlag == 0);
        stream.ReadLE(worldEntityId);
        stream.ReadLE(primaryTableSize);
        records.LoadFrom(stream);
    }
};

void AbortParsing(BinaryReader& stream) {
    std::cout << stream.GetPosition() << "\n";
    assert(false);
}

struct MainSection {
    HeaderSection mainHeader;
    StringArray stringTableA;
    StringArray stringTableB;

    void ReadFrom(BinaryReader& stream) {
        mainHeader.ReadFrom(stream);
        stringTableA.AllocateAndLoad(stream);
        assert(stringTableA.size == mainHeader.primaryTableSize);

        while (true) {
            uint32_t bytecodeVal, extraA, extraB;
            if (!stream.ReadLE(bytecodeVal)) break;

            if (bytecodeVal == 0) {
                stream.ReadLE(extraA);
                stream.ReadLE(extraB);
                assert(extraA == 0 && extraB == 0);
            } else {
                AbortParsing(stream);
            }
        }
    }
};

void StaticsParser::Parse(BinaryReader& reader) {
    MainSection section;
    section.ReadFrom(reader);
}

#include <iostream>
