using namespace std;

class student {
private:
    int rollNumber;
    char fullName[30];
    float sub1, sub2, sub3;
    float average;

public:
    void getData();
    void displayResult();
    void computeAverage();
};

void student::getData() {
    cout << "Enter roll number, name, and three subject marks: ";
    cin >> rollNumber;
    cin.ignore(); // Clear newline from buffer
    cin.getline(fullName, 30);
    cin >> sub1 >> sub2 >> sub3;
}

void student::computeAverage() {
    float sum = sub1 + sub2 + sub3;
    average = sum / 3.0f;
}

void student::displayResult() {
    computeAverage();
    cout << "Student Details:" << endl;
    cout << "Roll Number: " << rollNumber << endl;
    cout << "Name: " << fullName << endl;
    cout << "Average Marks: " << average << endl;
}

int main() {
    student s;
    s.getData();
    s.displayResult();
    return 0;
}

