    SetCommand(cmdBlock->getCommand());
}

void IUIScene_CommandBlockMenu::ConfirmButtonClicked()
{
    // Prepare packet data using stack-allocated buffer
    std::vector<char> payloadBuffer;
    ByteArrayOutputStream baos(&payloadBuffer);
    DataOutputStream dos(&baos);

    // Write command block coordinates
    dos.writeInt(m_commandBlock->x);
    dos.writeInt(m_commandBlock->y);
    dos.writeInt(m_commandBlock->z);

    // Write current command string
    dos.writeUTF(GetCommand());

    // Send packet via local player connection
    auto& localPlayer = Minecraft::GetInstance()->localplayers[GetPad()];
    auto packet = std::make_shared<CustomPayloadPacket>(
        CustomPayloadPacket::SET_ADVENTURE_COMMAND_PACKET,
        baos.toByteArray()
    );
    localPlayer->connection->send(packet);
}

