    // Helper lambda to reduce repetition when registering data members with attributes
    auto register_data_with_attrs = [](auto& factory, auto setter, auto getter, const char* name, const char* pretty_name,
                                       std::initializer_list<entt::attribute> extra_attrs = {}) {
        factory.data<setter, getter>(name);
        std::vector<entt::attribute> attrs;
        attrs.emplace_back("name", name);
        attrs.emplace_back("pretty_name", pretty_name);
        for (const auto& attr : extra_attrs) {
            attrs.push_back(attr);
        }
        factory.custom(entt::attributes{attrs});
    };

