IoContext::IoThread::IoThread(app::AppServer& server, IoContext& iocontext)
  : Thread(server, "Io"), _ioctx(iocontext) {}

IoContext::IoThread::IoThread(const IoThread& other)
  : Thread(other._server, "Io"), _ioctx(other._ioctx) {}

IoContext::IoThread::~IoThread() { terminate(); }

void IoContext::IoThread::execute() {
  // run the asio io context
  try {
    _ioctx.io_context.run();
  } catch (const std::exception& ex) {
    SDB_WARN("xxxxx", Logger::THREADS,
             "caught exception in IO thread: ", ex.what());
  }
}

IoContext::IoContext(app::AppServer& server)
  : io_context(1),  // only a single thread per context
    _server(server),
    _worker(server, *this),
    _guard(io_context.get_executor()),
    _activeClients(0) {
  _worker.start();
}

IoContext::IoContext(const IoContext& other)
  : io_context(1),
    _server(other._server),
    _worker(other._server, *this),
    _guard(io_context.get_executor()),
    _activeClients(0) {
  _worker.start();
}

IoContext::~IoContext() { shutdown(); }

void IoContext::shutdown() {
  _guard.reset();
  io_context.stop();
  while (_worker.isRunning()) {
    std::this_thread::yield();
  }
}

