// Helper function to run a single generation test
void run_single_test(
    AutoModel& chat,
    const std::string& prompt,
    const std::vector<std::string>& image_paths,
    int max_tokens,
    bool print_header = true
) {
    if (print_header) {
        std::cout << "Prompt: " << prompt << std::endl;
        std::cout << "Response: ";
    } else {
        std::cout << "Response: ";
    }

    lm_uniform_input_t input;
    input.prompt = prompt;
    input.images = image_paths;

    chat.start_total_timer();
    std::string response = chat.generate_with_prompt({}, input, max_tokens, std::cout);
    chat.stop_total_timer();

    std::cout << std::endl << std::endl;
    std::cout << chat.show_profile() << std::endl;
}

int main(int argc, char* argv[]) {
#ifdef __WINDOWS__
    SetConsoleOutputCP(CP_UTF8);
    SetConsoleCP(CP_UTF8);
    SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_LOWEST);
#endif

    // Parse command-line arguments
    arg_utils::po::options_description desc("Allowed options");
    arg_utils::po::variables_map vm;
    desc.add_options()
        ("model,m", arg_utils::po::value<std::string>()->required(), "Model file")
        ("Short,s", arg_utils::po::value<bool>()->default_value(true), "Use short prompt mode")
        ("Preemption,p", arg_utils::po::value<bool>()->default_value(false), "Enable preemption");

    arg_utils::po::store(arg_utils::po::parse_command_line(argc, argv, desc), vm);
    arg_utils::po::notify(vm);

    std::string model_tag = vm["model"].as<std::string>();
    bool use_short_prompt = vm["Short"].as<bool>();
    bool enable_preemption = vm["Preemption"].as<bool>();

    std::cout << "Model: " << model_tag << std::endl;

    std::string exe_dir = utils::get_executable_directory();
    std::string models_base_dir = utils::get_models_directory();
    std::string config_path = exe_dir + "/model_list.json";

    model_list model_db(config_path, models_base_dir);

    header_print("info", "Initializing chat model...");
    std::string model_file_path = model_db.get_model_path(model_tag);
    auto [_, model_json] = model_db.get_model_info(model_tag);

    std::cout << "Model path: " << model_file_path << std::endl;

    npu_device_global = xrt::device(0);
    std::unique_ptr<AutoModel> model_instance = std::make_unique<Qwen2VL>(&npu_device_global);

    model_instance->load_model(model_file_path, model_json, -1, enable_preemption);
    model_instance->set_topk(1);
    model_instance->set_topp(0.8f);
    model_instance->set_temperature(0.7f);
    model_instance->set_repetition_penalty(1.01f);
    model_instance->set_frequency_penalty(1.01f);

    lm_uniform_input_t uniformed_input;
    std::vector<std::string> sample_images = {"../../../tb_files/panda.png"};

    if (use_short_prompt) {
        uniformed_input.prompt = "What is this?";
        // Run three identical short tests
        for (int i = 0; i < 3; ++i) {
            run_single_test(*model_instance, uniformed_input.prompt, sample_images, 1024, i == 0);
        }
    } else {
        std::ifstream prompt_file("../../../../prompt.txt", std::ios::binary);
        if (!prompt_file.is_open()) {
            std::cerr << "Failed to open prompt file" << std::endl;
            return 1;
        }

        prompt_file.seekg(0, std::ios::end);
        size_t file_size = prompt_file.tellg();
        prompt_file.seekg(0, std::ios::beg);

        uniformed_input.prompt.resize(file_size);
        prompt_file.read(uniformed_input.prompt.data(), file_size);
        prompt_file.close();

        std::cout << "Prompt: " << uniformed_input.prompt << std::endl;
        run_single_test(*model_instance, uniformed_input.prompt, {}, 1024, false);
    }

    // Output history info
    auto [_, history_ids] = model_instance->get_history();
    std::cout << "History length: " << history_ids.size() << std::endl << std::endl;

    return 0;
}

