void ProcessProgram(LPBYTE dataPtr, LPBYTE endPtr, int type, ostream* outputStream) {
    LPBYTE startPtr = dataPtr;
    dataPtr += sizeof(UINT);
    dataPtr += sizeof(UINT);
    GetBytes(dataPtr, true);
    GetBytes(dataPtr, true);
    GetBytes(dataPtr, true);
    USHORT len = GetData<USHORT>(dataPtr);
    for (size_t i = 0; i < len; ++i)
        GetString(dataPtr, true);
    int flag = GetData<int>(dataPtr);
    dataPtr += sizeof(UINT);
    if ((flag & 1) != 0) dataPtr += 16;
    GetBytes(dataPtr, true);
    GetBytes(dataPtr, true);
    outputStream->write(C(startPtr), dataPtr - startPtr);

    vector<ESection_Program_Assembly> assemblies = GetAssemblies(dataPtr);
    vector<ESection_Program_Method> methods = GetMethods(dataPtr);

    if (type == 0) {
        vector<string*> remarkList;
        for (ESection_Program_Assembly& item : assemblies) {
            if ((item.Status & ETagStatus::C_External) == 0 && item.Remark.empty()) {
                remarkList.push_back(&item.Remark);
            }
        }
        for (ESection_Program_Method& item : methods) {
            if ((item.Attributes & EMethodAttr::M_External) == 0 && item.Remark.empty()) {
                size_t idx = GenerateRandom<size_t>(0, remarkList.size());
                remarkList.insert(remarkList.begin() + idx, &item.Remark);
            }
        }
        if (!remarkList.empty()) {
            for (int i = min(cc, (int)remarkList.size()); i > 0; --i) {
                size_t idx = GenerateRandom<size_t>(0, i - 1);
                remarkList[idx]->append(Join(GetRandomCopyright[redacted]
                remarkList.erase(remarkList.begin() + idx);
            }
        }
    } else if (type == 1) {
        vector<ESection_Program_Method*> methodList;
        for (ESection_Program_Method& item : methods) {
            if ((item.Attributes & EMethodAttr::M_External) == 0) {
                methodList.push_back(&item);
            }
        }
        for (int i = min(cc, (int)methodList.size()); i > 0; --i) {
            size_t idx = GenerateRandom<size_t>(0, i - 1);
            string remark;
            vector<UINT> rowOffsets;

            for (string& line : GetRandomCopyright[redacted]
                rowOffsets.push_back(remark.length());
                remark.append("\x6a\x00\x00\x00\x00\xff\xff\x00\x00\x00\x00\x00\x00", 13);
                UINT length = line.length() + 1;
                remark.append(C(&length), 4);
                remark.append(line.c_str(), length);
                remark.append("\x36\x01", 2);
            }

            ESection_Program_Method* methodItem = methodList[idx];
            UINT totalLen = remark.length();
            LPBYTE rowOffsetPtr = methodItem->RowOffset.begin()._Ptr;
            size_t rowCount = methodItem->RowOffset.size() / sizeof(UINT);
            for (size_t j = 0; j < rowCount; ++j, rowOffsetPtr += sizeof(UINT)) {
                *(LPUINT)rowOffsetPtr += totalLen;
            }

            vector<BYTE> newRow(rowOffsets.begin(), rowOffsets.end());
            methodItem->RowOffset.insert(methodItem->RowOffset.begin(), newRow.begin(), newRow.end());

            LPBYTE flowOffsetPtr = methodItem->FlowOffset.begin()._Ptr;
            size_t flowCount = methodItem->FlowOffset.size() / (sizeof(BYTE) + sizeof(UINT) + sizeof(UINT));
            for (size_t j = 0; j < flowCount; ++j, flowOffsetPtr += sizeof(BYTE) + sizeof(UINT) + sizeof(UINT)) {
                *(LPUINT)(flowOffsetPtr + sizeof(BYTE)) += totalLen;
                *(LPUINT)(flowOffsetPtr + sizeof(BYTE) + sizeof(UINT)) += totalLen;
            }

            LPBYTE methodOffsetPtr = methodItem->MethodOffset.begin()._Ptr;
            size_t methodCount = methodItem->MethodOffset.size() / sizeof(UINT);
            for (size_t j = 0; j < methodCount; ++j, methodOffsetPtr += sizeof(UINT)) {
                *(LPUINT)methodOffsetPtr += totalLen;
            }

            LPBYTE varOffsetPtr = methodItem->VariableOffset.begin()._Ptr;
            size_t varCount = methodItem->VariableOffset.size() / sizeof(UINT);
            for (size_t j = 0; j < varCount; ++j, varOffsetPtr += sizeof(UINT)) {
                *(LPUINT)varOffsetPtr += totalLen;
            }

            methodList[idx]->Code.insert(methodList[idx]->Code.begin(), remark.begin(), remark.end());
            methodList.erase(methodList.begin() + idx);
        }
    }

    WriteVectorAssembly(outputStream, assemblies);
    WriteVectorMethod(outputStream, methods);
    outputStream->write(C(dataPtr), endPtr - dataPtr);
}

void ParseDataBlock(LPBYTE buffer, size_t bufferSize, int mode, ostream* outStream) {
    EFile_Header header;
    memcpy(&header, buffer, sizeof(EFile_Header));
    if (arrcmp(header.Magic1, Magic1, 4) && arrcmp(header.Magic2, Magic2, 4)) {
        outStream->write(C(&header), sizeof(EFile_Header));
        long long offset = sizeof(EFile_Header);
        while (offset < bufferSize) {
            ESection_Header sh = GetData<ESection_Header>(buffer, offset);
            if (!arrcmp(sh.Magic, Magic_Section, 4))
                goto finish;

            ESection_Info si = GetData<ESection_Info>(buffer, offset);
            if (!arrcmp(si.Key, KEY, 4))
                Decode_Str(si.Name, si.Key);

            LPSZ Block_Name = (LPSZ)si.Name;
            if (strcmp(Block_Name, "") == 0) {
                outStream->write(C(buffer + offset - sizeof(ESection_Header) - sizeof(ESection_Info)), 
                                sizeof(ESection_Header) + sizeof(ESection_Info) + si.DataLength);
                break;
            } else if (mode == 2 && strcmp(Block_Name, "(u7bOo`k") == 0) {
                ostringstream stream;
                ProcessUserInfo(buffer + offset, buffer + offset + si.DataLength, &stream);
                UINT oldLen = si.DataLength;
                if (!arrcmp(si.Key, KEY, 4)) Decode_Str(si.Name, si.Key);
                si.DataLength = stream.tellp();
                si.Data_CheckSum = GetCheckValue(D(stream.str()), stream.tellp());
                sh.Info_CheckSum = GetCheckValue(D(&si), sizeof(ESection_Info));

                outStream->write(C(&sh), sizeof(ESection_Header));
                outStream->write(C(&si), sizeof(ESection_Info));
                outStream->write(stream.str().c_str(), stream.tellp());
                si.DataLength = oldLen;
            } else if ((mode == 0 || mode == 1) && strcmp(Block_Name, "z^k") == 0) {
                ostringstream stream;
                ProcessProgram(buffer + offset, buffer + offset + si.DataLength, mode, &stream);
                UINT oldLen = si.DataLength;
                if (!arrcmp(si.Key, KEY, 4)) Decode_Str(si.Name, si.Key);
                si.DataLength = stream.tellp();
                si.Data_CheckSum = GetCheckValue(D(stream.str()), stream.tellp());
                sh.Info_CheckSum = GetCheckValue(D(&si), sizeof(ESection_Info));

                outStream->write(C(&sh), sizeof(ESection_Header));
                outStream->write(C(&si), sizeof(ESection_Info));
                outStream->write(stream.str().c_str(), stream.tellp());
                si.DataLength = oldLen;
            } else {
                outStream->write(C(buffer + offset - sizeof(ESection_Header) - sizeof(ESection_Info)), 
                                sizeof(ESection_Header) + sizeof(ESection_Info) + si.DataLength);
            }
            offset += si.DataLength;
        }
    }
finish:
    ;
}

