#include <iostream>

// Abstract interface for printable objects
class Printable {
public:
    virtual void getName() = 0;
};

// First concrete implementation
class Base : public Printable {
public:
    void getName() override {
        std::cout << "base\n";
    }
};

// Second level of inheritance
class Derived : public Base {
public:
    void getName() override {
        std::cout << "derived\n";
    }
};

// Third level of inheritance
class Derived2 : public Derived {
public:
    void getName() override {
        std::cout << "derived2\n";
    }
};

// Function that accepts any Printable object via pointer
void display(Printable* obj) {
    obj->getName();
}

int main() {
    // Create and use Base instance
    Base* baseObj = new Base();
    display(baseObj);
    delete baseObj;

    // Create and use Derived instance
    Derived* derivedObj = new Derived();
    display(derivedObj);
    delete derivedObj;

    // Create and use Derived2 instance
    Derived2* derived2Obj = new Derived2();
    display(derived2Obj);
    delete derived2Obj;

    return 0;
}

