// Asynchronous timer that waits 5 seconds before printing a message
int main()
{
  asio::io_context context;

  // Create a steady timer set to trigger after 5 seconds
  asio::steady_timer timer(context, asio::chrono::seconds(5));

  // Define the callback function inline using a lambda
  timer.async_wait([](const asio::error_code& /*ec*/)
  {
    std::cout << "Hello, world!" << std::endl;
  });

  // Run the I/O context until all operations complete
  context.run();

  return 0;
}

