RayTracerWindow::RayTracerWindow(GLuint width, GLuint height)
	: m_pCameraRaysImage{ nullptr }
{
}

RayTracerWindow::~RayTracerWindow()
{
}

void RayTracerWindow::init(SurfaceRenderer& renderer)
{
	tc::ivec2 size{ renderer.getWidth(), renderer.getHeight() };
	tc::gpu::GPUBackend gpuDevice;

	m_pCameraRaysImage = new tc::BufferResource<tc::cpu::RGBA8, tc::Dim::D2>{ size };
	gpuDevice.uploadImage<tc::InternalFormat::RGBA32F>(*m_pCameraRaysImage);

	m_RayTracerKernel.outData.connect(m_pCameraRaysImage);
	m_VisualizeRaysKernel.inData.connect(m_pCameraRaysImage);
	m_VisualizeRaysKernel.outData.connect(renderer.getRenderBuffer());
}

void RayTracerWindow::compute(SurfaceRenderer& renderer)
{
	tc::gpu::GPUBackend gpuDevice;
	// tc::CPUBackend gpuDevice;

	tc::ivec2 resolution{ renderer.getWidth(), renderer.getHeight() };

	gpuDevice.activateKernel(m_RayTracerKernel);
	gpuDevice.bindStorageImage(m_RayTracerKernel.outData);
	gpuDevice.bindConstant(m_RayTracerKernel.fieldOfView);
	gpuDevice.launch(m_RayTracerKernel, tc::uvec3{ resolution.x, resolution.y, 1 });

	gpuDevice.activateKernel(m_VisualizeRaysKernel);
	gpuDevice.bindStorageImage(m_VisualizeRaysKernel.inData);
	gpuDevice.bindStorageImage(m_VisualizeRaysKernel.outData);
	gpuDevice.launch(m_VisualizeRaysKernel, tc::uvec3{ resolution.x, resolution.y, 1 });
}

