#include <cassert>
#include <fstream>
#include <sstream>
#include <vector>
#include "fuzzer_common.h"

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* Data, size_t Size);

int main(int argc, char* argv[]) {
    // Process each input file provided as command-line argument
    for (int idx = 1; idx < argc; ++idx) {
        std::ifstream file_stream(argv[idx]);
        assert(file_stream.is_open());

        // Seek to end to determine file size
        file_stream.seekg(0, std::ios::end);
        auto file_size = file_stream.tellg();
        assert(file_size >= 0);

        // Reset to beginning of file
        file_stream.seekg(0, std::ios::beg);

        // Read entire file into buffer
        std::vector<char> buffer(static_cast<size_t>(file_size));
        file_stream.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
        assert(file_stream.gcount() == file_size);

        // Call fuzzer with the file contents
        LLVMFuzzerTestOneInput(fmt_fuzzer::as_bytes(buffer.data()), buffer.size());
    }

    return 0;
}

#include <library/cpp/iterator/iterate_keys.h>
#include <library/cpp/testing/gtest/gtest.h>
#include <map>
using namespace testing;

TEST(IterateKeys, ConstMappingIteration) {
    const std::map<int, int> squares{
        {1, 1},
        {2, 4},
        {3, 9},
    };

    auto keys = IterateKeys(squares);
    std::vector<int> expected_keys{1, 2, 3};
    EXPECT_EQ(keys.size(), expected_keys.size());
    for (size_t i = 0; i < expected_keys.size(); ++i) {
        EXPECT_EQ(keys[i], expected_keys[i]);
    }
}

TEST(IterateKeys, ConstMultiMappingIteration) {
    const std::multimap<int, int> primesBelow{
        {2, 2},
        {5, 3},
        {5, 5},
        {11, 7},
        {11, 11},
        {23, 13},
        {23, 17},
        {23, 23},
    };

    auto keys = IterateKeys(primesBelow);
    std::vector<int> expected_keys{2, 5, 5, 11, 11, 23, 23, 23};
    EXPECT_EQ(keys.size(), expected_keys.size());
    for (size_t i = 0; i < expected_keys.size(); ++i) {
        EXPECT_EQ(keys[i], expected_keys[i]);
    }
}

