void ModelRenderSystem::render(Scene* scene, RenderContext& context) {
    // Iterate over all entities with ModelRendererComponent and TransformComponent
    scene->view<ModelRendererComponent, TransformComponent>([&](RID entity_id, auto& model_renderer, auto& transform) {
        // Skip entities without a valid model handle
        if (!model_renderer.ModelHandle.has_value()) {
            return;
        }

        // Submit the model for rendering using the computed model matrix
        context.submit_model(model_renderer.ModelHandle.value(), transform.get_model_matrix());
    });
}

