#include <ros/init.h>
#include <ros/package.h>
#include <ocs2_sqp/SqpMpc.h>
// #include <ocs2_ddp/GaussNewtonDDP_MPC.h>
#include <ocs2_ros_interfaces/mpc/MPC_ROS_Interface.h>
#include <ocs2_ros_interfaces/synchronized_module/RosReferenceManager.h>
#include <humanoid_wheel_interface/HumanoidWheelInterface.h>

using namespace ocs2;
using namespace mobile_manipulator;

int main(int argc, char** argv) {
  const std::string robotName = "mobile_manipulator";

  // Initialize ROS node
  ros::init(argc, argv, robotName + "_mpc");
  ros::NodeHandle nodeHandle;

  // Retrieve configuration parameters from the parameter server
  std::string taskFile, libFolder, urdfFile;
  nodeHandle.getParam("/taskFile", taskFile);
  nodeHandle.getParam("/libFolder", libFolder);
  nodeHandle.getParam("/urdfFile", urdfFile);

  // Log loading information to standard error stream
  std::cerr << "Task file path: " << taskFile << std::endl;
  std::cerr << "Library directory: " << libFolder << std::endl;
  std::cerr << "URDF model location: " << urdfFile << std::endl;

  // Construct the robot interface using loaded configuration
  HumanoidWheelInterface robotInterface(taskFile, libFolder, urdfFile);

  // Set up ROS-based reference manager
  auto rosRefManagerPtr = std::make_shared<RosReferenceManager>(
      robotName, robotInterface.getReferenceManagerPtr());
  rosRefManagerPtr->subscribe(nodeHandle);

  // Configure and initialize the SQP-MPC solver
  SqpMpc mpcSolver(
      robotInterface.mpcSettings(),
      robotInterface.sqpSettings(),
      robotInterface.getOptimalControlProblem(),
      robotInterface.getInitializer()
  );
  mpcSolver.getSolverPtr()->setReferenceManager(rosRefManagerPtr);

  // Launch ROS interfaces for MPC
  MPC_ROS_Interface mpcRosNode(mpcSolver, robotName);
  mpcRosNode.launchNodes(nodeHandle);

  return 0;
}

