// Helper function to generate unreachable error messages for unsupported symbol types
static std::string makeUnreachableMsg(const char* typeName) {
    return std::string("Attempt to dump ") + typeName + " with no dump implementation";
}

PDBSymDumper::PDBSymDumper(bool ShouldRequireImpl)
    : RequireImpl(ShouldRequireImpl) {}

PDBSymDumper::~PDBSymDumper() = default;

// Template-based approach to reduce code duplication
template<typename T>
static void dumpSymbol(const T& Symbol, bool requireImpl) {
    if (requireImpl) {
        const char* name = typeid(T).name();
        // Simplified type name extraction for common cases
        llvm_unreachable(makeUnreachableMsg(getTypeName<T>()).c_str());
    }
}

