using ::testing::_;
using ::testing::DoAll;
using ::testing::Return;
using ::testing::SetArgPointee;

namespace torch::comms::test {

void RcclMock::setupDefaultBehaviors() {
  // Helper lambda to initialize a unique ID with pattern byte 0x42
  auto initUniqueId = [](ncclUniqueId* idPtr) -> ncclStatus_t {
    std::memset(idPtr, 0x42, sizeof(ncclUniqueId));
    return ncclSuccess;
  };

  // Default communicator setup
  ON_CALL(*this, getUniqueId(_)).WillByDefault(initUniqueId);

  // Initialize rank configuration mock: assign dummy communicator pointer and succeed
  ON_CALL(*this, commInitRankConfig(_, _, _, _, _))
      .WillByDefault(DoAll(
          SetArgPointee<0>(reinterpret_cast<ncclComm_t>(0x3000)),
          Return(ncclSuccess)));

  // Cleanup operations always succeed
  ON_CALL(*this, commDestroy(_)).WillByDefault(Return(ncclSuccess));
  ON_CALL(*this, commAbort(_)).WillByDefault(Return(ncclSuccess));

  // Split communicator: assign new communicator at fixed address
  ON_CALL(*this, commSplit(_, _, _, _, _))
      .WillByDefault(DoAll(
          SetArgPointee<3>(reinterpret_cast<ncclComm_t>(0x4000)),
          Return(ncclSuccess)));

  // Query rank and size: default to 2 ranks, current rank 0
  ON_CALL(*this, commCount(_, _))
      .WillByDefault(DoAll(SetArgPointee<1>(2), Return(ncclSuccess)));
  ON_CALL(*this, commUserRank(_, _))
      .WillByDefault(DoAll(SetArgPointee<1>(0), Return(ncclSuccess)));

  // Async error status defaults to success
  ON_CALL(*this, commGetAsyncError(_, _))
      .WillByDefault(DoAll(SetArgPointee<1>(ncclSuccess), Return(ncclSuccess)));

  // Memory registration: return fixed virtual address on register
  ON_CALL(*this, commRegister(_, _, _, _))
      .WillByDefault(DoAll(
          SetArgPointee<3>(reinterpret_cast<void*>(0x5000)),
          Return(ncclSuccess)));
  ON_CALL(*this, commDeregister(_, _)).WillByDefault(Return(ncclSuccess));

  // All collective ops: no-op by default
  ON_CALL(*this, allReduce(_, _, _, _, _, _, _)).WillByDefault(Return(ncclSuccess));
  ON_CALL(*this, broadcast(_, _, _, _, _, _, _)).WillByDefault(Return(ncclSuccess));
  ON_CALL(*this, reduce(_, _, _, _, _, _, _, _)).WillByDefault(Return(ncclSuccess));
  ON_CALL(*this, allGather(_, _, _, _, _, _)).WillByDefault(Return(ncclSuccess));
  ON_CALL(*this, reduceScatter(_, _, _, _, _, _, _)).WillByDefault(Return(ncclSuccess));

  // Point-to-point operations: succeed silently
  ON_CALL(*this, send(_, _, _, _, _, _)).WillByDefault(Return(ncclSuccess));
  ON_CALL(*this, recv(_, _, _, _, _, _)).WillByDefault(Return(ncclSuccess));

  // Grouping operations: no-op wrappers
  ON_CALL(*this, groupStart()).WillByDefault(Return(ncclSuccess));
  ON_CALL(*this, groupEnd()).WillByDefault(Return(ncclSuccess));

  // Error string helper: always returns static message
  ON_CALL(*this, getErrorString(_)).WillByDefault(Return("Success"));
}

} // namespace torch::comms::test

