    ThePlatformMgr.RemoveSink(this, conn_status_change);
    UIPanel::Exit();
}

void ConnectionStatusPanel::Enter() {
    UIPanel::Enter();
    static Symbol conn_status_change("connection_status_changed");
    ThePlatformMgr.AddSink(this, conn_status_change);
    VerifyConnectionState();
}

