    if (!ThePlatformMgr.IsConnected()) {
        static Message lost_conn_msg("on_connection_lost");
        Dispatch(lost_conn_msg, true);
    }
}

DataNode ConnectionStatusPanel::OnMsg(const ConnectionStatusChangedMsg &msg) {
    VerifyConnectionState();
    return 0;
}

