namespace school
{
std::tuple<std::string, std::string, std::string> generateRandomName();

class ClassroomImplementation : public ClassroomBase
{
  SEN_NOCOPY_NOMOVE(ClassroomImplementation)
public:
  using ClassroomBase::ClassroomBase;

  ~ClassroomImplementation() override
  {
    if (communicationBus_)
    {
      communicationBus_->remove(studentList_);
      communicationBus_->remove(instructor_);
      studentList_.clear();
      instructor_.reset();
      communicationBus_.reset();
    }
  }

public:
  void registered(sen::kernel::RegistrationApi& api) override
  {
    // Initialize random seed
    srand(static_cast<unsigned>(time(nullptr)));

    // Establish communication channel
    communicationBus_ = api.getSource(getStudentsBus());

    // Discover all students (including remote ones)
    allStudents_ = api.selectAllFrom<StudentInterface>(getStudentsBus());

    // Create teacher if configured
    if (getCreateTeacher())
    {
      auto [givenName, familyName, completeName] = generateRandomName();
      instructor_ = std::make_shared<TeacherImplementation>(completeName, givenName, familyName, allStudents_);
      setNextTeacherName(completeName);

      // Register teacher on the bus
      communicationBus_->add(instructor_);
    }

    // Set up event listeners for student actions
    std::ignore = allStudents_->list.onAdded(
      [&](const auto& iterators)
      {
        for (auto itr = iterators.typedBegin; itr != iterators.typedEnd; ++itr)
        {
          // When a student makes noise, randomly select another student to hear it
          auto callback = [&](const std::string& sound, float32_t loudness)
          {
            studentList_.at(rand() % studentList_.size())->hearSomeNoise(sound, loudness);  // NOLINT
          };
          (*itr)->onMadeSomeNoise({this, std::move(callback)}).keep();
        }
      });

    // Add default number of students if specified
    if (getDefaultSize() != 0U)
    {
      addStudents(getDefaultSize());
    }
  }

protected:
  void addStudentsImpl(uint32_t count) override
  {
    // Prepare storage for new students
    std::vector<std::shared_ptr<StudentImplementation>> incomingStudents;
    incomingStudents.reserve(count);

    // Generate new student instances
    for (uint32_t idx = 0U; idx < count; ++idx)
    {
      auto [firstName, lastName, fullName] = generateRandomName();
      incomingStudents.emplace_back(std::make_shared<StudentImplementation>(fullName, lastName, firstName));
    }

    // Publish new students to the bus
    communicationBus_->add(incomingStudents);

    // Update local student list
    studentList_.insert(studentList_.end(), incomingStudents.begin(), incomingStudents.end());
  }

  void removeStudentsImpl(uint32_t count) override
  {
    // Collect students to be removed
    std::vector<std::shared_ptr<StudentImplementation>> outgoingStudents;
    outgoingStudents.reserve(count);

    for (std::size_t i = 0; i < count && !studentList_.empty(); ++i)
    {
      outgoingStudents.push_back(studentList_.back());
      studentList_.pop_back();
    }

    // Remove from bus
    communicationBus_->remove(outgoingStudents);
  }

private:
  std::shared_ptr<sen::ObjectSource> communicationBus_;
  std::shared_ptr<TeacherImplementation> instructor_;
  std::vector<std::shared_ptr<StudentImplementation>> studentList_;
  std::shared_ptr<sen::Subscription<StudentInterface>> allStudents_;
};

