#include <iostream>

int main() {
    char inputChar;
    std::cout << "enter any character";
    std::cin >> inputChar;

    bool isAlphabet = false;
    if ((inputChar >= 'A' && inputChar <= 'Z') || 
        (inputChar >= 'a' && inputChar <= 'z')) {
        isAlphabet = true;
    }

    if (isAlphabet) {
        std::cout << "this is an alphabet";
    } else {
        std::cout << "this is not alphabet";
    }

    return 0;
}

