    ::benchmark::MaybeReenterWithoutASLR(argc, argv);

    // Initialize Yt environment
    InitializeYt(argc, argv);

    // Execute pre-initialization hook
    NTesting::THook::CallBeforeInit();

    // Initialize benchmark framework
    ::benchmark::Initialize(&argc, argv);

    // Handle unrecognized arguments
    if (::benchmark::ReportUnrecognizedArguments(argc, argv)) {
        return 1;
    }

    // Execute pre-run hook
    NTesting::THook::CallBeforeRun();

    // Ensure post-run hook is called at scope exit
    Y_DEFER { 
        NTesting::THook::CallAfterRun(); 
    };

    // Run the benchmarks
    ::benchmark::RunSpecifiedBenchmarks();

    // Clean up benchmark resources
    ::benchmark::Shutdown();

    return 0;
}

