/**
 * Public interface implementation for the external image picker module
 */
class FExternalImagePickerModule : public IExternalImagePickerModule
{
public:
	// Build and return the editor widget using the provided configuration
	virtual TSharedRef<SWidget> MakeEditorWidget(const FExternalImagePickerConfiguration& InConfig) override
	{
		return SNew(SExternalImagePicker)
			.TargetImagePath(InConfig.TargetImagePath)
			.DefaultImagePath(InConfig.DefaultImagePath)
			.OnExternalImagePicked(InConfig.OnExternalImagePicked)
			.OnGetPickerPath(InConfig.OnGetPickerPath)
			.MaxDisplayedImageDimensions(InConfig.MaxDisplayedImageDimensions)
			.RequiresSpecificSize(InConfig.bRequiresSpecificSize)
			.RequiredImageDimensions(InConfig.RequiredImageDimensions)
			.Extensions(InConfig.FileExtensions);
	}
};

