#include "length.h"
#include <library/cpp/testing/unittest/registar.h>
#include <util/generic/string.h>

Y_UNIT_TEST_SUITE(TestLengthIO) {
    Y_UNIT_TEST(TestLengthLimitedInput) {
        char buffer[16];
        TStringStream source("abcd");
        TLengthLimitedInput limited(&source, 2);
        UNIT_ASSERT_VALUES_EQUAL(limited.Load(buffer, 3), 2);
        UNIT_ASSERT_VALUES_EQUAL(limited.Read(buffer, 1), 0);
    }

    Y_UNIT_TEST(TestCountingInput) {
        char tempBuffer[16];
        TStringStream input("abc\ndef\n");
        TCountingInput counter(&input);
        TString line;

        counter.ReadLine(line);
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 4);

        counter.Load(tempBuffer, 1);
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 5);

        counter.Skip(1);
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 6);

        counter.ReadLine(line);
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 8);
    }

    Y_UNIT_TEST(TestCountingOutput) {
        TStringStream output;
        TCountingOutput counter(&output);

        counter.Write('1');
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 1);

        counter.Write(TString("abcd"));
        UNIT_ASSERT_VALUES_EQUAL(counter.Counter(), 5);

        TString buffer("aaa");
        IOutputStream::TPart segments[] = {
            {buffer.data(), buffer.size()}, 
            {buffer.data(), buffer.size()}, 
            {buffer.data(), buffer.size()}
        };
