class Solution {
public:
    void rotate(vector<vector<int>>& matrix) {
        int n = matrix.size();

        // Create a temporary copy of the matrix
        vector<vector<int>> temp = matrix;

        // Place each element from the original matrix to its rotated position
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Element at (i, j) goes to position (j, n-1-i)
                matrix[j][n - 1 - i] = temp[i][j];
            }
        }
    }
};

