// Determine if a character is a vowel or consonant
int main() {
    char inputChar;
    std::cout << "enter any character";
    inputChar = std::cin.get();

    // Check if the character is an alphabet letter (uppercase or lowercase)
    bool isLetter = ((inputChar >= 'A' && inputChar <= 'Z') || (inputChar >= 'a' && inputChar <= 'z'));

    if (isLetter) {
        // Convert to lowercase for easier comparison
        char lowerChar = (inputChar >= 'A' && inputChar <= 'Z') ? inputChar + 32 : inputChar;

        // Check if it's a vowel
        bool isVowel = (lowerChar == 'a' || lowerChar == 'e' || lowerChar == 'i' || 
                        lowerChar == 'o' || lowerChar == 'u');

        if (isVowel) {
            std::cout << "it is vowel" << std::endl;
        } else {
            std::cout << "it is a consonent" << std::endl;
        }
    } else {
        std::cout << "itis not an alphabet" << std::endl;
    }

    return 0;
}

