int main(int argc, char **argv) {
  ros::init(argc, argv, "tofsense_parser");
  ros::NodeHandle nh;
  serial::Serial serial_port;
  initSerial(&serial_port);
  NProtocolExtracter protocol_extractor;
  tofsense::Init initializer(&protocol_extractor, &serial_port);

  ros::Rate update_rate(1000);

  while (ros::ok()) {
    size_t bytes_available = serial_port.available();
    std::string buffer;

    if (bytes_available > 0) {
      serial_port.read(buffer, bytes_available);
      protocol_extractor.AddNewData(buffer);
