namespace yaml {

// Helper function to conditionally map optional fields
template<typename T>
void mapOptionalField(IO &IO, const char *FieldName, T &FieldValue, const T &DefaultValue) {
  if (!IO.outputting() || FieldValue != DefaultValue) {
    IO.mapOptional(FieldName, FieldValue, DefaultValue);
  }
}

void MappingTraits<GOFFYAML::FileHeader>::mapping(
    IO &IO, GOFFYAML::FileHeader &FileHdr) {

  // Map optional fields with their defaults
  mapOptionalField(IO, "TargetEnvironment", FileHdr.TargetEnvironment, 0);
  mapOptionalField(IO, "TargetOperatingSystem", FileHdr.TargetOperatingSystem, 0);
  mapOptionalField(IO, "CCSID", FileHdr.CCSID, 0);
  mapOptionalField(IO, "CharacterSetName", FileHdr.CharacterSetName, std::string(""));
  mapOptionalField(IO, "LanguageProductIdentifier", FileHdr.LanguageProductIdentifier, std::string(""));
  mapOptionalField(IO, "ArchitectureLevel", FileHdr.ArchitectureLevel, 1);

  // Map required fields that don't have defaults
  IO.mapOptional("InternalCCSID", FileHdr.InternalCCSID);
  IO.mapOptional("TargetSoftwareEnvironment", FileHdr.TargetSoftwareEnvironment);
}

void MappingTraits<GOFFYAML::Object>::mapping(IO &IO, GOFFYAML::Object &Obj) {
  // Set the YAML tag for this object type
  IO.mapTag("!GOFF", /*Required=*/true);

  // Map the file header section
  IO.mapRequired("FileHeader", Obj.Header);
}

