extern std::size_t total_memory;
extern "C" void main() {
    // Initialize C++ constructors (global objects)
    utils::cxx::init_constructors();

    // Initialize bootloader-provided info
    bootloader::init();

    // Initialize terminal subsystem (basic then full)
    utils::flanterm::init();
    utils::flanterm::fullinit();

    // Initialize physical memory manager and heap
    pmm::init();
    kheap::init();

    // Report memory status
    klibc::printf("PMM: Total usable memory: %zu bytes\r\n", total_memory);
    klibc::printf("Paging: Enabled kernel root with %d level paging\r\n", arch::level_paging());
    klibc::printf("KHeap: Available memory %zu bytes\r\n", KHEAP_SIZE);

    // Initialize ACPI tables and architecture-specific features
    acpi::init_tables();
    arch::init(ARCH_INIT_EARLY);
    acpi::full_init();
    arch::init(ARCH_INIT_COMMON);

    // Mark that we've left early boot stage
    extern int boot_stage;
    boot_stage = 0;

    // Time-based diagnostics before triggering page fault
    const std::uint64_t current_time_sec = time::timer->current_nano() / (1000ULL * 1000ULL * 1000ULL);
    klibc::printf("Boot sequence complete\r\n");
    klibc::printf("Current time: %llu seconds, waiting 2 sec then page faulting\r\n", current_time_sec);
    klibc::printf("Current time: %llu seconds\r\n", current_time_sec);

    // Flush TLB entry at specific address
    arch::tlb_flush(0x47AFE000, PAGE_SIZE);

    // Trigger intentional page fault by writing to unmapped address (volatile for side-effect preservation)
    volatile int* fault_addr = reinterpret_cast<volatile int*>(0x47AFE710);
    *fault_addr = 0;

    // Halt CPU on fatal error (halt-and-catch-fire)
    arch::hcf();
}

class Solution {
public:
    uint32_t reverseBits(uint32_t n) {
        uint32_t result = 0;
        int position = 0;
        while (position < 32) {
            result <<= 1;
            if (n & 1) {
                result |= 1;
            }
            n >>= 1;
            position++;
        }
        return result;
    }
};

