TEST_F(RocksDBFormatTest, little_endian_conversion) {
  // Test uint64_t encoding and decoding in little-endian format
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 1);
  ASSERT_EQ(_buffer.length(), 8U);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()), 1U);

  _buffer.clear();
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 1337);
  ASSERT_EQ(_buffer.length(), 8U);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()), 1337U);

  _buffer.clear();
  rocksutils::UintToPersistentLittleEndian<uint64_t>(_buffer, 1212321);
  ASSERT_EQ(_buffer.length(), 8U);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint64_t>(_buffer.data()), 1212321U);

  _buffer.clear();
  rocksutils::UintToPersistentLittleEndian<uint32_t>(_buffer, 88888);
  ASSERT_EQ(_buffer.length(), 4U);
  ASSERT_EQ(rocksutils::UintFromPersistentLittleEndian<uint32_t>(_buffer.data()), 88888U);
}

TEST_F(RocksDBFormatTest, big_endian_conversion) {
  // Test uint64_t encoding and decoding in big-endian format
  rocksutils::UintToPersistentBigEndian<uint64_t>(_buffer, 1);
  ASSERT_EQ(_buffer.length(), 8U);
