  _buffer.clear();
  rocksutils::UintToPersistentBigEndian<uint32_t>(_buffer, 88888);
  ASSERT_EQ(_buffer.length(), 4U);
  ASSERT_EQ(rocksutils::UintFromPersistentBigEndian<uint32_t>(_buffer.data()), 88888U);
}

TEST_F(RocksDBFormatTest, specialized_endianness_functions) {
  // Test specialized functions for fixed-size types
  rocksutils::Uint32ToPersistent(_buffer, 1);
  ASSERT_EQ(_buffer.length(), 4U);
