void AvgEncodeDecodeCoreAlternative(size_t stride, size_t length) {
  std::vector<uint64_t> original_values;
  original_values.reserve(length);

  // Generate sequence using different loop structure
  for (size_t idx = 0; idx < length; ++idx) {
    original_values.push_back((idx + 1) * stride);
  }

  auto encoded_data = original_values;

  // Get encoding statistics
  const auto encoding_result =
    irs::encode::avg::encode(encoded_data.data(), encoded_data.data() + encoded_data.size());

  // Verify base value
  ASSERT_EQ(original_values[0], std::get<0>(encoding_result));

  // Verify stride (average difference)
  ASSERT_EQ(stride, std::get<1>(encoding_result));

  // Check if all encoded values are equal (compression property)
  ASSERT_EQ(irs::irstd::AllEqual(std::begin(encoded_data), std::end(encoded_data)),
            std::get<2>(encoding_result));

  // Verify all encoded values are zero after compression
  ASSERT_TRUE(std::all_of(encoded_data.begin(), encoded_data.end(),
                          [](uint64_t v) { return 0 == v; }));

  // Test decoding via visit function
  bool verification_success = true;
  auto value_iterator = original_values.begin();
  irs::encode::avg::visit(std::get<0>(encoding_result), std::get<1>(encoding_result),
                          encoded_data.data(), encoded_data.data() + encoded_data.size(),
                          [&value_iterator, &verification_success](uint64_t decoded_value) {
                            verification_success = verification_success && (decoded_value == *value_iterator);
                            ++value_iterator;
                          });
  ASSERT_TRUE(verification_success);
  ASSERT_EQ(original_values.end(), value_iterator);

  // Test full decode
  auto decoded_data = encoded_data;
  irs::encode::avg::decode(std::get<0>(encoding_result), std::get<1>(encoding_result),
                           decoded_data.data(), decoded_data.data() + decoded_data.size());
  ASSERT_EQ(original_values, decoded_data);
}

