// Forward declarations for initialization routines
void __OSPSInit();
void __OSFPRInit();
void __OSCacheInit();

// Hardware initialization: enables MMU/exception handling, calls init routines
asm void __init_hardware(void)
{
    nofralloc
    mfmsr   r0              // Read Machine State Register
    ori     r0, r0, 0x2000  // Set EE bit (enable exceptions)
    mtmsr   r0              // Write back to MSR
    mflr    r31             // Save return address
    bl      __OSPSInit      // Initialize PS (Processor Specific)
    bl      __OSFPRInit     // Initialize FPU state
    bl      __OSCacheInit   // Initialize cache settings
    mtlr    r31             // Restore LR
    blr                     // Return
}

// Cache flush routine: invalidates data/instruction caches for given region
asm void __flush_cache(register void *addr, register unsigned int bytes)
{
    nofralloc
    lis     r5, ~0          // Load high word of mask (~0xFFFF0000 → effectively ~0)
    ori     r5, r5, ~14     // Mask aligns address to cache line boundary (8-byte aligned)
    and     r5, r5, r3      // Align start address down to 8-byte boundary
    subf    r3, r5, r3      // Compute offset from aligned start (unused, kept for semantics)
    add     r4, r4, r3      // Convert size to end-offset (bytes remaining)
loop_flush:
    dcbst   r0, r5          // Store data cache block to memory (clean)
    sync                    // Ensure completion of store
    icbi    r0, r5          // Invalidate instruction cache block
    addic.  r5, r5, 8       // Advance to next cache line (8 bytes)
    subic.  r4, r4, 8       // Decrement byte count
    bge     loop_flush      // Continue until all bytes processed
    isync                   // Synchronize instruction stream
    blr                     // Return
}

// C++ runtime entry point: invokes static constructors
void __init_user()
{
    __init_cpp_runtime();
}

// Type alias: pointer to zero-argument void function
typedef void (*void_func_ptr)(void);

// External symbols for constructor/destructor arrays (placed in .init section)
__declspec(section ".init") extern void_func_ptr _ctors_array[];
__declspec(section ".init") extern void_func_ptr _dtors_array[];

// Run all static constructors
void __init_cpp_runtime()
{
    void_func_ptr* ctor_iter = _ctors_array;
    while (*ctor_iter) {
        (*ctor_iter)();
        ++ctor_iter;
    }
}

// Halt processor on exit
void _ExitProcess(void)
{
    PPCHalt();
}

