#include <boost/capy/ex/frame_allocator.hpp>

// Coroutine Frame Allocation System
// ---------------------------------
// This module provides a coroutine frame allocator built on std::pmr::memory_resource.
// It propagates a single memory resource throughout the entire coroutine call tree,
// leveraging thread-local storage (TLS) for implicit propagation.

// Allocation Flow Summary:
// 1. User initiates execution via run_async(ex) or run_async(ex, alloc)
// 2. A trampoline coroutine is created; its promise constructor initializes TLS:
//    - Default case: retrieves pointer to global recycling_memory_resource
//    - raw memory_resource*: stores pointer directly
//    - standard Allocator: wraps in frame_memory_resource<Alloc> inside promise
//    - Then sets this as current frame allocator in TLS
// 3. Trampoline resumes user's task
// 4. io_awaitable_promise_base (via CRTP) overrides operator new/delete to use TLS allocator
// 5. initial_suspend captures current TLS into promise via set_frame_allocator()
// 6. await_resume of initial_suspend restores TLS before executing body
// 7. transform_awaiter::await_resume restores parent's allocator after child completes
// 8. All nested tasks inherit same allocator through TLS

// Core Components:
// get_current_frame_allocator() / set_current_frame_allocator()
//     Thread-local accessors for current memory_resource*. Set by trampoline before any allocation.
//
// frame_memory_resource<Alloc>
//     Adapts standard Allocator to memory_resource interface (rebinds to std::byte).
//     Stored *by value* in trampoline's promise to ensure lifetime exceeds all frames.
//
// recycling_memory_resource
//     Default allocator using per-thread and global pools for efficient reuse.
//     Accessed via get_recycling_memory_resource(), returning static instance pointer.
//
// io_awaitable_promise_base
//     CRTP base class offering:
//       - operator new/delete that delegate to get_current_frame_allocator()
//       - alloc_ member storing captured allocator pointer
//       - set_frame_allocator()/frame_allocator() methods
//
// trampoline
//     Helper coroutine responsible for:
//       - Being allocated *before* user task (C++17 postfix evaluation order)
//       - Holding allocator (wrapped or raw) in its own promise
//       - Setting TLS in promise constructor prior to task creation
//       - Cleaning up user task first, then destroying itself

// Important Design Notes:
// -----------------------
// TLS must be established *before* user task frame allocation:
//     The trampoline's promise constructor runs during make_trampoline(),
//     *before* the user task is constructed — ensuring TLS is ready.
//
// Trampoline uses global new:
//     Since TLS isn’t yet initialized when trampoline’s frame is allocated,
//     it uses default operator new. This is intentional and safe.
//
// TLS restoration on resumption:
//     When a parent coroutine resumes after awaiting a child, its TLS may have changed.
//     transform_awaiter::await_resume restores the parent’s original allocator from its promise.
//
// memory_resource* safety:
//     Passing raw memory_resource* implies user guarantees lifetime — consistent with PMR conventions.
//
// Value-type allocators are safe:
//     Standard allocators are wrapped in frame_memory_resource and stored in trampoline’s promise,
//     which is destroyed last — after all associated frames are deallocated.

// Lifetime Guarantees:
// --------------------
// Destruction order (LIFO):
// 1. User task finishes, final_suspend yields back to trampoline
// 2. Trampoline executes completion handlers
// 3. Trampoline destroys user task handle → frame deallocated via TLS allocator
// 4. Trampoline’s final_suspend uses suspend_never → self-destruction
// 5. Trampoline’s promise (holding frame_memory_resource) destroyed last

// Ensures frame_memory_resource<Alloc> outlives all frames it allocated.

