// Helper to load font safely
bool loadCustomFont(QApplication& app) {
    int id = QFontDatabase::addApplicationFont(":/fonts/fonts/luculent.ttf");
    if (id == -1) return false;

    QStringList families = QFontDatabase::applicationFontFamilies(id);
    if (families.isEmpty()) return false;

    QString familyName = families.first();
    QFont customFont(familyName, 10);
    app.setFont(customFont);
    qDebug() << "Successfully loaded font family:" << familyName;
    return true;
}

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    // Load font early if available
    bool fontLoaded = loadCustomFont(app);
    if (!fontLoaded) {
        qWarning() << "Failed to load custom font from resources.";
    }

    // Initialize logging system first
    auto* loggerWidget = new LogWidget();
    LogWidget::bindTo(loggerWidget);
    LogWidget::installQtHandler(); // Capture Qt logs as well

    // Attach Z80 logger — ensure this happens before any Z80 output
    z80_set_logger(routeZ80Message);

    // Apply visual theming
    QApplication::setStyle(QStyleFactory::create("Fusion"));
    applyDarkTheme(app);

    // Show main window
    MainWindow window;
    window.show();

    return app.exec();
}

