// Constructor: Initialize audio settings UI scene
UIScene_SettingsAudioMenu::UIScene_SettingsAudioMenu(int controllerIndex, void *userData, UILayer *layerParent) 
    : UIScene(controllerIndex, layerParent)
{
    // Load required resources and initialize UI elements
    initialiseMovie();

    WCHAR buffer[256];

    // Setup music volume slider label and initial value
    int musicVol = app.GetGameSettings(controllerIndex, eGameSetting_MusicVolume);
    swprintf(buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_MUSIC), musicVol);
    m_sliderMusic.init(buffer, eControl_Music, 0, 100, musicVol);

    // Setup sound FX volume slider label and initial value
    int sfxVol = app.GetGameSettings(controllerIndex, eGameSetting_SoundFXVolume);
    swprintf(buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_SOUND), sfxVol);
    m_sliderSound.init(buffer, eControl_Sound, 0, 100, sfxVol);

    doHorizontalResizeCheck();

    // Adjust layout for splitscreen if applicable
    if (app.GetLocalPlayerCount() > 1)
    {
#if TO_BE_IMPLEMENTED
        app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, controllerIndex);
#endif
    }
}

// Destructor
UIScene_SettingsAudioMenu::~UIScene_SettingsAudioMenu()
{
}

// Return appropriate movie path based on player count
std::wstring UIScene_SettingsAudioMenu::getMoviePath() const
{
    return (app.GetLocalPlayerCount() > 1) ? L"SettingsAudioMenuSplit" : L"SettingsAudioMenu";
}

// Update tooltip strings
void UIScene_SettingsAudioMenu::updateTooltips()
{
    ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
}

// Manage visibility of UI components depending on game state
void UIScene_SettingsAudioMenu::updateComponents()
{
    bool inLevel = (Minecraft::GetInstance()->level != nullptr);

    if (!inLevel)
    {
        m_parentLayer->showComponent(m_iPad, eUIComponent_Panorama, true);
        m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, true);
    }
    else
    {
        m_parentLayer->showComponent(m_iPad, eUIComponent_Panorama, false);

        int playerCount = app.GetLocalPlayerCount();
        if (playerCount == 1)
            m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, true);
        else
            m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, false);
    }
}

// Handle input events
void UIScene_SettingsAudioMenu::handleInput(int controllerId, int keyCode, bool isRepeat, bool isDown, bool isUp, bool &consumed)
{
    ui.AnimateKeyPress(m_iPad, keyCode, isRepeat, isDown, isUp);

    switch (keyCode)
    {
    case ACTION_MENU_CANCEL:
        if (isDown)
        {
            navigateBack();
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(keyCode, isRepeat, isDown, isUp);
        break;

    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(keyCode, isRepeat, isDown, isUp);
        break;
    }
}

// Process slider movement and update settings accordingly
void UIScene_SettingsAudioMenu::handleSliderMove(F64 sliderIdentifier, F64 newValue)
{
    WCHAR labelBuffer[256];
    int adjustedValue = static_cast<int>(newValue);

    switch (static_cast<int>(sliderIdentifier))
    {
    case eControl_Music:
        m_sliderMusic.handleSliderMove(adjustedValue);
        app.SetGameSettings(m_iPad, eGameSetting_MusicVolume, adjustedValue);
        swprintf(labelBuffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_MUSIC), adjustedValue);
        m_sliderMusic.setLabel(labelBuffer);
        break;

    case eControl_Sound:
        m_sliderSound.handleSliderMove(adjustedValue);
        app.SetGameSettings(m_iPad, eGameSetting_SoundFXVolume, adjustedValue);
        swprintf(labelBuffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_SOUND), adjustedValue);
        m_sliderSound.setLabel(labelBuffer);
        break;
    }
}

