// Module-like behavior simulation using namespaces
namespace a {
    void func_a() { std::cout << "a::func_a" << std::endl; }
    void func_a2() { std::cout << "a::func_a2" << std::endl; }

    namespace b {
        void func_ab() { std::cout << "a::b::func_ab" << std::endl; }
        void func_b1() { std::cout << "a::b::func_b1" << std::endl; }
        void func_b2() { std::cout << "a::b::func_b2" << std::endl; }
    }
}

int main() {
    a::func_a();
    // a::func_a1(); // error: 'func_a1' is internal partition a1 of module 'a'
    a::func_a2();
    std::cout << "---" << std::endl;
    a::b::func_ab();
    a::b::func_b1();
    a::b::func_b2();
    return 0;
}

