// InputFile polymorphic mapping: distinguishes regular vs archive files
void MappingTraits<std::shared_ptr<eld::LDYAML::InputFile>>::mapping(
    IO &IO, std::shared_ptr<eld::LDYAML::InputFile> &input) {
  if (input) {
    input->mapping(IO);
    return;
  }

  std::vector<llvm::StringRef> keys = IO.keys();
  if (llvm::find(keys, "Members") == keys.end()) {
    input = std::make_shared<eld::LDYAML::RegularInput>();
  } else {
    input = std::make_shared<eld::LDYAML::Archive>();
  }
  input->mapping(IO);
}

