// Compute the absolute value of a 64-bit integer, ensuring the result is within int63 range
int64_t Int63Arith::i_abs(const int64_t value) {
    if (value < 0) {
        // Negate and mask to ensure the sign bit is cleared (int63 constraint)
        return ((-value) & 0x7FFFFFFFFFFFFFFFLL);
    } else {
        return value;
    }
}

#include <hip/hip_runtime.h>
#include <cstdlib>
