#define HIP_CHECK(expression)                        \
{                                                    \
    const hipError_t status = expression;            \
    if (status != hipSuccess)                        \
    {                                                \
        std::cerr << "HIP error " << status          \
                << ": " << hipGetErrorString(status) \
                << " at " << __FILE__ << ":"         \
                << __LINE__ << std::endl;            \
        std::exit(EXIT_FAILURE);                     \
    }                                                \
}

int main()
{
    int deviceCount = 0;
    HIP_CHECK(hipGetDeviceCount(&deviceCount));

    std::cout << "Detected GPU devices: " << deviceCount << std::endl;

    for (int id = 0; id < deviceCount; ++id)
    {
        hipDeviceProp_t props;
        HIP_CHECK(hipGetDeviceProperties(&props, id));

        std::cout << "Device #" << id << ":" << std::endl;
        std::cout << "  Model: " << props.name << std::endl;
        std::cout << "  Global Memory: " << props.totalGlobalMem / (1024 * 1024) << " MiB" << std::endl;
        std::cout << "  Shared Mem per Block: " << props.sharedMemPerBlock / 1024 << " KiB" << std::endl;
        std::cout << "  Registers per Block: " << props.regsPerBlock << std::endl;
        std::cout << "  Warp Size: " << props.warpSize << std::endl;
        std::cout << "  Max Threads in Block: " << props.maxThreadsPerBlock << std::endl;
        std::cout << "  Max Threads per SM: " << props.maxThreadsPerMultiProcessor << std::endl;
        std::cout << "  Multiprocessor Count: " << props.multiProcessorCount << std::endl;
        std::cout << "  Max Thread Dimensions: (" 
                << props.maxThreadsDim[0] << ", "
                << props.maxThreadsDim[1] << ", "
                << props.maxThreadsDim[2] << ")" << std::endl;
        std::cout << "  Max Grid Dimensions: (" 
                << props.maxGridSize[0] << ", "
                << props.maxGridSize[1] << ", "
                << props.maxGridSize[2] << ")" << std::endl;
        std::cout << std::endl;
    }

    return EXIT_SUCCESS;
}

