int main()
{
    int errorCode = 0;

    // Initialize a 4x4 identity matrix
    glm::mat4 transformationMatrix(1.0f);

    // Declare variables to store decomposition results
    glm::vec3 scaleComponents;
    glm::quat rotationOrientation;
    glm::vec3 translationComponents;
    glm::vec3 shearFactors(1.0f);
    glm::vec4 perspectiveComponents(1.0f);

