Looking at the original code, this is a bit-packing/unpacking library with template metaprogramming for handling different bit widths. The task is to create a Type III clone - maintaining the same functionality but with different implementation approach.

Here's my analysis:
1. The code has specialized functions for unpacking/packing different bit widths (1-64 bits)
2. It uses template recursion with Unroller structs
3. There are special cases for powers of 2 and edge cases

For the clone, I'll:
- Keep the same function signatures
- Replace the template-based unrolling with iterative approaches
- Use loops instead of recursive templates
- Maintain the same logic but with different control flow

```cpp
#include "bitpacking.h"
#include <cstdint>
#include <type_traits>

namespace {
// Helper function to extract DELTA bits starting at bit position SHR from input
template <typename T_in, typename T_out>
T_out extract_bits(const T_in* in, uint8_t delta, uint8_t shr) {
    T_out result = 0;
    const uint8_t bits_per_in = sizeof(T_in) * 8;

    if (shr + delta <= bits_per_in) {
        // All bits within current word
        const T_in mask = (delta == bits_per_in) ? T_in(-1) : ((T_in(1) << delta) - 1);
        result = static_cast<T_out>(((*in) >> shr) & mask);
    } else {
        // Bits span across words
        const uint8_t first_part = bits_per_in - shr;
        const T_in mask1 = (first_part == bits_per_in) ? T_in(-1) : ((T_in(1) << first_part) - 1);
        result = static_cast<T_out>((*in) >> shr) & mask1;

        const uint8_t remaining = delta - first_part;
        const T_in mask2 = (remaining == bits_per_in) ? T_in(-1) : ((T_in(1) << remaining) - 1);
        ++in;
        result |= (static_cast<T_out>((*in) & mask2) << first_part);
    }
    return result;
}

// Specialized unpack for 8-bit inputs
void unpack_8bit_delta(const uint8_t* in, uint8_t* out, uint8_t delta, int count) {
    uint8_t bit_pos = 0;
    for (int i = 0; i < count; ++i) {
        uint8_t val = 0;
        uint8_t bits_needed = delta;
        uint8_t current_bit = bit_pos;

        while (bits_needed > 0) {
            uint8_t bits_available = 8 - current_bit;
            uint8_t bits_to_take = std::min(bits_needed, bits_available);

            uint8_t mask = (1U << bits_to_take) - 1;
            val |= ((*in >> current_bit) & mask) << (delta - bits_needed);

            if (bits_to_take == bits_available) {
                ++in;
                current_bit = 0;
            } else {
                current_bit += bits_to_take;
            }
            bits_needed -= bits_to_take;
        }
        out[i] = val;
        bit_pos += delta;
        while (bit_pos >= 8) {
            bit_pos -= 8;
            if (bit_pos == 0) ++in;
        }
    }
}

// Specialized unpack for 16-bit inputs
void unpack_16bit_delta(const uint16_t* in, uint16_t* out, uint8_t delta, int count) {
    uint16_t bit_pos = 0;
    for (int i = 0; i < count; ++i) {
        uint16_t val = 0;
        uint8_t bits_needed = delta;
        uint16_t current_bit = bit_pos;

        while (bits_needed > 0) {
            uint8_t bits_available = 16 - current_bit;
            uint8_t bits_to_take = std::min(bits_needed, bits_available);

            uint16_t mask = (bits_to_take == 16) ? 0xFFFF : ((1U << bits_to_take) - 1);
            val |= ((*in >> current_bit) & mask) << (delta - bits_needed);

            if (bits_to_take == bits_available) {
                ++in;
                current_bit = 0;
            } else {
                current_bit += bits_to_take;
            }
            bits_needed -= bits_to_take;
        }
        out[i] = val;
        bit_pos += delta;
        while (bit_pos >= 16) {
            bit_pos -= 16;
            if (bit_pos == 0) ++in;
        }
    }
}

// Specialized unpack for 32-bit inputs to 32-bit outputs
void unpack_32to32_delta(const uint32_t* in, uint32_t* out, uint8_t delta, int count) {
    uint32_t bit_pos = 0;
    for (int i = 0; i < count; ++i) {
        uint32_t val = 0;
        uint8_t bits_needed = delta;
        uint32_t current_bit = bit_pos;

        while (bits_needed > 0) {
            uint8_t bits_available = 32 - current_bit;
            uint8_t bits_to_take = std::min(bits_needed, bits_available);

            uint32_t mask = (bits_to_take == 32) ? 0xFFFFFFFF : ((1U << bits_to_take) - 1);
            val |= ((*in >> current_bit) & mask) << (delta - bits_needed);

            if (bits_to_take == bits_available) {
                ++in;
                current_bit = 0;
            } else {
                current_bit += bits_to_take;
            }
            bits_needed -= bits_to_take;
        }
        out[i] = val;
        bit_pos += delta;
        while (bit_pos >= 32) {
            bit_pos -= 32;
            if (bit_pos == 0) ++in;
        }
    }
}

// Specialized unpack for 32-bit inputs to 64-bit outputs
void unpack_32to64_delta(const uint32_t* in, uint64_t* out, uint8_t delta, int count) {
    uint32_t bit_pos = 0;
    for (int i = 0; i < count; ++i) {
        uint64_t val = 0;
        uint8_t bits_needed = delta;
        uint32_t current_bit = bit_pos;

        while (bits_needed > 0) {
            uint8_t bits_available = 32 - current_bit;
            uint8_t bits_to_take = std::min(bits_needed, bits_available);

            uint32_t mask = (bits_to_take == 32) ? 0xFFFFFFFF : ((1U << bits_to_take) - 1);
            val |= (static_cast<uint64_t>(*in) >> current_bit & mask) << (delta - bits_needed);

            if (bits_to_take == bits_available) {
                ++in;
