// Specialized pack for 8-bit inputs
void pack_8bit_delta(const uint8_t* in, uint8_t* out, uint8_t delta, int count) {
    uint8_t bit_pos = 0;
    for (int i = 0; i < count; ++i) {
        uint8_t val = in[i];
        uint8_t bits_remaining = delta;
        uint8_t current_bit = bit_pos;

        while (bits_remaining > 0) {
            uint8_t bits_available = 8 - current_bit;
            uint8_t bits_to_write = std::min(bits_remaining, bits_available);

            uint8_t mask = (bits_to_write == 8) ? 0xFF : ((1U << bits_to_write) - 1);
            *out |= ((val & (mask << (delta - bits_remaining))) >> (delta - bits_remaining)) << current_bit;

            if (bits_to_write == bits_available) {
                ++out;
                current_bit = 0;
            } else {
                current_bit += bits_to_write;
            }
            bits_remaining -= bits_to_write;
        }
        bit_pos += delta;
        while (bit_pos >= 8) {
            bit_pos -= 8;
            if (bit_pos == 0) ++out;
        }
    }
}

