typedef struct ObUnicaseInfo {
  ob_wc_t maxchar;
  ObUnicaseInfoChar **page;
} ObUnicaseInfo;

ObUnicaseInfo ob_unicase_default = {
  0xFFFF,
  ob_unicase_pages_default
};

static int ob_mb_wc_utf8mb4(ob_wc_t * pwc, const uchar *s, const uchar *e) {
  uchar c;
  if (s >= e) return OB_CS_TOOSMALL;
  c = s[0];
  if (c < 0x80) {
    *pwc = c;
    return 1;
  } else if (c < 0xc2) {
    return OB_CS_ILSEQ;
  } else if (c < 0xe0) {
    if (s + 2 > e) return OB_CS_TOOSMALL2;
    if (!(IS_CONTINUATION_BYTE(s[1]))) return OB_CS_ILSEQ;
    *pwc = ((ob_wc_t)(c & 0x1f) << 6) | (ob_wc_t)(s[1] ^ 0x80);
    return 2;
  } else if (c < 0xf0) {
    if (s + 3 > e) return OB_CS_TOOSMALL3;
    if (!(IS_CONTINUATION_BYTE(s[1]) && IS_CONTINUATION_BYTE(s[2]) &&
          (c >= 0xe1 || s[1] >= 0xa0))) return OB_CS_ILSEQ;
    *pwc = ((ob_wc_t)(c & 0x0f) << 12) |
           ((ob_wc_t)(s[1] ^ 0x80) << 6) |
            (ob_wc_t)(s[2] ^ 0x80);
    return 3;
  } else if (c < 0xf5) {
    if (s + 4 > e) return OB_CS_TOOSMALL4;
    if (!(IS_CONTINUATION_BYTE(s[1]) &&
          IS_CONTINUATION_BYTE(s[2]) &&
          IS_CONTINUATION_BYTE(s[3]) &&
          (c >= 0xf1 || s[1] >= 0x90) &&
          (c <= 0xf3 || s[1] <= 0x8F))) return OB_CS_ILSEQ;
    *pwc = ((ob_wc_t)(c & 0x07) << 18) |
           ((ob_wc_t)(s[1] ^ 0x80) << 12) |
           ((ob_wc_t)(s[2] ^ 0x80) << 6) |
            (ob_wc_t)(s[3] ^ 0x80);
    return 4;
  }
  return OB_CS_ILSEQ;
}

static inline int bincmp_utf8mb4(const uchar *s, const uchar *se,
                                 const uchar *t, const uchar *te) {
  int slen = (int)(se - s), tlen = (int)(te - t);
  int len = MY_MIN(slen, tlen);
  int cmp_val = memcmp(s, t, len);
  return cmp_val ? cmp_val : slen - tlen;
}

static inline void ob_tosort_unicode(ObUnicaseInfo *uni_plane, ob_wc_t *wc, uint flags) {
  if (*wc <= uni_plane->maxchar) {
    ObUnicaseInfoChar *page_ptr = NULL;
    if ((page_ptr = uni_plane->page[*wc >> 8])) {
      *wc = (flags & OB_CS_LOWER_SORT) ?
           page_ptr[*wc & 0xFF].tolower :
           page_ptr[*wc & 0xFF].sort;
    }
  } else {
    *wc = OB_CS_REPLACEMENT_CHARACTER;
  }
}

static int __attribute__ ((noinline)) ob_strnncollsp_utf8mb4_help(
    const uchar **src_ptr, size_t src_len,
    const uchar **tgt_ptr, size_t tgt_len,
    const uchar **src_end_ptr, const uchar **tgt_end_ptr,
    ob_bool diff_if_only_endspace_difference, int *has_returned_flag, int *result_ptr) {
  const uchar *src = *src_ptr;
  const uchar *tgt = *tgt_ptr;
  const uchar *src_end = *src_end_ptr;
  const uchar *tgt_end = *tgt_end_ptr;
  int result = *result_ptr;
  *has_returned_flag = 0;
  int swap_factor = 1;

  if (src_len != tgt_len) {
    if (FALSE != diff_if_only_endspace_difference)
      result = 1;
    if (src_len < tgt_len) {
      src_len = tgt_len;
      src = tgt;
      src_end = tgt_end;
      swap_factor = -1;
      result = -result;
    }

    for (; src < src_end; src++) {
      if (*src != ' ') {
        *has_returned_flag = 1;
        break;
      }
    }
  }

  *src_ptr = src;
  *tgt_ptr = tgt;
  *src_end_ptr = src_end;
  *tgt_end_ptr = tgt_end;
  *result_ptr = result;

  if (*has_returned_flag == 1) {
    return (*src < ' ') ? -swap_factor : swap_factor;
  }
  return 0;
}

static bool is_argument_valid(const char *str1, int64_t str_len1, const char *str2, int64_t str_len2) {
  bool is_valid = true;
  if ((str_len1 < 0) ||
      (str_len2 < 0) ||
      (NULL == str1 && 0 != str_len1) ||
      (NULL == str2 && 0 != str_len2)) {
    is_valid = false;
  }
  return is_valid;
}

static int ob_strnncollsp_utf8mb4(const uchar *s, size_t slen,
                       const uchar *t, size_t tlen,
                       ob_bool diff_if_only_endspace_difference) {
  int res = 0;
  ob_wc_t s_wc = 0, t_wc = 0;
  const uchar *se = s + slen, *te = t + tlen;
  ObUnicaseInfo *uni_plane = &ob_unicase_default;

  while (s < se && t < te) {
    int s_res = ob_mb_wc_utf8mb4(&s_wc, s, se);
    int t_res = ob_mb_wc_utf8mb4(&t_wc, t, te);

    if (s_res <= 0 || t_res <= 0) {
      return bincmp_utf8mb4(s, se, t, te);
    }

    ob_tosort_unicode(uni_plane, &s_wc, state);
    ob_tosort_unicode(uni_plane, &t_wc, state);

    if (s_wc != t_wc) {
      return s_wc > t_wc ? 1 : -1;
    }

    s += s_res;
    t += t_res;
  }

  slen = (size_t)(se - s);
  tlen = (size_t)(te - t);
  res = 0;
  int has_returned = 0;
  int tmp_result = ob_strnncollsp_utf8mb4_help(
      &s, slen,
      &t, tlen,
      &se, &te,
      diff_if_only_endspace_difference, &has_returned, &res);

  return has_returned ? tmp_result : res;
}

int64_t jit_strcmpsp(const char *str1, int64_t str1_len,
             const char *str2, int64_t str2_len,
             bool cmp_endspace) {
  int64_t final_result = 0;

  if (is_argument_valid(str1, str1_len, str2, str2_len)) {
    final_result = (int64_t)ob_strnncollsp_utf8mb4(
        reinterpret_cast<const uchar *>(str1),
        str1_len,
        reinterpret_cast<const uchar *>(str2),
        str2_len,
        cmp_endspace);
  }

  return final_result;
}

