SubscriberListener::SubscriberListener(const NewMsgCallback& callback) : callback_(callback) {}

SubscriberListener::~SubscriberListener() {
    std::lock_guard<std::mutex> guard(mutex_);
    callback_.reset();
}

void SubscriberListener::onNewDataMessage(eprosima::fastrtps::Subscriber* subscriber) {
    if (!callback_) {
        return;
    }

    std::lock_guard<std::mutex> lock(mutex_);
    eprosima::fastrtps::SampleInfo_t sample_info;
    autolink::transport::UnderlayMessage message;

    if (!subscriber->takeNextData(reinterpret_cast<void*>(&message), &sample_info)) {
        return;
    }

    if (sample_info.sampleKind != eprosima::fastrtps::rtps::ALIVE) {
        return;
    }

    callback_(message.data());
}

