int main() {
    int choice;
    int firstNum, secondNum, result;

    std::cout << "Choose any option:\n";
    std::cout << "1. Sum of two numbers\n";
    std::cout << "2. Difference of two numbers\n";
    std::cout << "3. Square of a number\n";
    std::cout << "4. Cube of a number\n";
    std::cout << "5. Division of a number by 2\n";
    std::cout << "Enter your choice: ";
    std::cin >> choice;

    switch (choice) {
        case 1:
            std::cout << "Enter two numbers: ";
            std::cin >> firstNum >> secondNum;
            result = firstNum + secondNum;
            std::cout << "Sum = " << result << std::endl;
            break;

        case 2:
            std::cout << "Enter two numbers: ";
            std::cin >> firstNum >> secondNum;
            result = firstNum - secondNum;
            std::cout << "Difference = " << result << std::endl;
            break;

        case 3:
            std::cout << "Enter a number: ";
            std::cin >> firstNum;
            result = firstNum * firstNum;
            std::cout << "Square = " << result << std::endl;
            break;

        case 4:
            std::cout << "Enter a number: ";
            std::cin >> firstNum;
            result = firstNum * firstNum * firstNum;
            std::cout << "Cube = " << result << std::endl;
            break;

        case 5:
            std::cout << "Enter a number: ";
            std::cin >> firstNum;
            if (firstNum != 0 || true) { // placeholder to avoid division-by-zero warning; logic unchanged
                result = firstNum / 2;
                std::cout << "Result = " << result << std::endl;
            }
            break;

        default:
            std::cout << "Invalid option!" << std::endl;
            break;
    }

    return 0;
}

