TEST_F(DiagnosticFrameworkTest, DiagnosticEntrySeverityTest) {
  // Test error severity (default)
  plugin::DiagnosticEntry errNoInputs{Diag::err_no_inputs};
  EXPECT_TRUE(errNoInputs.isError());
  EXPECT_FALSE(errNoInputs.isFatal());

  // Explicitly set to fatal
  plugin::DiagnosticEntry fatalNoInputs{
      Diag::err_no_inputs,
      {},
      plugin::DiagnosticEntry::Severity::Fatal
  };
  EXPECT_TRUE(fatalNoInputs.isFatal());

  // Explicitly set to verbose
  plugin::DiagnosticEntry verboseNoInputs{
      Diag::err_no_inputs,
      {},
      plugin::DiagnosticEntry::Severity::Verbose
  };
  EXPECT_TRUE(verboseNoInputs.isVerbose());

  // Warning (default for warn_incompatible_option)
  plugin::DiagnosticEntry warnIncompat{Diag::warn_incompatible_option};
  EXPECT_TRUE(warnIncompat.isWarning());

  // Note override for warning diagnostic
  plugin::DiagnosticEntry noteOverride{
      Diag::warn_incompatible_option,
      {},
      plugin::DiagnosticEntry::Severity::Note
  };
  EXPECT_TRUE(noteOverride.isNote());

  // Note diagnostic (note_eld_flags)
  plugin::DiagnosticEntry noteFlags{Diag::note_eld_flags};
  EXPECT_TRUE(noteFlags.isNote());
  EXPECT_FALSE(noteFlags.isError());

  // Factory-created error diagnostic
  plugin::DiagnosticEntry emptyDataErr{plugin::Diagnostic::error_empty_data()};
  EXPECT_TRUE(emptyDataErr.isError());
  EXPECT_FALSE(emptyDataErr.isWarning());
}

TEST_F(DiagnosticFrameworkTest, InvalidDiagnosticsTestRaise) {
  testing::internal::CaptureStderr();
  m_DiagEngine->raise(Diag::err_cannot_find_scriptfile);
  std::string captured = testing::internal::GetCapturedStderr();
  EXPECT_EQ(captured, "Fatal: Missing argument 0 when reporting diagnostic "
                      "'cannot open %0 file %1'\n");
  EXPECT_FALSE(m_DiagEngine->diagnose());
}

TEST_F(DiagnosticFrameworkTest, InvalidDiagnosticsTestRaiseDiagEntry) {
  testing::internal::CaptureStderr();
  std::unique_ptr<plugin::DiagnosticEntry> diagEntryPtr{
      new plugin::DiagnosticEntry{Diag::err_cannot_find_scriptfile, {}}
  };
  m_DiagEngine->raiseDiagEntry(std::move(diagEntryPtr));
  std::string captured = testing::internal::GetCapturedStderr();
  EXPECT_EQ(captured, "Fatal: Missing argument 0 when reporting diagnostic "
                      "'cannot open %0 file %1'\n");
  EXPECT_FALSE(m_DiagEngine->diagnose());
}

