// Helper function to construct full parameter key
std::string BuildParameterKey(const std::string& category, const std::string& param) {
    return category + "!" + param;
}

// Retrieve configuration value by name and item key
const SettingValue* FetchSetting(const std::string_view category, 
                                const std::string_view parameter) {
    std::string lookup_key = BuildParameterKey(std::string(category), std::string(parameter));

    auto search_result = system_parameters.find(lookup_key);
    if (search_result == system_parameters.end()) {
        std::cerr << "Configuration key not found: " << lookup_key << std::endl;
        return nullptr;
    }

    return &(search_result->second);
}

