#include <google/protobuf/descriptor.pb.h>

using namespace Valdi;

namespace {
TEST(FullyQualifiedName, canInitWithSinglePackage) {
    Protobuf::FullyQualifiedName name("com");
    EXPECT_EQ("", name.getLeadingComponents());
    EXPECT_EQ("com", name.getLastComponent());
}

TEST(FullyQualifiedName, canInitWithNestedPackage) {
    Protobuf::FullyQualifiedName name("com.valdi");
    EXPECT_EQ("com", name.getLeadingComponents());
    EXPECT_EQ("valdi", name.getLastComponent());

    name = Protobuf::FullyQualifiedName("com.valdi.MyType");
    EXPECT_EQ("com.valdi", name.getLeadingComponents());
    EXPECT_EQ("MyType", name.getLastComponent());
}

TEST(FullyQualifiedName, canAppend) {
    Protobuf::FullyQualifiedName name;
    EXPECT_EQ("", name.getLeadingComponents());
    EXPECT_EQ("", name.getLastComponent());

    name.append("com");
    EXPECT_EQ("", name.getLeadingComponents());
    EXPECT_EQ("com", name.getLastComponent());

    name.append("valdi");
    EXPECT_EQ("com", name.getLeadingComponents());
    EXPECT_EQ("valdi", name.getLastComponent());

    name.append("nested.MyType");
    EXPECT_EQ("com.valdi.nested", name.getLeadingComponents());
    EXPECT_EQ("MyType", name.getLastComponent());
}

TEST(FullyQualifiedName, canRemoveLastComponent) {
    Protobuf::FullyQualifiedName name("com.valdi.MyType");
    EXPECT_EQ("com.valdi", name.getLeadingComponents());
    EXPECT_EQ("MyType", name.getLastComponent());
    EXPECT_TRUE(name.canRemoveLastComponent());

    name = name.removingLastComponent();
    EXPECT_EQ("com", name.getLeadingComponents());
    EXPECT_EQ("valdi", name.getLastComponent());
    EXPECT_TRUE(name.canRemoveLastComponent());

    name = name.removingLastComponent();
    EXPECT_EQ("", name.getLeadingComponents());
    EXPECT_EQ("com", name.getLastComponent());
    EXPECT_FALSE(name.canRemoveLastComponent());
}

TEST(FullyQualifiedName, canOutputAsString) {
    Protobuf::FullyQualifiedName name("com.valdi.MyType");
    EXPECT_EQ("com.valdi.MyType", name.toString());

    name = Protobuf::FullyQualifiedName("MyType");
    EXPECT_EQ("MyType", name.toString());
}
} // namespace

#include <algorithm>
