// Global configuration state
std::uint32_t unp_cfg_context          = 0;
std::uint32_t pack_sync_tile_dst_ptr   = 0;
std::uint32_t math_sync_tile_dst_index = 0;

#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_A.h"
#include "llk_unpack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
    // Configure hardware for unpacking A and B inputs
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        formats.unpack_A_src, formats.unpack_B_src,
        formats.unpack_A_dst, formats.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, 4 /* num_faces */, 4 /* num_faces */);

    // Initialize unpacker for tensor A (no broadcast, no reuse)
    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        0, 0, FACE_R_DIM, 4, formats.unpack_A_src, formats.unpack_A_dst);

    // Process all input tiles
    std::uint32_t tile_idx = 0;
    const std::uint32_t num_tiles = params->TILE_CNT;
    while (tile_idx < num_tiles)
    {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(params->buffer_A[tile_idx]), formats.unpack_A_src, formats.unpack_A_dst);
        ++tile_idx;
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "ckernel_sfpu.h"
#include "llk_math_common.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "llk_math_eltwise_unary_sfpu.h"
#include "params.h"

using namespace ckernel;
using namespace ckernel::sfpu;

void run_kernel(const volatile struct RuntimeParams* params)
{
    // Copy data from source A to destination register
#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(4, formats.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(4, formats.math);
#endif

    // Prepare synchronization for half-buffered destination writes
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(formats.math, formats.math);

    // Wait until destination buffer is ready
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Process each tile: copy and reduce
    std::uint32_t tile_idx = 0;
    const std::uint32_t max_tiles = get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>();
    const std::uint32_t num_tiles = params->TILE_CNT;

    while (tile_idx < num_tiles)
    {
        LLK_ASSERT(tile_idx < max_tiles, "Block tile index exceeds maximum destination tiles");
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tile_idx, formats.math, formats.math);
        ++tile_idx;
    }

    // Setup SPU reduction operation
    _llk_math_eltwise_unary_sfpu_init_<SfpuType::reduce>();
    ckernel::sfpu::_init_reduce_<POOL_TYPE, static_cast<DataFormat>(formats.math)>();

    if (REDUCE_DIM == ReduceDim::REDUCE_COL)
    {
        // Column-wise reduction: process per-tile
        tile_idx = 0;
        while (tile_idx < num_tiles)
        {
            LLK_ASSERT(tile_idx < max_tiles, "Block tile index exceeds maximum destination tiles");
            _llk_math_eltwise_unary_sfpu_start_<DstSync::SyncHalf>(tile_idx);
            ckernel::sfpu::_calculate_reduce_<POOL_TYPE, REDUCE_DIM, static_cast<DataFormat>(formats.math)>();
            ++tile_idx;
        }
    }
    else if (REDUCE_DIM == ReduceDim::REDUCE_ROW)
    {
        // Row-wise reduction: single call with full dimensions
        _llk_math_eltwise_unary_sfpu_start_<DstSync::SyncHalf>(0);
        ckernel::sfpu::_calculate_reduce_<POOL_TYPE, REDUCE_DIM, static_cast<DataFormat>(formats.math)>(BLOCK_CT_DIM, BLOCK_RT_DIM);
    }

#ifdef ADD_TOP_ROW
    // Add top row accumulation step
    _llk_math_eltwise_binary_sfpu_init_<SfpuType::add_top_row>();
    _llk_math_eltwise_binary_sfpu_start_<DstSync::SyncHalf>(0);
    ckernel::sfpu::_init_add_top_row_();

    // Accumulate top rows across tiles starting from index 1
    std::uint32_t accum_idx = 1;
    while (accum_idx < num_tiles)
    {
        LLK_ASSERT(accum_idx < max_tiles, "Block tile index exceeds maximum destination tiles");
        ckernel::sfpu::_calculate_add_top_row_<static_cast<DataFormat>(formats.math)>(0, accum_idx, 0); // accumulate into tile 0
        ++accum_idx;
    }
#endif

    // Finalize SFPU operations and release destination buffer
    _llk_math_eltwise_unary_sfpu_done_();
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(formats.pack_src, formats.pack_dst, 16 * 16 * 4);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(formats.pack_src, formats.pack_dst, 16 * 16 * 4);
#endif

    // Initialize packer
    _llk_pack_init_<false, false>(formats.pack_dst);

#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    // Wait until math processing completes
    _llk_packer_wait_for_math_done_();

    // Pack output tiles
    std::uint32_t tile_idx = 0;
    const std::uint32_t max_tiles = get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>();
    const std::uint32_t num_tiles = params->TILE_CNT;

    while (tile_idx < num_tiles)
    {
        LLK_ASSERT(tile_idx < max_tiles, "Block tile index exceeds maximum destination tiles");
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(tile_idx, L1_ADDRESS(params->buffer_Res[tile_idx]));
        ++tile_idx;
    }

    // Signal end of destination section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

