#include <singleapplication.h>
#include "messagereceiver.h"

int main(int argc, char *argv[])
{
    // Initialize application allowing multiple instances
    SingleApplication app(argc, argv, true);
    MessageReceiver receiver;

    // Check if another instance is already running
    if (app.isSecondary()) {
        // Send current arguments to the primary instance
        QString msg = app.arguments().join(" ");
        app.sendMessage(msg.toUtf8());

        qDebug() << "Application already active.";
        qDebug() << "Primary process ID:" << app.primaryPid();
        qDebug() << "User running primary instance:" << app.primaryUser();

        return 0;
    } else {
        // Connect message reception signal to handler slot
        QObject::connect(
            &app,
            &SingleApplication::receivedMessage,
            &receiver,
            &MessageReceiver::handleIncomingMessage
        );
    }

    return app.exec();
}

