// Helper lambda to compare layouts more flexibly
auto layoutMatches = [](const LinearLayout &actual,
                        const LinearLayout &expected) -> bool {
  if (actual.getNumInputs() != expected.getNumInputs()) return false;
  if (actual.getNumOutputs() != expected.getNumOutputs()) return false;

  for (const auto &[name, bases] : actual.getBases()) {
    if (!expected.containsBasis(name)) return false;
    const auto &expBases = expected.getBasis(name);
    if (bases.size() != expBases.size()) return false;
    for (size_t i = 0; i < bases.size(); ++i) {
      if (bases[i] != expBases[i]) return false;
    }
  }
  return true;
};

