// Function to print a character array with a prefix message
extern "C" int charv_print(Scope_Struct *scope_struct, char *c, int size) {
    std::cout << "print charv" << "\n";

    // Use index-based iteration with manual increment
    int idx = 0;
    while (idx < size) {
        std::cout << c[idx];
        ++idx;
    }

    return 0;
}

