// Enumerations for operation modes and parameters (renamed)
enum class OpMode {
    UnaryOp,
    BinaryOp,
    Shift,
    Mul,
    ReadMem,
    WriteMem,
    DT,
    Rot,
    ExtOp,
    Div0,
    FiprOp,
    WriteTOp
};

enum class ParamType {
    RN,
    RM,
    FRN,
    FRM,
    FR0,
    R0,
    SIMM8,
    UIMM8,
    PC_D8_x2,
    PC_D8_x4,
