    TWO,
    TWO_INV,
    ZERO_F32,
    ONE_F32,
    FPUL,
    SREG,
    CREG,
    FPN,
    FVN,
    FVM,
    XMTRX,
    FRM_FR0,
    FRN_SZ,
    FRM_SZ
};

// Structure to hold opcode information (renamed fields)
struct OpcodeEntry {
    u64 encoding;
    u32 mask;
    u32 base;
    std::string name;
    int cycles;
    int flags;
    std::string description;
};

// Global storage for decoded opcodes (different structure)
std::map<u32, u64> opcode_handlers;
std::map<u32, OpcodeEntry> opcode_descriptions;

// Helper functions with different naming
u64 encode_opcode(OpMode mode, ParamType dest, ParamType src, u32 extra = 0) {
    return ((u64)extra << 32) | (static_cast<u32>(mode) << 24) | (static_cast<u32>(dest) << 16) | (static_cast<u32>(src) << 8);
}

u64 create_unary_op(ParamType dest, ParamType src, u32 extra = 0) {
    return encode_opcode(OpMode::UnaryOp, dest, src, extra);
}

u64 create_binary_op(ParamType dest, ParamType src, u32 extra = 0) {
    return encode_opcode(OpMode::BinaryOp, dest, src, extra);
}

u64 create_shift_op(int offset, bool arithmetic = false) {
    if (offset > 0) {
        return encode_opcode(OpMode::Shift, ParamType::RN, ParamType::RN, offset);
    } else {
        return encode_opcode(OpMode::Shift, ParamType::RN, ParamType::RN, static_cast<u32>(arithmetic ? -offset : -offset) | 0x80000000);
    }
}

u64 create_compare_op(u32 type, ParamType param1, ParamType param2) {
    return encode_opcode(OpMode::WriteTOp, param1, param2, type);
}

u64 create_load_mem(ParamType dest) {
    return encode_opcode(OpMode::ReadMem, dest, ParamType::RN);
}

u64 create_store_mem(ParamType src) {
    return encode_opcode(OpMode::WriteMem, ParamType::RN, src);
}

// Mask definitions (renamed values)
const u32 MASK_NONE = 0xFFFF;
const u32 MASK_N = 0xF0FF;
const u32 MASK_M = 0xFF0F;
const u32 MASK_NM = 0xF00F;
const u32 MASK_IMM4 = 0xF000;
const u32 MASK_IMM8 = 0xFF00;
const u32 MASK_IMM12 = 0xF000;
const u32 MASK_NML3BIT = 0xF08F;
const u32 MASK_NH3BIT = 0xF1FF;
const u32 MASK_NH2BIT = 0xF3FF;

// Helper macros (rewritten as functions)
inline u32 get_n(u16 instr) { return (instr >> 8) & 0xF; }
inline u32 get_m(u16 instr) { return (instr >> 4) & 0xF; }
inline u32 get_imm4(u16 instr) { return instr & 0xF; }
inline u32 get_imm8(u16 instr) { return instr & 0xFF; }
inline s8 get_simm8(u16 instr) { return static_cast<s8>(instr & 0xFF); }
inline u32 get_imm12(u16 instr) { return instr & 0xFFF; }
inline s16 get_simm12(u16 instr) { return static_cast<s16>((get_imm12(instr) << 4) >> 4); }

