// Function to build opcode tables (restructured implementation)
void construct_opcode_tables() {
    std::cout << "Constructing opcode tables..." << std::endl;

    // Initialize all entries to default handler
    for (u32 i = 0; i < 0x10000; ++i) {
        opcode_handlers[i] = 0; // Default handler
    }

    // Process each opcode definition
    for (const auto& entry : opcode_database) {
        u32 shift_amount = 0;
        u32 count = 1;

        // Determine shift and count based on mask type
        switch (entry.mask) {
            case MASK_NONE:
                shift_amount = 0;
                count = 1;
                break;
            case MASK_N:
                shift_amount = 8;
                count = 16;
                break;
            case MASK_M:
                shift_amount = 4;
                count = 16;
                break;
            case MASK_NM:
                shift_amount = 4;
                count = 256;
                break;
            case MASK_IMM4:
                shift_amount = 0;
                count = 256 * 16;
                break;
            case MASK_IMM8:
                shift_amount = 0;
                count = 256;
                break;
            case MASK_NML3BIT:
                shift_amount = 4;
                count = 256;
                break;
            case MASK_NH3BIT:
                shift_amount = 9;
                count = 8;
                break;
            case MASK_NH2BIT:
                shift_amount = 10;
                count = 4;
                break;
            default:
                continue; // Skip unknown masks
        }

        // Populate the opcode table
        for (u32 i = 0; i < count; ++i) {
            u32 index = ((i << shift_amount) & ~entry.mask) + entry.base;
            if (index < 0x10000) {
                opcode_handlers[index] = entry.encoding;
                opcode_descriptions[index] = entry;
            }
        }
    }

    std::cout << "Opcode table construction complete." << std::endl;
}

// Main function demonstrating the new implementation
int main() {
    // Build the opcode tables
    construct_opcode_tables();

    // Example usage: print some opcode info
    std::cout << "Sample opcodes:" << std::endl;
    std::cout << "NOP (0x0009): " << (opcode_descriptions.count(0x0009) ? "Found" : "Not found") << std::endl;
    std::cout << "MOV.L (0x0006): " << (opcode_descriptions.count(0x0006) ? "Found" : "Not found") << std::endl;
    std::cout << "FADD (0xF000): " << (opcode_descriptions.count(0xF000) ? "Found" : "Not found") << std::endl;

    return 0;
}

