int main() {
    // Initialize semirings: one for forward propagation, one for reverse
    wpds::Semiring< StringWrapper > ring(StringWrapper::one());
    wpds::Semiring< StringWrapper > ringR(StringWrapper::one(), false);

    // Create two WPDS instances using the same semiring
    wpds::WPDS< StringWrapper > system1(ring);
    wpds::WPDS< StringWrapper > system2(ring);

    // Construct context-aware automata over the same semiring
    wpds::CA< StringWrapper > ca1(ring);
    wpds::CA< StringWrapper > ca2(ring);

    // Define keys for WPDS rules in system1
    wpds::wpds_key_t state_p = str2key("p");
    wpds::wpds_key_t nonterm_A = str2key("A");
    wpds::wpds_key_t nonterm_B = str2key("B");
    wpds::wpds_key_t nonterm_C = str2key("C");
    wpds::wpds_key_t nonterm_D = str2key("D");
    wpds::wpds_key_t epsilon = str2key("lambda");
    wpds::wpds_key_t final_state = str2key("accept");

    // Add rewrite rules to system1
    system1.add_rule(state_p, epsilon, state_p, nonterm_A, new StringWrapper("a"));
    system1.add_rule(state_p, nonterm_A, state_p, nonterm_B, new StringWrapper("b"));
    system1.add_rule(state_p, nonterm_B, state_p, nonterm_C, new StringWrapper("c"));
    system1.add_rule(state_p, nonterm_C, state_p, nonterm_D, new StringWrapper("d"));
    system1.add_rule(state_p, nonterm_A, state_p, nonterm_A, nonterm_B, new StringWrapper("w"));

    // Define keys for system2
    wpds::wpds_key_t state_pprime = str2key("p'");
    wpds::wpds_key_t var_x = str2key("x");
    wpds::wpds_key_t var_xprime = str2key("x'");
    wpds::wpds_key_t var_x2prime = str2key("x''");

    // Add rewrite rules to system2
    system2.add_rule(state_pprime, var_x,       state_p,      nonterm_A, StringWrapper::one());
    system2.add_rule(state_pprime, var_xprime,  state_pprime, var_x,     nonterm_B, StringWrapper::one());
    system2.add_rule(state_pprime, var_x2prime, state_pprime, var_xprime, nonterm_B, StringWrapper::one());

    // Set initial condition: accept state has weight 1
    ca1.add(state_p, epsilon, final_state, StringWrapper::one());

    std::cout << "accept's weight is ";
    // ca1.state_weight(final_state)->print(std::cout) << std::endl;

    std::cout << system1 << std::endl << std::endl;
    std::cout << "*** BEFORE ***\n" << ca1 << std::endl;

    // Compute post* image under system1
    wpds::CA< StringWrapper > ca_after_post =
        wpds::poststar< StringWrapper >(system1, ca1, ring);

    std::cout << "*** AFTER  ***\n" << ca_after_post << std::endl;

    // Compute pre* image under system2 using reverse semiring
    wpds::CA< StringWrapper > ca_before_prestar =
        wpds::prestar< StringWrapper >(system2, ca_after_post, ringR);

    wpds::CA< StringWrapper >::catrans_t target_trans;
    target_trans = ca_before_prestar.find(state_pprime, var_x2prime, final_state);

    std::cout << "\n\n AFTER PRESTAR ON WPDS2\n" << ca_before_prestar << std::endl;
    // target_trans->print(std::cout) << std::endl;
    target_trans->print(std::cout) << std::endl;

#if 1
    // Augment automaton with final state if needed
    ca_before_prestar.add_final_state(final_state);
    std::cout << "Calling path_summary...\n";

    std::set< wpds::wpds_key_t > relevant_nonterms;
    relevant_nonterms.insert(nonterm_B);

    ca_before_prestar.path_summary(relevant_nonterms);

    std::cout << "accept's weight is ";
    ca_before_prestar.state_weight(final_state)->print(std::cout) << std::endl;

    std::cout << "p's weight is ";
    ca_before_prestar.state_weight(state_p)->print(std::cout) << std::endl;
#endif

    return 0;
}
