static std::vector<uint8_t> convertStringToBytes(std::string_view str) {
    return std::vector<uint8_t>{(uint8_t*)str.data(), (uint8_t*)str.data() + str.length() + 1};
}

static int convertHexDigit(int hex_char) {
    if (hex_char >= '0' && hex_char <= '9') {
        return hex_char - 0x30;
    }
    if (hex_char >= 'a' && hex_char <= 'f') {
        return hex_char - 0x57;
    }
    if (hex_char >= 'A' && hex_char <= 'F') {
        return hex_char - 0x37;
    }
    return -1;
}

static std::vector<uint8_t> hexDecode(const std::string_view& hex_string) {
    if (hex_string.size() & 1) {
        return {};
    }
    std::vector<uint8_t> decoded_bytes;
    decoded_bytes.reserve(hex_string.size() >> 1);
    for (size_t i = 0; i < hex_string.size(); i += 2) {
        int high_nibble = convertHexDigit(hex_string[i]);
        int low_nibble = convertHexDigit(hex_string[i + 1]);
        if (high_nibble < 0 || low_nibble < 0) {
            return {};
        }
        decoded_bytes.push_back((uint8_t)(high_nibble << 4 | low_nibble));
    }
    return decoded_bytes;
}

