// Locked cache constants
#define LC_BLOCK_COUNT   512
#define CACHE_BLOCK_COUNT 1024

static asm void initializeLockedCache(void) {
    nofralloc
    mfmsr   r5
    ori     r5, r5, 0x1000
    mtmsr   r5
    lis     r3, OS_CACHED_REGION_PREFIX
    li      r4, CACHE_BLOCK_COUNT
    mtctr   r4
_prefetchLoop:
    dcbt    0,r3
    dcbst   0,r3
    addi    r3,r3,32
    bdnz    _prefetchLoop
    mfspr   r4, CACHE_CTRL_REG
    oris    r4, r4, 0x100F
    mtspr   CACHE_CTRL_REG, r4
    nop 
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    lis     r3, LC_BASE_PREFIX
    ori     r3, r3, 0x0002
    mtspr   DBAT3L, r3
    ori     r3, r3, 0x01fe
    mtspr   DBAT3U, r3
    isync
    lis     r3, LC_BASE_PREFIX
    li      r6, LC_BLOCK_COUNT
    mtctr   r6
    li      r6, 0
_lockLoop:
    dcbz_l  r6, r3
    addi    r3, r3, 32
    bdnz+    _lockLoop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    blr
}

void enableLockedCache(void) {
    BOOL interruptState;
    interruptState = OSDisableInterrupts();
    initializeLockedCache();
    OSRestoreInterrupts(interruptState);
}

asm void disableLockedCache(void) {
    nofralloc
    lis     r3, LC_BASE_PREFIX
    li      r4, LC_BLOCK_COUNT
    mtctr r4
@1
    dcbi r0, r3
    addi r3, r3, 32
    bdnz @1
    mfspr r4, CACHE_CTRL_REG
    rlwinm r4, r4, 0, 4, 2
    mtspr CACHE_CTRL_REG, r4
    blr
}

asm void allocateSingleTag(register BOOL shouldInvalidate, register void* tagAddress) {
    nofralloc
    cmpwi shouldInvalidate, 0
    beq @1
    dcbi r0, tagAddress
@1
    dcbz_l r0, tagAddress
    blr
}

asm void allocateMultipleTags(register BOOL shouldInvalidate, register void* startAddress, register u32 blockCount) {
    nofralloc
    mflr r6
    cmplwi blockCount, 0
    ble @3
    mtctr blockCount
    cmpwi shouldInvalidate, 0
    beq @2
@1
    dcbi r0, startAddress
    dcbz_l r0, startAddress
    addi startAddress, startAddress, 32
    bdnz @1
    b @3
@2
    dcbz_l r0, startAddress
    addi startAddress, startAddress, 32
    bdnz @2
@3
    mtlr r6
    blr
}

asm void loadBlocksToLockedCache(register void* targetTag, register void* sourceAddress, register u32 blockCount) {
    nofralloc
    rlwinm  r6, blockCount, 30, 27, 31
    rlwinm  sourceAddress, sourceAddress, 0, 4, 31
    or      r6, r6, sourceAddress
    mtspr   DMA_U, r6
    rlwinm  r6, blockCount, 2, 28, 29
    or      r6, r6, targetTag
    ori     r6, r6, 0x12
    mtspr   DMA_L, r6
    blr
}

asm void storeBlocksFromLockedCache(register void* targetAddress, register void* sourceTag, register u32 blockCount) {
    nofralloc
    rlwinm  r6, blockCount, 30, 27, 31
    rlwinm  targetAddress, targetAddress, 0, 4, 31
    or      r6, r6, targetAddress
    mtspr   DMA_U, r6
    rlwinm  r6, blockCount, 2, 28, 29
    or      r6, r6, sourceTag
    ori     r6, r6, 0x2
    mtspr   DMA_L, r6
    blr
}
