// High-level locked cache functions with modified implementation
void lockCacheAllocate(void* address, u32 sizeInBytes) {
    u32 blocksNeeded = sizeInBytes >> 5;
    u32 controllerStatus = PPCMfhid2();

    // Validate alignment requirements
    ASSERTMSGLINE(1319, !((u32)address & 31), "lockCacheAllocate(): address must be 32-byte aligned");
    ASSERTMSGLINE(1321, !((u32)sizeInBytes & 31), "lockCacheAllocate(): sizeInBytes must be 32-byte aligned");

    // Enable locked cache if needed
    if ((controllerStatus & 0x10000000) == 0) {
        enableLockedCache();
    }

    // Allocate tags with invalidation
    allocateMultipleTags(TRUE, address, blocksNeeded);
}

void lockCacheAllocatePreserve(void* address, u32 sizeInBytes) {
    u32 blocksNeeded = sizeInBytes >> 5;
    u32 controllerStatus = PPCMfhid2();

    // Validate alignment requirements
    ASSERTMSGLINE(1366, !((u32)address & 31), "lockCacheAllocatePreserve(): address must be 32-byte aligned");
    ASSERTMSGLINE(1368, "lockCacheAllocatePreserve(): sizeInBytes must be 32-byte aligned");

    // Enable locked cache if needed
    if ((controllerStatus & 0x10000000) == 0) {
        enableLockedCache();
    }

    // Allocate tags without invalidation
    allocateMultipleTags(FALSE, address, blocksNeeded);
}

u32 transferToLockedCache(void* destination, void* source, u32 sizeInBytes) {
    u32 totalBlocks = (sizeInBytes + 31) / 32;
    u32 transactionCount = (totalBlocks + 128 - 1) / 128;

    // Validate alignment
    ASSERTMSGLINE(1426, !((u32)source & 31), "transferToLockedCache(): source not 32-byte aligned");
    ASSERTMSGLINE(1428, !((u32)destination & 31), "transferToLockedCache(): destination not 32-byte aligned");

    while (totalBlocks > 0) {
        if (totalBlocks < 128) {
            loadBlocksToLockedCache(destination, source, totalBlocks);
            totalBlocks = 0;
        } else {
            loadBlocksToLockedCache(destination, source, 0);
            totalBlocks -= 128;
            destination = (void*)((u32)destination + 4096);
            source = (void*)((u32)source + 4096);
        }
    }
    return transactionCount;
}

u32 transferFromLockedCache(void* destination, void* source, u32 sizeInBytes) {
    u32 totalBlocks = (sizeInBytes + 31) / 32;
    u32 transactionCount = (totalBlocks + 128 - 1) / 128;

    // Validate alignment
    ASSERTMSGLINE(1494, !((u32)source & 31), "transferFromLockedCache(): source not 32-byte aligned");
    ASSERTMSGLINE(1496, !((u32)destination & 31), "transferFromLockedCache(): destination not 32-byte aligned");

    while (totalBlocks > 0) {
        if (totalBlocks < 128) {
            storeBlocksFromLockedCache(destination, source, totalBlocks);
            totalBlocks = 0;
        } else {
            storeBlocksFromLockedCache(destination, source, 0);
            totalBlocks -= 128;
            destination = (void*)((u32)destination + 4096);
            source = (void*)((u32)source + 4096);
        }
    }
    return transactionCount;
}

