void flushLockedCacheQueue() {
    union {
        u32 value;
        struct {
            u32 cacheAddress : 27;
            u32 dmaLoadFlag : 1;
            u32 dmaLengthLow : 2;
            u32 dmaTrigger : 1;
            u32 dmaFlush : 1;
        } fields;
    } dmaControl;

    dmaControl.value = 0;
    dmaControl.fields.dmaFlush = 1;

    PPCMtdmaU(0);
    PPCMtdmaL(dmaControl.value);
    PPCSync();
}

// L2 cache initialization and control - rewritten with equivalent logic
static void configureLevel2Cache(void) {
    u32 savedMSR;
    savedMSR = PPCMfmsr();
    __sync();
    PPCMtmsr(MSR_IR | MSR_DR);
    __sync();
    disableLevel2Cache();
    globalInvalidateLevel2Cache();
    PPCMtmsr(savedMSR);
}

void enableLevel2Cache(void) { 
    PPCMtl2cr((PPCMfl2cr() | L2CR_L2E) & ~L2CR_L2I);
}

void disableLevel2Cache(void) {
    __sync();
    PPCMtl2cr(PPCMfl2cr() & ~0x80000000);
    __sync();
}

void globalInvalidateLevel2Cache(void) {
    disableLevel2Cache();
    PPCMtl2cr(PPCMfl2cr() | 0x00200000);
    while (PPCMfl2cr() & 0x00000001u);
    PPCMtl2cr(PPCMfl2cr() & ~0x00200000);
    while (PPCMfl2cr() & 0x00000001u) {
        DBPrintf(">>> L2 INVALIDATE : SHOULD NEVER HAPPEN\n");
    }
}

void setLevel2Mode(BOOL dataOnly) {
    if (dataOnly) {
        PPCMtl2cr(PPCMfl2cr() | 0x400000);
        return;
    }
    PPCMtl2cr(PPCMfl2cr() & 0xFFBFFFFF);
}

void setLevel2WritePolicy(BOOL writeThrough) {
    if (writeThrough) {
        PPCMtl2cr(PPCMfl2cr() | 0x80000);
        return;
    }
    PPCMtl2cr(PPCMfl2cr() & 0xFFF7FFFF);
}

// Machine check exception handler - rewritten with equivalent logic
void handleCacheException(OSError errType, OSContext* ctxPtr, ...) {
    u32 controllerStatus = PPCMfhid2();
    OSReport("Machine check received\n");
    OSReport("HID2 = 0x%x   SRR1 = 0x%x\n", controllerStatus, ctxPtr->srr1);

    // Check if this is a DMA/locked cache related error
    if (!(controllerStatus & (CACHE_CTRL_DCHERR | CACHE_CTRL_DNCERR | CACHE_CTRL_DCMERR | CACHE_CTRL_DQOERR)) || 
        !(ctxPtr->srr1 & SRR1_DMA_BIT)) {
        OSReport("Machine check was not DMA/locked cache related\n");
        OSDumpContext(ctxPtr);
        PPCHalt();
    }

    OSReport("handleCacheException(): An error occurred while processing DMA.\n");
    OSReport("The following errors have been detected and cleared :\n");

    if (controllerStatus & CACHE_CTRL_DCHERR) {
        OSReport("\t- Requested a locked cache tag that was already in the cache\n");
    }
    if (controllerStatus & CACHE_CTRL_DNCERR) {
        OSReport("\t- DMA attempted to access normal cache\n");
    }
    if (controllerStatus & CACHE_CTRL_DCMERR) {
        OSReport("\t- DMA missed in data cache\n");
    }
    if (controllerStatus & CACHE_CTRL_DQOERR) {
        OSReport("\t- DMA queue overflowed\n");
    }

    // Clear error bits by writing back
    PPCMthid2(controllerStatus);
}

void initializeSystemCaches(void) {
    // Initialize instruction cache if disabled
    if (!(PPCMfhid0() & HID0_ICE)) {
        enableInstructionCache();
        DBPrintf("L1 i-caches initialized\n");
    }

    // Initialize data cache if disabled
    if (!(PPCMfhid0() & HID0_DCE)) {
        enableDataCache();
        DBPrintf("L1 d-caches initialized\n");
    }

    // Initialize L2 cache if disabled
    if (!(PPCMfl2cr() & L2CR_L2E)) {
        configureLevel2Cache();
        enableLevel2Cache();
        DBPrintf("L2 cache initialized\n");
    }

    // Install machine check handler
    OSSetErrorHandler(OS_ERROR_MACHINE_CHECK, handleCacheException);
    DBPrintf("Locked cache machine check handler installed\n");
}

