// Static ID for the MachineDominanceFrontier pass
char MachineDominanceFrontier::ID = 0;

// Pass initialization macro
INITIALIZE_PASS_BEGIN(MachineDominanceFrontier, "machine-domfrontier",
                      "Machine Dominance Frontier Computation", true, true)
INITIALIZE_PASS_DEPENDENCY(MachineDominatorTree)
INITIALIZE_PASS_END(MachineDominanceFrontier, "machine-domfrontier",
                    "Machine Dominance Frontier Computation", true, true)

// Constructor: initializes the pass and registers it with the pass registry
MachineDominanceFrontier::MachineDominanceFrontier() 
    : MachineFunctionPass(ID) {
  initializeMachineDominanceFrontierPass(*PassRegistry::getPassRegistry());
}

// Expose the pass ID externally
char &llvm::MachineDominanceFrontierID = MachineDominanceFrontier::ID;

// Main execution method: computes the dominance frontier for the current function
bool MachineDominanceFrontier::runOnMachineFunction(MachineFunction &MF) {
  // Clear any previously computed results
  releaseMemory();

  // Compute the dominance frontier based on the machine dominator tree
  Base.analyze(getAnalysis<MachineDominatorTree>().getBase());

  // Return false to indicate no modification to the function
  return false;
}

// Release memory used by the underlying dominance frontier structure
void MachineDominanceFrontier::releaseMemory() {
  Base.releaseMemory();
}

// Declare analysis dependencies and preservation properties
void MachineDominanceFrontier::getAnalysisUsage(AnalysisUsage &AU) const {
  // This pass does not modify the function
  AU.setPreservesAll();

  // Requires the machine dominator tree as input
  AU.addRequired<MachineDominatorTree>();

  // Inherit analysis usage from base class
  MachineFunctionPass::getAnalysisUsage(AU);
}

