FAnimBlueprintCompilerHandler_PropertyAccess::FAnimBlueprintCompilerHandler_PropertyAccess(IAnimBlueprintCompilerCreationContext& InCreationContext)
{
    // Register callbacks for class compilation lifecycle events
    InCreationContext.OnStartCompilingClass().BindRaw(this, &FAnimBlueprintCompilerHandler_PropertyAccess::HandleClassCompilationStart);
    InCreationContext.OnFinishCompilingClass().BindRaw(this, &FAnimBlueprintCompilerHandler_PropertyAccess::HandleClassCompilationEnd);
}

int32 FAnimBlueprintCompilerHandler_PropertyAccess::AddCopy(TArrayView<FString> InSourcePath, TArrayView<FString> InDestPath, EPropertyAccessBatchType InBatchType, UObject* InObject)
{
    return PropertyAccessLibraryCompiler.AddCopy(InSourcePath, InDestPath, InBatchType, InObject);
}

void FAnimBlueprintCompilerHandler_PropertyAccess::HandleClassCompilationStart(const UClass* InClass, IAnimBlueprintCompilationBracketContext& InCompilationContext, IAnimBlueprintGeneratedClassCompiledData& OutCompiledData)
{
    PropertyAccessLibraryCompiler.Configure(InClass, &OutCompiledData.GetPropertyAccessLibrary());
    PropertyAccessLibraryCompiler.StartCompilationProcess(InClass);
}

void FAnimBlueprintCompilerHandler_PropertyAccess::HandleClassCompilationEnd(const UClass* InClass, IAnimBlueprintCompilationBracketContext& InCompilationContext, IAnimBlueprintGeneratedClassCompiledData& OutCompiledData)
{
    PreCompilationCompleteEvent.Broadcast();

    if (!PropertyAccessLibraryCompiler.EndCompilation())
    {
        PropertyAccessLibraryCompiler.VisitErrors([&InCompilationContext](const FText& InErrorMessage, UObject* InAffectedObject)
        {
            // Report property access issues as warnings
            if (InAffectedObject)
            {
                InCompilationContext.GetMessageLog().Warning(*InErrorMessage.ToString(), InAffectedObject);
            }
            else
            {
                InCompilationContext.GetMessageLog().Warning(*InErrorMessage.ToString());
            }
        });
    }

    PostCompilationCompleteEvent.Broadcast(OutCompiledData);
}

int32 FAnimBlueprintCompilerHandler_PropertyAccess::MapCopyIndex(int32 InIndex) const
{
    return PropertyAccessLibraryCompiler.MapCopyIndex(InIndex);
}

