class MoeDistributeDispatchV2 : public OpDef {
public:
    explicit MoeDistributeDispatchV2(const char* name) : OpDef(name) {
        // Define inputs
        auto& x = this->Input("x");
        x.ParamType(REQUIRED)
          .DataType({ge::DT_BF16, ge::DT_BF16, ge::DT_FLOAT16, ge::DT_FLOAT16})
          .FormatList({ge::FORMAT_ND})
          .AutoContiguous();

        auto& expert_ids = this->Input("expert_ids");
        expert_ids.ParamType(REQUIRED)
                  .DataTypeList({ge::DT_INT32})
                  .FormatList({ge::FORMAT_ND})
                  .AutoContiguous();

        auto& scales = this->Input("scales");
        scales.ParamType(OPTIONAL)
              .DataTypeList({ge::DT_FLOAT})
              .FormatList({ge::FORMAT_ND})
              .AutoContiguous();

        auto& x_active_mask = this->Input("x_active_mask");
        x_active_mask.ParamType(OPTIONAL)
                     .DataTypeList({ge::DT_BOOL})
                     .FormatList({ge::FORMAT_ND})
                     .AutoContiguous();

        auto& elastic_info = this->Input("elastic_info");
        elastic_info.ParamType(OPTIONAL)
                    .DataTypeList({ge::DT_INT32})
                    .FormatList({ge::FORMAT_ND})
                    .AutoContiguous();

        // Define outputs
        auto& expand_x = this->Output("expand_x");
        expand_x.ParamType(REQUIRED)
                .DataType({ge::DT_BF16, ge::DT_INT8, ge::DT_FLOAT16, ge::DT_INT8})
                .FormatList({ge::FORMAT_ND});

        auto& dynamic_scales = this->Output("dynamic_scales");
        dynamic_scales.ParamType(REQUIRED)
                      .DataTypeList({ge::DT_FLOAT})
                      .FormatList({ge::FORMAT_ND});

        auto& assist_info = this->Output("assist_info_for_combine");
        assist_info.ParamType(REQUIRED)
                   .DataTypeList({ge::DT_INT32})
                   .FormatList({ge::FORMAT_ND});

        auto& expert_token_nums = this->Output("expert_token_nums");
        expert_token_nums.ParamType(REQUIRED)
                         .DataTypeList({ge::DT_INT64})
                         .FormatList({ge::FORMAT_ND});

        auto& ep_recv_count = this->Output("ep_recv_count");
        ep_recv_count.ParamType(REQUIRED)
                     .DataTypeList({ge::DT_INT32})
                     .FormatList({ge::FORMAT_ND});

        auto& tp_recv_count = this->Output("tp_recv_count");
        tp_recv_count.ParamType(REQUIRED)
                     .DataTypeList({ge::DT_INT32})
                     .FormatList({ge::FORMAT_ND});

        // Define required attributes
        this->Attr("group_ep").AttrType(REQUIRED).String();
        this->Attr("ep_world_size").AttrType(REQUIRED).Int();
        this->Attr("ep_rank_id").AttrType(REQUIRED).Int();
        this->Attr("moe_expert_num").AttrType(REQUIRED).Int();

        // Optional attributes with default values
        this->Attr("group_tp").AttrType(OPTIONAL).String("");
        this->Attr("tp_world_size").AttrType(OPTIONAL).Int(0);
        this->Attr("tp_rank_id").AttrType(OPTIONAL).Int(0);
        this->Attr("expert_shard_type").AttrType(OPTIONAL).Int(0);
        this->Attr("shared_expert_num").AttrType(OPTIONAL).Int(1);
        this->Attr("shared_expert_rank_num").AttrType(OPTIONAL).Int(0);
        this->Attr("quant_mode").AttrType(OPTIONAL).Int(0);
        this->Attr("global_bs").AttrType(OPTIONAL).Int(0);
        this->Attr("expert_token_nums_type").AttrType(OPTIONAL).Int(1);
        this->Attr("comm_alg").AttrType(OPTIONAL).String("");
        this->Attr("zero_expert_num").AttrType(OPTIONAL).Int(0);
        this->Attr("copy_expert_num").AttrType(OPTIONAL).Int(0);
        this->Attr("const_expert_num").AttrType(OPTIONAL).Int(0);

        // Build AICore config
        OpAICoreConfig cfg;
        cfg.DynamicCompileStaticFlag(true)
           .DynamicFormatFlag(true)
           .DynamicRankSupportFlag(true)
           .DynamicShapeSupportFlag(true)
           .NeedCheckSupportFlag(false)
           .PrecisionReduceFlag(true);

        // Add extended config info
        cfg.ExtendCfgInfo("aclnnSupport.value", "support_aclnn")
          .ExtendCfgInfo("prebuildPattern.value", "Opaque")
          .ExtendCfgInfo("jitCompile.flag", "static_true")
          .ExtendCfgInfo("multiKernelSupportDynamicGraph.value", "multi_kernel");

        this->AICore().AddConfig("ascend910_93", cfg);

        // HCCL group setup
        this->MC2().HcclGroup({"group_ep", "group_tp"});
    }
};

OP_ADD(MoeDistributeDispatchV2);

