//-------------------------------------------------------------------
DVAPI TSpectrumT<TPixel64> convert(const TSpectrumT<TPixel32> &s) {
  std::vector<TSpectrum64::ColorKey> convertedKeys;
  int keyCount = s.getKeyCount();
  for (int index = 0; index < keyCount; ++index) {
    TSpectrumT<TPixel32>::Key originalKey = s.getKey(index);
    TSpectrum64::ColorKey convertedKey(originalKey.first, toPixel64(originalKey.second));
    convertedKeys.push_back(convertedKey);
  }
  return TSpectrumT<TPixel64>(convertedKeys.size(), convertedKeys.data());
}

