// Construct full PSON path using image host and metadata fields
QString PsonPath(const QString& hostRoot, const QVariantHash& psonData) {
  using namespace PERFORMER_DB_HEADER_KEY;
  return PsonPath(hostRoot,
                  psonData[ENUM_2_STR(Ori)].toString(),
                  psonData[ENUM_2_STR(Name)].toString());
}

// Build QVariantHash from SQL record using compile-time field mapping macros
QVariantHash PerformerJsonJoiner(const QSqlRecord& dbRecord) {
  using namespace PERFORMER_DB_HEADER_KEY;

#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    dbRecord.field(enu).value().sqlRecordToValueFunc(),

  return PerformerJsonJoiner(
      PSON_MODEL_FIELD_MAPPING
      nullptr);

#undef PSON_KEY_ITEM
}

// Internal overload: unpacks macro-defined fields into local variables, then returns initialized hash
QVariantHash PerformerJsonJoiner(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    decltype(defaultValue) _val_##enu,
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
    void* /* unused */) {
  using namespace PERFORMER_DB_HEADER_KEY;

  // Explicit initializer list for clarity; equivalent to original
  QVariantHash result;
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    result.insert(ENUM_2_STR(enu), _val_##enu);
  PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM

  return result;
}

// Serialize performer data into JSON byte array
QByteArray CastValues2PsonStr(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    decltype(defaultValue) _val_##enu,
    PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
    void* /* unused */) {
  // Build intermediate hash via PerformerJsonJoiner
  QVariantHash tempHash = PerformerJsonJoiner(
#define PSON_KEY_ITEM(enu, enumVal, defaultValue, sqlRecordToValueFunc, tblFieldDefinition) \
    _val_##enu,
      PSON_MODEL_FIELD_MAPPING
#undef PSON_KEY_ITEM
      nullptr);

  // Serialize to compact JSON string
  return JsonHelper::SerializedJsonDict2ByteArray(std::move(tempHash));
}

} // namespace CastPsonFileHelper

