// Factory method to create and register a new variable declaration
VarDecl* VarDecl::create(CypherAST* ast,
                         DeclContext* declContext,
                         std::string_view name,
                         EvaluatedType type) {
    // Instantiate the variable declaration
    VarDecl* newDecl = new VarDecl(type, name);

    // Register it with the AST
    ast->addVarDecl(newDecl);

    // Add it to the current declaration context
    declContext->addDecl(newDecl);

    return newDecl;
}

