// Helper function to compute sum using arithmetic progression formula
int compute_sum(int n) {
    return n * (n + 1) / 2;
}

int main() {
    int result = 0;
    // Compute the sum of integers from 1 to 5 using direct calculation
    int upper_limit = 5;
    result = compute_sum(upper_limit);

    std::cout << result << std::endl;
    return 0;
}

