#ifndef H5_NO_DEPRECATED_SYMBOLS

/*--------------------------------------------------------------------------
 NAME
    H5Rget_obj_type1
 PURPOSE
    Determine the type of object referenced by a legacy object reference
 USAGE
    H5G_obj_t H5Rget_obj_type1(id, ref_type, ref)
        hid_t id;           IN: Dataset location or group ID containing ref
        H5R_type_t ref_type; IN: Type of reference (e.g., H5R_OBJECT1)
        const void *ref;    IN: Pointer to raw reference data
 RETURNS
    On success: Object type constant from H5Gpublic.h (e.g., H5G_GROUP)
    On failure: H5G_UNKNOWN
 DESCRIPTION
    Given a legacy object reference, this function resolves the underlying
    HDF5 object type and maps it to the legacy group object type enum.
    This is provided for backward compatibility with older APIs.
 GLOBAL VARIABLES
 COMMENTS, BUGS, ASSUMPTIONS
 EXAMPLES
 REVISION LOG
--------------------------------------------------------------------------*/
H5G_obj_t
H5Rget_obj_type1(hid_t id, H5R_type_t ref_type, const void *ref)
{
    H5G_loc_t loc;              /* Location structure for input ID */
    H5O_type_t obj_type;        /* Internal HDF5 object type */
    H5G_obj_t result;           /* Return value in legacy enum */

    FUNC_ENTER_API(H5G_UNKNOWN)
    H5TRACE3("Go", "iRt*x", id, ref_type, ref);

    /* Validate arguments */
    if (H5G_loc(id, &loc) < 0)
        HGOTO_ERROR(H5E_ARGS, H5E_BADTYPE, H5G_UNKNOWN, "invalid location identifier")
    if (ref_type <= H5R_BADTYPE || ref_type >= H5R_MAXTYPE)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, H5G_UNKNOWN, "unsupported reference type")
    if (ref == NULL)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, H5G_UNKNOWN, "null reference pointer")

    /* Query object type via internal routine */
    if (H5R_get_obj_type(loc.oloc->file, H5AC_ind_dxpl_id, ref_type, ref, &obj_type) < 0)
        HGOTO_ERROR(H5E_REFERENCE, H5E_CANTINIT, H5G_UNKNOWN, "cannot resolve object type")

    /* Map internal type to legacy group object type */
    result = H5G_map_obj_type(obj_type);

done:
    FUNC_LEAVE_API(result)
}   /* end H5Rget_obj_type1() */
#endif /* H5_NO_DEPRECATED_SYMBOLS */

#include <cstdio>

// Initialize all timers in the control structure to zero
void SetupTimers(ctrl_t *ctrl)
{
    gk_clearcputimer(ctrl->TotalTmr);
    gk_clearcputimer(ctrl->InitPartTmr);
    gk_clearcputimer(ctrl->MatchTmr);
    gk_clearcputimer(ctrl->ContractTmr);
    gk_clearcputimer(ctrl->CoarsenTmr);
    gk_clearcputimer(ctrl->UncoarsenTmr);
    gk_clearcputimer(ctrl->RefTmr);
    gk_clearcputimer(ctrl->ProjectTmr);
    gk_clearcputimer(ctrl->SplitTmr);
    gk_clearcputimer(ctrl->Aux1Tmr);
    gk_clearcputimer(ctrl->Aux2Tmr);
    gk_clearcputimer(ctrl->Aux3Tmr);
}

/*************************************************************************
* This function displays timing statistics for various phases of the algorithm
**************************************************************************/
void ShowTimings(ctrl_t *ctrl)
{
    printf("\nTiming Information -------------------------------------------------");
    printf("\n Total Time: \t\t %7.3"PRREAL"", gk_getcputimer(ctrl->TotalTmr));
    printf("\n Coarsening Phase: \t\t %7.3"PRREAL"", gk_getcputimer(ctrl->CoarsenTmr));
    printf("\n   - Matching Step: \t\t\t %7.3"PRREAL"", gk_getcputimer(ctrl->MatchTmr));
    printf("\n   - Contraction Step: \t\t\t %7.3"PRREAL"", gk_getcputimer(ctrl->ContractTmr));
    printf("\n Initial Partitioning: \t %7.3"PRREAL"", gk_getcputimer(ctrl->InitPartTmr));
    printf("\n Uncoarsening Phase: \t\t %7.3"PRREAL"", gk_getcputimer(ctrl->UncoarsenTmr));
    printf("\n   - Refinement Step: \t\t\t %7.3"PRREAL"", gk_getcputimer(ctrl->RefTmr));
    printf("\n   - Projection Step: \t\t\t %7.3"PRREAL"", gk_getcputimer(ctrl->ProjectTmr));
