std::string ToUtf8(std::u16string_view utf16)
{
  std::string result;
  utf8::unchecked::utf16to8(utf16.begin(), utf16.end(), std::back_inserter(result));
  return result;
}
std::string ToUtf8(std::u32string_view utf32)
{
