using namespace NPerforator::NLinguist::NPython;

// Forward declaration of TryScanVersion function
namespace NPerforator::NLinguist::NPython {
    TMaybe<TPythonVersion> TryScanVersion(TConstArrayRef<char> data);
}

TEST(PythonVersionParsing, TryScanVersion) {
    // Test cases for version parsing
    struct TestCase {
        TString InputString;
        bool ExpectedSuccess;
        TPythonVersion ExpectedResult;
    };

    TVector<TestCase> testSuites = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},   // Unsupported major version
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}},  // Invalid major version
    };

    for (const auto& testCase : testSuites) {
        TMaybe<TPythonVersion> parsedVersion = TryScanVersion(
            TConstArrayRef<char>{testCase.InputString.data(), testCase.InputString.size()}
        );

        if (testCase.ExpectedSuccess) {
            ASSERT_TRUE(parsedVersion.Defined()) 
                << "Expected successful parse for input: '" << testCase.InputString << "'";

            TString expectedStr = std::to_string(testCase.ExpectedResult.MajorVersion) + "." +
                                  std::to_string(testCase.ExpectedResult.MinorVersion) + "." +
                                  std::to_string(testCase.ExpectedResult.MicroVersion);
            TString actualStr = std::to_string(parsedVersion->MajorVersion) + "." +
                                std::to_string(parsedVersion->MinorVersion) + "." +
                                std::to_string(parsedVersion->MicroVersion);

            EXPECT_EQ(parsedVersion->MajorVersion, testCase.ExpectedResult.MajorVersion)
                << "Major version mismatch for '" << testCase.InputString << "'"
                << "\nExpected: " << expectedStr << ", Got: " << actualStr;
            EXPECT_EQ(parsedVersion->MinorVersion, testCase.ExpectedResult.MinorVersion)
                << "Minor version mismatch for '" << testCase.InputString << "'"
                << "\nExpected: " << expectedStr << ", Got: " << actualStr;
            EXPECT_EQ(parsedVersion->MicroVersion, testCase.ExpectedResult.MicroVersion)
                << "Micro version mismatch for '" << testCase.InputString << "'"
                << "\nExpected: " << expectedStr << ", Got: " << actualStr;
        } else {
            EXPECT_FALSE(parsedVersion.Defined())
                << "Should not have parsed version from: '" << testCase.InputString << "'";
        }
    }
}

