#include <gtest/gtest.h>
#include <jonssonic/core/common/circular_audio_buffer.h>

using namespace jnsc;

// Test buffer initialization and basic write/read operations
TEST(CircularAudioBufferTest, ResizeAndWriteRead) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 8);

    ASSERT_EQ(audioBuffer.getNumChannels(), 2u);
    ASSERT_EQ(audioBuffer.getBufferSize(), 8u);

    // Write sample values to each channel
    audioBuffer.write(0, 1.0f);
    audioBuffer.write(1, 2.0f);

    // Verify the written values can be read back correctly
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 1.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 2.0f);
}

// Test circular behavior when data exceeds buffer capacity
TEST(CircularAudioBufferTest, WrapAround) {
    CircularAudioBuffer<float> ringBuffer;
    ringBuffer.resize(1, 4);

    // Overwrite data to trigger wrap-around effect
    for (int idx = 0; idx < 6; ++idx)
        ringBuffer.write(0, static_cast<float>(idx));

    // After writing [0,1,2,3,4,5], only last 4 samples remain: [2,3,4,5]
    // Read order is newest first: 5,4,3,2
    EXPECT_FLOAT_EQ(ringBuffer.read(0, 0), 5.0f);
    EXPECT_FLOAT_EQ(ringBuffer.read(0, 1), 4.0f);
    EXPECT_FLOAT_EQ(ringBuffer.read(0, 2), 3.0f);
    EXPECT_FLOAT_EQ(ringBuffer.read(0, 3), 2.0f);
}

// Test clearing the buffer and subsequent writes
TEST(CircularAudioBufferTest, Clear) {
    CircularAudioBuffer<float> sampleBuffer;
    sampleBuffer.resize(1, 4);

    sampleBuffer.write(0, 1.0f);
    sampleBuffer.write(0, 2.0f);
    sampleBuffer.clear();

    // After clear, new data should start fresh
    sampleBuffer.write(0, 3.0f);
    EXPECT_FLOAT_EQ(sampleBuffer.read(0, 0), 3.0f);
}

// Test multi-channel buffer with interleaved writes
TEST(CircularAudioBufferTest, MultiChannel) {
    CircularAudioBuffer<float> multiChanBuffer;
    multiChanBuffer.resize(2, 4);

    // Fill both channels with sequential data
    for (int pos = 0; pos < 4; ++pos) {
        multiChanBuffer.write(0, static_cast<float>(pos));
        multiChanBuffer.write(1, static_cast<float>(pos + 10));
    }

    // Verify latest entries in each channel
    EXPECT_FLOAT_EQ(multiChanBuffer.read(0, 0), 3.0f);
    EXPECT_FLOAT_EQ(multiChanBuffer.read(1, 0), 13.0f);

    // Verify oldest entries in each channel
    EXPECT_FLOAT_EQ(multiChanBuffer.read(0, 3), 0.0f);
    EXPECT_FLOAT_EQ(multiChanBuffer.read(1, 3), 10.0f);
}

