// Helper function to parse TOFSense-M Frame0 data (renamed for clarity)
void decodeTofsensemData(const uint8_t *buffer, size_t buffer_size) {
    if (g_ntsm_frame0.UnpackData(buffer, buffer_size)) {
        printf("TOFSense-M Frame0 %d Pixel data decoded successfully:\r\n",
               g_ntsm_frame0.pixel_count);
        printf("id:%d, system_time:%d\r\n", g_ntsm_frame0.id,
               g_ntsm_frame0.system_time);
        for (int idx = 0; idx < g_ntsm_frame0.pixel_count; ++idx) {
            ntsm_frame0_pixel_t *pixel = &g_ntsm_frame0.pixels[idx];
            printf("pixel %d: dis:%f, dis_status:%d, signal_strength:%d\r\n", idx,
                   pixel->dis, pixel->dis_status, pixel->signal_strength);
        }
    } else {
        printf("decoding error\n");
    }
}

