namespace {
TEST(misc, version_check) {
    // Verify computed version matches expected format
    EXPECT_EQ(PROJ_COMPUTE_VERSION(2200, 98, 76), 22009876);

    // Confirm version number calculation using macros
    int calculated_version = PROJ_VERSION_MAJOR * 10000 +
                             PROJ_VERSION_MINOR * 100 +
                             PROJ_VERSION_PATCH;
    EXPECT_EQ(PROJ_VERSION_NUMBER, calculated_version);

    // Test version comparison functions
    EXPECT_TRUE(PROJ_AT_LEAST_VERSION(PROJ_VERSION_MAJOR, 
                                      PROJ_VERSION_MINOR, 
                                      PROJ_VERSION_PATCH));

    // Should pass with one minor version less
    EXPECT_TRUE(PROJ_AT_LEAST_VERSION(PROJ_VERSION_MAJOR - 1,
                                      PROJ_VERSION_MINOR, 
                                      PROJ_VERSION_PATCH));

    // Should fail when patch is incremented by 1
    EXPECT_FALSE(PROJ_AT_LEAST_VERSION(PROJ_VERSION_MAJOR, 
                                       PROJ_VERSION_MINOR, 
                                       PROJ_VERSION_PATCH + 1));
}
