#include "trie.h"
#include <gtest/gtest.h>

class TrieTest : public ::testing::Test
{
protected:
    void SetUp() override
    {
        // Reset or initialize any shared state if needed (currently no-op)
    }
};

// Helper lambda to reduce repetition in tests
auto classify = [](const std::string& instr, int arch) -> InstCategory {
    return Trie::inst_type(instr, arch);
};

TEST_F(TrieTest, VectorALUOperationsAreCorrectlyClassified)
{
    EXPECT_EQ(classify("v_add_f32", 10), InstCategory::VALU);
    EXPECT_EQ(classify("v_mul_f16", 11), InstCategory::VALU);
    EXPECT_EQ(classify("v_cmp_eq_u32", 12), InstCategory::VALU);
    EXPECT_EQ(classify("v_mfma_f32_32x32x8f16", 9), InstCategory::VALU);
}

TEST_F(TrieTest, MFMA_ScaleIsSpecialOnGfx9)
{
    EXPECT_EQ(classify("v_mfma_scale_f32_32x32x64_f8f6f4", 9), InstCategory::MFMA_SCALE);
    EXPECT_EQ(classify("v_mfma_scale_f32_32x32x64_f8f6f4", 10), InstCategory::VALU);
}

TEST_F(TrieTest, SynchronizationWaitOpsAreImmediate)
{
    EXPECT_EQ(classify("s_waitcnt vmcnt(0)", 10), InstCategory::IMMED);
    EXPECT_EQ(classify("s_wait_idle", 11), InstCategory::IMMED);
    EXPECT_EQ(classify("s_wait_kmcnt 0", 12), InstCategory::IMMED);
    EXPECT_EQ(classify("s_wait_loadcnt 0", 12), InstCategory::IMMED);
    EXPECT_EQ(classify("s_wait_storecnt 0", 12), InstCategory::IMMED);
}

TEST_F(TrieTest, ConditionalAndUnconditionalBranchesAreRecognized)
{
    EXPECT_EQ(classify("s_cbranch_scc0 -5", 10), InstCategory::BRANCH);
    EXPECT_EQ(classify("s_cbranch_execz 10", 11), InstCategory::BRANCH);
    EXPECT_EQ(classify("s_branch 100", 9), InstCategory::BRANCH);
}

TEST_F(TrieTest, ScalarMemoryInstructionsUseSMEM)
{
    EXPECT_EQ(classify("s_load_dwordx4 s[0:3], s[4:5], 0x0", 10), InstCategory::SMEM);
    EXPECT_EQ(classify("s_buffer_load_dword", 11), InstCategory::SMEM);
    EXPECT_EQ(classify("s_atomic_add", 12), InstCategory::SMEM);
}

TEST_F(TrieTest, VectorMemoryInstructionsUseVMEM)
{
    EXPECT_EQ(classify("buffer_load_dword v0, v1, s[0:3], 0", 10), InstCategory::VMEM);
    EXPECT_EQ(classify("global_load_dword v0, v[1:2], off", 11), InstCategory::VMEM);
    EXPECT_EQ(classify("scratch_load_dword v0, v1, off", 12), InstCategory::VMEM);
}

TEST_F(TrieTest, LDSAccessOpsAreLDSCategory)
{
    EXPECT_EQ(classify("ds_read_b32 v0, v1", 10), InstCategory::LDS);
    EXPECT_EQ(classify("ds_write_b64 v0, v[1:2]", 11), InstCategory::LDS);
}

TEST_F(TrieTest, FlatMemoryOpsFallUnderFLAT)
{
    EXPECT_EQ(classify("flat_load_dword v0, v[1:2]", 10), InstCategory::FLAT);
    EXPECT_EQ(classify("flat_store_dword v[0:1], v2", 11), InstCategory::FLAT);
}

TEST_F(TrieTest, ScalarALUOpsAreSALU)
{
    EXPECT_EQ(classify("s_add_u32 s0, s1, s2", 10), InstCategory::SALU);
    EXPECT_EQ(classify("s_mov_b32 s0, 0", 11), InstCategory::SALU);
    EXPECT_EQ(classify("s_and_b64 s[0:1], s[2:3], s[4:5]", 12), InstCategory::SALU);
    EXPECT_EQ(classify("s_cmp_eq_u32 s0, s1", 9), InstCategory::SALU);
}

TEST_F(TrieTest, DependencyWaitOpsAreSKIP)
{
    EXPECT_EQ(classify("s_wait_dep 0", 12), InstCategory::SKIP);
    EXPECT_EQ(classify("s_wait_alu 0x0", 12), InstCategory::SKIP);
    EXPECT_EQ(classify("s_delay_alu", 11), InstCategory::SKIP);
}

TEST_F(TrieTest, BVHInstructionsAreBVHCategory)
{
    EXPECT_EQ(classify("image_bvh_intersect_ray", 10), InstCategory::BVH);
    EXPECT_EQ(classify("image_bvh64_intersect_ray", 11), InstCategory::BVH);
}

TEST_F(TrieTest, UnknownScalarOpsDefaultToSALU)
{
    EXPECT_EQ(classify("s_unknown_instruction", 10), InstCategory::SALU);
}

TEST_F(TrieTest, ControlFlowOpsAreImmediate)
{
    EXPECT_EQ(classify("s_endpgm", 10), InstCategory::IMMED);
    EXPECT_EQ(classify("s_trap 0x1", 11), InstCategory::IMMED);
    EXPECT_EQ(classify("s_nop 0", 12), InstCategory::IMMED);
    EXPECT_EQ(classify("s_sleep 10", 9), InstCategory::IMMED);
}

// Edge cases
TEST_F(TrieTest, EmptyInputYieldsDontKnow)
{
    EXPECT_EQ(classify("", 10), InstCategory::DONT_KNOW);
}

TEST_F(TrieTest, WhitespaceOnlyInputYieldsDontKnow)
{
    EXPECT_EQ(classify("   ", 10), InstCategory::DONT_KNOW);
}

TEST_F(TrieTest, UnrecognizedInstructionDefaultsToDontKnow)
{
    EXPECT_EQ(classify("xyz_unknown_instruction", 10), InstCategory::DONT_KNOW);
}

TEST_F(TrieTest, ImageOpsAreVMEMUnlessSpecifiedOtherwise)
{
    EXPECT_EQ(classify("image_load v0, v[1:2], s[0:7]", 10), InstCategory::VMEM);
    EXPECT_EQ(classify("image_store v0, v[1:2], s[0:7]", 11), InstCategory::VMEM);
    EXPECT_EQ(classify("image_atomic_add v0, v[1:2], s[0:7]", 12), InstCategory::VMEM);
    EXPECT_EQ(classify("image_gather4 v[0:3], v[1:2], s[0:7]", 10), InstCategory::VMEM);
    EXPECT_EQ(classify("image_sample v0, v[1:2], s[0:7], s[8:11]", 11), InstCategory::VMEM);
}

TEST_F(TrieTest, MfmaScaleNotSpecialOnNonGfx9)
{
    EXPECT_EQ(classify("v_mfma_scale_f32_32x32x64_f8f6f4", 11), InstCategory::VALU);
    EXPECT_EQ(classify("v_mfma_scale_f32_32x32x64_f8f6f4", 12), InstCategory::VALU);
}

TEST_F(TrieTest, BranchDetectionHandlesOperandsAndVariants)
{
    EXPECT_EQ(classify("s_cbranch_vccz 0x10", 10), InstCategory::BRANCH);
    EXPECT_EQ(classify("s_cbranch_vccnz label", 11), InstCategory::BRANCH);
    EXPECT_EQ(classify("s_cbranch_cdbgsys", 12), InstCategory::BRANCH);
}

