#include <bpf/bpf.h>

// Tracepoint structure for scheduler switch event
struct sched_switch_event {
    u64 reserved;
    char prev_task_name[16];
    u32 prev_process_id;
    u32 prev_priority;
    u64 prev_state_flag;
    char next_task_name[16];
    u32 next_process_id;
    u32 next_priority;
};

// Custom data container for storing large buffers
struct large_data_container {
    u8 storage[1024];
};

BTF_EXPORT(struct large_data_container);

// Define a BPF map structure with specific attributes
BPF_MAP_STRUCT(memory_pool, BPF_MAP_TYPE_ARRAY, u32, struct large_data_container, 400 * 1024, 0);

// Nested map configuration: array of maps
struct {
    BPF_MAP_DEF_UINT(type, BPF_MAP_TYPE_ARRAY_OF_MAPS);
    BPF_MAP_DEF_UINT(key_size, sizeof(u32));
    BPF_MAP_DEF_UINT(max_entries, 1024);
    BPF_MAP_DEF_ARRAY(entries, struct memory_pool);
} multi_gigabyte_storage SEC(BPF_SEC_BTF_MAPS);

// Attach to the scheduler switch tracepoint
SEC("tracepoint/sched/sched_switch")
int on_scheduler_switch(struct sched_switch_event* event) {
    BPF_PRINTK("Scheduler event: %d -> %d\n", event->prev_process_id, event->next_process_id);
    return 0;
}

