// ============================
// Global headers configuration tests
// ============================
TEST(HttpServerConfigTest, ReplaceAllGlobalHeaders) {
  HttpServerConfig cfg;
  std::vector<http::Header> initial_headers = {
      http::Header{"X-Valid", "value"}, 
      http::Header{"X-Custom", "value"}
  };
  cfg.withGlobalHeaders(initial_headers);
  ASSERT_EQ(cfg.globalHeaders.nbConcatenatedStrings(), 2U);

  std::vector<http::Header> replacement_headers = {
      http::Header{"X-Valid2", "value"}, 
      http::Header{"X-Custom2", "value"}
  };
  cfg.withGlobalHeaders(replacement_headers);
  EXPECT_EQ(cfg.globalHeaders.nbConcatenatedStrings(), 2U);

  cfg.withGlobalHeaders({});
  EXPECT_TRUE(cfg.globalHeaders.empty());
  EXPECT_NO_THROW(cfg.validate());
}

TEST(HttpServerConfigTest, EmptyGlobalHeadersIsValid) {
  HttpServerConfig cfg;
  cfg.withGlobalHeaders({});
  EXPECT_TRUE(cfg.globalHeaders.empty());
  EXPECT_NO_THROW(cfg.validate());
  EXPECT_TRUE(cfg.globalHeaders.empty());
}

TEST(HttpServerConfigTest, AddSingleGlobalHeader) {
  HttpServerConfig cfg;
  cfg.addGlobalHeader(http::Header{"X-Test", "value"});
  EXPECT_NO_THROW(cfg.validate());
}

TEST(HttpServerConfigTest, ValidHeaderKeys) {
  HttpServerConfig cfg;
