// Safely zero out a memory region in a way that compilers cannot optimize away
void SecureZero(void* pointer, size_t count) noexcept {
#ifdef _MSC_VER
    // Use Windows-specific secure zero function on MSVC
    SecureZeroMemory(pointer, count);
#elif defined(__STDC_LIB_EXT1__) && defined(memset_s)
    // Use C11 bounds-checking interface if available
    memset_s(pointer, count, 0, count);
#else
    // Fallback: use volatile pointer to prevent compiler optimization
    volatile unsigned char* vPtr = static_cast<volatile unsigned char*>(pointer);
    for (size_t i = 0; i < count; ++i) {
        vPtr[i] = 0;
    }
#endif
}

