#include <GetBulkProfileDataProcessor.h>
#include <BulkProfileDataMessage.pb.h>
#include <ProfileData.pb.h>
#include <PlayerDatabase.h>

GetBulkProfileDataProcessor::GetBulkProfileDataProcessor(SpectreRpcType rpcType) 
    : WebsocketPacketProcessor(rpcType) {
}

void GetBulkProfileDataProcessor::Process(SpectreWebsocketRequest& packet, SpectreWebsocket& sock) {
    // Extract the request payload as a GetBulkProfileDataMessage
    std::unique_ptr<GetBulkProfileDataMessage> request = packet.GetPayloadAsMessage<GetBulkProfileDataMessage>();

    // Prepare the response object
    BulkProfileDataResponse response;

    // Iterate through all player IDs in the request
    int count = request->playerids_size();
    for (int index = 0; index < count; ++index) {
        // Retrieve ProfileData for each player ID and add it to the response
        ProfileData* profileData = PlayerDatabase::Get().GetField<ProfileData>(
            FieldKey::PROFILE_DATA, 
            request->playerids(index)
        );

        // Add a new entry to the bulk profile data list and copy the data
        response.add_bulkprofiledata()->CopyFrom(*profileData);
    }

    // Send the response back through the websocket connection
    sock.SendPacket(response, packet.GetResponseType(), packet.GetRequestId());
}

#include "RigUnit_GetRelativeTransform.h"
#include "Units/Math/RigUnit_MathTransform.h"
#include "Units/Hierarchy/RigUnit_GetTransform.h"
#include "Units/RigUnitContext.h"

FRigUnit_GetRelativeTransformForItem_Execute()
{
    DECLARE_SCOPE_HIERARCHICAL_COUNTER_RIGUNIT()

    // Initialize output transform
    FTransform OutputTransform = FTransform::Identity;

    // Retrieve transforms using helper variables
    FTransform SourceBoneTM = FTransform::Identity;
    FTransform TargetBoneTM = FTransform::Identity;

    // Get the global space transform for the child bone
    FRigUnit_GetTransform::StaticExecute(
        RigVMExecuteContext, 
        Child, 
        EBoneGetterSetterMode::GlobalSpace, 
        bChildInitial, 
        SourceBoneTM, 
        CachedChild, 
        Context
    );

    // Get the global space transform for the parent bone
    FRigUnit_GetTransform::StaticExecute(
        RigVMExecuteContext, 
        Parent, 
        EBoneGetterSetterMode::GlobalSpace, 
        bParentInitial, 
        TargetBoneTM, 
        CachedParent, 
        Context
    );

    // Calculate relative transform by making source relative to target
    FRigUnit_MathTransformMakeRelative::StaticExecute(
        RigVMExecuteContext, 
        SourceBoneTM, 
        TargetBoneTM, 
        OutputTransform, 
        Context
    );

    // Assign the computed relative transform to the output parameter
    RelativeTransform = OutputTransform;
}

