// Minimal crash handler implementation for debugging purposes
namespace sdb {

void CrashHandler::logBacktrace() {
    // Intentionally left empty in this mock version
}

[[noreturn]] void CrashHandler::crash(std::string_view reason) {
    std::cerr << "[LightCrashHandler] " << reason << std::endl;
    std::cerr.flush();
    std::terminate();
}

[[noreturn]] void CrashHandler::assertionFailure(const char* file, int line,
                                                 const char* func,
                                                 const char* condition,
                                                 const char* details) {
    std::string error_msg;
    absl::strings_internal::OStringStream stream{&error_msg};

    stream << "Assertion failed at " << file << ":" << line 
           << " in function '" << (func ? func : "") << "'\n"
           << "Expression: " << (condition ? condition : "") << "\n";

    if (details && details[0] != '\0') {
        stream << "Message: " << details << "\n";
    }

    stream << std::endl;

    CrashHandler::crash(error_msg);
}

