// Helper to register common attributes for types/members
inline auto make_attributes(std::initializer_list<entt::attribute> attrs) {
    return entt::attributes{attrs};
}

// Lambda to simplify repeated data registration with tooltip/min/max/etc.
template<typename T, typename M>
void register_data_with_attrs(entt::meta_factory<T>& factory, M ptr, std::string_view name,
                              std::string_view pretty_name, std::initializer_list<entt::attribute> extra = {}) {
    factory.data(ptr, name);
    factory.custom(make_attributes({
        entt::attribute{"name", std::string{name}},
        entt::attribute{"pretty_name", std::string{pretty_name}}
    }));
    for (const auto& attr : extra) {
        factory.custom(attr);
    }
}

