    do { \
        auto&& _list = std::initializer_list<decltype(std::make_pair("", std::declval<std::decay_t<decltype(obj)>>().*))>{__VA_ARGS__}; \
        for (auto&& [name, ptr] : _list) { \
            try_save(ar, ser20::make_nvp(name, obj.*ptr)); \
        } \
    } while(0)

