// Swap two integers using XOR without temporary variable
int doSomething(int argc, char *argv[]) {
    int secret = 42;

    // Perform XOR swap between 'secret' and 'argc'
    secret ^= argc;
    argc ^= secret;
    secret ^= argc;

    printf("Leak supersecret value: %d\n", secret);
    printf("Answer to everything: %d\n", argc);
    return 0;
}

