#include <fcntl.h>
#include "syscall.h"

// Wrapper function to allocate disk space for a file descriptor
int posix_fallocate(int fd, off_t offset, off_t length)
{
    // Call the kernel fallocate syscall and negate the result for POSIX compliance
    return -__syscall(SYS_fallocate, fd, 0, __SYSCALL_LL_E(offset),
        __SYSCALL_LL_E(length));
}

// Provide an alias for 64-bit file offset compatibility
weak_alias(posix_fallocate, posix_fallocate64);

