std::shared_ptr<Colist::colist<std::shared_ptr<Nat>>>
Colist::nats(std::shared_ptr<Nat> start_num) {
    // Helper lambda to generate natural numbers recursively
    auto generate_sequence = [&](std::function<std::shared_ptr<Colist::colist<std::shared_ptr<Nat>>>(std::shared_ptr<Nat>)> self_ref) 
        -> std::function<std::shared_ptr<Colist::colist<std::shared_ptr<Nat>>>(std::shared_ptr<Nat>)> {
        return [self_ref](std::shared_ptr<Nat> current) 
            -> std::shared_ptr<Colist::colist<std::shared_ptr<Nat>>> {
            return colist<std::shared_ptr<Nat>>::ctor::lazy_(
                [=]() -> std::shared_ptr<Colist::colist<std::shared_ptr<Nat>>> {
                    return colist<std::shared_ptr<Nat>>::ctor::cocons_(
                        current, self_ref(self_ref)(Nat::ctor::S_(current)));
                });
        };
    };

    // Create the generator function and apply it to the starting number
    auto nats_generator = generate_sequence(generate_sequence);
    return nats_generator(start_num);
}

