};

void OreRecipies::_init() {
    // Initialize with known ore recipes using a more explicit approach
    std::vector<OreRecipe> tempRecipes;

    // Add gold recipe
    tempRecipes.push_back({Tile::goldBlock, ItemInstance(Item::goldIngot, 9)});
    // Add iron recipe
    tempRecipes.push_back({Tile::ironBlock, ItemInstance(Item::ironIngot, 9)});
    // Add diamond recipe
    tempRecipes.push_back({Tile::diamondBlock, ItemInstance(Item::diamond, 9)});
    // Add emerald recipe
    tempRecipes.push_back({Tile::emeraldBlock, ItemInstance(Item::emerald, 9)});
    // Add lapis recipe with special color parameter
    tempRecipes.push_back({Tile::lapisBlock, ItemInstance(Item::dye_powder, 9, DyePowderItem::BLUE)});

    // Convert to internal storage format
    map = new std::vector<Object*>[MAX_ORE_RECIPES];
    for (size_t idx = 0; idx < tempRecipes.size(); ++idx) {
        ADD_OBJECT(map[idx], tempRecipes[idx].inputTile);
        ADD_OBJECT(map[idx], new ItemInstance(tempRecipes[idx].outputInstance));
    }
}

void OreRecipies::addRecipes(Recipes* r) {
    // Process each recipe pair using index-based iteration
    int recipeCount = MAX_ORE_RECIPES;
    for (int recipeIndex = 0; recipeIndex < recipeCount; ++recipeIndex) {
        // Extract components from stored data
        Tile* sourceTile = static_cast<Tile*>(map[recipeIndex].at(0)->tile);
        ItemInstance* resultItem = static_cast<ItemInstance*>(map[recipeIndex].at(1)->iteminstance);

        // Create block-to-ingot crafting recipe
        r->addShapedRecipy(
            new ItemInstance(sourceTile),
            L"sssczg",
            L"###", 
            L"###", 
            L"###", 
            L'#',
            resultItem,
            L'D'
        );

        // Create ingot-to-block crafting recipe
        r->addShapedRecipy(
            resultItem,
            L"sctg",
            L"#", 
            L'#',
            sourceTile,
            L'D'
        );
    }
}

