                reg_map_table[source_info->detail->x86.operands[i].mem.index].id;
            result->x86.operands[i].mem.scale =
                source_info->detail->x86.operands[i].mem.scale;
            result->x86.operands[i].mem.disp =
                source_info->detail->x86.operands[i].mem.disp;
        }

        result->x86.operands[i].size = source_info->detail->x86.operands[i].size;

        // Handle access types with switch restructuring
        switch (source_info->detail->x86.operands[i].access) {
            case CS_AC_READ:
                result->x86.operands[i].access = dt_CS_AC_READ;
                break;
            case CS_AC_WRITE:
                result->x86.operands[i].access = dt_CS_AC_WRITE;
                break;
            case (CS_AC_READ | CS_AC_WRITE):
                result->x86.operands[i].access = dt_CS_AC_READ | dt_CS_AC_WRITE;
                break;
        }

        result->x86.operands[i].avx_bcast =
            bcast_map_table[source_info->detail->x86.operands[i].avx_bcast].id;
        result->x86.operands[i].avx_zero_opmask =
            source_info->detail->x86.operands[i].avx_zero_opmask;
    }

    result->x86.avx_cc = avx_cc_map_table[source_info->detail->x86.avx_cc].id;
    result->size = source_info->size;
    result->address = source_info->address;
    return result;
}

int get_disassembly(const uint8_t *code, size_t code_size,
        uint64_t address,
        size_t count, struct la_dt_insn **output_insn,
        int instr_index, void *instruction_base)
{
    cs_insn *disasm_result;
    struct la_dt_insn *converted;
    dtassert(capstone_handle);

    int result_count = latx_cs_disasm(capstone_handle, code, code_size,
        address, count, &disasm_result, 0, temp_buffer);

    if (disasm_result == NULL) {
        *output_insn = NULL;
        qemu_log_mask(LAT_LOG_DT, "%s: can't disasm code 0x%x\n",
            __func__, *(uint32_t *)code);
        return result_count;
    }

    converted = convert_disasm_result(disasm_result, instr_index, instruction_base);
    *output_insn = converted;
    return result_count;
}

