// Modified initialization function
static void initialize_capstone_system(int abi_version)
{
    int mode = 0;
    current_mode_flags = abi_version;

    if (abi_version == 32) {
        mode = CS_MODE_32;
    } else {
        mode = CS_MODE_64;
    }

    if (cs_open(CS_ARCH_X86, mode, &capstone_handle) != CS_ERR_OK) {
        fprintf(stderr, "%s %s %d error : cs_open\n",
                __FILE__, __func__, __LINE__);
        exit(-1);
    }

    cs_option(capstone_handle, CS_OPT_DETAIL, CS_OPT_ON);
}

void capstone_wrapper_init(int abi_bits)
{
#ifdef CONFIG_LATX_CAPSTONE_NEXT
    dtassert(handle != NULL);
    capstone_handle = handle;
#else
    initialize_capstone_system(abi_bits);
#endif
    initialize_instruction_mapping();
    initialize_register_mapping();
    initialize_broadcast_mapping();
    initialize_operand_type_mapping();
    initialize_avx_cc_mapping();
}

