// Subtraction: equivalent to adding the negation of b to a
COMPILER_RT_ABI fp_t __subtf3(fp_t a, fp_t b) {
  // Flip the sign bit of b to get -b, then perform addition
  return __addtf3(a, fromRep(toRep(b) ^ signBit));
}
