#include <vector>
#include <algorithm>

class Solution {
public:
    double findMaxAverage(std::vector<int>& nums, int k) {
        int n = nums.size();
        double currentSum = 0;

        // Calculate sum of first k elements
        for (int i = 0; i < k; ++i) {
            currentSum += nums[i];
        }

        double bestSum = currentSum;
        int startIndex = 0;

        // Slide the window across the array
        for (int endIndex = k; endIndex < n; ++endIndex) {
            currentSum = currentSum - nums[startIndex] + nums[endIndex];
            bestSum = std::max(currentSum, bestSum);
            ++startIndex;
        }

        return bestSum / k;
    }
};

