#include "libm.h"

// Copy the sign of y to x using bitwise operations
double copysign(double x, double y) {
    union { double f; unsigned long long i; } u_x = {x}, u_y = {y};

    // Clear the sign bit of x (keep magnitude)
    u_x.i &= 0x7FFFFFFFFFFFFFFFULL;

    // Extract sign bit from y and apply to x
    u_x.i |= (u_y.i >> 63) << 63;

    return u_x.f;
}

