// Unit test for complex dot product with minimal input size (N=1)
void test_zdotu_n_1(void)
{
    int N = 1;
    int incX = 1;
    int incY = 1;

    double x_data[] = {1.0, 1.0};
    double y_data[] = {1.0, 2.0};

    double _Complex computed_result = 0.0;
    double _Complex reference_result = 0.0;

    // Compute using OpenBLAS implementation
    computed_result = BLASFUNC(zdotu)(&N, x_data, &incX, y_data, &incY);

    // Compute using reference implementation
    reference_result = BLASFUNC_REF(zdotu)(&N, x_data, &incX, y_data, &incY);

    // Verify real and imaginary parts match within tolerance
    CU_ASSERT_DOUBLE_EQUAL(creal(computed_result), creal(reference_result), CHECK_EPS);
    CU_ASSERT_DOUBLE_EQUAL(cimag(computed_result), cimag(reference_result), CHECK_EPS);
}

// Unit test for complex dot product with offset pointers (N=1, offset by 1 element)
void test_zdotu_offset_1(void)
{
    int N = 1;
    int incX = 1;
    int incY = 1;

    double x_array[] = {1.0, 2.0, 3.0, 4.0};
    double y_array[] = {5.0, 6.0, 7.0, 8.0};

    double _Complex test_result = 0.0;
    double _Complex expected_result = 0.0;

    // Compute using OpenBLAS with pointer offset
    test_result = BLASFUNC(zdotu)(&N, x_array + 1, &incX, y_array + 1, &incY);

    // Compute using reference with same pointer offset
    expected_result = BLASFUNC_REF(zdotu)(&N, x_array + 1, &incX, y_array + 1, &incY);

    // Verify real and imaginary parts match within tolerance
    CU_ASSERT_DOUBLE_EQUAL(creal(test_result), creal(expected_result), CHECK_EPS);
    CU_ASSERT_DOUBLE_EQUAL(cimag(test_result), cimag(expected_result), CHECK_EPS);
}

