static pthread_mutex_t memlock = PTHREAD_MUTEX_INITIALIZER;

// Internal tracking structures
typedef struct {
    char *origin_file;
    long  line_number;
    long  slot_index;
    long  payload_size;
} memory_header;

// Global state
static void   **tracked_pointers = NULL;
static long    *free_slot_list   = NULL; // linked list of freed slots
static char   **file_names       = NULL;
static long    *file_usage_bytes = NULL;
static int      file_count       = 0;
static int      total_used_slots = 0;
static int      total_capacity   = 0;
static int      next_free_slot   = -1;   // index of first free slot in freelist

long global_bytes = 0;
long start_time_ms = -1;

// Helper: Append new file name if not already present
static int _register_file(const char *filename) {
    for (int i = 0; i < file_count; ++i) {
        if (file_names[i] && strcmp(file_names[i], filename) == 0)
            return i;
    }
    // Not found — add new entry
    int idx = file_count++;
    file_names = (char**)realloc(file_names, sizeof(char*) * file_count);
    file_usage_bytes = (long*)realloc(file_usage_bytes, sizeof(long) * file_count);
    file_names[idx] = strdup(filename);
    file_usage_bytes[idx] = 0;
    return idx;
}

// Helper: Grow internal arrays safely
static void _ensure_capacity() {
    if (total_used_slots >= total_capacity) {
        total_capacity += 64;
        tracked_pointers = (void**)realloc(tracked_pointers, sizeof(void*) * total_capacity);
        free_slot_list   = (long*)realloc(free_slot_list, sizeof(long) * total_capacity);
    }
}

// Helper: Insert pointer into tracking table
static void *_track_allocation(void *raw_ptr, long size, const char *file, long line) {
    memory_header *hdr = (memory_header *)raw_ptr;
    hdr->origin_file     = (char *)file;
    hdr->line_number     = line;
    hdr->slot_index      = next_free_slot;
    hdr->payload_size    = size - HEAD_ALIGN;

    pthread_mutex_lock(&memlock);

    _ensure_capacity();

    tracked_pointers[total_used_slots] = raw_ptr;
    if (next_free_slot == -1 || next_free_slot >= total_used_slots) {
        next_free_slot = ++total_used_slots;
    } else {
        long temp = next_free_slot;
        next_free_slot = free_slot_list[temp];
    }

#ifdef _VDBG_GRAPHFILE
    {
        FILE *out;
        struct timeval tv;
        static struct timezone tz = {0};
        char buffer[128];

        gettimeofday(&tv, &tz);
        int file_idx = _register_file(file);
        file_usage_bytes[file_idx] += size - HEAD_ALIGN;

        if (start_time_ms == -1)
            start_time_ms = (tv.tv_sec * 1000) + (tv.tv_usec / 1000);

        snprintf(buffer, sizeof(buffer), "%s%s", file, _VDBG_GRAPHFILE);
        out = fopen(buffer, "a");
        if (out) {
            fprintf(out, "%ld, %ld\n",
                    -(start_time_ms) + (tv.tv_sec * 1000) + (tv.tv_usec / 1000),
                    file_usage_bytes[file_idx] - (size - HEAD_ALIGN));
            fprintf(out, "%ld, %ld # FILE %s LINE %ld\n",
                    -(start_time_ms) + (tv.tv_sec * 1000) + (tv.tv_usec / 1000),
                    file_usage_bytes[file_idx],
                    file, line);
            fclose(out);
        }

        out = fopen(_VDBG_GRAPHFILE, "a");
        if (out) {
            fprintf(out, "%ld, %ld\n",
                    -(start_time_ms) + (tv.tv_sec * 1000) + (tv.tv_usec / 1000),
                    global_bytes);
            fprintf(out, "%ld, %ld\n",
                    -(start_time_ms) + (tv.tv_sec * 1000) + (tv.tv_usec / 1000),
                    global_bytes + (size - HEAD_ALIGN));
            fclose(out);
        }
    }
#endif

    global_bytes += (size - HEAD_ALIGN);
    pthread_mutex_unlock(&memlock);
    return (void*)((char*)raw_ptr + HEAD_ALIGN);
}

// Helper: Remove pointer from tracking
static void _untrack_allocation(void *raw_ptr) {
    pthread_mutex_lock(&memlock);

#ifdef _VDBG_GRAPHFILE
    {
        FILE *out;
        struct timeval tv;
        static struct timezone tz = {0};
        char buffer[128];

        memory_header *hdr = (memory_header *)raw_ptr;
        long payload = hdr->payload_size;
        char *file = hdr->origin_file;

        gettimeofday(&tv, &tz);
        fprintf(_VDBG_GRAPHFILE, "%ld, %ld\n",
                -(start_time_ms) + (tv.tv_sec * 1000) + (tv.tv_usec / 1000),
                global_bytes);
        fprintf(_VDBG_GRAPHFILE, "%ld, %ld\n",
                -(start_time_ms) + (tv.tv_sec * 1000) + (tv.tv_usec / 1000),
                global_bytes - payload);
        fclose(_VDBG_GRAPHFILE);

        int i;
        for (i = 0; i < file_count; ++i)
            if (file_names[i] && strcmp(file_names[i], file) == 0) break;

        snprintf(buffer, sizeof(buffer), "%s%s", file, _VDBG_GRAPHFILE);
        out = fopen(buffer, "a");
        if (out) {
            fprintf(out, "%ld, %ld\n",
                    -(start_time_ms) + (tv.tv_sec * 1000) + (tv.tv_usec / 1000),
                    file_usage_bytes[i]);
            fprintf(out, "%ld, %ld\n",
                    -(start_time_ms) + (tv.tv_sec * 1000) + (tv.tv_usec / 1000),
                    file_usage_bytes[i] - payload);
            fclose(out);
        }
        file_usage_bytes[i] -= payload;
    }
#endif

    global_bytes -= ((memory_header *)raw_ptr)->payload_size;

    long slot = ((memory_header *)raw_ptr)->slot_index;
    free_slot_list[slot] = next_free_slot;
    next_free_slot = slot;

    if (tracked_pointers[slot] == NULL) {
        fprintf(stderr, "DEBUGGING MALLOC ERROR: freeing previously freed memory\n");
        fprintf(stderr, "\t%s %ld\n", ((memory_header *)raw_ptr)->origin_file,
                ((memory_header *)raw_ptr)->line_number);
    }

    if (global_bytes < 0) {
        fprintf(stderr, "DEBUGGING MALLOC ERROR: freeing unmalloced memory\n");
    }

    tracked_pointers[slot] = NULL;
    pthread_mutex_unlock(&memlock);
}

// Public API: dump leaked allocations
void _VDBG_dump(void) {
    pthread_mutex_lock(&memlock);
    for (int i = 0; i < total_used_slots; ++i) {
        memory_header *hdr = (memory_header *)tracked_pointers[i];
        if (hdr != NULL) {
            fprintf(stderr, "unfreed bytes from %s:%ld\n",
                    hdr->origin_file, hdr->line_number);
        }
    }
    pthread_mutex_unlock(&memlock);
}

// External malloc wrapper
extern void *_VDBG_malloc(void *old_ptr, long size, const char *file, long line) {
    size += HEAD_ALIGN;
    if (old_ptr) {
        old_ptr = (char*)old_ptr - HEAD_ALIGN;
        _untrack_allocation(old_ptr);
        old_ptr = realloc(old_ptr, size);
    } else {
        old_ptr = malloc(size);
        memset(old_ptr, 0, size);
    }
    return _track_allocation(old_ptr, size, file, line);
}

// External free wrapper
extern void _VDBG_free(void *ptr, const char *file, long line) {
    if (ptr) {
        ptr = (char*)ptr - HEAD_ALIGN;
        _untrack_allocation(ptr);
        free(ptr);
    }
}

