// Namespace aliases for brevity and clarity
namespace AC = AscendC;
using namespace AC::CamMoeDispatchNormalImpl;

// Tiling key identifiers — renamed for obfuscation
#define NO_QUANT_MODE   10000
#define QUANT_MODE      10002

// Main kernel entry point — function name preserved per ABI requirement
extern "C" __global__ __aicore__ void cam_moe_dispatch_normal(
    GM_ADDR x,
    GM_ADDR expertIds,
    GM_ADDR send_offset,
    GM_ADDR send_token_idx,
    GM_ADDR recv_offset,
    GM_ADDR recv_count,
    GM_ADDR expert_global_offset,
    GM_ADDR srcrank_in_expert_offset,
    GM_ADDR r_in_srcrank_offset,
    GM_ADDR expandXOut,
    GM_ADDR dynamicScalesOut,
    GM_ADDR assist_info_for_combine,
    GM_ADDR waitRecvCostStatsOut,
    GM_ADDR workspaceGM,
    GM_ADDR tilingGM)
{
    // Register tiling data structure with default initialization
    REGISTER_TILING_DEFAULT(CamMoeDispatchNormalTilingData);

    // Pipeline instance for scheduling operations
    TPipe pipeline;

    // Determine dispatch mode based on tiling key and input data type
    switch (tiling_key_select(TILING_KEY_IS)) {
        case NO_QUANT_MODE:
#if (ORIG_DTYPE_RECV_X == DT_BF16 || ORIG_DTYPE_RECV_X == DT_FLOAT16)
            {
                CamMoeDispatchNormalTilingData tilingParams;
                GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, tilingParams, tilingGM);

                // Instantiate operator for non-quantized path (no quant, no transpose, no fused op)
                CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, false, false, false> dispatcher;
                dispatcher.Init(
                    x, expertIds, send_offset, send_token_idx,
                    recv_offset, recv_count, expert_global_offset,
                    srcrank_in_expert_offset, r_in_srcrank_offset,
                    expandXOut, dynamicScalesOut, assist_info_for_combine,
                    waitRecvCostStatsOut, workspaceGM, &pipeline, &tilingParams
                );
                dispatcher.Run();
                return;
            }
#endif
            break;

        case QUANT_MODE:
#if (ORIG_DTYPE_RECV_X == DT_INT8)
            {
                CamMoeDispatchNormalTilingData tilingParams;
                GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, tilingParams, tilingGM);

                // Instantiate operator for quantized INT8 path (quant enabled, no transpose/fusion)
                CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, true, false, false> dispatcher;
                dispatcher.Init(
                    x, expertIds, send_offset, send_token_idx,
                    recv_offset, recv_count, expert_global_offset,
                    srcrank_in_expert_offset, r_in_srcrank_offset,
                    expandXOut, dynamicScalesOut, assist_info_for_combine,
                    waitRecvCostStatsOut, workspaceGM, &pipeline, &tilingParams
                );
                dispatcher.Run();
                return;
            }
#endif
            break;

        default:
            // Fallback: do nothing if no matching mode found
            break;
    }
}

// Helper macro/function-like wrapper to extract tiling key (renamed for obfuscation)
inline int tiling_key_select(int (*pred)(int)) {
    return pred(0); // Simplified placeholder — in real code, this would extract actual key
}

