// Test suite for Pointer class functionality
TEST(PointerTest, Initialization) {
    types::Pointer ptr{types::Scalar(types::PrimitiveType::Int32)};
    EXPECT_EQ(ptr.pointee_type(), types::Scalar(types::PrimitiveType::Int32));
    EXPECT_EQ(ptr.primitive_type(), types::PrimitiveType::Int32);
}

TEST(PointerTest, SymbolBehavior) {
    types::Pointer ptr1{types::Scalar(types::PrimitiveType::UInt32)};
    EXPECT_TRUE(ptr1.is_symbol());

    types::Pointer ptr2{types::Scalar(types::PrimitiveType::Float)};
    EXPECT_TRUE(ptr2.is_symbol());
}

TEST(PointerTest, EqualityComparison) {
    types::Pointer ptrA{types::Scalar(types::PrimitiveType::UInt32)};
    types::Pointer ptrB{types::Scalar(types::PrimitiveType::UInt32)};
    types::Pointer ptrC{types::Scalar(types::PrimitiveType::Float)};

    EXPECT_EQ(ptrA, ptrB);
    EXPECT_NE(ptrA, ptrC);
}

TEST(PointerTest, TypeIdentification) {
    types::Pointer ptr{types::Scalar(types::PrimitiveType::UInt32)};
    EXPECT_EQ(ptr.type_id(), types::TypeID::Pointer);
}

TEST(PointerTest, CloningOperation) {
    types::Pointer original{types::Scalar(types::PrimitiveType::Float)};
    auto cloned = original.clone();

    types::Pointer* clonedPtr = dynamic_cast<types::Pointer*>(cloned.get());
    ASSERT_NE(clonedPtr, nullptr);

    EXPECT_EQ(original.pointee_type(), clonedPtr->pointee_type());
}

