  invert();
  flip();
  setTextWrap(false);
}

void DspCore::clearDsp(bool black) { 
  fillScreen(black ? 0 : config.theme.background); 
}

void DspCore::flip() { 
  setRotation(config.store.flipscreen ? 1 : 3); 
}

void DspCore::invert() { 
  invertDisplay(config.store.invertdisplay); 
}

void DspCore::sleep(void) {
  sendCommand(GC9106_SLPIN);
  delay(150);
  sendCommand(GC9106_DISPOFF);
  delay(150);
}

void DspCore::wake(void) {
  sendCommand(GC9106_DISPON);
  delay(150);
  sendCommand(GC9106_SLPOUT);
  delay(150);
}
