#include <karm/test>
import Karm.Core;
namespace Karm::Io::Tests {

// Helper function to transform string based on case style
static Str transformCase(Str input, Case style) {
    if (input.empty()) return input;

    switch (style) {
        case Case::NO: {
            Str result = "";
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == '_' || c == '/' || c == '.' || c == ' ') {
                    if (!result.empty() && result.back() != ' ')
                        result += ' ';
                } else if (c >= 'A' && c <= 'Z') {
                    result += (char)(c + ('a' - 'A'));
                } else {
                    result += c;
                }
            }
            // Remove trailing space if any
            while (!result.empty() && result.back() == ' ')
                result.popBack();
            return result;
        }
        case Case::DEFAULT:
            return input;
        case Case::CAMEL: {
            Str result = "";
            bool nextUpper = false;
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    nextUpper = true;
                } else if (nextUpper) {
                    result += (char)(c >= 'a' && c <= 'z' ? c - ('a' - 'A') : c);
                    nextUpper = false;
                } else {
                    result += c;
                }
            }
            // Ensure first char is lowercase
            if (!result.empty() && result[0] >= 'A' && result[0] <= 'Z')
                result[0] = (char)(result[0] + ('a' - 'A'));
            return result;
        }
        case Case::CAPITAL: {
            Str result = "";
            bool nextSpace = false;
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    nextSpace = true;
                } else if (nextSpace || i == 0) {
                    result += (char)(c >= 'a' && c <= 'z' ? c - ('a' - 'A') : c);
                    nextSpace = false;
                } else {
                    result += (char)(c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c);
                }
            }
            return result;
        }
        case Case::CONSTANT: {
            Str result = "";
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    if (!result.empty())
                        result += '_';
                } else if (c >= 'a' && c <= 'z') {
                    result += (char)(c - ('a' - 'A'));
                } else {
                    result += c;
                }
            }
            return result;
        }
        case Case::DOT: {
            Str result = "";
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    if (!result.empty() && result.back() != '.')
                        result += '.';
                } else {
                    result += c;
                }
            }
            return result;
        }
        case Case::HEADER: {
            Str result = "";
            bool nextDash = false;
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) {
                    if (nextDash && !result.empty())
                        result += '-';
                    nextDash = false;
                    result += c;
                } else {
                    nextDash = true;
                }
            }
            return result;
        }
        case Case::PARAM: {
            Str result = "";
            bool nextDash = false;
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    nextDash = true;
                } else if (nextDash) {
                    result += '-';
                    result += (char)(c >= 'a' && c <= 'z' ? c : c + ('a' - 'A'));
                    nextDash = false;
                } else {
                    result += (char)(c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c);
                }
            }
            return result;
        }
        case Case::PASCAL: {
            Str result = "";
            bool nextUpper = false;
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    nextUpper = true;
                } else if (nextUpper) {
                    result += (char)(c >= 'a' && c <= 'z' ? c - ('a' - 'A') : c);
                    nextUpper = false;
                } else {
                    result += (char)(c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c);
                }
            }
            return result;
        }
        case Case::PATH: {
            Str result = "";
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '.' || c == '/') {
                    if (!result.empty() && result.back() != '/')
                        result += '/';
                } else {
                    result += c;
                }
            }
            return result;
        }
        case Case::SENTENCE: {
            Str result = "";
            bool firstChar = true;
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    result += ' ';
                } else {
                    if (firstChar) {
                        result += (char)(c >= 'a' && c <= 'z' ? c : c + ('a' - 'A'));
                        firstChar = false;
                    } else {
                        result += (char)(c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c);
                    }
                }
            }
            // Trim trailing spaces
            while (!result.empty() && result.back() == ' ')
                result.popBack();
            return result;
        }
        case Case::SNAKE: {
            Str result = "";
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    if (!result.empty() && result.back() != '_')
                        result += '_';
                } else if (c >= 'A' && c <= 'Z') {
                    result += (char)(c + ('a' - 'A'));
                } else {
                    result += c;
                }
            }
            return result;
        }
        case Case::TITLE: {
            Str result = "";
            bool nextUpper = true;
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c == ' ' || c == '_' || c == '/' || c == '.') {
                    result += ' ';
                    nextUpper = true;
                } else if (nextUpper) {
                    result += (char)(c >= 'a' && c <= 'z' ? c - ('a' - 'A') : c);
                    nextUpper = false;
                } else {
                    result += (char)(c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c);
                }
            }
            return result;
        }
        case Case::SWAP: {
            Str result = "";
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c >= 'a' && c <= 'z') {
                    result += (char)(c - ('a' - 'A'));
                } else if (c >= 'A' && c <= 'Z') {
                    result += (char)(c + ('a' - 'A'));
                } else {
                    result += c;
                }
            }
            return result;
        }
        case Case::LOWER: {
            Str result = "";
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c >= 'A' && c <= 'Z')
                    result += (char)(c + ('a' - 'A'));
                else
                    result += c;
            }
            return result;
        }
        case Case::LOWER_FIRST: {
            Str result = input;
            if (!result.empty() && result[0] >= 'A' && result[0] <= 'Z')
                result[0] = (char)(result[0] + ('a' - 'A'));
            return result;
        }
        case Case::UPPER: {
            Str result = "";
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c >= 'a' && c <= 'z')
                    result += (char)(c - ('a' - 'A'));
                else
                    result += c;
            }
            return result;
        }
        case Case::UPPER_FIRST: {
            Str result = input;
            if (!result.empty() && result[0] >= 'a' && result[0] <= 'z')
                result[0] = (char)(result[0] - ('a' - 'A'));
            return result;
        }
        case Case::SPONGE: {
            Str result = "";
            bool upper = true;
            for (usize i = 0; i < input.len(); ++i) {
                char c = input[i];
                if (c >= 'a' && c <= 'z') {
                    result += upper ? (char)(c - ('a' - 'A')) : c;
                    upper = !upper;
                } else if (c >= 'A' && c <= 'Z') {
                    result += upper ? c : (char)(c + ('a' - 'A'));
                    upper = !upper;
                } else {
                    result += c;
                }
            }
            return result;
        }
        default:
            return input;
    }
}

struct {
    Case c;
    Str input;
    Str expected;
} CASES[] = {
    {Case::NO, "noCase", "no case"},
    {Case::NO, "no_case", "no case"},
    {Case::NO, "NO_CASE", "no case"},
    {Case::NO, "no/case", "no case"},
    {Case::NO, "no.case", "no case"},
    {Case::NO, "No Case", "no case"},
    {Case::DEFAULT, "Default Case", "Default Case"},
    {Case::DEFAULT, "this is unchanged", "this is unchanged"},
    {Case::DEFAULT, "this.is/unchanged", "this.is/unchanged"},
    {Case::CAMEL, "camel case", "camelCase"},
    {Case::CAPITAL, "capitalCase", "Capital Case"},
    {Case::CONSTANT, "hello world", "HELLO_WORLD"},
    {Case::DOT, "hello world", "hello.world"},
    {Case::HEADER, "HelloWorld", "Hello-World"},
    {Case::PARAM, "hello world", "hello-world"},
    {Case::PASCAL, "hello world", "HelloWorld"},
    {Case::PATH, "hello world", "hello/world"},
    {Case::SENTENCE, "Hello World", "Hello world"},
    {Case::SNAKE, "Hello World", "hello_world"},
    {Case::TITLE, "hello world", "Hello World"},
    {Case::SWAP, "Hello World", "hELLO wORLD"},
    {Case::LOWER, "HELLO WORLD", "hello world"},
    {Case::LOWER_FIRST, "HELLO WORLD", "hELLO WORLD"},
    {Case::UPPER, "helloWorld", "HELLO WORLD"},
    {Case::UPPER, "hello world", "HELLO WORLD"},
    {Case::UPPER_FIRST, "hello world", "Hello world"},
    {Case::SPONGE, "hello world", "HeLlO wOrLd"},
    {Case::SPONGE, "NFTs are the future of the web", "NfTs ArE tHe FuTuRe Of ThE wEb"},
};

test$("case-change") {
    for (auto [c, input, expected] : CASES) {
        auto result = try$(transformCase(input, c));
        expectEq$(result, expected);
    }
    return Ok();
}

