#include "xdelta3.h"

// External variable declaration and definition
extern int VVV;
int VVV;

// Function to assign value to VVV
void assign_value(int val) {
    VVV = val;
}

int main() {
    xd3_config cfg;
    xd3_stream strm;
    xd3_source src;

    // Initialize configuration with default settings
    xd3_init_config(&cfg, 0);

    // Use helper function to set stream configuration
    assign_value(xd3_config_stream(&strm, &cfg));

    // Close and clean up the stream
    assign_value(xd3_close_stream(&strm));
    xd3_abort_stream(&strm);
    xd3_free_stream(&strm);

    // Additional stream operations (input/output handling)
    xd3_avail_input(&strm, NULL, 0);
    xd3_consume_output(&strm);

    // Set source and flags for stream processing
    assign_value(xd3_set_source(&strm, &src));
    xd3_set_flags(&strm, 0);

    // Decoding operations
    assign_value(xd3_decode_stream(&strm, NULL, 0, NULL, NULL, 0));
    assign_value(xd3_decode_input(&strm));
    assign_value(xd3_get_appheader(&strm, NULL, NULL));

#if XD3_ENCODER
    // Encoder-specific operations
    assign_value(xd3_encode_input(&strm));
    assign_value(xd3_encode_stream(&strm, NULL, 0, NULL, NULL, 0));
    assign_value(xd3_set_appheader(&strm));
    assign_value(xd3_encoder_used_source(&strm));
    assign_value(xd3_encoder_srcbase(&strm));
    assign_value(xd3_encoder_srclen(&strm));
#endif

    return 0;
}

