#include <iostream>
#include "sophus/geometry.hpp"

int main() {
  // Demonstrate composition of 3D rotations using SO(3) group operations
  constexpr double pi = Sophus::Constants<double>::pi();

  // Construct three rotation operators: around x, y, and z axes
  Sophus::SO3d Rx = Sophus::SO3d::rotX(pi / 4.0);
  Sophus::SO3d Ry = Sophus::SO3d::rotY(pi / 6.0);
  Sophus::SO3d Rz = Sophus::SO3d::rotZ(-pi / 3.0);

  std::cout << "Individual rotation matrices:" << std::endl;
  std::cout << "Rx:\n" << Rx.matrix() << std::endl;
  std::cout << "Ry:\n" << Ry.matrix() << std::endl;
  std::cout << "Rz:\n" << Rz.matrix() << std::endl;
  std::cout << "Composite rotation Rx * Ry * Rz:\n"
            << (Rx * Ry * Rz).matrix() << std::endl;
  std::cout << std::endl;

  // Apply rotations to a test vector
  Eigen::Vector3d point;
  point << 0.0, 0.0, 1.0;

  std::cout << "Vector transformation examples:" << std::endl;
  std::cout << "Original vector:\n" << point << std::endl;
  std::cout << "Ry applied to vector:\n" << Ry * point << std::endl;
  std::cout << "Rx applied to (Ry * vector):\n" << Rx * (Ry * point) << std::endl;
  std::cout << "(Rx * Ry) applied to vector:\n" << (Rx * Ry) * point << std::endl;
  std::cout << std::endl;

  // Show internal representation as unit quaternion
  std::cout << "SO(3) element Rx in matrix form:\n" << Rx.matrix() << std::endl;
  std::cout << "Same rotation in quaternion form (i, j, k, w):\n"
            << Rx.unit_quaternion().coeffs() << std::endl;
  // Note: Eigen uses (imaginary_part_x, imag_y, imag_z, real_part) ordering
  std::cout << std::endl;

  return 0;
}

