namespace FFBEngineTests {
    TEST_CASE(test_channel_stats_average, "Performance") {
        ChannelStats stats;

        // Add sample values to compute average
        stats.Update(10.0);
        stats.Update(20.0);
        stats.Update(30.0);

        // Verify computed average matches expected value
        ASSERT_NEAR(stats.Avg(), 20.0, 0.001);
    }

    TEST_CASE(test_channel_stats_resets, "Performance") {
        ChannelStats stats;

        // First measurement interval
        stats.Update(10.0);
        stats.Update(100.0);
        ASSERT_NEAR(stats.session_max, 100.0, 0.001);

        // Reset current interval but preserve session-level data
        stats.ResetInterval();
        ASSERT_NEAR(stats.interval_sum, 0.0, 0.001);
        ASSERT_NEAR(stats.latched_max, 100.0, 0.001); // Previously recorded maximum is preserved

        // Second measurement interval
        stats.Update(20.0);
        stats.Update(50.0);

        ASSERT_NEAR(stats.interval_sum, 70.0, 0.001);
        ASSERT_NEAR(stats.session_max, 100.0, 0.001); // Session max unchanged

        // New maximum exceeds previous session max
        stats.Update(150.0);
        ASSERT_NEAR(stats.session_max, 150.0, 0.001);
    }

    TEST_CASE(test_channel_stats_empty_reset, "Performance") {
        ChannelStats stats;
        stats.ResetInterval();
        ASSERT_NEAR(stats.latched_avg, 0.0, 0.001);
    }
} // namespace FFBEngineTests

