// Global state variables for kernel configuration
std::uint32_t unp_cfg_context          = 0;
std::uint32_t pack_sync_tile_dst_ptr   = 0;
std::uint32_t math_sync_tile_dst_index = 0;

#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_A.h"
#include "llk_unpack_common.h"
#include "params.h"

// Entry point for unpacker-side kernel execution
void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& formats = params->formats;
#endif

    // Configure unpack hardware with face dimensions and count
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        formats.unpack_A_src, 
        formats.unpack_B_src, 
        formats.unpack_A_dst, 
        formats.unpack_B_dst, 
        FACE_R_DIM, 
        FACE_R_DIM, 
        4U /* num_faces */, 
        4U /* num_faces */);

    // Initialize unpack A operation (no broadcast, no reuse)
    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        0U, 0U, FACE_R_DIM, 4U, formats.unpack_A_src, formats.unpack_A_dst);

    // Process each tile via unpack A
    std::size_t tile_idx = 0U;
    while (tile_idx < static_cast<std::size_t>(params->TILE_CNT))
    {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(params->buffer_A[tile_idx]), 
            formats.unpack_A_src, 
            formats.unpack_A_dst);
        ++tile_idx;
    }
}
#endif // LLK_TRISC_UNPACK


#ifdef LLK_TRISC_MATH
#include "ckernel_defs.h"
#include "ckernel_sfpu.h"
#include "llk_math_common.h"
#include "llk_math_eltwise_binary_sfpu.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "params.h"
#include "sfpu_operations.h"

using namespace ckernel::sfpu;

// Entry point for math-side kernel execution
void run_kernel(const volatile struct RuntimeParams* params)
{
    constexpr bool is_int_fpu_en = false;

    // Initialize pack sync and configure math unit
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(formats.math, formats.math);

#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, is_int_fpu_en>(4U, formats.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, is_int_fpu_en>(4U, formats.math);
#endif

    // Wait until destination buffer has space for tiles
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Copy input data into destination registers tile-by-tile
    std::size_t tile_counter = 0U;
    while (tile_counter < static_cast<std::size_t>(params->TILE_CNT))
    {
        // Ensure tile index is within bounds
        if (!(tile_counter < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()))
        {
            // In debug builds, this would trigger assertion failure
            __builtin_unreachable();
        }

        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            static_cast<int>(tile_counter), 
            formats.math, 
            formats.math);
        ++tile_counter;
    }

    // Setup SFPU binary add-1 operation
    _llk_math_eltwise_binary_sfpu_init_<SfpuType::add1>();

    // Start SFPU binary op: first operand at dest index 0, second at index 1
    _llk_math_eltwise_binary_sfpu_start_<DstSync::SyncHalf>(0);

    // Execute SFPU operation (approximate mode enabled)
    test_utils::call_binary_sfpu_operation<APPROX_MODE, SFPU_BINARY_OPERATION, 32U, formats.math>(0, 1, 0);

    // Finalize SFPU binary op
    _llk_math_eltwise_binary_sfpu_done_();

    // Signal completion of destination section
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif // LLK_TRISC_MATH


#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

// Entry point for packer-side kernel execution
void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(formats.pack_src, formats.pack_dst, 16U * 16U);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(formats.pack_src, formats.pack_dst, 16U * 16U);
#endif

    // Initialize packer module
    _llk_pack_init_<false, false>(formats.pack_dst);

#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    // Wait until math operations are done before packing
    _llk_packer_wait_for_math_done_();

    // Pack output tiles back to L1 memory
    std::size_t out_tile_idx = 0U;
    while (out_tile_idx < static_cast<std::size_t>(params->TILE_CNT))
    {
        if (!(out_tile_idx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()))
        {
            __builtin_unreachable();
        }

        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            static_cast<int>(out_tile_idx), 
            L1_ADDRESS(params->buffer_Res[out_tile_idx]));
        ++out_tile_idx;
    }

    // Mark end of packed section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif // LLK_TRISC_PACK

