extern template struct EnumIntAction<ScenePageNaviHelper::PageNaviE>;
extern template struct EnumIntAction<SceneSortOrderHelper::SortDimE>;
extern template struct EnumIntAction<Qt::TextElideMode>;
extern template struct EnumIntAction<QHeaderView::ResizeMode>;
extern template struct EnumIntAction<Qt::ScrollBarPolicy>;

class EnumActionValidation : public PlainTestSuite {
  Q_OBJECT

 public:
  // Helper to validate enum-to-action mapping under various exclusion policies
  template <typename E>
  void validateEnumFromActions(E firstVal, E secondVal, E fallbackVal,
                               QActionGroup::ExclusionPolicy policy) {
    QAction actionA{"ascii b large"};
    actionA.setCheckable(true);
    QAction actionB{"ascii a less"};
    QVERIFY2(actionA.text() > actionB.text(), "First action should sort after second");

    actionB.setCheckable(true);
    QVERIFY2(firstVal < secondVal, "First enum must be less than second");

    if (policy == QActionGroup::ExclusionPolicy::Exclusive) {
      actionB.setChecked(true);
    }

    EnumIntAction<E> mapper;
    QCOMPARE(mapper, false); // Initially invalid

    mapper.init({{&actionA, firstVal}, {&actionB, secondVal}}, fallbackVal, policy);
    QCOMPARE(mapper, true); // Now initialized

    QCOMPARE(mapper.defVal(), fallbackVal);

    const auto expectedCurrent = (policy == QActionGroup::ExclusionPolicy::Exclusive)
                                     ? secondVal
                                     : fallbackVal;
    QCOMPARE(mapper.curVal(), expectedCurrent);

    auto* grp = mapper.getActionGroup();
    QVERIFY(grp != nullptr);
    QCOMPARE(grp->actions().size(), 2);

    // Order depends on input container; ascending by pointer address is not guaranteed
    QCOMPARE(mapper.getActionEnumAscendingList(), (QList<QAction*>{&actionA, &actionB}));
    QCOMPARE(mapper.getActionNameAscendingList(), (QList<QAction*>{&actionB, &actionA}));

    // Test enum ↔ action mappings
    QCOMPARE(mapper.act2Enum(&actionA), firstVal);
    QCOMPARE(mapper.act2Enum(static_cast<const QAction*>(&actionA)), firstVal);
    QCOMPARE(mapper.intVal2Enum(static_cast<int>(firstVal)), firstVal);

    QCOMPARE(mapper.act2Enum(&actionB), secondVal);
    QCOMPARE(mapper.act2Enum(static_cast<const QAction*>(&actionB)), secondVal);
    QCOMPARE(mapper.intVal2Enum(static_cast<int>(secondVal)), secondVal);

    // Set check via int or enum value
    QCOMPARE(mapper.setCheckedIfActionExist(static_cast<int>(secondVal)), &actionB);
    QCOMPARE(mapper.setCheckedIfActionExist(secondVal), &actionB);

    if (policy != QActionGroup::ExclusionPolicy::None) {
      QCOMPARE(mapper.curVal(), secondVal);
    }
  }

 private slots:
  void test_exclusive_mode() {
    validateEnumFromActions<ViewTypeTool::ViewType>(
        ViewTypeTool::ViewType::TABLE,
        ViewTypeTool::ViewType::SEARCH,
        ViewTypeTool::DEFAULT_VIEW_TYPE,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<Style::StyleE>(
        Style::StyleE::STYLE_WINDOWS_VISTA,
        Style::StyleE::STYLE_FUSION,
        Style::StyleE::STYLE_WINDOWS_VISTA,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<Style::StyleSheetE>(
        Style::StyleSheetE::STYLESHEET_DEFAULT_LIGHT,
        Style::StyleSheetE::STYLESHEET_DARK_THEME_MOON_FOG,
        Style::StyleSheetE::STYLESHEET_DEFAULT_LIGHT,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<SearchTools::SearchModeE>(
        SearchTools::SearchModeE::REGEX,
        SearchTools::SearchModeE::FILE_CONTENTS,
        SearchTools::DEFAULT_SEARCH_MODE,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<BytesRangeTool::BytesRangeE>(
        BytesRangeTool::BytesRangeE::FIRST_16_BYTES,
        BytesRangeTool::BytesRangeE::ENTIRE_FILE,
        BytesRangeTool::DEFAULT_BYTE_RANGE,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<QCryptographicHash::Algorithm>(
        QCryptographicHash::Algorithm::Md5,
        QCryptographicHash::Algorithm::Sha256,
        QCryptographicHash::Algorithm::Md5,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<DuplicateImageDetectionCriteria::DICriteriaE>(
        DuplicateImageDetectionCriteria::DICriteriaE::LIBRARY,
        DuplicateImageDetectionCriteria::DICriteriaE::MD5,
        DuplicateImageDetectionCriteria::DEFAULT_DI_CRITERIA_E,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<FileStructurePolicy::FileStuctureModeE>(
        FileStructurePolicy::FileStuctureModeE::PRESERVE,
        FileStructurePolicy::FileStuctureModeE::FLATTEN,
        FileStructurePolicy::FileStuctureModeE::QUERY,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<SceneSortOrderHelper::SortDimE>(
        SceneSortOrderHelper::SortDimE::MOVIE_PATH,
        SceneSortOrderHelper::SortDimE::MOVIE_SIZE,
        SceneSortOrderHelper::DEFAULT_SCENE_SORT_ORDER,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<Qt::TextElideMode>(
        Qt::TextElideMode::ElideLeft,
        Qt::TextElideMode::ElideRight,
        Qt::TextElideMode::ElideNone,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<QHeaderView::ResizeMode>(
        QHeaderView::ResizeMode::Interactive,
        QHeaderView::ResizeMode::Stretch,
        QHeaderView::ResizeMode::Interactive,
        QActionGroup::ExclusionPolicy::Exclusive);

    validateEnumFromActions<Qt::ScrollBarPolicy>(
        Qt::ScrollBarPolicy::ScrollBarAsNeeded,
        Qt::ScrollBarPolicy::ScrollBarAlwaysOff,
        Qt::ScrollBarPolicy::ScrollBarAsNeeded,
        QActionGroup::ExclusionPolicy::Exclusive);
  }

  void test_exclusive_optional_mode() {
    validateEnumFromActions<PreviewTypeTool::PREVIEW_TYPE_E>(
        PreviewTypeTool::PREVIEW_TYPE_E::CATEGORY,
        PreviewTypeTool::PREVIEW_TYPE_E::PROGRESSIVE_LOAD,
        PreviewTypeTool::DEFULT_PREVIEW_TYPE_E,
        QActionGroup::ExclusionPolicy::ExclusiveOptional);
  }

  void test_non_exclusive_mode() {
    validateEnumFromActions<ScenePageNaviHelper::PageNaviE>(
        ScenePageNaviHelper::PageNaviE::FRONT,
        ScenePageNaviHelper::PageNaviE::PREVIOUS,
        ScenePageNaviHelper::PageNaviE::BEGIN_DEFAULT,
        QActionGroup::ExclusionPolicy::None);
  }
};

