// Test case: Append two coverings and verify simplification behavior
UNIT_TEST(Covering_Append_Simple)
{
  vector<CellId> v1, v2, expected;

  // First covering components
  v1.emplace_back("012");
  v1.emplace_back("023");
  v1.emplace_back("130");
  v1.emplace_back("131");
  v1.emplace_back("1320");
  v1.emplace_back("1321");

  // Second covering components
  v2.emplace_back("0123");
  v2.emplace_back("023");
  v2.emplace_back("133");
  v2.emplace_back("1322");
  v2.emplace_back("1323");

  // Expected result after append and simplification
  expected.emplace_back("012");
  expected.emplace_back("023");
  expected.emplace_back("13");
  expected.emplace_back("130");
  expected.emplace_back("131");
  expected.emplace_back("132");
  expected.emplace_back("133");

  // Perform appending operation
  covering::Covering<CellId> c1(v1);
  c1.Append(covering::Covering<CellId>(v2));

  vector<CellId> actual;
  c1.OutputToVector(actual);

  // Sort both vectors using pre-order comparison
  sort(actual.begin(), actual.end(), CellId::LessPreOrder());
  sort(expected.begin(), expected.end(), CellId::LessPreOrder());

  TEST_EQUAL(actual, expected, ());
}

// Test case: Intersection between empty triangle and cells
UNIT_TEST(IntersectCellWithTriangle_EmptyTriangle)
{
  m2::PointD point(27.0, 31.0);

  // All cells except "3" should have no intersection with degenerate triangle
  TEST_EQUAL(covering::CELL_OBJECT_NO_INTERSECTION,
             covering::IntersectCellWithTriangle(CellId("0"), point, point, point), ());
  TEST_EQUAL(covering::CELL_OBJECT_NO_INTERSECTION,
             covering::IntersectCellWithTriangle(CellId("1"), point, point, point), ());
  TEST_EQUAL(covering::CELL_OBJECT_NO_INTERSECTION,
             covering::IntersectCellWithTriangle(CellId("2"), point, point, point), ());
  TEST_EQUAL(covering::OBJECT_INSIDE_CELL,
             covering::IntersectCellWithTriangle(CellId("3"), point, point, point), ());
}

// Test case: Covering of a degenerate triangle (single point)
UNIT_TEST(Covering_EmptyTriangle)
{
  m2::PointU gridPoint(27, 31);
  m2::PointD doublePoint(gridPoint);

  // Calculate expected cell at maximum depth
  CellId const expectedCell = CellId::FromXY(gridPoint.x, gridPoint.y, CellId::DEPTH_LEVELS - 1);
  TEST_GREATER(expectedCell.ToInt64(CellId::DEPTH_LEVELS), 5, ());

  // Create covering for degenerate triangle (all points same)
  covering::Covering<CellId> cover(doublePoint, doublePoint, doublePoint);

  vector<CellId> resultCells;
  cover.OutputToVector(resultCells);

  vector<CellId> expectedCells(1, expectedCell);
  TEST_EQUAL(resultCells, expectedCells, ());
}

// Test case: Simplify covering by merging adjacent cells where possible
UNIT_TEST(Covering_Simplify_Smoke)
{
  vector<CellId> inputCells;
  inputCells.emplace_back("03");
  inputCells.emplace_back("020");
  inputCells.emplace_back("021");
  inputCells.emplace_back("022");
  inputCells.emplace_back("0012");

  // Build initial covering
  covering::Covering<CellId> cover(inputCells);

  // Apply simplification
  cover.Simplify();

  vector<CellId> simplifiedCells;
  cover.OutputToVector(simplifiedCells);

  // Expected simplified result
  vector<CellId> expectedCells;
  expectedCells.emplace_back("02");
  expectedCells.emplace_back("03");
  expectedCells.emplace_back("0012");

  TEST_EQUAL(simplifiedCells, expectedCells, ());
}
