#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include "lbug.h"

int main() {
    lbug_database db;
    lbug_connection conn;

    // Initialize database with default configuration
    lbug_database_init("" /* database path */, lbug_default_system_config(), &db);
    lbug_connection_init(&db, &conn);

    // Define schema for Person node
    lbug_query_result result;
    lbug_connection_query(
        &conn, 
        "CREATE NODE TABLE Person(name STRING, age INT64, PRIMARY KEY(name));", 
        &result);
    lbug_query_result_destroy(&result);

    // Insert sample data
    lbug_connection_query(&conn, "CREATE (:Person {name: 'Alice', age: 25});", &result);
    lbug_query_result_destroy(&result);
    lbug_connection_query(&conn, "CREATE (:Person {name: 'Bob', age: 30});", &result);
    lbug_query_result_destroy(&result);

    // Execute query to retrieve all Person nodes
    lbug_connection_query(&conn, "MATCH (p:Person) RETURN p.name AS NAME, p.age AS AGE;", &result);

    // Process each row in the result set
    lbug_flat_tuple tuple;
    lbug_value value;
    while (lbug_query_result_has_next(&result)) {
        lbug_query_result_get_next(&result, &tuple);

        // Extract name field
        lbug_flat_tuple_get_value(&tuple, 0, &value);
        char* person_name;
        lbug_value_get_string(&value, &person_name);

        // Extract age field
        lbug_flat_tuple_get_value(&tuple, 1, &value);
        int64_t person_age;
        lbug_value_get_int64(&value, &person_age);

        // Output record
        printf("name: %s, age: %" PRIi64 "\n", person_name, person_age);

        // Clean up dynamically allocated string
        lbug_destroy_string(person_name);
    }

    // Cleanup resources
    lbug_value_destroy(&value);
    lbug_flat_tuple_destroy(&tuple);

    // Print final result summary
    char* output_summary = lbug_query_result_to_string(&result);
    printf("%s", output_summary);
    lbug_destroy_string(output_summary);

    lbug_query_result_destroy(&result);
    lbug_connection_destroy(&conn);
    lbug_database_destroy(&db);

    return 0;
}

