void LayoutController::init(PaneLayout* layout, ClientManager* manager, domain::Window* win) {
    m_pane_layout = layout;

    // Handle new client registration
    manager->onClientAdded([=](KakouneClient* client) {
        // Subscribe to UI option changes for this client
        client->onUIOptionsChanged([=](const domain::UIOptions&) {
            m_pane_layout->recomputeLayout();
        });
        // Initial arrangement after adding client
        m_pane_layout->recomputeLayout();
    });

    // Handle client removal
    manager->onClientRemoved([=](KakouneClient*) {
        m_pane_layout->recomputeLayout();
    });

    // Handle window resize events
    win->onResize([this, win](int w, int h) {
        m_pane_layout->setBounds(domain::Rectangle{0.0f, 0.0f, static_cast<float>(w), static_cast<float>(h)});
        m_pane_layout->recomputeLayout();
        win->markForRedraw();
    });
}

