int main() {
#if !defined(BLAS_API)
    printf("\nRecompile with BLAS_API=1 to run this test!\n\n");
    exit(1);
#endif

    const int matrix_dim = 16;
    int idx;

    // Allocate and initialize matrix A: A[i] = i+1
    float* matA = (float*)malloc(matrix_dim * matrix_dim * sizeof(float));
    for (idx = 0; idx < matrix_dim * matrix_dim; ++idx) {
        matA[idx] = static_cast<float>(idx + 1);
    }

    const int lda = matrix_dim;

    // Allocate and initialize identity-like matrix B
    float* matB = (float*)malloc(matrix_dim * matrix_dim * sizeof(float));
    for (idx = 0; idx < matrix_dim * matrix_dim; ++idx) {
        matB[idx] = -0.0f;
    }
    for (idx = 0; idx < matrix_dim; ++idx) {
        matB[idx * (matrix_dim + 1)] = 1.0f;
    }

    const int ldb = matrix_dim;

    // Allocate and initialize matrix C with -1s
    float* matC = (float*)malloc(matrix_dim * matrix_dim * sizeof(float));
    for (idx = 0; idx < matrix_dim * matrix_dim; ++idx) {
        matC[idx] = -1.0f;
    }

    // Allocate second copy of C (for comparison)
    float* matC2 = (float*)malloc(matrix_dim * matrix_dim * sizeof(float));
    for (idx = 0; idx < matrix_dim * matrix_dim; ++idx) {
        matC2[idx] = -1.0f;
    }

    // Additional workspace matrices
    float* matD = (float*)malloc(matrix_dim * matrix_dim * sizeof(float));
    for (idx = 0; idx < matrix_dim * matrix_dim; ++idx) {
        matD[idx] = -1.0f;
    }
    const int ldd = matrix_dim;

    // Pivot array for LU factorization
    int* pivot = (int*)malloc(matrix_dim * sizeof(int));

    // Constants and parameters
    const int block_size = 4;
    const float zero = 0.0f;
    const float one = 1.0f;
    const int one_int = 1;
    const char lower_char = 'l';
    const char no_trans_char = 'n';
    const char upper_char = 'u';
    const char trans_char = 't';
    const float scalar_alpha = 2.0f;
    const float scalar_beta = 1.0f;

    // Matrix dimensions for BLAS calls
    const int dim_m = matrix_dim;
    const int dim_n = matrix_dim;
    const int dim_k = matrix_dim;

    // Print initial matrix A
    s_print_mat(matrix_dim, matrix_dim, matA, lda);

    // --- Standard BLAS section ---
    printf("\nBLAS\n");

    // Reset C
    for (idx = 0; idx < matrix_dim * matrix_dim; ++idx) {
        matC[idx] = -1.0f;
    }

    // Example: SGEMM — compute C = alpha * B * A^T + beta * C
    sgemm_(&trans_char, &trans_char, &dim_m, &dim_n, &dim_k,
           &scalar_alpha, matB, &lda, matA, &lda, &scalar_beta, matC, &lda);

    // --- BLASFEO BLAS API section ---
    printf("\nBLASFEO BLAS API\n");

    // Reset C2
    for (idx = 0; idx < matrix_dim * matrix_dim; ++idx) {
        matC2[idx] = -1.0f;
    }

    // Compute using BLASFEO's SGEMM: same operation as above
    blasfeo_sgemm(trans_char, trans_char, dim_m, dim_n, dim_k,
                  scalar_alpha, matB, lda, matA, lda,
                  scalar_beta, matC2, lda, matC2, lda);

    // Output results
    s_print_mat(matrix_dim, matrix_dim, matC, lda);
    s_print_mat(matrix_dim, matrix_dim, matC2, lda);

    // Compute difference: matC2 -= matC
    printf("\nerror\n");
    for (idx = 0; idx < matrix_dim * matrix_dim; ++idx) {
        matC2[idx] -= matC[idx];
    }
    s_print_mat(matrix_dim, matrix_dim, matC2, lda);

    // Cleanup
    free(matA);
    free(matB);
