#include <nanobind/nanobind.h>
#include <nanobind/stl/string.h>
#include <mscclpp/errors.hpp>

namespace nb = nanobind;
using namespace mscclpp;

// Helper lambda to register exception translator for a given exception type
auto register_exception_translator = [](nb::module_& mod, const char* name, nb::handle py_class) {
  nb::register_exception_translator(
      [py_class](const std::exception_ptr& p, void* payload) {
        try {
          std::rethrow_exception(p);
        } catch (const BaseError& e) {
          PyErr_SetObject(reinterpret_cast<PyObject*>(payload),
                          PyTuple_Pack(2,
                                       PyLong_FromLong(static_cast<long>(e.getErrorCode())),
                                       PyUnicode_FromString(e.what())));
        }
      },
      py_class.ptr());
};

void register_error(nb::module_& m) {
  // Define ErrorCode enum values via initializer list style
  nb::enum_<ErrorCode>(m, "ErrorCode")
      .value("SystemError",   ErrorCode::SystemError)
      .value("InternalError", ErrorCode::InternalError)
      .value("RemoteError",   ErrorCode::RemoteError)
      .value("InvalidUsage",  ErrorCode::InvalidUsage)
      .value("Timeout",       ErrorCode::Timeout)
      .value("Aborted",       ErrorCode::Aborted)
      .value("ExecutorError", ErrorCode::ExecutorError);

  // Register BaseError and its translator
  auto base_err = nb::exception<BaseError>(m, "BaseError");
  register_exception_translator(m, "BaseError", base_err);

  // Register derived exceptions in sequence
  auto err = nb::exception<Error>(m, "Error", base_err.ptr());
  register_exception_translator(m, "Error", err);

  auto sys_err = nb::exception<SysError>(m, "SysError", base_err.ptr());
  register_exception_translator(m, "SysError", sys_err);

  auto cuda_err = nb::exception<CudaError>(m, "CudaError", base_err.ptr());
  register_exception_translator(m, "CudaError", cuda_err);

  auto cu_err = nb::exception<CuError>(m, "CuError", base_err.ptr());
  register_exception_translator(m, "CuError", cu_err);

  auto ib_err = nb::exception<IbError>(m, "IbError", base_err.ptr());
  register_exception_translator(m, "IbError", ib_err);
}

