const SignalKind SignalKind::User2{SIGUSR2};
#endif

// Constructor initializes the signal kind and sets up notification tracking
Signal::Signal(SignalKind kind)
    : m_kind(kind),
      m_notified() {}

// Poll method: ensures signal subscription once, then delegates to notification
bool Signal::poll(Context& cx) {
    if (!m_notified.has_value()) {
        auto& driver = cx.runtime()->signalDriver();
        m_notified.emplace(driver.addSignal(m_kind).notified());
    }
    return m_notified->poll(cx);
}

