#include "nlink_unpack/nlink_utils.h"
#include "protocol_extracter/nprotocol_extracter.h"
#include <chrono>
#include <thread>

int main(int argc, char **argv) {
  ros::init(argc, argv, "tofsensem_parser");
  ros::NodeHandle nh;
  serial::Serial serial_port;
  initSerial(&serial_port);
  NProtocolExtracter parser;
  tofsensem::Init initializer(&parser);

  ros::Rate update_rate(1000);

  while (ros::ok()) {
    size_t bytes_available = serial_port.available();
    std::string buffer;

    if (bytes_available > 0) {
      serial_port.read(buffer, bytes_available);
      parser.ProcessNewData(buffer);
    } else {
      std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

