// Reset all specific allocators and the main bump pointer allocator
void eld::freeArena() {
  // Iterate through instances in reverse order and reset each one
  for (SpecificAllocBase *Alloc : llvm::reverse(SpecificAllocBase::Instances)) {
    Alloc->reset();
  }
  // Finally, reset the main bump allocator
  BAlloc.Reset();
}

