#include "test/jemalloc_test.h"
#include "jemalloc/internal/peak.h"

TEST_BEGIN(test_peak_variant) {
	peak_t peak = PEAK_INITIALIZER;

	// Initial state should be zero
	expect_u64_eq(0, peak_max(&peak),
	    "Initial peak value must be zero");

	// First update: alloc=100, dealloc=50 → net +50
	peak_update(&peak, 100, 50);
	expect_u64_eq(50, peak_max(&peak),
	    "Peak should reflect net allocation after first update");

	// Second update: alloc=100, dealloc=100 → net 0 (no change to peak)
	peak_update(&peak, 100, 100);
	expect_u64_eq(50, peak_max(&peak), 
	    "Deallocation alone shouldn't affect the peak");

	// Third update: alloc=100, dealloc=200 → net -100 (still below peak)
	peak_update(&peak, 100, 200);
	expect_u64_eq(50, peak_max(&peak), 
	    "Net deallocation shouldn't increase peak");

	// Fourth update: alloc=200, dealloc=200 → net 0 (still below peak)
	peak_update(&peak, 200, 200);
	expect_u64_eq(50, peak_max(&peak), 
	    "Still haven't reached previous peak level");

	// Fifth update: alloc=300, dealloc=200 → net +100 (new peak)
	peak_update(&peak, 300, 200);
	expect_u64_eq(100, peak_max(&peak), 
	    "New peak should be recorded after net increase");

	// Reset peak to zero while at net +100
	peak_set_zero(&peak, 300, 200);
	expect_u64_eq(0, peak_max(&peak), 
	    "Zeroing should reset the peak value");

	// Subsequent deallocations shouldn't raise the peak
	peak_update(&peak, 300, 300);
	expect_u64_eq(0, peak_max(&peak), 
	    "No-ops shouldn't affect peak");

	peak_update(&peak, 400, 300);
	expect_u64_eq(0, peak_max(&peak), 
	    "Still net negative; peak remains zero");

	peak_update(&peak, 500, 300);
	expect_u64_eq(100, peak_max(&peak), 
	    "Now net +200 from original baseline, but peak is 100");

	// Now test zeroing when current state is net deallocator
	peak_set_zero(&peak, 600, 700);
	expect_u64_eq(0, peak_max(&peak), 
	    "Zeroing works regardless of current net direction");

	peak_update(&peak, 600, 800);
	expect_u64_eq(0, peak_max(&peak), 
	    "Further net deallocation doesn’t affect peak");

	peak_update(&peak, 700, 800);
	expect_u64_eq(0, peak_max(&peak), 
	    "Still net negative overall");

	peak_update(&peak, 800, 800);
	expect_u64_eq(100, peak_max(&peak), 
	    "Back to net +100 relative to zeroed point, matching prior peak");
}
TEST_END

int
main(void) {
	return test_no_reentrancy(
	    test_peak_variant);
}

