/// @requirements(SEN-1061)
TEST(Rest, status_code) {
  struct TestCase {
    int code;
    std::string phrase;
  };

  const std::vector<TestCase> tests = {
    {200, "OK"},
    {403, "Forbidden"},
    {502, "Bad Gateway"}
  };

  for (const auto& tc : tests) {
    HttpResponse resp(tc.code);
    EXPECT_EQ(resp.getStatusCode(), tc.code);
    EXPECT_EQ(resp.getReasonPhrase(), tc.phrase);
  }
}

/// @test
/// Confirm proper serialization of HTTP headers
/// @requirements(SEN-1061)
TEST(Rest, serialization_headers) {
  {
    HttpResponse resp(200);
    EXPECT_EQ(resp.toBuffer(),
              std::string("HTTP/1.1 200 OK\r\n") +
              buildDefaultCorsHeaders() +
              "Content-Length: 0\r\n\r\n");
  }

  {
    std::vector<HttpHeader> hdrs = {{"Content-Type", "text/javascript; charset=utf-8"}};
    HttpResponse resp(200, hdrs);
    EXPECT_EQ(resp.toBuffer(),
              "HTTP/1.1 200 OK\r\n"
              "Content-Type: text/javascript; charset=utf-8\r\n" +
              buildDefaultCorsHeaders() +
              "Content-Length: 0\r\n\r\n");
  }

  {
    std::vector<HttpHeader> hdrs = {
      {"Cache-Control", "max-age=604800"},
      {"Content-Type", "text/javascript; charset=utf-8"}
    };
    HttpResponse resp(200, hdrs);
    std::string expected = "HTTP/1.1 200 OK\r\n"
                           "Cache-Control: max-age=604800\r\n"
                           "Content-Type: text/javascript; charset=utf-8\r\n" +
                           buildDefaultCorsHeaders() +
                           "Content-Length: 0\r\n\r\n";
    EXPECT_EQ(resp.toBuffer(), expected);
  }
}

/// @test
/// Ensure body content is correctly appended in serialized output
/// @requirements(SEN-1061)
TEST(Rest, body) {
  std::string payload = "hello world";
  std::vector<HttpHeader> hdrs = {{"Content-Type", "text/plain; charset=utf-8"}};
  HttpResponse resp(200, hdrs, payload);

  std::string expected = "HTTP/1.1 200 OK\r\n"
                         "Content-Type: text/plain; charset=utf-8\r\n" +
                         buildDefaultCorsHeaders() +
                         "Content-Length: " + std::to_string(payload.size()) + "\r\n\r\n" +
                         payload;

  EXPECT_EQ(resp.toBuffer(), expected);
}

/// @test
/// Validate behavior when CORS headers are explicitly disabled
/// @requirements(SEN-1061)
TEST(Rest, no_cors_headers) {
  HttpResponse resp(200, {}, "", false);
  EXPECT_EQ(resp.toBuffer(),
            "HTTP/1.1 200 OK\r\n"
            "Content-Length: 0\r\n\r\n");
}

