// Wrapper function to change file ownership using system calls
int chown(const char *path, uid_t uid, gid_t gid)
{
#if defined(SYS_chown)
	// Use direct chown system call if available
	return syscall(SYS_chown, path, uid, gid);
#else
	// Fallback to fchownat with AT_FDCWD for current directory
	return syscall(SYS_fchownat, AT_FDCWD, path, uid, gid, 0);
#endif
}

