#include "int_lib.h"

// Swap bytes in a 32-bit unsigned integer
COMPILER_RT_ABI uint32_t __bswapsi2(uint32_t value) {
    uint32_t result = 0;

    // Extract each byte and place it in the swapped position
    result |= (value & 0x000000FF) << 24;  // Move lowest byte to highest position
    result |= (value & 0x0000FF00) << 8;   // Move second byte to third position
    result |= (value & 0x00FF0000) >> 8;   // Move third byte to second position
    result |= (value & 0xFF000000) >> 24;  // Move highest byte to lowest position

    return result;
}

