int main() {
    int n;
    std::cout << "Enter your number: ";
    std::cin >> n;

    if (n <= 1) {
        std::cout << "It is not prime" << std::endl;
    } else {
        bool isPrime = true;
        for (int i = 2; i * i <= n; ++i) {
            if (n % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            std::cout << "It is prime" << std::endl;
        } else {
            std::cout << "It is not prime" << std::endl;
        }
    }

    return 0;
}

