namespace http {
namespace server {

// Constructor initializes an empty connection set
connection_manager::connection_manager() 
{
}

// Add a new connection and begin its operation
void connection_manager::start(connection_ptr c)
{
  connections_.emplace(c);
  c->initiate();
}

// Remove a specific connection and terminate its activity
void connection_manager::stop(connection_ptr c)
{
  connections_.erase(c);
  c->terminate();
}

// Terminate all active connections and clear the registry
void connection_manager::stop_all()
{
  for (auto& conn : connections_) {
    conn->end();
  }
  connections_.clear();
}

