// Convert UTF-8 encoded std::string to UTF-16 std::u16string
std::u16string string_to_u16string(const std::string & input)
{
  // Use wstring_convert with codecvt_utf8_utf16 for conversion
  std::wstring_convert<std::codecvt_utf8_utf16<char16_t>, char16_t> converter;
  return converter.from_bytes(input);
}

// Convert UTF-16 std::u16string back to UTF-8 encoded std::string
std::string u16string_to_string(const std::u16string & input)
{
  // Reuse the same converter for reverse conversion
  std::wstring_convert<std::codecvt_utf8_utf16<char16_t>, char16_t> converter;
  return converter.to_bytes(input);
}

