// A pollable that always throws during polling
struct AlwaysThrowingPollable : arc::Pollable<AlwaysThrowingPollable> {
    bool poll(arc::Context& cx) {
        throw std::runtime_error("Polling operation intentionally fails");
        return false;
    }
};

// A pollable that completes successfully without throwing
struct SuccessfulPollable : arc::NoexceptPollable<SuccessfulPollable, void> {
    bool poll(arc::Context& cx) noexcept {
        return true;
    }
};

// Main asynchronous function demonstrating exception handling
Future<> asyncMain() {
    // First await a non-throwing pollable
    co_await SuccessfulPollable{};

    // Then attempt to await a throwing pollable with exception handling
    try {
        co_await AlwaysThrowingPollable{};
        fmt::println("No exception was thrown");
    } catch (const std::exception& ex) {
        fmt::println("Exception caught from AlwaysThrowingPollable: {}", ex.what());
    } catch (...) {
        fmt::println("Unknown exception type caught from AlwaysThrowingPollable");
    }
}

ARC_DEFINE_MAIN_NT(asyncMain, 1);

