class TByteOrderSwapTest : public TTestBase {
    UNIT_TEST_SUITE(TByteOrderSwapTest);
    UNIT_TEST(TestSwap16Bit)
    UNIT_TEST(TestSwap32Bit)
    UNIT_TEST(TestSwap64Bit)
    UNIT_TEST_SUITE_END();

private:
    inline void TestSwap16Bit() {
        const ui16 original = 0x3412;
        const ui16 expected = 0x1234;
        UNIT_ASSERT_EQUAL(expected, SwapBytes(original));
    }

    inline void TestSwap32Bit() {
        const ui32 input = 0x78563412;
        const ui32 target = 0x12345678;
        UNIT_ASSERT_EQUAL(target, SwapBytes(input));
    }

    inline void TestSwap64Bit() {
        const ui64 value = (ui64)ULL(0xefcdab9078563412);
        const ui64 reference = 0x1234567890abcdefULL;
        UNIT_ASSERT_EQUAL(reference, SwapBytes(value));
    }
};

UNIT_TEST_SUITE_REGISTRATION(TByteOrderSwapTest);

