          "Ch Count",   "Model file",  "Pos X",     "Pos Y",
          "Pos Z",      "Roll (X)",    "Pitch (Y)", "Yaw (Z)",
          "Power (W)",  "Weight (kg)", "Color"};
}

void ConfigureColumns(wxDataViewListCtrl *table,
                      const std::vector<wxString> &labels) {
  // Predefined column widths — aligned with original order
  const std::vector<int> colWidths = {90, 150, 180, 100, 120, 80, 80, 120, 80, 180,
                                      80, 80,  80,  80,  80,  80, 100, 100, 80};

  const int commonFlags = wxDATAVIEW_COL_RESIZABLE | wxDATAVIEW_COL_SORTABLE;

  // First 7 columns use standard text renderer
  for (int idx = 0; idx < 7; ++idx) {
    auto *renderer = new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT);
    table->AppendColumn(
        new wxDataViewColumn(labels[idx], renderer, idx,
                             colWidths[idx], wxALIGN_LEFT, commonFlags));
  }

  // Middle columns (indices 7 to n-2) also use same renderer
  size_t midStart = 7;
  size_t midEnd = labels.size() - 1;
  for (size_t i = midStart; i < midEnd; ++i) {
    auto *renderer = new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT);
    table->AppendColumn(
        new wxDataViewColumn(labels[i], renderer, static_cast<int>(i),
                             colWidths[i], wxALIGN_LEFT, commonFlags));
  }

  // Last column uses icon-text renderer
  auto *iconTextRenderer =
      new ColorfulIconTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT);
  iconTextRenderer->EnableEllipsize(wxELLIPSIZE_NONE);
  size_t lastIdx = labels.size() - 1;
  table->AppendColumn(
      new wxDataViewColumn(labels[lastIdx], iconTextRenderer,
                           static_cast<int>(lastIdx),
                           colWidths[lastIdx], wxALIGN_LEFT, commonFlags));

  ColumnUtils::EnforceMinColumnWidth(table);
}

} // namespace FixtureTableColumns

