////////////////////////////////////////////////////////////////////////////////
/// test_simpleString
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_simpleString) {
  std::string input_str = "test";
  std::vector<AttributeName> parsed_attrs;
  ParseAttributeString(input_str, parsed_attrs, false);

  ASSERT_EQ(parsed_attrs.size(), static_cast<size_t>(1));
  EXPECT_EQ(parsed_attrs[0].name, input_str);
  EXPECT_FALSE(parsed_attrs[0].should_expand);
}

////////////////////////////////////////////////////////////////////////////////
/// test_subAttribute
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_subAttribute) {
  std::string input_str = "foo.bar";
  std::vector<AttributeName> parsed_attrs;
  ParseAttributeString(input_str, parsed_attrs, false);

  ASSERT_EQ(parsed_attrs.size(), static_cast<size_t>(2));
  EXPECT_EQ(parsed_attrs[0].name, "foo");
  EXPECT_FALSE(parsed_attrs[0].should_expand);
  EXPECT_EQ(parsed_attrs[1].name, "bar");
  EXPECT_FALSE(parsed_attrs[1].should_expand);
}

////////////////////////////////////////////////////////////////////////////////
/// test_subsubAttribute
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_subsubAttribute) {
  std::string input_str = "foo.bar.baz";
  std::vector<AttributeName> parsed_attrs;
  ParseAttributeString(input_str, parsed_attrs, false);

  ASSERT_EQ(parsed_attrs.size(), static_cast<size_t>(3));
  EXPECT_EQ(parsed_attrs[0].name, "foo");
  EXPECT_FALSE(parsed_attrs[0].should_expand);
  EXPECT_EQ(parsed_attrs[1].name, "bar");
  EXPECT_FALSE(parsed_attrs[1].should_expand);
  EXPECT_EQ(parsed_attrs[2].name, "baz");
  EXPECT_FALSE(parsed_attrs[2].should_expand);
}

