////////////////////////////////////////////////////////////////////////////////
/// test_invalidAttributeAfterExpand
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_invalidAttributeAfterExpand) {
  std::string input_str = "foo[*]bar";
  std::vector<AttributeName> parsed_attrs;

  try {
    ParseAttributeString(input_str, parsed_attrs, false);
    FAIL() << "Expected exception not thrown for invalid format (expand mode off)";
  } catch (Exception& e) {
    EXPECT_EQ(e.code(), sdb::ERROR_BAD_PARAMETER);
  }

  try {
    ParseAttributeString(input_str, parsed_attrs, true);
    FAIL() << "Expected exception not thrown for invalid format (expand mode on)";
  } catch (Exception& e) {
    EXPECT_EQ(e.code(), sdb::ERROR_SERVER_ATTRIBUTE_PARSER_FAILED);
  }
}

