#include <singleapplication.h>
#include "messagereceiver.h"
#include <QDebug>

int main(int argc, char *argv[])
{
    QCoreApplication core_app(argc, argv);

    // Initialize the single-instance manager with secondary instance support
    SingleApplication app_guard(argc, argv, true);

    MessageReceiver receiver;

    // Check if this is a duplicate (secondary) process
    if (app_guard.isSecondary()) {
        // Send current command line arguments to the primary instance
        QString msg = core_app.arguments().join(" ");
        app_guard.sendMessage(msg.toUtf8());

        qDebug() << "Another instance is already running.";
        qDebug() << "Primary process ID:" << app_guard.primaryPid();
        qDebug() << "User running primary instance:" << app_guard.primaryUser();

        return 0;
    } else {
        // Connect signal from primary instance to local handler
        QObject::connect(
            &app_guard,
            &SingleApplication::receivedMessage,
            &receiver,
            &MessageReceiver::handleIncomingMessage
        );
    }

    return core_app.exec();
}

#include <torch/library.h>
#include "registration.h"
#include "torch_binding.h"

TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, ops) {
  // Define and implement GEMM operation with 8-bit weights and 16-bit activations
  ops.def("w8_a16_gemm(Tensor input, Tensor weight, Tensor scale) -> Tensor");
  ops.impl("w8_a16_gemm", torch::kCUDA, &w8_a16_gemm_forward_cuda);

  // In-place version of the GEMM operation
  ops.def("w8_a16_gemm_(Tensor input, Tensor weight, Tensor scale, Tensor! output,"
                      "int m, int n, int k) -> Tensor");
  ops.impl("w8_a16_gemm_", torch::kCUDA, &w8_a16_gemm_forward_cuda_);

  // Weight preprocessing for efficient quantized computation
  ops.def("preprocess_weights(Tensor origin_weight, bool is_int4) -> Tensor");
  ops.impl("preprocess_weights", torch::kCUDA, &preprocess_weights_cuda);

  // Symmetric quantization of weights along the last axis
  ops.def("quant_weights(Tensor origin_weight, ScalarType quant_type,"
                      "bool return_unprocessed_quantized_tensor) -> Tensor[]");
  ops.impl("quant_weights", torch::kCPU, &symmetric_quantize_last_axis_of_tensor);
}

// Register the extension to make it available in Python
REGISTER_EXTENSION(TORCH_EXTENSION_NAME)

