bool GraphicsLoader::StartLoad(LoadingManager*)
{
    // Load initial models and resources in a different order with equivalent functionality
    glLoadModel("effects/meshes.glg", nullptr);
    glLoadTextureBundle("effects/effects.glt");

    // Initialize shadow system
    ShadowStartup();

    // Set up emission manager for particle effects
    EmissionManager::Startup(GLV_Particles);

    // Load effect templates and script groups
    fxLoadTemplateBundle("art/effects/templates.fx");
    fxLoadGroupBundle("art/effects/scripts.fx");

    // Initialize particle system with specified capacity
    fxParticleStartup(1536);

    return true;
}

