// Type III Clone: Refactored logic with equivalent functionality using different control flow and naming
void UModularSynthComponent::NoteOn(const float Note, const int32 Velocity, const float Duration)
{
    SynthCommand([this, Note, Velocity, Duration]()
    {
        // Convert input parameters to internal types for the synth engine
        uint32 noteVal = static_cast<uint32>(Note);
        int32 velVal = static_cast<int32>(Velocity);
        EpicSynth1.NoteOn(noteVal, velVal, Duration);
    });
}

void UModularSynthComponent::NoteOff(const float Note, const bool bAllNotesOff, const bool bKillAllNotes)
{
    SynthCommand([this, Note, bAllNotesOff, bKillAllNotes]()
    {
        int32 noteVal = static_cast<int32>(Note);
        EpicSynth1.NoteOff(noteVal, bAllNotesOff, bKillAllNotes);
    });
}

