        EpicSynth1.SetChorusDepth(Audio::EChorusDelays::Left, Depth);
        EpicSynth1.SetChorusDepth(Audio::EChorusDelays::Center, Depth);
        EpicSynth1.SetChorusDepth(Audio::EChorusDelays::Right, Depth);
    });
}

