#define TILING_KEY_INT 23
#define TILING_KEY_A2_INT 123

extern "C" __global__ __aicore__ void dispatch_layout(
    GM_ADDR topkIdx,
    GM_ADDR numTokensPerRank,
    GM_ADDR numTokensPerExpert,
    GM_ADDR isTokenInRank,
    GM_ADDR notifySendData,
    GM_ADDR sendTokenIdxSmall,
    GM_ADDR workspace,
    GM_ADDR tiling)
{
    // Register and retrieve tiling data using default mechanism
    REGISTER_TILING_DEFAULT(DispatchLayoutTilingData);
    GET_TILING_DATA_WITH_STRUCT(DispatchLayoutTilingData, tilingData, tiling);

    TPipe pipe;

    // Determine which operator to instantiate based on tiling key
    bool useStandardLayout = (TILING_KEY == TILING_KEY_INT);
    bool useA2Layout       = (TILING_KEY == TILING_KEY_A2_INT);

    if (useStandardLayout) {
        MoeDispatchLayout::DispatchLayout<int32_t> op;
        op.Init(topkIdx, numTokensPerRank, numTokensPerExpert, isTokenInRank,
                notifySendData, sendTokenIdxSmall, workspace, &pipe, &tilingData);
        op.Run();
    } else if (useA2Layout) {
        MoeDispatchLayoutA2::DispatchLayoutA2<int32_t> op;
        op.Init(topkIdx, numTokensPerRank, numTokensPerExpert, isTokenInRank,
                notifySendData, sendTokenIdxSmall, workspace, &pipe, &tilingData);
        op.Run();
    }
}

#include <iostream>
#include <cstdlib>

// Calculate area of square using side length
void calculateSquareArea(int sideLength) {
    int result = sideLength * sideLength;
    std::cout << "area of square= " << result << std::endl;
}

// Calculate perimeter of rectangle using length and width
void calculateRectanglePerimeter(int lengthVal, int widthVal) {
    int perimeter = 2 * (lengthVal + widthVal);
    std::cout << "perimeter of rectangle= " << perimeter << std::endl;
}

// Calculate area of circle using radius (approximating pi as 3.14)
void calculateCircleArea(int radiusVal) {
    float area = 3.14f * radiusVal * radiusVal;
    std::cout << "area of circle= " << area << std::endl;
}

// Find maximum among three numbers
int findMaximum(int firstNum, int secondNum, int thirdNum) {
    int maxVal = firstNum;
    if (secondNum > maxVal) maxVal = secondNum;
    if (thirdNum > maxVal) maxVal = thirdNum;
    return maxVal;
}

// Generate multiplication table for a number
void generateMultiplicationTable(int baseNumber) {
    std::cout << "table of " << baseNumber << ":" << std::endl;
    for (int i = 1; i <= 10; ++i) {
        std::cout << baseNumber << " * " << i << " = " << (baseNumber * i) << std::endl;
    }
}

int main() {
    int choice = 0;
    int side, length, width, radius, num1, num2, num3, tableNum;

    while (choice != 6) {
        system("cls");

        std::cout << "1. area of square" << std::endl;
        std::cout << "2. perimeter of rectangle" << std::endl;
        std::cout << "3. area of circle" << std::endl;
        std::cout << "4. max of 3 nos" << std::endl;
        std::cout << "5. table of number" << std::endl;
        std::cout << "6. exit" << std::endl;
        std::cout << "enter any choice: ";

        std::cin >> choice;

        switch (choice) {
            case 1:
                std::cout << "enter any side: ";
                std::cin >> side;
                calculateSquareArea(side);
                break;

            case 2:
                std::cout << "enter length and breadth: ";
                std::cin >> length >> width;
                calculateRectanglePerimeter(length, width);
                break;

            case 3:
                std::cout << "enter radius: ";
                std::cin >> radius;
                calculateCircleArea(radius);
                break;

            case 4:
                std::cout << "enter three numbers: ";
                std::cin >> num1 >> num2 >> num3;
                int maxResult = findMaximum(num1, num2, num3);
                std::cout << "max of 3 nos= " << maxResult << std::endl;
                break;

            case 5:
                std::cout << "enter number for table: ";
                std::cin >> tableNum;
                generateMultiplicationTable(tableNum);
                break;

            case 6:
                std::cout << "Exiting..." << std::endl;
                break;

            default:
                std::cout << "Invalid choice! Please try again." << std::endl;
                break;
        }

        if (choice != 6) {
            std::cout << "Press Enter to continue...";
            std::cin.ignore();
            std::cin.get();
        }
    }

    return 0;
}

#include "test/jemalloc_test.h"
#define BILLION	UINT64_C(1000000000)

TEST_BEGIN(test_nstime_init) {
	nstime_t time_val;
	nstime_init(&time_val, 42000000043ULL);
	expect_u64_eq(nstime_ns(&time_val), 42000000043ULL, "nanoseconds value mismatch");
	expect_u64_eq(nstime_sec(&time_val), 42ULL, "seconds value mismatch");
	expect_u64_eq(nstime_nsec(&time_val), 43ULL, "nanoseconds portion mismatch");
}
TEST_END

TEST_BEGIN(test_nstime_init2) {
	nstime_t time_val;
	nstime_init2(&time_val, 42ULL, 43ULL);
	expect_u64_eq(nstime_sec(&time_val), 42ULL, "seconds value mismatch");
	expect_u64_eq(nstime_nsec(&time_val), 43ULL, "nanoseconds value mismatch");
}
TEST_END

TEST_BEGIN(test_nstime_copy) {
	nstime_t src_time, dst_time;
	nstime_init2(&src_time, 42ULL, 43ULL);
	nstime_init_zero(&dst_time);
	nstime_copy(&dst_time, &src_time);
	expect_u64_eq(nstime_sec(&dst_time), 42ULL, "copied seconds value mismatch");
	expect_u64_eq(nstime_nsec(&dst_time), 43ULL, "copied nanoseconds value mismatch");
}
TEST_END

TEST_BEGIN(test_nstime_compare) {
	nstime_t t1, t2;
	nstime_init2(&t1, 42ULL, 43ULL);
	nstime_copy(&t2, &t1);
	expect_d_eq(nstime_compare(&t1, &t2), 0, "equal times should return zero");
	expect_d_eq(nstime_compare(&t2, &t1), 0, "equal times should return zero");

	nstime_init2(&t2, 42ULL, 42ULL);
	expect_d_eq(nstime_compare(&t1, &t2), 1, "t1 should be greater than t2");
	expect_d_eq(nstime_compare(&t2, &t1), -1, "t2 should be less than t1");

	nstime_init2(&t2, 42ULL, 44ULL);
	expect_d_eq(nstime_compare(&t1, &t2), -1, "t1 should be less than t2");
	expect_d_eq(nstime_compare(&t2, &t1), 1, "t2 should be greater than t1");

	nstime_init2(&t2, 41ULL, BILLION - 1ULL);
	expect_d_eq(nstime_compare(&t1, &t2), 1, "t1 should be greater than t2");
	expect_d_eq(nstime_compare(&t2, &t1), -1, "t2 should be less than t1");

	nstime_init2(&t2, 43ULL, 0ULL);
	expect_d_eq(nstime_compare(&t1, &t2), -1, "t1 should be less than t2");
	expect_d_eq(nstime_compare(&t2, &t1), 1, "t2 should be greater than t1");
}
TEST_END

TEST_BEGIN(test_nstime_add) {
	nstime_t sum_time, addend;
	nstime_init2(&sum_time, 42ULL, 43ULL);
	nstime_copy(&addend, &sum_time);
	nstime_add(&sum_time, &addend);
	nstime_init2(&addend, 84ULL, 86ULL);
	expect_d_eq(nstime_compare(&sum_time, &addend), 0, "addition result incorrect");

	nstime_init2(&sum_time, 42ULL, BILLION - 1ULL);
	nstime_copy(&addend, &sum_time);
	nstime_add(&sum_time, &addend);
	nstime_init2(&addend, 85ULL, BILLION - 2ULL);
	expect_d_eq(nstime_compare(&sum_time, &addend), 0, "addition with carry result incorrect");
}
TEST_END

TEST_BEGIN(test_nstime_iadd) {
	nstime_t val;
	nstime_init2(&val, 42ULL, BILLION - 1ULL);
	nstime_iadd(&val, 1ULL);
	nstime_init2(val, 43ULL, 0ULL);
	expect_d_eq(nstime_compare(&val, &val), 0, "increment by 1 ns result incorrect");

	nstime_init2(&val, 42ULL, 1ULL);
	nstime_iadd(&val, BILLION + 1ULL);
	nstime_init2(val, 43ULL, 2ULL);
	expect_d_eq(nstime_compare(&val, &val), 0, "increment across second boundary result incorrect");
}
TEST_END

TEST_BEGIN(test_nstime_subtract) {
	nstime_t diff_time, subtrahend;
	nstime_init2(&diff_time, 42ULL, 43ULL);
	nstime_copy(&subtrahend, &diff_time);
	nstime_subtract(&diff_time, &subtrahend);
	nstime_init_zero(&subtrahend);
	expect_d_eq(nstime_compare(&diff_time, &subtrahend), 0, "subtraction result incorrect");

	nstime_init2(&diff_time, 42ULL, 43ULL);
	nstime_init2(&subtrahend, 41ULL, 44ULL);
	nstime_subtract(&diff_time, &subtrahend);
	nstime_init2(&subtrahend, 0ULL, BILLION - 1ULL);
	expect_d_eq(nstime_compare(&diff_time, &subtrahend), 0, "borrowing subtraction result incorrect");
}
TEST_END

TEST_BEGIN(test_nstime_isubtract) {
	nstime_t val;
	nstime_init2(&val, 42ULL, 43ULL);
	nstime_isubtract(&val, 42ULL * BILLION + 43ULL);
	nstime_init_zero(&val);
	expect_d_eq(nstime_compare(&val, &val), 0, "subtract entire time result incorrect");

	nstime_init2(&val, 42ULL, 43ULL);
	nstime_isubtract(&val, 41ULL * BILLION + 44ULL);
	nstime_init2(&val, 0ULL, BILLION - 1ULL);
	expect_d_eq(nstime_compare(&val, &val), 0, "borrowing subtraction result incorrect");
}
TEST_END

TEST_BEGIN(test_nstime_imultiply) {
	nstime_t val;
	nstime_init2(&val, 42ULL, 43ULL);
	nstime_imultiply(&val, 10ULL);
	nstime_init2(&val, 420ULL, 430ULL);
	expect_d_eq(nstime_compare(&val, &val), 0, "multiply by scalar result incorrect");

	nstime_init2(&val, 42ULL, 666666666ULL);
	nstime_imultiply(&val, 3ULL);
	nstime_init2(&val, 127ULL, 999999998ULL);
	expect_d_eq(nstime_compare(&val, &val), 0, "multiply with carry result incorrect");
}
TEST_END

TEST_BEGIN(test_nstime_idivide) {
	nstime_t val, original;
	nstime_init2(&val, 42ULL, 43ULL);
	nstime_copy(&original, &val);
	nstime_imultiply(&val, 10ULL);
	nstime_idivide(&val, 10ULL);
	expect_d_eq(nstime_compare(&val, &original), 0, "divide by scalar result incorrect");

	nstime_init2(&val, 42ULL, 666666666ULL);
	nstime_copy(&original, &val);
	nstime_imultiply(&val, 3ULL);
	nstime_idivide(&val, 3ULL);
	expect_d_eq(nstime_compare(&val, &original), 0, "divide with remainder result incorrect");
}
TEST_END

TEST_BEGIN(test_nstime_divide) {
	nstime_t dividend, divisor, temp;
	nstime_init2(&dividend, 42ULL, 43ULL);
	nstime_copy(&divisor, &dividend);
	nstime_imultiply(&dividend, 10ULL);
	expect_u64_eq(nstime_divide(&dividend, &divisor), 10ULL, "division quotient incorrect");

	nstime_init2(&dividend, 42ULL, 43ULL);
	nstime_copy(&divisor, &dividend);
	nstime_imultiply(&dividend, 10ULL);
	nstime_init(&temp, 1ULL);
	nstime_add(&dividend, &temp);
	expect_u64_eq(nstime_divide(&dividend, &divisor), 10ULL, "division with remainder truncated");

	nstime_init2(&dividend, 42ULL, 43ULL);
	nstime_copy(&divisor, &dividend);
	nstime_imultiply(&dividend, 10ULL);
	nstime_init(&temp, 1ULL);
	nstime_subtract(&dividend, &temp);
	expect_u64_eq(nstime_divide(&dividend, &divisor), 9ULL, "division rounding down");
}
TEST_END

static void
test_nstime_since_once(nstime_t *current_time) {
	nstime_t previous_time;
	nstime_copy(&previous_time, current_time);
	uint64_t elapsed_ns = nstime_ns_since(current_time);
	nstime_update(current_time);
	nstime_t delta;
	nstime_copy(&delta, current_time);
	nstime_subtract(&delta, &previous_time);
	expect_u64_ge(nstime_ns(&delta), elapsed_ns, "elapsed time measurement incorrect");
}

TEST_BEGIN(test_nstime_ns_since) {
	nstime_t current_time;
	nstime_init_update(&current_time);
	for (uint64_t iteration = 0; iteration < 10000ULL; iteration++) {
		test_nstime_since_once(&current_time);
	}
}
TEST_END

TEST_BEGIN(test_nstime_monotonic) {
	nstime_monotonic();
}
TEST_END

int
main(void) {
	return test(
	    test_nstime_init,
	    test_nstime_init2,
	    test_nstime_copy,
	    test_nstime_compare,
	    test_nstime_add,
	    test_nstime_iadd,
	    test_nstime_subtract,
	    test_nstime_isubtract,
	    test_nstime_imultiply,
	    test_nstime_idivide,
	    test_nstime_divide,
	    test_nstime_ns_since,
	    test_nstime_monotonic);
}

