// Overload for 1D vector: prints elements separated by spaces
template <typename T>
IGL_INLINE void igl::print_vector(std::vector<T>& v)
{
  using namespace std;
  int len = v.size();
  for (int idx = 0; idx < len; ++idx)
    cerr << v[idx] << " ";
  cerr << endl;
}

// Overload for 2D vector: prints each row with its index prefix
template <typename T>
IGL_INLINE void igl::print_vector(std::vector<std::vector<T>>& v)
{
  using namespace std;
  int rows = v.size();
  for (int row_idx = 0; row_idx < rows; ++row_idx)
  {
    cerr << row_idx << ": ";
    int cols = v[row_idx].size();
    for (int col_idx = 0; col_idx < cols; ++col_idx)
      cerr << v[row_idx][col_idx] << " ";
    cerr << endl;
  }
}

// Overload for 3D vector: prints each 2D matrix with header and footer markers
template <typename T>
IGL_INLINE void igl::print_vector(std::vector<std::vector<std::vector<T>>>& v)
{
  using namespace std;
  int matrices = v.size();
  for (int mat_num = 0; mat_num < matrices; ++mat_num)
  {
    cerr << "Matrix " << mat_num << endl;
    int rows = v[mat_num].size();
    for (int row_idx = 0; row_idx < rows; ++row_idx)
    {
      cerr << row_idx << ": ";
      int cols = v[mat_num][row_idx].size();
      for (int col_idx = 0; col_idx < cols; ++col_idx)
        cerr << v[mat_num][row_idx][col_idx] << " ";
      cerr << endl;
    }
    cerr << "---- end " << mat_num << endl;
  }
}

