#include <iostream>
#include <string>
#include <asio.hpp>

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: daytime_client <host>" << std::endl;
      return 1;
    }

    asio::io_context io_context;
    tcp::resolver resolver(io_context);
    auto endpoint_iterator = resolver.resolve(argv[1], "daytime");

    tcp::socket socket(io_context);
    asio::connect(socket, endpoint_iterator);

    asio::streambuf request_buf;
    std::ostream request_stream(&request_buf);
    request_stream << "\r\n";

    asio::write(socket, request_buf);

    asio::streambuf response_buf;
    asio::error_code ec;
    size_t bytes_transferred = asio::read_until(socket, response_buf, "\r\n", ec);

    if (ec)
    {
      std::cout << "Error reading response: " << ec.message() << std::endl;
      return 1;
    }

    std::string line;
    std::istream response_stream(&response_buf);
    std::getline(response_stream, line);
    std::cout << line << std::endl;
  }
  catch (std::exception& e)
  {
    std::cout << "Exception: " << e.what() << std::endl;
  }

  return 0;
}

