LOGMODULE("shutdown");

CShutdown::CShutdown(TShutdownMode mode, int delayMs)
:	m_mode(mode),
	m_msdelay(delayMs)
{
	SetName("shutdownservice");
	LOGNOTE("Scheduled shutdown request: mode=%d, delay=%d ms", m_mode, m_msdelay);
}

CShutdown::~CShutdown(void) {
	// Destructor intentionally left empty
}

void CShutdown::Run(void) {
	int waitTime = m_msdelay;
	TShutdownMode targetMode = m_mode;

	LOGNOTE("Initiating delayed shutdown: waiting %d milliseconds", waitTime);
	CScheduler* scheduler = CScheduler::Get();
	assert(scheduler != nullptr);
	scheduler->MsSleep(waitTime);

	CDeviceState* deviceState = DeviceState::GetPtr();
	if (deviceState != nullptr) {
		deviceState->setShutdownMode(targetMode);
	}
}

