void OreRecipies::_init() {
    // Initialize recipe storage: each entry holds [inputTile, outputItemInstance]
    oreRecipeMap = new vector<Object*>[MAX_ORE_RECIPES];

    // Register gold block <-> gold ingot
    oreRecipeMap[0].push_back(Tile::goldBlock);
    oreRecipeMap[0].push_back(new ItemInstance(Item::goldIngot, 9));

    // Register iron block <-> iron ingot
    oreRecipeMap[1].push_back(Tile::ironBlock);
    oreRecipeMap[1].push_back(new ItemInstance(Item::ironIngot, 9));

    // Register diamond block <-> diamond
    oreRecipeMap[2].push_back(Tile::diamondBlock);
    oreRecipeMap[2].push_back(new ItemInstance(Item::diamond, 9));

    // Register emerald block <-> emerald
    oreRecipeMap[3].push_back(Tile::emeraldBlock);
    oreRecipeMap[3].push_back(new ItemInstance(Item::emerald, 9));

    // Register lapis lazuli block <-> blue dye
    oreRecipeMap[4].push_back(Tile::lapisBlock);
    oreRecipeMap[4].push_back(new ItemInstance(Item::dye_powder, 9, DyePowderItem::BLUE));
}

void OreRecipies::addRecipes(Recipes *recipeRegistry) {
    // Iterate through all registered ore recipes
    for (int idx = 0; idx < MAX_ORE_RECIPES; ++idx) {
        // Extract source tile and destination item from current recipe slot
        Tile* inputTile = static_cast<Tile*>(oreRecipeMap[idx][0]);
        ItemInstance* outputItem = static_cast<ItemInstance*>(oreRecipeMap[idx][1]);

        // Add shapeless recipe: 9 ingots → 1 ore block (reverse transformation)
        recipeRegistry->addShapedRecipy(
            new ItemInstance(inputTile),
            L"sssczg",
            L"###", 
            L"###", 
            L"###", 
            L'#', outputItem,
            L'D'
        );

        // Add shaped recipe: 1 ore block → 9 ingots (forward transformation)
        recipeRegistry->addShapedRecipy(
            outputItem,
            L"sctg",
            L"#", 
            L'#', inputTile,
            L'D'
        );
    }
}

