#include "pch.h"
#include "Patcher.h"

void patcher::PatchAddress(void* target, const std::vector<BYTE>* patchData)
{
    DWORD previousProtection;
    VirtualProtect(target, patchData->size(), PAGE_EXECUTE_READWRITE, &previousProtection);

    // Copy the patch bytes to the target address
    for (size_t i = 0; i < patchData->size(); ++i) {
        static_cast<BYTE*>(target)[i] = (*patchData)[i];
    }

    // Restore original memory protection
    VirtualProtect(target, patchData->size(), previousProtection, &previousProtection);

    // Ensure CPU instruction cache is invalidated
    FlushInstructionCache(GetCurrentProcess(), target, patchData->size());
}

