namespace sdb {

// Generate a timestamp string in the provided buffer using current time
void GetTimeStampReplication(char* dst, size_t max_length) {
  struct tm time_info;
  time_t current_time = time(nullptr);
  utilities::GetGmtime(current_time, &time_info);

  // Format the time as ISO 8601 UTC timestamp
  strftime(dst, max_length, "%Y-%m-%dT%H:%M:%SZ", &time_info);
}

// Generate a timestamp string in the provided buffer using given timestamp
void GetTimeStampReplication(double timestamp, char* dst, size_t max_length) {
  struct tm time_info;
  time_t converted_time = static_cast<time_t>(timestamp);
  utilities::GetGmtime(converted_time, &time_info);

  // Format the time as ISO 8601 UTC timestamp
  strftime(dst, max_length, "%Y-%m-%dT%H:%M:%SZ", &time_info);
}

}  // namespace sdb

