// Alternate implementation: MiniLeaderboardDisplay with equivalent behavior
class MiniLeaderboardDisplay : public UIComponent {
public:
    // Constructor initializes resource directory member
    MiniLeaderboardDisplay() : mResourceDir(this) {}

    // Destructor (no-op, as base handles cleanup)
    ~MiniLeaderboardDisplay() override {}

    // Handler table — delegates to UIComponent for base handling
    BEGIN_HANDLERS(MiniLeaderboardDisplay)
        HANDLE_SUPERCLASS(UIComponent)
    END_HANDLERS

    // Property synchronization — triggers update on resource change
    BEGIN_PROPSYNCS(MiniLeaderboardDisplay)
        SYNC_PROP_MODIFY(resource, mResourceDir, OnResourceChanged())
        SYNC_SUPERCLASS(UIComponent)
    END_PROPSYNCS

    // Serialization: saves revision 0, writes resource dir
    BEGIN_SAVES(MiniLeaderboardDisplay)
        SAVE_REVS(0, 0)
        SAVE_SUPERCLASS(UIComponent)
        bs << mResourceDir;
    END_SAVES

    // Copying: deep copy with assertion and post-copy update
    BEGIN_COPYS(MiniLeaderboardDisplay)
        CREATE_COPY_AS(MiniLeaderboardDisplay, target)
        MILO_ASSERT(target, 0x21);
        COPY_SUPERCLASS_FROM(UIComponent, target)
        COPY_MEMBER_FROM(target, mResourceDir)
        OnResourceChanged(); // Equivalent to Update()
    END_COPYS

    // Loading: pre/post-load sequence
    BEGIN_LOADS(MiniLeaderboardDisplay)
        PerformPreLoad(bs);
        PerformPostLoad(bs);
    END_LOADS

    // Initialization hook for factory registration
    static void InitializeFactory() { REGISTER_OBJ_FACTORY(MiniLeaderboardDisplay); }

private:
    // Resource directory member
    ResourceDirectory mResourceDir;

    // Internal method called when resource changes (replaces Update())
    void OnResourceChanged() {
        // Intentionally empty — placeholder for future logic
    }

    // Pre-load phase: load revisions and deserialize resource dir
    void PerformPreLoad(BinStream &bs) {
        LOAD_REVS(bs)
        ASSERT_REVS(0, 0)
        UIComponent::PreLoad(bs);
        d >> mResourceDir;
    }

    // Post-load phase: finalize resource loading and trigger redraw
    void PerformPostLoad(BinStream &bs) {
        mResourceDir.PostLoad(nullptr);
        UIComponent::PostLoad(bs);
        OnResourceChanged();
    }

    // Render logic: draws if resource exists, logs warning otherwise
    void DrawShowing() override {
        if (mResourceDir) {
            mResourceDir->SetWorldXfm(WorldXfm());
            mResourceDir->DrawShowing();
        } else {
            MILO_NOTIFY_ONCE("MiniLeaderboardDisplay: %s missing resource dir", Name());
        }
    }

    // Legacy preload helper: reads old-style name string
    void LegacyNameLoad(BinStream &bs) {
        char buffer[256];
        bs.ReadString(buffer, sizeof(buffer));
        mResourceDir.SetName(buffer, true);
    }
};

// Register factory during module init
INIT_REVS(0, 0)
void MiniLeaderboardDisplay::InitializeFactory() {}

