#include <iostream>
#include <unordered_map>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

int main() {
    // Construct a JSON object with various data types
    json data_object = {
        {"flag", true},
        {
            "numeric_data", {
                {"whole_number", 42},
                {"decimal_value", 17.23f}
            }
        },
        {"text", "Hello, world!"},
        {"sequence", {1, 2, 3, 4, 5}},
        {"empty_value", nullptr}
    };

    // Declare variables for type conversion
    bool boolean_result;
    int integer_result;
    short short_result;
    float float_result;
    int double_as_int_result;
    std::string string_result;
    std::vector<short> short_vector_result;
    std::unordered_map<std::string, json> object_result;

    // Perform explicit type conversions using get_to()
    data_object["flag"].get_to(boolean_result);
    data_object["numeric_data"]["whole_number"].get_to(integer_result);
    data_object["numeric_data"]["whole_number"].get_to(short_result);
    data_object["numeric_data"]["decimal_value"].get_to(float_result);
    data_object["numeric_data"]["decimal_value"].get_to(double_as_int_result);
    data_object["text"].get_to(string_result);
    data_object["sequence"].get_to(short_vector_result);
    data_object.get_to(object_result);

    // Output the converted values
    std::cout << boolean_result << '\n';
    std::cout << integer_result << ' ' << short_result << '\n';
    std::cout << float_result << ' ' << double_as_int_result << '\n';
    std::cout << string_result << '\n';

    // Print elements of the short vector
    for (const auto& item : short_vector_result) {
        std::cout << item << ' ';
    }
    std::cout << "\n\n";

    // Print key-value pairs from the JSON object
    for (const auto& [key, value] : object_result) {
        std::cout << key << ": " << value << '\n';
    }

    return 0;
}

