#define NOINLINE __attribute__((noinline))
#define LOG_TAG "ThreadLeakTest"
#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)

static NOINLINE void TestThreadLeak(int64_t delay) {
    std::thread worker([&delay]() {
        pthread_setname_np(pthread_self(), "main_test_thread");
        LOGI("main_test_thread started");

        // Create two additional threads dynamically
        std::thread* child1 = new std::thread([]() {
            pthread_setname_np(pthread_self(), "child_thread_1");
            LOGI("child_thread_1 executing");
        });

        std::thread* child2 = new std::thread([]() {
            pthread_setname_np(pthread_self(), "child_thread_2");
            LOGI("child_thread_2 executing");
        });

        // Simulate work with sleep
        std::this_thread::sleep_for(std::chrono::milliseconds(delay));

        // Detach first thread (intentionally leaked)
        child1->detach();
        LOGI("child_thread_1 detached");

        // Join second thread properly
        child2->join();
        LOGI("child_thread_2 joined");
    });

    // Detach the main test thread
    worker.detach();
}

