std::shared_ptr<Stream::stream<std::shared_ptr<Nat>>>
Stream::nats_from(std::shared_ptr<Nat> start_val) {
  return stream<std::shared_ptr<Nat>>::ctor::lazy_(
      [start_val]() mutable -> std::shared_ptr<Stream::stream<std::shared_ptr<Nat>>> {
        auto next_val = Nat::ctor::S_(start_val);
        return stream<std::shared_ptr<Nat>>::ctor::scons_(
            start_val, 
            stream<std::shared_ptr<Nat>>::ctor::lazy_(
                [next_val]() mutable -> std::shared_ptr<Stream::stream<std::shared_ptr<Nat>>> {
                  return nats_from(next_val);
                }));
      });
}

