std::error_code ConverterEBCDIC::convertToEBCDIC(StringRef Input,
                                                 SmallVectorImpl<char> &Output) {
  // Ensure output buffer is clean before processing
  if (!Output.empty())
    Output.clear();

  const unsigned char *SourceBytes =
      reinterpret_cast<const unsigned char *>(Input.data());
  size_t Remaining = Input.size();

  // Pre-allocate space for efficiency
  Output.reserve(Input.size());

  for (size_t i = 0; i < Remaining; ++i) {
    unsigned char CurrentByte = SourceBytes[i];

    // Handle potential UTF-8 multi-byte sequences
    if (CurrentByte >= 128) {
      // Only support 2-byte UTF-8 sequences starting with 0xc2 or 0xc3
      if (CurrentByte != 0xc2 && CurrentByte != 0xc3)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      // Check if we have enough bytes remaining
      if (i + 1 >= Remaining)
        return std::make_error_code(std::errc::invalid_argument);

      unsigned char NextByte = SourceBytes[++i];

      // Validate continuation byte format (must be 0x80-0xbf)
      if ((NextByte & 0xc0) != 0x80)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      // Combine bytes into single Unicode code point
      CurrentByte = NextByte | (CurrentByte << 6);
    }

    // Apply translation table
    unsigned char Translated = Latin1ToEBCDIC[CurrentByte];
    Output.push_back(static_cast<char>(Translated));
  }

  return std::error_code();
}

void ConverterEBCDIC::convertToUTF8(StringRef Input,
                                    SmallVectorImpl<char> &Output) {
  // Clear output buffer first
  Output.clear();

  const unsigned char *SourceBytes =
      reinterpret_cast<const unsigned char *>(Input.data());
  size_t Length = Input.size();

  // Reserve space to avoid reallocations
  Output.reserve(Input.size());

  for (size_t i = 0; i < Length; ++i) {
    unsigned char OriginalByte = SourceBytes[i];

    // Translate from EBCDIC to Latin-1
    unsigned char LatinChar = EBCDICToLatin1[OriginalByte];

    // Convert Latin-1 characters above 127 to UTF-8
    if (LatinChar >= 128) {
      // Split into two-byte UTF-8 sequence
      Output.push_back(static_cast<char>(0xc0 | (LatinChar >> 6)));
      Output.push_back(static_cast<char>(0x80 | (LatinChar & 0x3f)));
    } else {
      // ASCII characters pass through unchanged
      Output.push_back(static_cast<char>(LatinChar));
    }
  }
}

