#include <sol/sol.hpp>
#include <iostream>
#include <functional>
#include <vector>

int main() {
    std::cout << "=== capturing variadic arguments for later execution ===" << std::endl;

    sol::state lua;
    lua.open_libraries(sol::lib::base);

    std::function<void()> captured_action;

    auto capture_call = [&captured_action](sol::function func, sol::variadic_args args) {
        // Convert variadic arguments to a vector of sol::object
        std::vector<sol::object> arg_objects;
        for (const auto& arg : args) {
            arg_objects.push_back(arg);
        }

        // Store the lambda that will invoke the function with captured arguments
        captured_action = [func, arg_objects]() {
            func(sol::as_args(arg_objects));
        };
    };

    lua.set_function("capture_call", capture_call);

    lua.script(R"(
function greet_user(username)
    print("Hello, " .. username .. "!")
end

capture_call(greet_user, "Alice")
)");
    captured_action();

    lua.script(R"(
function display_info(count, item_name)
    print(count, "pieces of", item_name)
end

capture_call(display_info, 5, "oranges")
)");
    captured_action();

    std::cout << std::endl;

    return 0;
}

