#include <iostream>

// Function to calculate matrix sum and print transpose
int main() {
    int rows, cols;

    std::cout << "enter total row and columns ";
    std::cin >> rows >> cols;

    // Using dynamic allocation for flexibility
    int** matrix = new int*[rows];
    for(int i = 0; i < rows; ++i) {
        matrix[i] = new int[cols];
    }

    // Input matrix elements
    for(int i = 0; i < rows; ++i) {
        for(int j = 0; j < cols; ++j) {
            std::cout << " enter [" << i << "] [" << j << "] element ";
            std::cin >> matrix[i][j];
        }
    }

    int totalSum = 0;

    // Print original matrix and calculate sum once
    std::cout << "original matrix\n";
    for(int i = 0; i < rows; ++i) {
        for(int j = 0; j < cols; ++j) {
            std::cout << matrix[i][j];
            totalSum += matrix[i][j];
        }
        std::cout << "\n";
    }

    // Print transpose and add those values again (matching original behavior)
    std::cout << "transport of matrix\n";
    for(int j = 0; j < cols; ++j) {
        for(int i = 0; i < rows; ++i) {
            std::cout << matrix[i][j];
            totalSum += matrix[i][j];  // This duplicates the sum calculation
        }
        std::cout << "\n";
    }

    std::cout << "sum => " << totalSum << " \n";

    // Clean up dynamically allocated memory
    for(int i = 0; i < rows; ++i) {
        delete[] matrix[i];
    }
    delete[] matrix;

    return 0;
}

