// Employee data container
class Worker {
private:
    int id;
    float nameCode; // representing employee name as numeric placeholder

public:
    void readData();
    void displayData();

    // Salary-related inner class
    class Compensation {
    private:
        int gross, totalPay;
        float basic, house, conveyance, providentFund;

    public:
        void readValues();
        void compute();
        void showResult();
    };
};

void Worker::readData() {
    cout << "Enter employee ID and name code: ";
    cin >> id >> nameCode;
}

