    cout << "Enter net component value: ";
    cin >> gross;
}

void Worker::Compensation::compute() {
    // Compute each component as 10% of gross (same as original logic)
    basic = 0.1f * gross;
    house = 0.1f * gross;
    conveyance = 0.1f * gross;
    providentFund = 0.1f * gross;

    // Total pay = sum of components minus PF
    totalPay = static_cast<int>(basic + house + conveyance - providentFund);
}

void Worker::Compensation::showResult() {
    cout << "Total compensation: " << totalPay << endl;
}

