#include "NL/nlEndian.h"
#include "types.h"

/**
 * Offset/Address/Size: 0x0 | 0x801D2C38 | size: 0x2C
 */
void nlSwapEndian(unsigned short in, unsigned short* out)
{
    // Initialize output to zero
    *out = 0;

    // Extract the high byte and move it to low position, then mask
    unsigned short lowByte = (in & 0xFFU) << 8;

    // Extract the low byte and move it to high position, then mask
    unsigned short highByte = (in >> 8U) & 0xFFU;

    // Combine both bytes to form the swapped result
    *out = lowByte | highByte;
}

