void test_drot_inc_0(void)
{
    int idx;
    int length = 4, strideX = 0, strideY = 0;
    double cos_val = 0.25, sin_val = 0.5;
    double srcX1[] = {1.0, 3.0, 5.0, 7.0};
    double srcY1[] = {2.0, 4.0, 6.0, 8.0};
    double refX2[] = {1.0, 3.0, 5.0, 7.0};
    double refY2[] = {2.0, 4.0, 6.0, 8.0};

    // OpenBLAS call
    BLASFUNC(drot)(&length, srcX1, &strideX, srcY1, &strideY, &cos_val, &sin_val);
    // Reference implementation
    BLASFUNC_REF(drot)(&length, refX2, &strideX, refY2, &strideY, &cos_val, &sin_val);

    for (idx = 0; idx < length; ++idx) {
        CU_ASSERT_DOUBLE_EQUAL(srcX1[idx], refX2[idx], CHECK_EPS);
        CU_ASSERT_DOUBLE_EQUAL(srcY1[idx], refY2[idx], CHECK_EPS);
    }
}

